    public function with(FunctionDefinition $definition): self
    {
        if ($definition->name === 'pi' || $definition->name === 'e') {
            throw new \InvalidArgumentException(
                \sprintf(
                    'The constant name "%s" is reserved and cannot be registered as a function.',
                    $definition->name,
                ),
            );
        }

        if (isset($this->definitions[$definition->name])) {
            throw new \InvalidArgumentException(
                \sprintf(
                    'Function "%s" is already registered and cannot be overridden.',
                    $definition->name,
                ),
            );
        }

        $definitions = $this->definitions;
        $definitions[$definition->name] = $definition;

        return new self($definitions, $this->builtInNames);
    }

    public function find(string $name): ?FunctionDefinition
    {
        return $this->definitions[$name] ?? null;
    }

    public function isBuiltIn(string $name): bool
    {
        return isset($this->builtInNames[$name]);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function absolute(array $arguments): int|float
    {
        $value = $arguments[0];

        if ($value === \PHP_INT_MIN) {
            throw new \OverflowException(
                'The absolute value of PHP_INT_MIN is not representable as an integer.',
            );
        }

        return \abs($value);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function squareRoot(array $arguments): float
    {
        $value = $arguments[0];

        if ($value < 0) {
            throw new \DomainException(
                'sqrt() requires a non-negative argument.',
            );
        }

        return \sqrt($value);
    }

    /** @param list<int|float> $arguments */
    private static function cubeRoot(array $arguments): float
    {
        $value = (float) $arguments[0];

        return $value < 0.0 ? -\pow(-$value, 1.0 / 3.0) : \pow($value, 1.0 / 3.0);
    }

    /** @param list<int|float> $arguments */
    private static function nthRoot(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('root() requires a finite real radicand.');
        }

        $degree = self::requireInteger($arguments[1], 'root');
        if ($degree < 1) {
            throw new \DomainException('root() requires a positive integer degree.');
        }
        if ($value < 0.0 && $degree % 2 === 0) {
            throw new \DomainException('root() cannot take an even root of a negative radicand.');
        }

        if ($value === 0.0) {
            return 0.0;
        }

        return $value < 0.0
            ? -\pow(-$value, 1.0 / $degree)
            : \pow($value, 1.0 / $degree);
    }

    /** @param list<int|float> $arguments */
    private static function errorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('erf() requires a finite argument.');
        }
        if ($value == 0.0) {
            return 0.0;
        }

        $sign = $value < 0.0 ? -1.0 : 1.0;
        $absolute = abs($value);
        if ($absolute <= 4.0) {
            $square = $absolute * $absolute;
            $term = $absolute;
            $sum = $term;
            for ($index = 1; $index <= 256; ++$index) {
                $term *= -$square / $index;
                $addend = $term / (2.0 * $index + 1.0);
                $sum += $addend;
                if (abs($addend) <= abs($sum) * 1.0E-16) {
                    break;
                }
            }
            $result = $sign * (2.0 / sqrt(M_PI)) * $sum;
        } else {
            $complement = self::positiveComplementaryErrorFunction($absolute);
            $result = $sign * (1.0 - $complement);
        }

        return self::finiteSpecialResult($result, 'erf');
    }

    /** @param list<int|float> $arguments */
    private static function complementaryErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('erfc() requires a finite argument.');
        }

        $absolute = abs($value);
        if ($absolute < 2.0) {
            return self::finiteSpecialResult(1.0 - self::errorFunction([$value]), 'erfc');
        }

        $tail = self::positiveComplementaryErrorFunction($absolute);
        return self::finiteSpecialResult($value < 0.0 ? 2.0 - $tail : $tail, 'erfc');
    }

    /** @param list<int|float> $arguments */
    private static function scaledComplementaryErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('erfcx() requires a finite argument.');
        }

        if ($value >= 2.0) {
            // erfcx(x) = 1 / (sqrt(pi) * (x + continued fraction)); this
            // cancels exp(-x²) analytically and remains useful for huge x.
            $fraction = 0.0;
            for ($index = 64; $index >= 1; --$index) {
                $fraction = ($index / 2.0) / ($value + $fraction);
            }

            return self::finiteSpecialResult(
                1.0 / sqrt(M_PI) / ($value + $fraction),
                'erfcx',
            );
        }

        $logResult = $value * $value + log(self::complementaryErrorFunction([$value]));
        if ($logResult > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('erfcx() produced a non-finite result.');
        }

        return self::finiteSpecialResult(exp($logResult), 'erfcx');
    }

    /** @param list<int|float> $arguments */
    private static function logComplementaryErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('logerfc() requires a finite argument.');
        }
        if ($value >= 2.0) {
            $fraction = 0.0;
            for ($index = 64; $index >= 1; --$index) {
                $fraction = ($index / 2.0) / ($value + $fraction);
            }

            return self::finiteSpecialResult(
                -$value * $value - 0.5 * log(M_PI) - log($value + $fraction),
                'logerfc',
            );
        }

        return self::finiteSpecialResult(log(self::complementaryErrorFunction([$value])), 'logerfc');
    }

    /** @param list<int|float> $arguments */
    private static function logComplementaryErrorFunctionDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('logerfcprime() requires a finite argument.');
        }
        if ($value >= 2.0) {
            if ($value > PHP_FLOAT_MAX / 2.0) {
                throw new \OverflowException('logerfcprime() derivative exceeds the finite floating-point range.');
            }
            return self::finiteSpecialResult(
                -2.0 / sqrt(M_PI) / self::scaledComplementaryErrorFunction([$value]),
                'logerfcprime',
            );
        }

        $logDerivativeMagnitude = log(2.0 / sqrt(M_PI)) - $value * $value
            - self::logComplementaryErrorFunction([$value]);
        return self::finiteSpecialResult(-exp($logDerivativeMagnitude), 'logerfcprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogComplementaryErrorFunction(array $arguments): float
    {
        $logProbability = (float) $arguments[0];
        if (!is_finite($logProbability) || $logProbability > 0.0) {
            throw new \DomainException('erfcinvlog() requires a finite log probability no greater than zero.');
        }
        if ($logProbability === 0.0) {
            return 0.0;
        }

        $lower = 0.0;
        $upper = max(2.0, sqrt(-$logProbability) * 0.5);
        while (self::logComplementaryErrorFunction([$upper]) > $logProbability) {
            if ($upper >= sqrt(PHP_FLOAT_MAX)) {
                throw new \OverflowException('erfcinvlog() quantile exceeds the finite floating-point range.');
            }
            $upper *= 2.0;
        }
        for ($index = 0; $index < 128; ++$index) {
            $middle = $lower + ($upper - $lower) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::logComplementaryErrorFunction([$middle]) > $logProbability) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(($lower + ($upper - $lower) / 2.0), 'erfcinvlog');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogComplementaryErrorFunctionDerivative(array $arguments): float
    {
        $logProbability = (float) $arguments[0];
        if (!is_finite($logProbability) || $logProbability > 0.0) {
            throw new \DomainException('erfcinvlogprime() requires a finite log probability no greater than zero.');
        }

        $quantile = self::inverseLogComplementaryErrorFunction([$logProbability]);
        return self::finiteSpecialResult(
            -0.5 * sqrt(M_PI) * self::scaledComplementaryErrorFunction([$quantile]),
            'erfcinvlogprime',
        );
    }

    private static function positiveComplementaryErrorFunction(float $value): float
    {
        if ($value === 0.0) {
            return 1.0;
        }

        // Evaluate the continued fraction for erfc(x) directly. Unlike 1 - erf(x),
        // this retains relative precision for very small positive tails.
        $fraction = 0.0;
        for ($index = 64; $index >= 1; --$index) {
            $fraction = ($index / 2.0) / ($value + $fraction);
        }

        $result = exp(-$value * $value) / sqrt(M_PI) / ($value + $fraction);
        return self::finiteSpecialResult($result, 'erfc');
    }

    /** @param list<int|float> $arguments */
    private static function inverseErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value <= -1.0 || $value >= 1.0) {
            throw new \DomainException('erfinv() requires a finite argument strictly between -1 and 1.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $lower = -8.0;
        $upper = 8.0;
        for ($index = 0; $index < 128; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if (self::errorFunction([$middle]) < $value) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(($lower + $upper) / 2.0, 'erfinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseComplementaryErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value <= 0.0 || $value >= 2.0) {
            throw new \DomainException('erfcinv() requires a finite argument strictly between 0 and 2.');
        }
        if ($value === 1.0) {
            return 0.0;
        }
        $reflected = $value > 1.0;
        if ($reflected) {
            $value = 2.0 - $value;
            $sign = -1.0;
        } else {
            $sign = 1.0;
        }
        if ($value >= 1.0e-3) {
            return $sign * self::inverseErrorFunction([1.0 - $value]);
        }

        $lower = 0.0;
        $upper = 8.0;
        while (self::positiveComplementaryErrorFunction($upper) > $value) {
            $upper *= 2.0;
        }
        for ($index = 0; $index < 128; ++$index) {
            $middle = $lower + ($upper - $lower) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::positiveComplementaryErrorFunction($middle) > $value) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult($sign * ($lower + ($upper - $lower) / 2.0), 'erfcinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseErrorFunctionDerivative(array $arguments): float
    {
        $quantile = self::inverseErrorFunction($arguments);
        return self::inverseErrorFunctionDerivativeValue($quantile, false, false, 'erfinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseErrorFunctionSecondDerivative(array $arguments): float
    {
        $quantile = self::inverseErrorFunction($arguments);
        return self::inverseErrorFunctionDerivativeValue($quantile, false, true, 'erfinvsecond');
    }

    /** @param list<int|float> $arguments */
    private static function inverseComplementaryErrorFunctionDerivative(array $arguments): float
    {
        $quantile = self::inverseComplementaryErrorFunction($arguments);
        return self::inverseErrorFunctionDerivativeValue($quantile, true, false, 'erfcinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseComplementaryErrorFunctionSecondDerivative(array $arguments): float
    {
        $quantile = self::inverseComplementaryErrorFunction($arguments);
        return self::inverseErrorFunctionDerivativeValue($quantile, true, true, 'erfcinvsecond');
    }

    private static function inverseErrorFunctionDerivativeValue(
        float $quantile,
        bool $complementary,
        bool $second,
        string $function,
    ): float {
        if ($second && $quantile === 0.0) {
            return 0.0;
        }
        $square = $quantile * $quantile;
        $logMagnitude = $second
            ? log(M_PI / 2.0) + 2.0 * $square + log(abs($quantile))
            : 0.5 * log(M_PI) - log(2.0) + $square;
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . ' derivative exceeds the finite floating-point range.');
        }

        $sign = $second
            ? ($quantile < 0.0 ? -1.0 : 1.0)
            : ($complementary ? -1.0 : 1.0);
        return self::finiteSpecialResult($sign * exp($logMagnitude), $function);
    }

    /** @param list<int|float> $arguments */
    private static function imaginaryErrorFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('erfi() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        $sign = $value < 0.0 ? -1.0 : 1.0;
        $absolute = abs($value);
        $square = $absolute * $absolute;
        if ($square < 500.0) {
            $term = $absolute;
            $sum = $term;
            for ($index = 1; $index <= 1000; ++$index) {
                $term *= $square / $index;
                $addend = $term / (2.0 * $index + 1.0);
                $sum += $addend;
                if (abs($addend) <= abs($sum) * 1.0E-15) {
                    break;
                }
            }
            return self::finiteSpecialResult($sign * (2.0 / sqrt(M_PI)) * $sum, 'erfi');
        }

        $term = 1.0;
        $sum = 1.0;
        for ($index = 1; $index <= 1000; ++$index) {
            $term *= (2.0 * $index - 1.0) / (2.0 * $square);
            $sum += $term;
            if (abs($term) <= abs($sum) * 1.0E-15) {
                break;
            }
        }
        $result = exp($square) * $sum / (sqrt(M_PI) * $absolute);
        return self::finiteSpecialResult($sign * $result, 'erfi');
    }

    /** @param list<int|float> $arguments */
    private static function errorFunctionPrime(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erf', false);
    }

    /** @param list<int|float> $arguments */
    private static function errorFunctionSecond(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erf', true);
    }

    /** @param list<int|float> $arguments */
    private static function errorFunctionThird(array $arguments): float
    {
        return self::errorFunctionThirdDerivative($arguments, 'erf');
    }

    /** @param list<int|float> $arguments */
    private static function complementaryErrorFunctionPrime(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erfc', false);
    }

    /** @param list<int|float> $arguments */
    private static function complementaryErrorFunctionSecond(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erfc', true);
    }

    /** @param list<int|float> $arguments */
    private static function complementaryErrorFunctionThird(array $arguments): float
    {
        return self::errorFunctionThirdDerivative($arguments, 'erfc');
    }

    /** @param list<int|float> $arguments */
    private static function imaginaryErrorFunctionPrime(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erfi', false);
    }

    /** @param list<int|float> $arguments */
    private static function imaginaryErrorFunctionSecond(array $arguments): float
    {
        return self::errorFunctionDerivative($arguments, 'erfi', true);
    }

    /** @param list<int|float> $arguments */
    private static function imaginaryErrorFunctionThird(array $arguments): float
    {
        return self::errorFunctionThirdDerivative($arguments, 'erfi');
    }

    /** @param list<int|float> $arguments */
    private static function errorFunctionThirdDerivative(array $arguments, string $kind): float
    {
        $value = (float) $arguments[0];
        $function = $kind . 'third';
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if (abs($value) > sqrt(PHP_FLOAT_MAX)) {
            if ($kind !== 'erfi') {
                return 0.0;
            }
            throw new \OverflowException($function . '() result exceeds the finite floating-point range.');
        }

        $square = $value * $value;
        $polynomial = $kind === 'erfi' ? 2.0 * $square + 1.0 : 2.0 * $square - 1.0;
        $exponent = ($kind === 'erfi' ? 1.0 : -1.0) * $square;
        $result = (4.0 / sqrt(M_PI)) * $polynomial * exp($exponent);
        if ($kind === 'erfc') {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, $function);
    }

    /** @param list<int|float> $arguments */
    private static function errorFunctionDerivative(array $arguments, string $kind, bool $second): float
    {
        $value = (float) $arguments[0];
        $function = $kind . ($second ? 'second' : 'prime');
        if (!\is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($second && $value === 0.0) {
            return 0.0;
        }

        $imaginary = $kind === 'erfi';
        $exponent = ($imaginary ? 1.0 : -1.0) * $value * $value;
        $logMagnitude = $second
            ? \log(4.0 * \abs($value) / \sqrt(M_PI)) + $exponent
            : \log(2.0 / \sqrt(M_PI)) + $exponent;
        if ($logMagnitude > \log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() result exceeds the finite floating-point range.');
        }

        $sign = 1.0;
        if ($kind === 'erfc' && !$second) {
            $sign = -1.0;
        } elseif ($second && $kind === 'erf') {
            $sign = $value < 0.0 ? 1.0 : -1.0;
        } elseif ($second && $value < 0.0) {
            $sign = -1.0;
        }

        return self::finiteSpecialResult($sign * \exp($logMagnitude), $function);
    }

    /** @param list<int|float> $arguments */
    private static function dawsonFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('dawson() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $sign = $value < 0.0 ? -1.0 : 1.0;
        $magnitude = abs($value);
        if ($magnitude <= 0.5) {
            $term = $magnitude;
            $sum = $term;
            for ($index = 1; $index <= 1000; ++$index) {
                $term *= -2.0 * $magnitude * $magnitude / (2.0 * $index + 1.0);
                $sum += $term;
                if (abs($term) <= abs($sum) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult($sign * $sum, 'dawson');
        }
        if ($magnitude < 10.0) {
            $scaled = 0.5 * sqrt(M_PI) * exp(-$magnitude * $magnitude)
                * self::imaginaryErrorFunction([$magnitude]);
            return self::finiteSpecialResult($sign * $scaled, 'dawson');
        }

        $inverse = 1.0 / $magnitude;
        $inverseSquare = $inverse * $inverse;
        $term = 0.5 * $inverse;
        $sum = $term;
        for ($index = 1; $index <= 1000; ++$index) {
            $nextTerm = $term * (2.0 * $index - 1.0) * $inverseSquare / 2.0;
            if (abs($nextTerm) >= abs($term)) {
                break;
            }
            $sum += $nextTerm;
            $term = $nextTerm;
            if (abs($term) <= abs($sum) * 2.0e-16) {
                break;
            }
        }

        return self::finiteSpecialResult($sign * $sum, 'dawson');
    }

    /** @param list<int|float> $arguments */
    private static function dawsonDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('dawsonprime() requires a finite argument.');
        }
        if (abs($value) < 10.0) {
            return self::finiteSpecialResult(1.0 - 2.0 * $value * self::dawsonFunction([$value]), 'dawsonprime');
        }

        $inverse = 1.0 / abs($value);
        $inverseSquare = $inverse * $inverse;
        $term = -0.5 * $inverseSquare;
        $sum = $term;
        for ($index = 1; $index <= 1000; ++$index) {
            $nextTerm = $term * (2.0 * $index + 1.0) * $inverseSquare / 2.0;
            if (abs($nextTerm) >= abs($term)) {
                break;
            }
            $sum += $nextTerm;
            $term = $nextTerm;
            if (abs($term) <= abs($sum) * 2.0e-16) {
                break;
            }
        }

        return self::finiteSpecialResult($sum, 'dawsonprime');
    }

    /** @param list<int|float> $arguments */
    private static function dawsonSecondDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('dawsonsecond() requires a finite argument.');
        }
        if (abs($value) < 10.0) {
            $result = -2.0 * self::dawsonFunction([$value]) - 2.0 * $value * self::dawsonDerivative([$value]);
            return self::finiteSpecialResult($result, 'dawsonsecond');
        }

        $inverse = 1.0 / abs($value);
        $inverseSquare = $inverse * $inverse;
        $term = $inverse * $inverseSquare;
        $sum = $term;
        for ($index = 1; $index <= 1000; ++$index) {
            $nextTerm = $term * (2.0 * $index + 1.0) * ($index + 1.0) * $inverseSquare
                / (2.0 * $index);
            if (abs($nextTerm) >= abs($term)) {
                break;
            }
            $sum += $nextTerm;
            $term = $nextTerm;
            if (abs($term) <= abs($sum) * 2.0e-16) {
                break;
            }
        }
        if ($value < 0.0) {
            $sum = -$sum;
        }

        return self::finiteSpecialResult($sum, 'dawsonsecond');
    }

    /** @param list<int|float> $arguments */
    private static function dawsonThirdDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('dawsonthird() requires a finite argument.');
        }
        if (\abs($value) < 100.0) {
            $result = -4.0 * self::dawsonDerivative([$value])
                - 2.0 * $value * self::dawsonSecondDerivative([$value]);

            return self::finiteSpecialResult($result, 'dawsonthird');
        }

        $inverse = 1.0 / \abs($value);
        $inverseSquare = $inverse * $inverse;
        $term = -3.0 * $inverseSquare * $inverseSquare;
        $sum = $term;
        for ($index = 1; $index <= 1000; ++$index) {
            $nextTerm = $term * ($index + 1.0) * (2.0 * $index + 3.0) * $inverseSquare
                / (2.0 * $index);
            if (\abs($nextTerm) >= \abs($term)) {
                break;
            }
            $sum += $nextTerm;
            $term = $nextTerm;
            if (\abs($term) <= \abs($sum) * 2.0e-16) {
                break;
            }
        }
        return self::finiteSpecialResult($sum, 'dawsonthird');
    }

    /** @param list<int|float> $arguments */
    private static function airyAi(array $arguments): float
    {
        $value = (float) $arguments[0];
