    /** @param list<int|float> $arguments */
    private static function airyAiSecond(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('airyaisecond() requires a finite argument.');
        }

        return self::finiteSpecialResult($value * self::airyValue($value, false), 'airyaisecond');
    }

    /** @param list<int|float> $arguments */
    private static function airyBiSecond(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('airybisecond() requires a finite argument.');
        }

        return self::finiteSpecialResult($value * self::airyValue($value, true), 'airybisecond');
    }

    /** @param list<int|float> $arguments */
    private static function airyAiThird(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('airyaithird() requires a finite argument.');
        }

        return self::finiteSpecialResult(
            self::airyValue($value, false) + $value * self::airyDerivative($value, false),
            'airyaithird',
        );
    }

    /** @param list<int|float> $arguments */
    private static function airyBiThird(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('airybithird() requires a finite argument.');
        }

        return self::finiteSpecialResult(
            self::airyValue($value, true) + $value * self::airyDerivative($value, true),
            'airybithird',
        );
    }

    private static function airyValue(float $value, bool $secondSolution): float
    {
        if (abs($value) <= 3.0) {
            $gammaOneThird = 2.6789385347077476337;
            $gammaTwoThirds = 1.3541179394264004169;
            $a0 = $secondSolution
                ? 1.0 / (($gammaTwoThirds) * (3.0 ** (1.0 / 6.0)))
                : 1.0 / (($gammaTwoThirds) * (3.0 ** (2.0 / 3.0)));
            $a1 = $secondSolution
                ? (3.0 ** (1.0 / 6.0)) / $gammaOneThird
                : -1.0 / ((3.0 ** (1.0 / 3.0)) * $gammaOneThird);
            $coefficients = [$a0, $a1, 0.0];
            for ($index = 1; $index <= 240; ++$index) {
                $coefficients[$index + 2] = $coefficients[$index - 1] / (($index + 2.0) * ($index + 1.0));
            }
            $power = 1.0;
            $sum = 0.0;
            foreach ($coefficients as $index => $coefficient) {
                if ($index > 0) {
                    $power *= $value;
                }
                $term = $coefficient * ($index === 0 ? 1.0 : $power);
                $sum += $term;
                if ($index > 24 && abs($term) <= max(1.0, abs($sum)) * 1.0E-16) {
                    break;
                }
            }

            return $sum;
        }

        $absolute = abs($value);
        $zeta = (2.0 / 3.0) * ($absolute ** 1.5);
        $first = 5.0 / (72.0 * $zeta);
        $second = 385.0 / (10368.0 * $zeta * $zeta);
        $third = 85085.0 / (2239488.0 * $zeta ** 3);
        if ($value > 0.0) {
            $correction = $secondSolution
                ? 1.0 + $first + $second + $third
                : 1.0 - $first + $second - $third;
            $exponent = $secondSolution ? exp($zeta) : exp(-$zeta);
            $scale = $secondSolution ? 1.0 / sqrt(M_PI) : 1.0 / (2.0 * sqrt(M_PI));

            return $scale * $absolute ** (-0.25) * $exponent * $correction;
        }
        $phase = $zeta + M_PI / 4.0;
        $amplitude = 1.0 / (sqrt(M_PI) * $absolute ** 0.25);

        return $amplitude * ($secondSolution ? cos($phase) : sin($phase));
    }

    private static function airyDerivative(float $value, bool $secondSolution): float
    {
        if (abs($value) <= 3.0) {
            $gammaOneThird = 2.6789385347077476337;
            $gammaTwoThirds = 1.3541179394264004169;
            $a0 = $secondSolution
                ? 1.0 / (($gammaTwoThirds) * (3.0 ** (1.0 / 6.0)))
                : 1.0 / (($gammaTwoThirds) * (3.0 ** (2.0 / 3.0)));
            $a1 = $secondSolution
                ? (3.0 ** (1.0 / 6.0)) / $gammaOneThird
                : -1.0 / ((3.0 ** (1.0 / 3.0)) * $gammaOneThird);
            $coefficients = [$a0, $a1, 0.0];
            for ($index = 1; $index <= 240; ++$index) {
                $coefficients[$index + 2] = $coefficients[$index - 1] / (($index + 2.0) * ($index + 1.0));
            }
            $power = 1.0;
            $sum = 0.0;
            foreach ($coefficients as $index => $coefficient) {
                if ($index > 1) {
                    $power *= $value;
                }
                if ($index === 0) {
                    continue;
                }
                $term = $index * $coefficient * $power;
                $sum += $term;
                if ($index > 24 && abs($term) <= max(1.0, abs($sum)) * 1.0E-16) {
                    break;
                }
            }

            return $sum;
        }

        $absolute = abs($value);
        $zeta = (2.0 / 3.0) * ($absolute ** 1.5);
        $first = 5.0 / (72.0 * $zeta);
        $second = 385.0 / (10368.0 * $zeta * $zeta);
        $third = 85085.0 / (2239488.0 * $zeta ** 3);
        if ($value > 0.0) {
            $correction = $secondSolution
                ? 1.0 + $first + $second + $third
                : 1.0 - $first + $second - $third;
            $correctionDerivative = $secondSolution
                ? -$first - 2.0 * $second - 3.0 * $third
                : $first - 2.0 * $second + 3.0 * $third;
            $logDerivative = ($secondSolution ? 1.0 : -1.0) * sqrt($value) - 1.0 / (4.0 * $value);
            $scale = $secondSolution ? 1.0 / sqrt(M_PI) : 1.0 / (2.0 * sqrt(M_PI));
            $envelope = $scale * $absolute ** (-0.25) * ($secondSolution ? exp($zeta) : exp(-$zeta));

            return $envelope * ($logDerivative * $correction + sqrt($value) / $zeta * $correctionDerivative);
        }

        $phase = $zeta + M_PI / 4.0;
        $amplitude = 1.0 / (sqrt(M_PI) * $absolute ** 0.25);
        $amplitudeDerivative = $amplitude / (4.0 * $absolute);
        $phaseDerivative = -sqrt($absolute);

        return $secondSolution
            ? $amplitudeDerivative * cos($phase) - $amplitude * $phaseDerivative * sin($phase)
            : $amplitudeDerivative * sin($phase) + $amplitude * $phaseDerivative * cos($phase);
    }

    /** @param list<int|float> $arguments */
    private static function completeEllipticK(array $arguments): float
    {
        $parameter = self::requireEllipticParameter($arguments, 'ellipk');
        if ($parameter === 1.0) {
            throw new \DomainException('ellipk() diverges at parameter one.');
        }

        [$agM, $unused] = self::ellipticAgm($parameter);
        return self::finiteSpecialResult(M_PI / (2.0 * $agM), 'ellipk');
    }

    /** @param list<int|float> $arguments */
    private static function completeEllipticE(array $arguments): float
    {
        $parameter = self::requireEllipticParameter($arguments, 'ellipe');
        if ($parameter === 1.0) {
            return 1.0;
        }
        if ($parameter < 0.0) {
            return self::finiteSpecialResult(self::ellipticNumericalE($parameter), 'ellipe');
        }

        [$agM, $correction] = self::ellipticAgm($parameter);
        $completeK = M_PI / (2.0 * $agM);
        return self::finiteSpecialResult($completeK * (1.0 - $correction), 'ellipe');
    }

    /** @param list<int|float> $arguments */
    private static function completeEllipticKDerivative(array $arguments): float
    {
        $parameter = self::requireEllipticParameter($arguments, 'ellipkprime');
        if ($parameter === 1.0) {
            throw new \DomainException('ellipkprime() diverges at parameter one.');
        }
        if (abs($parameter) < 0.1) {
            return self::finiteSpecialResult(self::completeEllipticDerivativeSeries($parameter, false), 'ellipkprime');
        }

        $completeK = self::completeEllipticK([$parameter]);
        $completeE = self::completeEllipticE([$parameter]);
        return self::finiteSpecialResult(
            ($completeE / (1.0 - $parameter) - $completeK) / (2.0 * $parameter),
            'ellipkprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function completeEllipticEDerivative(array $arguments): float
    {
        $parameter = self::requireEllipticParameter($arguments, 'ellipeprime');
        if ($parameter === 1.0) {
            throw new \DomainException('ellipeprime() diverges at parameter one.');
        }
        if (abs($parameter) < 0.1) {
            return self::finiteSpecialResult(self::completeEllipticDerivativeSeries($parameter, true), 'ellipeprime');
        }

        return self::finiteSpecialResult(
            (self::completeEllipticE([$parameter]) - self::completeEllipticK([$parameter]))
                / (2.0 * $parameter),
            'ellipeprime',
        );
    }

    private static function completeEllipticDerivativeSeries(float $parameter, bool $secondKind): float
    {
        $coefficient = 1.0;
        $power = 1.0;
        $sum = 0.0;
        for ($index = 1; $index <= 80; ++$index) {
            $ratio = (2.0 * $index - 1.0) / (2.0 * $index);
            $coefficient *= $ratio * $ratio;
            $term = $index * $coefficient * $power;
            if ($secondKind) {
                $term /= 2.0 * $index - 1.0;
                $term = -$term;
            }
            $sum += $term;
            if ($index > 8 && abs($term) <= max(1.0, abs($sum)) * 1.0E-16) {
                break;
            }
            $power *= $parameter;
        }

        return (M_PI / 2.0) * $sum;
    }

    /** @param list<int|float> $arguments */
    private static function ellipticNome(array $arguments): float
    {
        $parameter = (float) $arguments[0];
        if (!is_finite($parameter) || $parameter < 0.0 || $parameter > 1.0) {
            throw new \DomainException('ellipnome() requires a finite parameter in [0, 1].');
        }
        if ($parameter === 0.0) {
            return 0.0;
        }
        if ($parameter === 1.0) {
            return 1.0;
        }

        if ($parameter < 1.0e-4) {
            return $parameter * (
                1.0 / 16.0 + $parameter * (
                    1.0 / 32.0 + $parameter * (
                        21.0 / 1024.0 + $parameter * (
                            31.0 / 2048.0 + $parameter * (6257.0 / 524288.0)
                        )
                    )
                )
            );
        }

        $complete = self::completeEllipticK([$parameter]);
        $complementary = self::completeEllipticK([1.0 - $parameter]);

        return self::finiteSpecialResult(exp(-M_PI * $complementary / $complete), 'ellipnome');
    }

    /** @param list<int|float> $arguments */
    private static function inverseEllipticNome(array $arguments): float
    {
        $nome = (float) $arguments[0];
        if (!is_finite($nome) || $nome < 0.0 || $nome > 1.0) {
            throw new \DomainException('ellipnomeinv() requires a finite nome in [0, 1].');
        }
        if ($nome === 0.0) {
            return 0.0;
        }
        if ($nome === 1.0) {
            return 1.0;
        }

        $transformedNome = $nome <= 0.5
            ? $nome
            : exp(-(M_PI * M_PI) / -log($nome));
        $theta2 = self::jacobiTheta([0.0, $transformedNome], 2);
        $theta3 = self::jacobiTheta([0.0, $transformedNome], 3);
        $transformedParameter = ($theta2 / $theta3) ** 4;
        $parameter = $nome <= 0.5 ? $transformedParameter : 1.0 - $transformedParameter;

        return self::finiteSpecialResult($parameter, 'ellipnomeinv');
    }

    /** @param list<int|float> $arguments */
    private static function requireEllipticParameter(array $arguments, string $function): float
    {
        $parameter = (float) $arguments[0];
        if (!is_finite($parameter) || $parameter > 1.0) {
            throw new \DomainException($function . '() requires a finite real parameter less than or equal to one.');
        }

        return $parameter;
    }

    /** @return array{0: float, 1: float} */
    private static function ellipticAgm(float $parameter): array
    {
        $arithmetic = 1.0;
        $geometric = sqrt(1.0 - $parameter);
        $correction = $parameter / 2.0;
        for ($index = 0; $index < 64; ++$index) {
            $difference = ($arithmetic - $geometric) / 2.0;
            $correction += (2.0 ** $index) * $difference * $difference;
            $nextArithmetic = ($arithmetic + $geometric) / 2.0;
            $nextGeometric = sqrt($arithmetic * $geometric);
            $arithmetic = $nextArithmetic;
            $geometric = $nextGeometric;
            if (abs($arithmetic - $geometric) <= abs($arithmetic) * 1.0E-16) {
                break;
            }
        }

        return [$arithmetic, $correction];
    }

    /** @param list<int|float> $arguments */
    private static function jacobiEllipticSn(array $arguments): float
    {
        return self::jacobiEllipticValues($arguments, 'jacobisn')[0];
    }

    /** @param list<int|float> $arguments */
    private static function jacobiEllipticCn(array $arguments): float
    {
        return self::jacobiEllipticValues($arguments, 'jacobicn')[1];
    }

    /** @param list<int|float> $arguments */
    private static function jacobiEllipticDn(array $arguments): float
    {
        return self::jacobiEllipticValues($arguments, 'jacobidn')[2];
    }

    /** @param list<int|float> $arguments */
    private static function jacobiAmplitude(array $arguments): float
    {
        $argument = (float) $arguments[0];
        $parameter = (float) $arguments[1];
        if (!\is_finite($argument) || !\is_finite($parameter) || $parameter < 0.0 || $parameter > 1.0) {
            throw new \DomainException('jacobiam() requires a finite argument and parameter in [0, 1].');
        }
        if ($parameter === 0.0) {
            return $argument;
        }
        if ($parameter === 1.0) {
            return self::gudermannian([$argument]);
        }

        [$agm] = self::ellipticAgm($parameter);
        $period = M_PI / $agm;
        $turns = \floor($argument / $period);
        $reduced = \fmod($argument, $period);
        if ($reduced < 0.0) {
            $reduced += $period;
        }
        if ($reduced >= $period) {
            $reduced = 0.0;
            $turns += 1.0;
        }

        [$sn, $cn] = self::jacobiEllipticValues([$reduced, $parameter], 'jacobiam');
        $amplitude = $turns * M_PI + \atan2($sn, $cn);

        return self::finiteSpecialResult($amplitude, 'jacobiam');
    }

