    /** @param list<int|float> $arguments */
    private static function jacobiEllipticSc(array $arguments): float
    {
        return self::jacobiEllipticQuotient($arguments, 'jacobisc', 0, 1);
    }

    /** @param list<int|float> $arguments */
    private static function jacobiEllipticNs(array $arguments): float
    {
        return self::jacobiEllipticQuotient($arguments, 'jacobins', -1, 0);
