    /** @param list<int|float> $arguments */
    private static function jacobiEllipticQuotient(
        array $arguments,
        string $function,
        int $numeratorIndex,
        int $denominatorIndex,
    ): float {
        [$sn, $cn, $dn] = self::jacobiEllipticValues($arguments, $function);
        $values = [$sn, $cn, $dn];
        $numerator = $numeratorIndex < 0 ? 1.0 : $values[$numeratorIndex];
        $denominator = $values[$denominatorIndex];
        if (\abs($denominator) <= 4.0 * \PHP_FLOAT_EPSILON) {
            throw new \DomainException($function . '() is singular when its denominator is zero.');
        }

        return self::finiteSpecialResult($numerator / $denominator, $function);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function jacobiEllipticValues(array $arguments, string $function): array
    {
        $argument = (float) $arguments[0];
        $parameter = (float) $arguments[1];
        if (!is_finite($argument) || !is_finite($parameter) || $parameter < 0.0 || $parameter > 1.0) {
            throw new \DomainException($function . '() requires a finite argument and parameter in [0, 1].');
        }
        if ($parameter === 0.0) {
            return [sin($argument), cos($argument), 1.0];
        }
        if ($parameter === 1.0) {
            $tail = exp(-abs($argument));
            $sech = 2.0 * $tail / (1.0 + $tail * $tail);

            return [tanh($argument), $sech, $sech];
        }

        [$agm] = self::ellipticAgm($parameter);
        $completeK = M_PI / (2.0 * $agm);
        $reducedArgument = fmod($argument, 4.0 * $completeK);
        $arithmetic = 1.0;
        $geometric = sqrt(1.0 - $parameter);
        $cValues = [];
        $aValues = [];
        for ($iteration = 0; $iteration < 64; ++$iteration) {
            $c = ($arithmetic - $geometric) / 2.0;
            $nextArithmetic = ($arithmetic + $geometric) / 2.0;
            $nextGeometric = sqrt($arithmetic * $geometric);
            $cValues[] = $c;
            $aValues[] = $nextArithmetic;
            $arithmetic = $nextArithmetic;
            $geometric = $nextGeometric;
            if (abs($c) <= abs($arithmetic) * 1.0e-16) {
                break;
            }
        }

        $phi = (2.0 ** count($cValues)) * $arithmetic * $reducedArgument;
        for ($index = count($cValues) - 1; $index >= 0; --$index) {
            $sine = sin($phi);
            $ratio = ($cValues[$index] / $aValues[$index]) * $sine;
            $ratio = max(-1.0, min(1.0, $ratio));
            $phi = ($phi + asin($ratio)) / 2.0;
        }
        $sn = sin($phi);
        $cn = cos($phi);
        $dn = sqrt(max(0.0, 1.0 - $parameter * $sn * $sn));

        return [
            self::finiteSpecialResult($sn, 'jacobisn'),
            self::finiteSpecialResult($cn, 'jacobicn'),
            self::finiteSpecialResult($dn, 'jacobidn'),
        ];
    }

    /** @param list<int|float> $arguments */
    private static function jacobiZeta(array $arguments): float
    {
        $argument = (float) $arguments[0];
        $parameter = (float) $arguments[1];
        if (!is_finite($argument) || !is_finite($parameter) || $parameter < 0.0 || $parameter > 1.0) {
            throw new \DomainException('jacobizeta() requires a finite argument and parameter in [0, 1].');
        }
        if ($parameter === 0.0) {
            return 0.0;
        }
        if ($parameter === 1.0) {
            return self::finiteSpecialResult(tanh($argument), 'jacobizeta');
        }

        [$agm] = self::ellipticAgm($parameter);
        $completeK = M_PI / (2.0 * $agm);
        $period = 2.0 * $completeK;
        $reducedArgument = fmod($argument, $period);
        if ($reducedArgument > $completeK) {
            $reducedArgument -= $period;
        } elseif ($reducedArgument < -$completeK) {
            $reducedArgument += $period;
        }
        if (abs($reducedArgument) === $completeK) {
            return 0.0;
        }

        [$sn, $cn] = self::jacobiEllipticValues([$reducedArgument, $parameter], 'jacobizeta');
        $amplitude = atan2($sn, $cn);
        $incompleteE = self::ellipticIncompleteIntegral($amplitude, $parameter, true);
        $completeE = self::completeEllipticE([$parameter]);
        $zeta = $incompleteE - ($completeE / $completeK) * $reducedArgument;

        return self::finiteSpecialResult($zeta, 'jacobizeta');
    }

    /** @param list<int|float> $arguments */
    private static function jacobiTheta1(array $arguments): float
    {
        return self::jacobiTheta($arguments, 1);
    }

    /** @param list<int|float> $arguments */
    private static function jacobiTheta2(array $arguments): float
    {
        return self::jacobiTheta($arguments, 2);
    }

    /** @param list<int|float> $arguments */
    private static function jacobiTheta3(array $arguments): float
    {
        return self::jacobiTheta($arguments, 3);
    }

    /** @param list<int|float> $arguments */
    private static function jacobiTheta4(array $arguments): float
    {
        return self::jacobiTheta($arguments, 4);
    }

    /** @param list<int|float> $arguments */
    private static function jacobiTheta(array $arguments, int $index): float
    {
        $argument = (float) $arguments[0];
        $nome = (float) $arguments[1];
        $function = 'jacobitheta' . $index;
        if (!is_finite($argument) || !is_finite($nome) || $nome < 0.0 || $nome >= 1.0) {
            throw new \DomainException($function . '() requires a finite argument and nome in [0, 1).');
        }
        if ($nome === 0.0) {
            return $index <= 2 ? 0.0 : 1.0;
        }

        $period = $index <= 2 ? 2.0 * M_PI : M_PI;
        $argument = fmod($argument, $period);
        $logNome = log($nome);
        $sum = $index >= 3 ? 1.0 : 0.0;
        $compensation = 0.0;
        for ($termIndex = 0; $termIndex < self::MAX_JACOBI_THETA_TERMS; ++$termIndex) {
            if ($index <= 2) {
                $halfIndex = $termIndex + 0.5;
                $exponent = $halfIndex * $halfIndex;
                $phase = (2.0 * $termIndex + 1.0) * $argument;
            } else {
                $integerIndex = $termIndex + 1.0;
                $exponent = $integerIndex * $integerIndex;
                $phase = 2.0 * $integerIndex * $argument;
            }

            $coefficient = 2.0 * exp($logNome * $exponent);
            $sign = ($index === 1 || $index === 4) && $termIndex % 2 !== 0 ? -1.0 : 1.0;
            if ($index === 4) {
                $sign = -$sign;
            }
            $wave = $index === 1 ? sin($phase) : cos($phase);
            $adjusted = $sign * $coefficient * $wave - $compensation;
            $updated = $sum + $adjusted;
            $compensation = ($updated - $sum) - $adjusted;
            $sum = $updated;

            $delta = $index <= 2 ? 2.0 * ($termIndex + 1.0) : 2.0 * ($termIndex + 1.0) + 1.0;
            $ratio = exp($logNome * $delta);
            if ($ratio < 1.0) {
                $nextCoefficient = $coefficient * $ratio;
                $tailBound = $nextCoefficient / (1.0 - $ratio);
                if ($tailBound <= 1.0E-16 * max(1.0, abs($sum))) {
                    return self::finiteSpecialResult($sum, $function);
                }
            }
        }

        throw new \OverflowException($function . '() series did not converge within the iteration limit.');
    }

    private static function ellipticNumericalE(float $parameter): float
    {
        $segments = 16384;
        $step = (M_PI / 2.0) / $segments;
        $sum = 1.0 + sqrt(1.0 - $parameter);
        for ($index = 1; $index < $segments; ++$index) {
            $angle = $index * $step;
            $weight = $index % 2 === 0 ? 2.0 : 4.0;
            $sum += $weight * sqrt(1.0 - $parameter * sin($angle) ** 2);
        }

        return $step * $sum / 3.0;
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticF(array $arguments): float
    {
        [$angle, $parameter] = self::requireIncompleteEllipticArguments($arguments, 'ellipf');
        return self::finiteSpecialResult(self::ellipticIncompleteIntegral($angle, $parameter, false), 'ellipf');
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticFDerivative(array $arguments): float
    {
        [$angle, $parameter] = self::requireIncompleteEllipticArguments($arguments, 'ellipfprime');
        $radicand = 1.0 - $parameter * sin($angle) ** 2;

        return self::finiteSpecialResult(1.0 / sqrt($radicand), 'ellipfprime');
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticE(array $arguments): float
    {
        [$angle, $parameter] = self::requireIncompleteEllipticArguments($arguments, 'ellipeinc');
        return self::finiteSpecialResult(self::ellipticIncompleteIntegral($angle, $parameter, true), 'ellipeinc');
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticEDerivative(array $arguments): float
    {
        [$angle, $parameter] = self::requireIncompleteEllipticArguments($arguments, 'ellipeincprime');

        return self::finiteSpecialResult(
            sqrt(1.0 - $parameter * sin($angle) ** 2),
            'ellipeincprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function completeEllipticPi(array $arguments): float
    {
        [$characteristic, $parameter] = self::requireCompleteEllipticPiArguments($arguments);
        return self::finiteSpecialResult(
            self::ellipticThirdIntegral(M_PI / 2.0, $characteristic, $parameter),
            'ellippi',
        );
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticPi(array $arguments): float
    {
        [$angle, $characteristic, $parameter] = self::requireIncompleteEllipticPiArguments($arguments);
        return self::finiteSpecialResult(
            self::ellipticThirdIntegral($angle, $characteristic, $parameter),
            'ellippinc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function incompleteEllipticPiDerivative(array $arguments): float
    {
        [$angle, $characteristic, $parameter] = self::requireIncompleteEllipticPiArguments($arguments);
        $sineSquared = sin($angle) ** 2;
        $radicand = 1.0 - $parameter * $sineSquared;
        $characteristicFactor = 1.0 - $characteristic * $sineSquared;

        return self::finiteSpecialResult(
            (1.0 / sqrt($radicand)) / $characteristicFactor,
            'ellippincprime',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function requireCompleteEllipticPiArguments(array $arguments): array
    {
        $characteristic = (float) $arguments[0];
        $parameter = (float) $arguments[1];
        if (!is_finite($characteristic) || !is_finite($parameter) || $characteristic >= 1.0 || $parameter >= 1.0) {
            throw new \DomainException(
                'ellippi() requires finite real characteristic n < 1 and parameter m < 1.',
            );
        }

        return [$characteristic, $parameter];
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function requireIncompleteEllipticPiArguments(array $arguments): array
    {
        $angle = (float) $arguments[0];
        $characteristic = (float) $arguments[1];
        $parameter = (float) $arguments[2];
        if (
            !is_finite($angle)
            || !is_finite($characteristic)
            || !is_finite($parameter)
            || $characteristic >= 1.0
            || $parameter > 1.0
        ) {
            throw new \DomainException(
                'ellippinc() requires finite angle and real characteristic n < 1 with parameter m <= 1.',
            );
        }
        if ($parameter === 1.0 && abs($angle) >= M_PI / 2.0) {
            throw new \DomainException('ellippinc() is singular at and beyond ±pi/2 when the parameter is one.');
        }

        return [$angle, $characteristic, $parameter];
    }

    private static function ellipticThirdIntegral(float $angle, float $characteristic, float $parameter): float
    {
        if ($angle === 0.0) {
            return 0.0;
        }
        $sign = $angle < 0.0 ? -1.0 : 1.0;
        $upper = abs($angle);
        $segments = max(1024, min(262144, (int) ceil($upper * 2048.0)));
        if ($segments % 2 !== 0) {
            ++$segments;
        }
        $step = $upper / $segments;
        $sum = 0.0;
        for ($index = 0; $index <= $segments; ++$index) {
            $position = $index * $step;
            $sineSquared = sin($position) ** 2;
            $factor = 1.0 - $parameter * $sineSquared;
            $value = 1.0 / ((1.0 - $characteristic * $sineSquared) * sqrt($factor));
            $weight = $index === 0 || $index === $segments ? 1.0 : ($index % 2 === 0 ? 2.0 : 4.0);
            $sum += $weight * $value;
        }

        return $sign * $step * $sum / 3.0;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function requireIncompleteEllipticArguments(array $arguments, string $function): array
    {
        $angle = (float) $arguments[0];
        $parameter = (float) $arguments[1];
        if (!is_finite($angle) || !is_finite($parameter) || $parameter > 1.0) {
            throw new \DomainException(
                $function . '() requires finite arguments with a real parameter less than or equal to one.',
            );
        }
        if ($parameter === 1.0 && abs($angle) >= M_PI / 2.0) {
            throw new \DomainException($function . '() is singular at ±pi/2 when the parameter is one.');
        }

        return [$angle, $parameter];
    }

    private static function ellipticIncompleteIntegral(float $angle, float $parameter, bool $secondKind): float
    {
        if ($angle === 0.0) {
            return 0.0;
        }
        $sign = $angle < 0.0 ? -1.0 : 1.0;
        $upper = abs($angle);
        $segments = max(1024, min(262144, (int) ceil($upper * 2048.0)));
        if ($segments % 2 !== 0) {
            ++$segments;
        }
        $step = $upper / $segments;
        $sum = 0.0;
        for ($index = 0; $index <= $segments; ++$index) {
            $position = $index * $step;
            $factor = 1.0 - $parameter * sin($position) ** 2;
            $value = $secondKind ? sqrt($factor) : 1.0 / sqrt($factor);
            $weight = $index === 0 || $index === $segments ? 1.0 : ($index % 2 === 0 ? 2.0 : 4.0);
            $sum += $weight * $value;
        }

        return $sign * $step * $sum / 3.0;
    }

    /** @param list<int|float> $arguments */
    private static function sinc(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('sinc() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        return sin($value) / $value;
    }

    /** @param list<int|float> $arguments */
    private static function sincDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sincprime');
        if (abs($value) < 1.0e-3) {
            $square = $value * $value;
            return $value * (-1.0 / 3.0 + $square * (1.0 / 30.0 - $square / 840.0));
        }

        return (cos($value) - sin($value) / $value) / $value;
    }

    /** @param list<int|float> $arguments */
    private static function sincSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sincsecond');
        if (abs($value) < 1.0e-3) {
            $square = $value * $value;
            return -1.0 / 3.0 + $square * (1.0 / 10.0 + $square * (-1.0 / 168.0 + $square / 6480.0));
        }

        return -sin($value) / $value - 2.0 * cos($value) / ($value * $value)
            + 2.0 * sin($value) / ($value * $value * $value);
    }

    /** @param list<int|float> $arguments */
    private static function normalizedSincDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sincpiprime');
        if ($value === 0.0) {
            return 0.0;
        }
        if (abs($value) < 1.0e-3) {
            $square = $value * $value;
            return M_PI * M_PI * $value
                * (-1.0 / 3.0 + M_PI * M_PI * $square * (1.0 / 30.0 - M_PI * M_PI * $square / 840.0));
        }
        $reduced = fmod($value, 2.0);
        if (floor($value) === $value) {
            return cos(M_PI * $reduced) / $value;
        }
        $angle = M_PI * $reduced;
        return cos($angle) / $value - (sin($angle) / M_PI) / ($value * $value);
    }

    /** @param list<int|float> $arguments */
    private static function normalizedSincSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sincpisecond');
        if ($value === 0.0) {
            return -M_PI * M_PI / 3.0;
        }
        if (abs($value) < 1.0e-3) {
            $square = $value * $value;
            $piSquare = M_PI * M_PI;
            return $piSquare * (-1.0 / 3.0 + $piSquare * $square
                * (1.0 / 10.0 + $piSquare * $square * (-1.0 / 168.0 + $piSquare * $square / 6480.0)));
        }
        $reduced = fmod($value, 2.0);
        $angle = M_PI * $reduced;
        if (floor($value) === $value) {
            return -2.0 * cos($angle) / ($value * $value);
        }
        return -M_PI * sin($angle) / $value - 2.0 * cos($angle) / ($value * $value)
            + (2.0 * sin($angle) / M_PI) / ($value * $value * $value);
    }

    /** @param list<int|float> $arguments */
    private static function requireFiniteSincArgument(array $arguments, string $function): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }

        return $value;
    }

    /** @param list<int|float> $arguments */
    private static function cosineQuotient(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('cosc() requires a finite argument.');
        }

        $halfSinc = self::sinc([$value / 2.0]);
        return 0.5 * $halfSinc * $halfSinc;
    }

    /** @param list<int|float> $arguments */
    private static function cosineQuotientDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'coscprime') / 2.0;

        return 0.5 * self::sinc([$value]) * self::sincDerivative([$value]);
    }

    /** @param list<int|float> $arguments */
    private static function cosineQuotientSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'coscsecond') / 2.0;
        $first = self::sincDerivative([$value]);

        return 0.25 * ($first * $first + self::sinc([$value]) * self::sincSecondDerivative([$value]));
    }

    /** @param list<int|float> $arguments */
    private static function normalizedCosineQuotient(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('coscpi() requires a finite argument.');
        }

        $halfSinc = self::normalizedSinc([$value / 2.0]);
        return 0.5 * $halfSinc * $halfSinc;
    }

    /** @param list<int|float> $arguments */
    private static function normalizedCosineQuotientDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'coscpiprime') / 2.0;

        return 0.5 * self::normalizedSinc([$value]) * self::normalizedSincDerivative([$value]);
    }

    /** @param list<int|float> $arguments */
    private static function normalizedCosineQuotientSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'coscpisecond') / 2.0;
        $first = self::normalizedSincDerivative([$value]);

        return 0.25 * (
            $first * $first + self::normalizedSinc([$value]) * self::normalizedSincSecondDerivative([$value])
        );
    }

    /** @param list<int|float> $arguments */
    private static function normalizedSinc(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('sincpi() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        if (floor($value) === $value) {
            return 0.0;
        }

        $reduced = \fmod($value, 2.0);
        if ($reduced === 0.0) {
            return 0.0;
        }

        if (\abs($value) < 1.0e-4) {
            $scaled = M_PI * $value;
            $square = $scaled * $scaled;

            return 1.0 - $square / 6.0 + $square * $square / 120.0;
        }

        return (\sin(M_PI * $reduced) / M_PI) / $value;
    }

    /** @param list<int|float> $arguments */
    private static function sinhc(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('sinhc() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(sinh($value) / $value, 'sinhc');
    }

    /** @param list<int|float> $arguments */
    private static function normalizedHyperbolicSinc(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('sinhcpi() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        $scaled = M_PI * $value;
        if (!is_finite($scaled)) {
            throw new \OverflowException('sinhcpi() result exceeds the finite floating-point range.');
        }
        if (abs($scaled) > log(PHP_FLOAT_MAX) + log(2.0)) {
            throw new \OverflowException('sinhcpi() result exceeds the finite floating-point range.');
        }
        if (abs($scaled) < 1.0e-4) {
            $square = $scaled * $scaled;
            return 1.0 + $square / 6.0 + $square * $square / 120.0;
        }

        return self::finiteSpecialResult(sinh($scaled) / $scaled, 'sinhcpi');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSincDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sinhcprime');
        return self::hyperbolicSincDerivativeValue($value, false, 'sinhcprime');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSincSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sinhcsecond');
        return self::hyperbolicSincDerivativeValue($value, true, 'sinhcsecond');
    }

    /** @param list<int|float> $arguments */
    private static function normalizedHyperbolicSincDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sinhcpiprime');
        $scaled = M_PI * $value;
        if (!is_finite($scaled)) {
            throw new \OverflowException('sinhcpiprime() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(
            M_PI * self::hyperbolicSincDerivativeValue($scaled, false, 'sinhcpiprime'),
            'sinhcpiprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function normalizedHyperbolicSincSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteSincArgument($arguments, 'sinhcpisecond');
        $scaled = M_PI * $value;
        if (!is_finite($scaled)) {
            throw new \OverflowException('sinhcpisecond() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(
            M_PI * M_PI * self::hyperbolicSincDerivativeValue($scaled, true, 'sinhcpisecond'),
            'sinhcpisecond',
        );
    }

    private static function hyperbolicSincDerivativeValue(float $value, bool $second, string $function): float
    {
        if (abs($value) < 1.0e-3) {
            $square = $value * $value;
            if ($second) {
                return 1.0 / 3.0 + $square * (1.0 / 10.0 + $square * (1.0 / 168.0 + $square / 6480.0));
            }

            return $value * (1.0 / 3.0 + $square * (1.0 / 30.0 + $square / 840.0));
        }

        $absolute = abs($value);
        if ($absolute <= 20.0) {
            if ($second) {
                return (sinh($value) * ($value * $value + 2.0) - 2.0 * $value * cosh($value))
                    / ($value * $value * $value);
            }

            return ($value * cosh($value) - sinh($value)) / ($value * $value);
        }

        $decay = exp(-2.0 * $absolute);
        if ($second) {
            $polynomial = $absolute * $absolute - 2.0 * $absolute + 2.0
                - ($absolute * $absolute + 2.0 * $absolute + 2.0) * $decay;
            $logMagnitude = $absolute - log(2.0) + log($polynomial) - 3.0 * log($absolute);
            $sign = 1.0;
        } else {
            $polynomial = $absolute - 1.0 + ($absolute + 1.0) * $decay;
            $logMagnitude = $absolute - log(2.0) + log($polynomial) - 2.0 * log($absolute);
            $sign = $value < 0.0 ? -1.0 : 1.0;
        }
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult($sign * exp($logMagnitude), $function);
    }

    /** @param list<int|float> $arguments */
    private static function exponentialRelative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('exprel() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        if (\abs($value) < 1.0e-5) {
            $sum = 1.0;
            $term = 1.0;
            for ($order = 1; $order <= 12; ++$order) {
                $term *= $value / ($order + 1);
                $sum += $term;
            }

            return $sum;
        }

        $logMaximum = \log(\PHP_FLOAT_MAX);
        if ($value > $logMaximum) {
            $logResult = $value - \log($value);
            if ($logResult > $logMaximum) {
                throw new \OverflowException('exprel() produced a non-finite result.');
            }

            return self::finiteSpecialResult(\exp($logResult), 'exprel');
        }

        return self::finiteSpecialResult(\expm1($value) / $value, 'exprel');
    }

    /** @param list<int|float> $arguments */
    private static function inverseExponentialRelative(array $arguments): float
    {
        $target = (float) $arguments[0];
        if (!is_finite($target) || $target <= 0.0) {
            throw new \DomainException('exprelinv() requires a finite positive argument.');
        }
        if ($target === 1.0) {
            return 0.0;
        }
        if ($target < 0.02) {
            $result = -1.0 / $target;
            if (!is_finite($result)) {
                throw new \OverflowException('exprelinv() result exceeds the finite floating-point range.');
            }

            return $result;
        }

        $logTarget = log($target);
        if ($target < 1.0) {
            $lower = -2.0 / $target;
            $upper = 0.0;
        } else {
            $lower = 0.0;
            $upper = max(1.0, $logTarget + log1p($logTarget) + 2.0);
        }

        for ($iteration = 0; $iteration < 128; ++$iteration) {
            $middle = $lower + ($upper - $lower) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::logExponentialRelativeValue($middle) < $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult($lower + ($upper - $lower) / 2.0, 'exprelinv');
    }

    private static function logExponentialRelativeValue(float $value): float
    {
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value > 50.0) {
            return $value - log($value) + log1p(-exp(-$value));
        }

        return log(expm1($value) / $value);
    }

    /** @param list<int|float> $arguments */
    private static function softplus(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('softplus() requires a finite argument.');
        }

        $result = $value > 0.0
            ? $value + \log1p(\exp(-$value))
            : \log1p(\exp($value));

        return self::finiteSpecialResult($result, 'softplus');
    }

    /** @param list<int|float> $arguments */
    private static function softplusDerivative(array $arguments): float
    {
        return self::sigmoid($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function softplusSecondDerivative(array $arguments): float
    {
        return self::sigmoidDerivative($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function inverseSoftplus(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('softplusinv() requires a finite argument greater than zero.');
        }

        $result = $value > 50.0
            ? $value + log1p(-exp(-$value))
            : log(expm1($value));

        return self::finiteSpecialResult($result, 'softplusinv');
    }

    /** @param list<int|float> $arguments */
    private static function sigmoid(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException('sigmoid() requires a finite argument.');
        }
        if ($value >= 0.0) {
            return 1.0 / (1.0 + exp(-$value));
        }

        $exponential = exp($value);

        return $exponential / (1.0 + $exponential);
    }

    /** @param list<int|float> $arguments */
    private static function sigmoidDerivative(array $arguments): float
    {
        $value = self::sigmoid($arguments);
        return self::finiteSpecialResult($value * (1.0 - $value), 'sigmoidprime');
    }

    /** @param list<int|float> $arguments */
    private static function sigmoidSecondDerivative(array $arguments): float
    {
        $value = self::sigmoid($arguments);
        return self::finiteSpecialResult(
            $value * (1.0 - $value) * (1.0 - 2.0 * $value),
            'sigmoidsecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseSigmoid(array $arguments): float
    {
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('sigmoidinv() requires a probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(log($probability) - log1p(-$probability), 'sigmoidinv');
    }

    /** @param list<int|float> $arguments */
    private static function logit(array $arguments): float
    {
        $probability = (float) $arguments[0];
        if (!\is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logit() requires a probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(\log($probability) - \log1p(-$probability), 'logit');
    }

    /** @param list<int|float> $arguments */
    private static function logitDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logitprime() requires a probability strictly between 0 and 1.');
        }
        $logDerivative = -log($probability) - log1p(-$probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('logitprime() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'logitprime');
    }

    /** @param list<int|float> $arguments */
    private static function logitSecondDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logitsecond() requires a probability strictly between 0 and 1.');
        }
        $numerator = 2.0 * $probability - 1.0;
        if ($numerator === 0.0) {
            return 0.0;
        }
        $logMagnitude = log(abs($numerator)) - 2.0 * log($probability) - 2.0 * log1p(-$probability);
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('logitsecond() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(
            ($numerator < 0.0 ? -1.0 : 1.0) * exp($logMagnitude),
            'logitsecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function gammaFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || ($value <= 0.0 && floor($value) === $value)) {
            throw new \DomainException('gamma() requires a finite non-pole argument.');
        }

        if ($value < 0.5) {
            $sine = self::sinePi($value);
            $logMagnitude = log(M_PI) - log(abs($sine)) - self::logGammaPositive(1.0 - $value);
            $sign = $sine < 0.0 ? -1.0 : 1.0;

            return self::finiteSpecialResult($sign * exp($logMagnitude), 'gamma');
        }

        return self::finiteSpecialResult(exp(self::logGammaPositive($value)), 'gamma');
    }

    /** @param list<int|float> $arguments */
    private static function confluentHypergeometric(array $arguments): float
    {
        [$a, $b, $z] = array_map(static fn (int|float $value): float => (float) $value, $arguments);
        if (!is_finite($a) || !is_finite($b) || !is_finite($z)) {
            throw new \DomainException('hyp1f1() requires finite real parameters.');
        }
        if ($b <= 0.0 && floor($b) === $b) {
            throw new \DomainException('hyp1f1() requires a second parameter that is not a non-positive integer.');
        }

        $terminating = $a <= 0.0 && floor($a) === $a;
        if ($z < 0.0 && !$terminating) {
            $factor = exp($z);
            $transformed = self::confluentHypergeometricSeries($b - $a, $b, -$z);

            return self::finiteSpecialResult($factor * $transformed, 'hyp1f1');
        }

        return self::finiteSpecialResult(self::confluentHypergeometricSeries($a, $b, $z), 'hyp1f1');
    }

    private static function confluentHypergeometricSeries(float $a, float $b, float $z): float
    {
        $sum = 1.0;
        $term = 1.0;
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $term *= (($a + $index - 1.0) * $z) / (($b + $index - 1.0) * $index);
            $sum += $term;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('hyp1f1() result exceeds the finite floating-point range.');
            }
            if ($term === 0.0 || abs($term) <= abs($sum) * 2.0e-16) {
                return $sum;
            }
        }

        throw new \OverflowException('hyp1f1() series did not converge within the supported iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function gaussHypergeometric(array $arguments): float
    {
        [$a, $b, $c, $x] = array_map(static fn (int|float $value): float => (float) $value, $arguments);
        if (!is_finite($a) || !is_finite($b) || !is_finite($c) || !is_finite($x)) {
            throw new \DomainException('hyp2f1() requires finite real parameters.');
        }
        if ($c <= 0.0 && floor($c) === $c) {
            throw new \DomainException('hyp2f1() requires a third parameter that is not a non-positive integer.');
        }

        $terminating = ($a <= 0.0 && floor($a) === $a) || ($b <= 0.0 && floor($b) === $b);
        if ($x > 1.0 && !$terminating) {
            throw new \DomainException(
                'hyp2f1() is real-valued only for arguments at most one in this implementation.',
            );
        }
        if ($x === 1.0 && !$terminating) {
            return self::finiteSpecialResult(self::gaussHypergeometricAtOne($a, $b, $c), 'hyp2f1');
        }
        if ($x < 0.0 && !$terminating) {
            $transformedX = $x / ($x - 1.0);
            $factor = exp(-$a * log1p(-$x));

            return self::finiteSpecialResult(
                $factor * self::gaussHypergeometricSeries($a, $c - $b, $c, $transformedX),
                'hyp2f1',
            );
        }

        return self::finiteSpecialResult(self::gaussHypergeometricSeries($a, $b, $c, $x), 'hyp2f1');
    }

    private static function gaussHypergeometricAtOne(float $a, float $b, float $c): float
    {
        $excess = $c - $a - $b;
        if ($excess <= 0.0) {
            throw new \DomainException('hyp2f1() at one requires c - a - b to be positive.');
        }
        foreach ([$c - $a, $c - $b] as $denominatorArgument) {
            if ($denominatorArgument <= 0.0 && floor($denominatorArgument) === $denominatorArgument) {
                throw new \DomainException('hyp2f1() at one has a singular Gauss summation denominator.');
            }
        }

        $logMagnitude = self::logGammaPositive($c)
            + self::logGammaPositive($excess)
            - self::logGammaFunction([$c - $a])
            - self::logGammaFunction([$c - $b]);
        $sign = self::gammaSign([$c - $a]) * self::gammaSign([$c - $b]);

        return $sign * exp($logMagnitude);
    }

    private static function gaussHypergeometricSeries(float $a, float $b, float $c, float $x): float
    {
        $sum = 1.0;
        $term = 1.0;
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $term *= (($a + $index - 1.0) * ($b + $index - 1.0) * $x)
                / (($c + $index - 1.0) * $index);
            $sum += $term;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('hyp2f1() result exceeds the finite floating-point range.');
            }
            if ($term === 0.0 || abs($term) <= abs($sum) * 2.0e-16) {
                return $sum;
            }
        }

        throw new \OverflowException('hyp2f1() series did not converge within the supported iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function confluentHypergeometricLimit(array $arguments): float
    {
        [$b, $z] = array_map(static fn (int|float $value): float => (float) $value, $arguments);
        if (!is_finite($b) || !is_finite($z)) {
            throw new \DomainException('hyp0f1() requires finite real parameters.');
        }
        if ($b <= 0.0 && floor($b) === $b) {
            throw new \DomainException('hyp0f1() requires a parameter that is not a non-positive integer.');
        }
        if ($z === 0.0) {
            return 1.0;
        }

        $sum = 1.0;
        $term = 1.0;
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $term *= $z / (($b + $index - 1.0) * $index);
            $sum += $term;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('hyp0f1() result exceeds the finite floating-point range.');
            }
            $pastPotentialSmallDenominators = $index > max(0.0, 1.0 - $b);
            if (
                $pastPotentialSmallDenominators
                && ($term === 0.0 || abs($term) <= abs($sum) * 2.0e-16)
            ) {
                return $sum;
            }
        }

        throw new \OverflowException('hyp0f1() series did not converge within the supported iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedHypergeometric3F2(array $arguments): float
    {
        [$a, $b, $c, $d, $e, $x] = array_map(static fn (int|float $value): float => (float) $value, $arguments);
        if (
            !is_finite($a) || !is_finite($b) || !is_finite($c)
            || !is_finite($d) || !is_finite($e) || !is_finite($x)
        ) {
            throw new \DomainException('hyp3f2() requires finite real parameters.');
        }
        foreach ([$d, $e] as $denominatorParameter) {
            if ($denominatorParameter <= 0.0 && floor($denominatorParameter) === $denominatorParameter) {
                throw new \DomainException('hyp3f2() denominator parameters must not be non-positive integers.');
            }
        }

        $terminating = ($a <= 0.0 && floor($a) === $a)
            || ($b <= 0.0 && floor($b) === $b)
            || ($c <= 0.0 && floor($c) === $c);
        $excess = $d + $e - $a - $b - $c;
        if (abs($x) > 1.0 && !$terminating) {
            throw new \DomainException('hyp3f2() requires |x| <= 1 unless the series terminates.');
        }
        if (abs($x) === 1.0 && !$terminating && $excess <= 0.0) {
            throw new \DomainException('hyp3f2() at |x| = 1 requires d + e - a - b - c to be positive.');
        }

        return self::finiteSpecialResult(self::generalizedHypergeometric3F2Series($a, $b, $c, $d, $e, $x), 'hyp3f2');
    }

    private static function generalizedHypergeometric3F2Series(
        float $a,
        float $b,
        float $c,
        float $d,
        float $e,
        float $x,
    ): float {
        $sum = 1.0;
        $term = 1.0;
        $tailStart = 2.0 * max(1.0, abs($a), abs($b), abs($c), abs($d), abs($e));
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $term *= (($a + $index - 1.0) * ($b + $index - 1.0) * ($c + $index - 1.0) * $x)
                / (($d + $index - 1.0) * ($e + $index - 1.0) * $index);
            $sum += $term;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('hyp3f2() result exceeds the finite floating-point range.');
            }
            if ($index >= $tailStart && ($term === 0.0 || abs($term) <= abs($sum) * 2.0e-16)) {
                return $sum;
            }
        }

        throw new \OverflowException('hyp3f2() series did not converge within the supported iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedHypergeometric(array $arguments): float
    {
        $numeratorCount = (float) $arguments[0];
        $denominatorCount = (float) $arguments[1];
        if (
            !is_finite($numeratorCount) || !is_finite($denominatorCount)
            || floor($numeratorCount) !== $numeratorCount || floor($denominatorCount) !== $denominatorCount
            || $numeratorCount < 0.0 || $denominatorCount < 0.0
        ) {
            throw new \DomainException('hypergeom() requires non-negative integer numerator and denominator counts.');
        }
        if (
            $numeratorCount + $denominatorCount > 13.0
            || (int) $numeratorCount + (int) $denominatorCount + 3 !== count($arguments)
        ) {
            throw new \DomainException('hypergeom() argument count must match its numerator and denominator counts.');
        }

        $p = (int) $numeratorCount;
        $q = (int) $denominatorCount;
        $numerator = array_map(static fn (int|float $value): float => (float) $value, array_slice($arguments, 2, $p));
        $denominator = array_map(
            static fn (int|float $value): float => (float) $value,
            array_slice($arguments, 2 + $p, $q),
        );
        $lastArgument = end($arguments);
        if ($lastArgument === false) {
            throw new \LogicException('hypergeom() requires a final evaluation argument.');
        }
        $x = (float) $lastArgument;
        foreach ([$x, ...$numerator, ...$denominator] as $parameter) {
            if (!is_finite($parameter)) {
                throw new \DomainException('hypergeom() requires finite real parameters.');
            }
        }
        foreach ($denominator as $parameter) {
            if ($parameter <= 0.0 && floor($parameter) === $parameter) {
                throw new \DomainException('hypergeom() denominator parameters must not be non-positive integers.');
            }
        }

        $terminating = false;
        foreach ($numerator as $parameter) {
            if ($parameter <= 0.0 && floor($parameter) === $parameter) {
                $terminating = true;
                break;
            }
        }
        if ($p > $q + 1 && !$terminating) {
            throw new \DomainException(
                'hypergeom() series diverges for p > q + 1 unless a numerator parameter terminates it.',
            );
        }
        if ($p === $q + 1 && !$terminating) {
            if (abs($x) > 1.0) {
                throw new \DomainException('hypergeom() requires |x| <= 1 when p = q + 1.');
            }
            if (abs($x) === 1.0 && array_sum($denominator) - array_sum($numerator) <= 0.0) {
                throw new \DomainException('hypergeom() at |x| = 1 requires positive parametric excess.');
            }
        }

        return self::finiteSpecialResult(
            self::generalizedHypergeometricSeries($numerator, $denominator, $x),
            'hypergeom',
        );
    }

    /**
     * @param list<float> $numerator
     * @param list<float> $denominator
     */
    private static function generalizedHypergeometricSeries(array $numerator, array $denominator, float $x): float
    {
        $sum = 1.0;
        $term = 1.0;
        $largestParameter = 1.0;
        foreach ([...$numerator, ...$denominator] as $parameter) {
            $largestParameter = max($largestParameter, abs($parameter));
        }
        $tailStart = 2.0 * $largestParameter;
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $ratio = $x / $index;
            foreach ($numerator as $parameter) {
                $ratio *= $parameter + $index - 1.0;
            }
            foreach ($denominator as $parameter) {
                $ratio /= $parameter + $index - 1.0;
            }
            $term *= $ratio;
            $sum += $term;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('hypergeom() result exceeds the finite floating-point range.');
            }
            if ($index >= $tailStart && ($term === 0.0 || abs($term) <= abs($sum) * 2.0e-16)) {
                return $sum;
            }
        }

        throw new \OverflowException('hypergeom() series did not converge within the supported iteration limit.');
    }

    private static function sinePi(float $value): float
    {
        $nearestInteger = \round($value);
        $fraction = $value - $nearestInteger;
        $sine = sin(M_PI * $fraction);

        return fmod(abs($nearestInteger), 2.0) === 0.0 ? $sine : -$sine;
    }

    /** @param list<int|float> $arguments */
    private static function logGammaFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || ($value <= 0.0 && floor($value) === $value)) {
            throw new \DomainException('lgamma() requires a finite non-pole argument.');
        }

        if ($value > 0.0) {
            return self::finiteSpecialResult(self::logGammaPositive($value), 'lgamma');
        }

        $sine = self::sinePi($value);
        $logMagnitude = log(M_PI) - log(abs($sine)) - self::logGammaPositive(1.0 - $value);

        return self::finiteSpecialResult($logMagnitude, 'lgamma');
    }

    /** @param list<int|float> $arguments */
    private static function gammaSign(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || ($value <= 0.0 && floor($value) === $value)) {
            throw new \DomainException('gammasign() requires a finite non-pole argument.');
        }
        if ($value > 0.0) {
            return 1.0;
        }

        return self::sinePi($value) < 0.0 ? -1.0 : 1.0;
    }

    /** @param list<int|float> $arguments */
    private static function regularizedGammaLower(array $arguments): float
    {
        [$shape, $value] = self::requireIncompleteGammaArguments($arguments);
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value >= $shape + 1.0) {
            return self::finiteSpecialResult(1.0 - self::regularizedGammaUpperValue($shape, $value), 'gammainc');
        }
        $term = 1.0 / $shape;
        $sum = $term;
        for ($index = 1; $index <= 10000; ++$index) {
            $term *= $value / ($shape + $index);
            $sum += $term;
            if (abs($term) <= abs($sum) * 1.0E-15) {
                break;
            }
        }
        $prefactor = exp(-$value + $shape * log($value) - self::logGammaPositive($shape));
        return self::finiteSpecialResult($prefactor * $sum, 'gammainc');
    }

    /** @param list<int|float> $arguments */
    private static function regularizedGammaUpper(array $arguments): float
    {
        [$shape, $value] = self::requireIncompleteGammaArguments($arguments);
        if ($value === 0.0) {
            return 1.0;
        }
        return self::finiteSpecialResult(self::regularizedGammaUpperValue($shape, $value), 'gammaincc');
    }

    /** @param list<int|float> $arguments */
    private static function logRegularizedGammaLower(array $arguments): float
    {
        [$shape, $value] = self::requireIncompleteGammaArguments($arguments);
        if ($value === 0.0) {
            throw new \DomainException('loggammainc() is singular at zero.');
        }

        return self::finiteSpecialResult(
            self::regularizedGammaLowerLogValue($shape, $value, log($value)),
            'loggammainc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logRegularizedGammaUpper(array $arguments): float
    {
        [$shape, $value] = self::requireIncompleteGammaArguments($arguments);
        if ($value === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(self::regularizedGammaUpperLogValue($shape, $value), 'loggammaincc');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaLower(array $arguments): float
    {
        [$shape, $target] = self::requireInverseGammaArguments($arguments, 'gammaincinv', false);
        if ($target === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::inverseRegularizedGammaValue($shape, $target),
            'gammaincinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaUpper(array $arguments): float
    {
        [$shape, $target] = self::requireInverseGammaArguments($arguments, 'gammainccinv', true);
        if ($target === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::inverseRegularizedGammaUpperValue($shape, $target),
            'gammainccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaLowerDerivative(array $arguments): float
    {
        [$shape, $probability] = self::requireInverseGammaDerivativeArguments($arguments, 'gammaincinvprime');
        $value = self::inverseRegularizedGammaValue($shape, $probability);

        return self::inverseRegularizedGammaDerivativeValue($shape, $value, 'gammaincinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaUpperDerivative(array $arguments): float
    {
        [$shape, $probability] = self::requireInverseGammaDerivativeArguments($arguments, 'gammainccinvprime');
        $value = self::inverseRegularizedGammaUpperValue($shape, $probability);

        return -self::inverseRegularizedGammaDerivativeValue($shape, $value, 'gammainccinvprime');
    }

    /** @param list<int|float> $arguments @return array{0: float, 1: float} */
    private static function requireInverseGammaDerivativeArguments(array $arguments, string $function): array
    {
        [$shape, $probability] = self::requireInverseGammaArguments(
            $arguments,
            $function,
            $function === 'gammainccinvprime',
        );
        if ($probability === 0.0 || $probability === 1.0) {
            throw new \DomainException($function . '() requires a probability strictly between zero and one.');
        }

        return [$shape, $probability];
    }

    private static function inverseRegularizedGammaDerivativeValue(
        float $shape,
        float $value,
        string $function,
    ): float {
        $logDerivative = $value - ($shape - 1.0) * log($value) + self::logGammaPositive($shape);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), $function);
    }

    /** @param list<int|float> $arguments */
    private static function lowerIncompleteGamma(array $arguments): float
    {
        [$shape, $value] = self::requireUnregularizedIncompleteGammaArguments($arguments, 'lowerincompletegamma');
        if ($value === 0.0) {
            return 0.0;
        }

        return self::exponentialIncompleteGammaResult(
            self::logLowerIncompleteGammaValue($shape, $value),
            'lowerincompletegamma',
        );
    }

    /** @param list<int|float> $arguments */
    private static function upperIncompleteGamma(array $arguments): float
    {
        [$shape, $value] = self::requireUnregularizedIncompleteGammaArguments($arguments, 'upperincompletegamma');
        return self::exponentialIncompleteGammaResult(
            self::logUpperIncompleteGammaValue($shape, $value),
            'upperincompletegamma',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logLowerIncompleteGamma(array $arguments): float
    {
        [$shape, $value] = self::requireUnregularizedIncompleteGammaArguments($arguments, 'loglowerincompletegamma');
        if ($value === 0.0) {
            throw new \DomainException('loglowerincompletegamma() is singular at zero.');
        }

        return self::logLowerIncompleteGammaValue($shape, $value);
    }

    /** @param list<int|float> $arguments */
    private static function logUpperIncompleteGamma(array $arguments): float
    {
        [$shape, $value] = self::requireUnregularizedIncompleteGammaArguments($arguments, 'logupperincompletegamma');
        return self::logUpperIncompleteGammaValue($shape, $value);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function requireUnregularizedIncompleteGammaArguments(array $arguments, string $function): array
    {
        $shape = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (
            !is_finite($shape)
            || $shape <= 0.0
            || $shape > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($value)
            || $value < 0.0
        ) {
            throw new \DomainException(
                $function . '() requires a finite shape in (0, 10000] and a non-negative finite value.',
            );
        }

        return [$shape, $value];
    }

    private static function logLowerIncompleteGammaValue(float $shape, float $value): float
    {
        return self::finiteSpecialResult(
            self::logGammaPositive($shape)
                + self::regularizedGammaLowerLogValue($shape, $value, log($value)),
            'loglowerincompletegamma',
        );
    }

    private static function logUpperIncompleteGammaValue(float $shape, float $value): float
    {
        $logRegularizedValue = $value === 0.0
            ? 0.0
            : self::regularizedGammaUpperLogValue($shape, $value);
        return self::finiteSpecialResult(
            self::logGammaPositive($shape) + $logRegularizedValue,
            'logupperincompletegamma',
        );
    }

    private static function exponentialIncompleteGammaResult(float $logValue, string $function): float
    {
        if ($logValue > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() result exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logValue), $function);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function requireIncompleteGammaArguments(array $arguments): array
    {
        $shape = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (
            !is_finite($shape)
            || $shape <= 0.0
            || $shape > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($value)
            || $value < 0.0
        ) {
            throw new \DomainException(
                'gammainc() and gammaincc() require a finite shape in (0, 10000] and a non-negative value.',
            );
        }

        return [$shape, $value];
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function requireInverseGammaArguments(array $arguments, string $function, bool $upper): array
    {
        $shape = (float) $arguments[0];
        $target = (float) $arguments[1];
        $validTarget = $upper ? $target > 0.0 && $target <= 1.0 : $target >= 0.0 && $target < 1.0;
        $range = $upper ? '(0, 1]' : '[0, 1)';
        if (
            !is_finite($shape)
            || $shape <= 0.0
            || $shape > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($target)
            || !$validTarget
        ) {
            throw new \DomainException(
                $function . '() requires a finite shape in (0, 10000] and a probability in ' . $range . '.',
            );
        }

        return [$shape, $target];
    }

    private static function inverseRegularizedGammaValue(float $shape, float $target): float
    {
        $lower = 0.0;
        $upper = max(1.0, $shape);
        if ($shape < 1.0 && $target < 0.1) {
            $logEstimate = (log($target) + self::logGammaPositive($shape + 1.0)) / $shape;
            $estimate = exp($logEstimate);
            if ($estimate === 0.0) {
                return 0.0;
            }

            $upper = $estimate * 2.0;
            for ($index = 0; $index < 64; ++$index) {
                if (self::regularizedGammaLower([$shape, $upper]) >= $target) {
                    break;
                }
                $upper *= 2.0;
                if ($upper >= 1048576.0) {
                    throw new \OverflowException('The gamma quantile exceeds the finite search range.');
                }
            }
        } else {
            for ($index = 0; $index < 64; ++$index) {
                if (self::regularizedGammaLower([$shape, $upper]) >= $target) {
                    break;
                }
                $upper *= 2.0;
                if ($upper >= 1048576.0) {
                    throw new \OverflowException('The gamma quantile exceeds the finite search range.');
                }
            }
        }
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedGammaLower([$shape, $middle]) < $target) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return ($lower + $upper) / 2.0;
    }

    private static function inverseRegularizedGammaUpperValue(float $shape, float $target): float
    {
        if ($target === 1.0) {
            return 0.0;
        }

        $logTarget = log($target);
        $lower = 0.0;
        $upper = max(1.0, $shape);
        for ($index = 0; $index < 64; ++$index) {
            if (self::regularizedGammaUpperLogValue($shape, $upper) <= $logTarget) {
                break;
            }
            $upper *= 2.0;
            if ($upper >= 1048576.0) {
                throw new \OverflowException('The gamma quantile exceeds the finite search range.');
            }
        }
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedGammaUpperLogValue($shape, $middle) > $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return ($lower + $upper) / 2.0;
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaLowerLog(array $arguments): float
    {
        [$shape, $logTarget] = self::requireInverseGammaLogArguments($arguments, 'gammaincinvlog');
        if ($logTarget === 0.0) {
            throw new \DomainException('gammaincinvlog() requires a negative log probability.');
        }
        $logEstimate = ($logTarget + self::logGammaPositive($shape + 1.0)) / $shape;
        $estimate = exp($logEstimate);
        if ($estimate === 0.0) {
            return 0.0;
        }

        $lower = 0.0;
        $upper = max($estimate * 2.0, PHP_FLOAT_MIN);
        for ($index = 0; $index < 64; ++$index) {
            if (self::regularizedGammaLowerLogValue($shape, $upper, log($upper)) >= $logTarget) {
                break;
            }
            $upper *= 2.0;
        }
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedGammaLowerLogValue($shape, $middle, log($middle)) < $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(($lower + $upper) / 2.0, 'gammaincinvlog');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedGammaUpperLog(array $arguments): float
    {
        [$shape, $logTarget] = self::requireInverseGammaLogArguments($arguments, 'gammainccinvlog');
        if ($logTarget === 0.0) {
            return 0.0;
        }
        $lower = 0.0;
        $upper = max(1.0, $shape);
        for ($index = 0; $index < 64; ++$index) {
            if (self::regularizedGammaUpperLogValue($shape, $upper) <= $logTarget) {
                break;
            }
            $upper *= 2.0;
            if (!is_finite($upper) || $upper >= 1048576.0) {
                throw new \OverflowException('gammainccinvlog() quantile exceeds the finite search range.');
            }
        }
        if (self::regularizedGammaUpperLogValue($shape, $upper) > $logTarget) {
            throw new \OverflowException('gammainccinvlog() quantile exceeds the finite search range.');
        }
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedGammaUpperLogValue($shape, $middle) > $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(($lower + $upper) / 2.0, 'gammainccinvlog');
    }

    /** @param list<int|float> $arguments @return array{0: float, 1: float} */
    private static function requireInverseGammaLogArguments(array $arguments, string $function): array
    {
        $shape = (float) $arguments[0];
        $logProbability = (float) $arguments[1];
        if (
            !is_finite($shape)
            || $shape <= 0.0
            || $shape > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($logProbability)
            || $logProbability > 0.0
        ) {
            throw new \DomainException(
                $function . '() requires a finite shape in (0, 10000] and a finite log probability '
                . 'no greater than zero.',
            );
        }

        return [$shape, $logProbability];
    }

    private static function regularizedGammaUpperValue(float $shape, float $value): float
    {
        if ($value < $shape + 1.0) {
            return 1.0 - self::regularizedGammaLower([$shape, $value]);
        }

        return exp(self::regularizedGammaUpperLogContinuedFraction($shape, $value));
    }

    private static function regularizedGammaUpperLogValue(float $shape, float $value): float
    {
        if ($value < $shape + 1.0) {
            return log(1.0 - self::regularizedGammaLower([$shape, $value]));
        }

        return self::regularizedGammaUpperLogContinuedFraction($shape, $value);
    }

    private static function regularizedGammaUpperLogContinuedFraction(float $shape, float $value): float
    {
        $fpmIn = 1.0E-300;
        $b = $value + 1.0 - $shape;
        $c = 1.0 / $fpmIn;
        $d = 1.0 / max($b, $fpmIn);
        $h = $d;
        for ($index = 1; $index <= 10000; ++$index) {
            $an = -$index * ($index - $shape);
            $b += 2.0;
            $d = $an * $d + $b;
            if (abs($d) < $fpmIn) {
                $d = $fpmIn;
            }
            $c = $b + $an / $c;
            if (abs($c) < $fpmIn) {
                $c = $fpmIn;
            }
            $d = 1.0 / $d;
            $delta = $d * $c;
            $h *= $delta;
            if (abs($delta - 1.0) <= 1.0E-15) {
                break;
            }
        }
        if (!is_finite($h) || $h <= 0.0) {
            throw new \OverflowException('The incomplete gamma continued fraction did not converge.');
        }

        return -$value + $shape * log($value) - self::logGammaPositive($shape) + log($h);
    }

    private static function logGammaPositive(float $value): float
    {
        $coefficients = [
            676.5203681218851,
            -1259.1392167224028,
            771.32342877765313,
            -176.61502916214059,
            12.507343278686905,
            -0.13857109526572012,
            9.9843695780195716e-6,
            1.5056327351493116e-7,
        ];
        $shifted = $value - 1.0;
        $sum = 0.99999999999980993;
        foreach ($coefficients as $index => $coefficient) {
            $sum += $coefficient / ($shifted + $index + 1.0);
        }
        $base = $shifted + 7.5;

        return 0.5 * log(2.0 * M_PI)
            + ($shifted + 0.5) * log($base)
            - $base
            + log($sum);
    }

    /** @param list<int|float> $arguments */
    private static function regularizedBetaLower(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value === 1.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            self::regularizedBetaValue($left, $right, $value),
            'betainc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function regularizedBetaUpper(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 0.0) {
            return 1.0;
        }
        if ($value === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::regularizedBetaUpperValue($left, $right, $value),
            'betaincc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logRegularizedBetaLower(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 0.0) {
            throw new \DomainException('logbetainc() is singular at zero.');
        }
        if ($value === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::regularizedBetaLogLowerValue($left, $right, $value),
            'logbetainc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logRegularizedBetaUpper(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 1.0) {
            throw new \DomainException('logbetaincc() is singular at one.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::regularizedBetaLogLowerFromLogs($right, $left, log1p(-$value), log($value)),
            'logbetaincc',
        );
    }

    /** @param list<int|float> $arguments */
    private static function lowerIncompleteBeta(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value === 1.0) {
            return self::finiteSpecialResult(exp(self::logBetaFunction([$left, $right])), 'lowerincompletebeta');
        }

        $logValue = self::logBetaFunction([$left, $right])
            + self::regularizedBetaLogLowerValue($left, $right, $value);

        return self::finiteSpecialResult(exp($logValue), 'lowerincompletebeta');
    }

    /** @param list<int|float> $arguments */
    private static function upperIncompleteBeta(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 1.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            return self::finiteSpecialResult(exp(self::logBetaFunction([$left, $right])), 'upperincompletebeta');
        }

        $logValue = self::logBetaFunction([$left, $right])
            + self::regularizedBetaLogLowerFromLogs($right, $left, log1p(-$value), log($value));

        return self::finiteSpecialResult(exp($logValue), 'upperincompletebeta');
    }

    /** @param list<int|float> $arguments */
    private static function logLowerIncompleteBeta(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 0.0) {
            throw new \DomainException('loglowerincompletebeta() is singular at zero.');
        }
        if ($value === 1.0) {
            return self::finiteSpecialResult(self::logBetaFunction([$left, $right]), 'loglowerincompletebeta');
        }

        return self::finiteSpecialResult(
            self::logBetaFunction([$left, $right]) + self::regularizedBetaLogLowerValue($left, $right, $value),
            'loglowerincompletebeta',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logUpperIncompleteBeta(array $arguments): float
    {
        [$left, $right, $value] = self::requireIncompleteBetaArguments($arguments);
        if ($value === 1.0) {
            throw new \DomainException('logupperincompletebeta() is singular at one.');
        }
        if ($value === 0.0) {
            return self::finiteSpecialResult(self::logBetaFunction([$left, $right]), 'logupperincompletebeta');
        }

        return self::finiteSpecialResult(
            self::logBetaFunction([$left, $right])
            + self::regularizedBetaLogLowerFromLogs($right, $left, log1p(-$value), log($value)),
            'logupperincompletebeta',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaLower(array $arguments): float
    {
        [$left, $right, $target] = self::requireInverseBetaArguments($arguments, 'betaincinv');
        return self::finiteSpecialResult(
            self::inverseRegularizedBetaValue($left, $right, $target),
            'betaincinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaLowerLog(array $arguments): float
    {
        [$leftShape, $rightShape, $logTarget] = self::requireInverseBetaLogArguments($arguments, 'betaincinvlog');
        if ($logTarget === 0.0) {
            return 1.0;
        }

        $logEstimate = ($logTarget + log($leftShape) + self::logBetaFunction([$leftShape, $rightShape])) / $leftShape;
        $estimate = exp($logEstimate);
        if ($estimate === 0.0) {
            return 0.0;
        }
        $lower = 0.0;
        $upper = min(1.0, $estimate * 2.0);
        for ($index = 0; $index < 64; ++$index) {
            if ($upper === 1.0 || self::regularizedBetaLogLowerValue($leftShape, $rightShape, $upper) >= $logTarget) {
                break;
            }
            $upper = min(1.0, $upper * 2.0);
        }
        for ($index = 0; $index < 180; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedBetaLogLowerValue($leftShape, $rightShape, $middle) < $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(($lower + $upper) / 2.0, 'betaincinvlog');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaUpperLog(array $arguments): float
    {
        [$leftShape, $rightShape, $logTarget] = self::requireInverseBetaLogArguments($arguments, 'betainccinvlog');
        if ($logTarget === 0.0) {
            return 0.0;
        }

        $logEstimate = ($logTarget + log($rightShape) + self::logBetaFunction([$leftShape, $rightShape])) / $rightShape;
        $estimate = exp($logEstimate);
        if ($estimate === 0.0) {
            return 1.0;
        }
        $lower = 0.0;
        $upper = min(1.0, $estimate * 2.0);
        for ($index = 0; $index < 64; ++$index) {
            if ($upper === 1.0 || self::regularizedBetaLogLowerValue($rightShape, $leftShape, $upper) >= $logTarget) {
                break;
            }
            $upper = min(1.0, $upper * 2.0);
        }
        for ($index = 0; $index < 180; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedBetaLogLowerValue($rightShape, $leftShape, $middle) < $logTarget) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return self::finiteSpecialResult(1.0 - ($lower + $upper) / 2.0, 'betainccinvlog');
    }

    /** @param list<int|float> $arguments @return array{0: float, 1: float, 2: float} */
    private static function requireInverseBetaLogArguments(array $arguments, string $function): array
    {
        $leftShape = (float) $arguments[0];
        $rightShape = (float) $arguments[1];
        $logProbability = (float) $arguments[2];
        self::requireIncompleteBetaArguments([$leftShape, $rightShape, 0.0]);
        if (!is_finite($logProbability) || $logProbability > 0.0) {
            throw new \DomainException($function . '() requires a finite log probability no greater than zero.');
        }

        return [$leftShape, $rightShape, $logProbability];
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaUpper(array $arguments): float
    {
        [$left, $right, $target] = self::requireInverseBetaArguments($arguments, 'betainccinv');
        return self::finiteSpecialResult(
            self::inverseRegularizedBetaUpperValue($left, $right, $target),
            'betainccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaLowerDerivative(array $arguments): float
    {
        [$left, $right, $probability] = self::requireInverseBetaDerivativeArguments($arguments, 'betaincinvprime');
        $value = self::inverseRegularizedBetaValue($left, $right, $probability);

        return self::inverseRegularizedBetaDerivativeValue($left, $right, $value, 'betaincinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRegularizedBetaUpperDerivative(array $arguments): float
    {
        [$left, $right, $probability] = self::requireInverseBetaDerivativeArguments($arguments, 'betainccinvprime');
        $value = self::inverseRegularizedBetaUpperValue($left, $right, $probability);

        return -self::inverseRegularizedBetaDerivativeValue($left, $right, $value, 'betainccinvprime');
    }

    /** @param list<int|float> $arguments @return array{0: float, 1: float, 2: float} */
    private static function requireInverseBetaDerivativeArguments(array $arguments, string $function): array
    {
        [$left, $right, $probability] = self::requireInverseBetaArguments($arguments, $function);
        if ($probability === 0.0 || $probability === 1.0) {
            throw new \DomainException($function . '() requires a probability strictly between zero and one.');
        }

        return [$left, $right, $probability];
    }

    private static function inverseRegularizedBetaDerivativeValue(
        float $left,
        float $right,
        float $value,
        string $function,
    ): float {
        if ($value === 0.0) {
            if ($left < 1.0) {
                return 0.0;
            }
            if ($left > 1.0) {
                throw new \OverflowException($function . '() derivative exceeds the finite floating-point range.');
            }
            return self::finiteSpecialResult(exp(self::logBetaFunction([$left, $right])), $function);
        }
        if ($value === 1.0) {
            if ($right < 1.0) {
                return 0.0;
            }
            if ($right > 1.0) {
                throw new \OverflowException($function . '() derivative exceeds the finite floating-point range.');
            }
            return self::finiteSpecialResult(exp(self::logBetaFunction([$left, $right])), $function);
        }

        $logDerivative = self::logBetaFunction([$left, $right])
            - ($left - 1.0) * log($value)
            - ($right - 1.0) * log1p(-$value);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() derivative exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), $function);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function requireIncompleteBetaArguments(array $arguments): array
    {
        $left = (float) $arguments[0];
        $right = (float) $arguments[1];
        $value = (float) $arguments[2];
        if (
            !is_finite($left)
            || !is_finite($right)
            || $left <= 0.0
            || $right <= 0.0
            || $left > self::MAX_DISTRIBUTION_SHAPE
            || $right > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($left + $right)
            || $left + $right > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($value)
            || $value < 0.0
            || $value > 1.0
        ) {
            throw new \DomainException(
                'betainc() and betaincc() require finite positive shapes with a sum in (0, 10000] '
                . 'and a value in [0, 1].',
            );
        }

        return [$left, $right, $value];
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function requireInverseBetaArguments(array $arguments, string $function): array
    {
        $left = (float) $arguments[0];
        $right = (float) $arguments[1];
        $target = (float) $arguments[2];
        if (
            !is_finite($left)
            || !is_finite($right)
            || $left <= 0.0
            || $right <= 0.0
            || $left > self::MAX_DISTRIBUTION_SHAPE
            || $right > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($left + $right)
            || $left + $right > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($target)
            || $target < 0.0
            || $target > 1.0
        ) {
            throw new \DomainException(
                $function . '() requires finite positive shapes with a sum in (0, 10000] and a probability in [0, 1].',
            );
        }

        return [$left, $right, $target];
    }

    private static function inverseRegularizedBetaValue(float $left, float $right, float $target): float
    {
        if ($target === 0.0) {
            return 0.0;
        }
        if ($target === 1.0) {
            return 1.0;
        }

        $lower = 0.0;
        $upper = 1.0;
        if ($left < 1.0 && $target < 0.1) {
            $logBeta = self::logGammaPositive($left)
                + self::logGammaPositive($right)
                - self::logGammaPositive($left + $right);
            $logEstimate = (log($target) + log($left) + $logBeta) / $left;
            $estimate = exp($logEstimate);
            if ($estimate === 0.0) {
                return 0.0;
            }

            $upper = min(1.0, $estimate * 2.0);
            for ($index = 0; $index < 64; ++$index) {
                if (self::regularizedBetaValue($left, $right, $upper) >= $target) {
                    break;
                }
                $upper = min(1.0, $upper * 2.0);
            }
        }
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedBetaValue($left, $right, $middle) < $target) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return ($lower + $upper) / 2.0;
    }

    private static function inverseRegularizedBetaUpperValue(float $left, float $right, float $target): float
    {
        if ($target === 0.0) {
            return 1.0;
        }
        if ($target === 1.0) {
            return 0.0;
        }

        $lower = 0.0;
        $upper = 1.0;
        for ($index = 0; $index < 160; ++$index) {
            $middle = ($lower + $upper) / 2.0;
            if ($middle === $lower || $middle === $upper) {
                break;
            }
            if (self::regularizedBetaUpperValue($left, $right, $middle) > $target) {
                $lower = $middle;
            } else {
                $upper = $middle;
            }
        }

        return ($lower + $upper) / 2.0;
    }

    private static function regularizedBetaValue(float $left, float $right, float $value): float
    {
        $threshold = ($left + 1.0) / ($left + $right + 2.0);
        if ($value <= $threshold) {
            $factor = self::incompleteBetaFactor($left, $right, $value);
            return $factor * self::incompleteBetaContinuedFraction($left, $right, $value) / $left;
        }

        $factor = self::incompleteBetaFactor($right, $left, 1.0 - $value);
        return 1.0 - $factor * self::incompleteBetaContinuedFraction($right, $left, 1.0 - $value) / $right;
    }

    private static function regularizedBetaUpperValue(float $left, float $right, float $value): float
    {
        return self::regularizedBetaValue($right, $left, 1.0 - $value);
    }

    private static function regularizedBetaLogLowerValue(float $left, float $right, float $value): float
    {
        if ($value <= 0.0 || $value >= 1.0) {
            throw new \DomainException('A finite log incomplete-beta probability requires x in (0, 1).');
        }

        return self::regularizedBetaLogLowerFromLogs($left, $right, log($value), log1p(-$value));
    }

    private static function regularizedBetaLogLowerFromLogs(
        float $left,
        float $right,
        float $logValue,
        float $logComplement,
    ): float {
        $threshold = ($left + 1.0) / ($left + $right + 2.0);
        if ($logValue > log($threshold)) {
            return self::logOneMinusExponential([
                self::regularizedBetaLogLowerFromLogs($right, $left, $logComplement, $logValue),
            ]);
        }

        $logFactor = self::logGammaPositive($left + $right)
            - self::logGammaPositive($left)
            - self::logGammaPositive($right)
            + $left * $logValue
            + $right * $logComplement;

        return self::finiteSpecialResult(
            $logFactor + log(self::incompleteBetaContinuedFraction($left, $right, exp($logValue))) - log($left),
            'betalogcdf',
        );
    }

    private static function incompleteBetaFactor(float $left, float $right, float $value): float
    {
        return exp(
            self::logGammaPositive($left + $right)
            - self::logGammaPositive($left)
            - self::logGammaPositive($right)
            + $left * log($value)
            + $right * log1p(-$value),
        );
    }

    private static function incompleteBetaContinuedFraction(float $left, float $right, float $value): float
    {
        $fpmIn = 1.0E-300;
        $continued = 1.0;
        $c = 1.0;
        $d = 1.0 - ($left + $right) * $value / ($left + 1.0);
        if (abs($d) < $fpmIn) {
            $d = $fpmIn;
        }
        $d = 1.0 / $d;
        $continued = $d;
        for ($index = 1; $index <= 10000; ++$index) {
            $step = 2.0 * $index;
            $numerator = $index * ($right - $index) * $value
                / (($left + $step - 1.0) * ($left + $step));
            $d = 1.0 + $numerator * $d;
            if (abs($d) < $fpmIn) {
                $d = $fpmIn;
            }
            $c = 1.0 + $numerator / $c;
            if (abs($c) < $fpmIn) {
                $c = $fpmIn;
            }
            $d = 1.0 / $d;
            $delta = $d * $c;
            $continued *= $delta;

            $numerator = -($left + $index) * ($left + $right + $index) * $value
                / (($left + $step) * ($left + $step + 1.0));
            $d = 1.0 + $numerator * $d;
            if (abs($d) < $fpmIn) {
                $d = $fpmIn;
            }
            $c = 1.0 + $numerator / $c;
            if (abs($c) < $fpmIn) {
                $c = $fpmIn;
            }
            $d = 1.0 / $d;
            $delta = $d * $c;
            $continued *= $delta;
            if (abs($delta - 1.0) <= 1.0E-15) {
                break;
            }
        }

        return $continued;
    }

    /** @param list<int|float> $arguments */
    private static function betaFunction(array $arguments): float
    {
        self::requirePositiveBetaArguments($arguments);
        $logValue = self::logBetaFunction($arguments);

        return self::finiteSpecialResult(exp($logValue), 'beta');
    }

    /** @param list<int|float> $arguments */
    private static function logBetaFunction(array $arguments): float
    {
        self::requirePositiveBetaArguments($arguments);
        $leftArgument = (float) $arguments[0];
        $rightArgument = (float) $arguments[1];
        $sumArgument = $leftArgument + $rightArgument;
        if (!is_finite($sumArgument)) {
            throw new \DomainException('logbeta() requires a finite sum of arguments.');
        }
        $left = self::logGammaPositive($leftArgument);
        $right = self::logGammaPositive($rightArgument);
        $sum = self::logGammaPositive($sumArgument);
        $value = $left + $right - $sum;

        return self::finiteSpecialResult($value, 'logbeta');
    }

    /** @param list<int|float> $arguments */
    private static function requirePositiveBetaArguments(array $arguments): void
    {
        if (
            !is_finite((float) $arguments[0])
            || !is_finite((float) $arguments[1])
            || $arguments[0] <= 0
            || $arguments[1] <= 0
        ) {
            throw new \DomainException('beta() and logbeta() require two finite positive arguments.');
        }
    }

    /** @param list<int|float> $arguments */
    private static function hurwitzZetaFunction(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        $offset = (float) $arguments[1];
        if (!is_finite($exponent) || $exponent === 1.0 || !is_finite($offset) || $offset <= 0.0) {
            throw new \DomainException('hurwitzzeta() requires a finite exponent other than one and positive offset.');
        }
        if ($exponent < 1.0) {
            if ($exponent <= 0.0 && floor($exponent) === $exponent && $exponent >= -31.0) {
                $degree = (int) (1.0 - $exponent);

                return self::finiteSpecialResult(
                    -self::bernoulliPolynomial([$degree, $offset]) / $degree,
                    'hurwitzzeta',
                );
            }

            return self::hurwitzZetaAnalyticContinuation($exponent, $offset);
        }

        // Keep the Euler–Maclaurin expansion in its stable range when s is moderate.
        // For very large s, the omitted tail after 32 terms is below floating-point
        // significance, while the initial terms contain the meaningful mass.
        $limit = $exponent < 500.0 ? max(32, (int) ceil(2.0 * $exponent - $offset)) : 32;
        $sum = 0.0;
        for ($index = 0; $index < $limit; ++$index) {
            $logTerm = -$exponent * log($offset + $index);
            $sum += exp($logTerm);
        }

        $endpoint = $offset + $limit;
        $logEndpoint = log($endpoint);
        $tail = exp((1.0 - $exponent) * $logEndpoint - log($exponent - 1.0))
            + 0.5 * exp(-$exponent * $logEndpoint);
        $bernoulliOverFactorial = [
            1.0 / 12.0,
            -1.0 / 720.0,
            1.0 / 30240.0,
            -1.0 / 1209600.0,
            1.0 / 47900160.0,
            -691.0 / 1307674368000.0,
            7.0 / 523069747200.0,
            -3617.0 / 10670622842880000.0,
        ];
        $correction = 0.0;
        foreach ($bernoulliOverFactorial as $index => $coefficient) {
            $order = 2 * $index + 1;
            $logRisingFactorial = 0.0;
            for ($factor = 0; $factor < $order; ++$factor) {
                $logRisingFactorial += log($exponent + $factor);
            }
            $logMagnitude = log(abs($coefficient)) + $logRisingFactorial
                - ($exponent + $order) * $logEndpoint;
            $correction += ($coefficient < 0.0 ? -1.0 : 1.0) * exp($logMagnitude);
        }

        return self::finiteSpecialResult($sum + $tail + $correction, 'hurwitzzeta');
    }

    private static function hurwitzZetaAnalyticContinuation(float $exponent, float $offset): float
    {
        if (abs($exponent) > 500.0) {
            throw new \OverflowException('hurwitzzeta() analytic continuation exceeds the supported exponent range.');
        }
        $limit = max(64, (int) ceil(2.0 * abs($exponent) + 16.0 - $offset));
        $sum = 0.0;
        for ($index = 0; $index < $limit; ++$index) {
            $logTerm = -$exponent * log($offset + $index);
            if ($logTerm > log(PHP_FLOAT_MAX)) {
                throw new \OverflowException('hurwitzzeta() result exceeds the finite floating-point range.');
            }
            $sum += exp($logTerm);
        }

        $endpoint = $offset + $limit;
        $logEndpoint = log($endpoint);
        $tailLogMagnitude = (1.0 - $exponent) * $logEndpoint - log(abs($exponent - 1.0));
        if ($tailLogMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('hurwitzzeta() result exceeds the finite floating-point range.');
        }
        $tail = ($exponent < 1.0 ? -1.0 : 1.0) * exp($tailLogMagnitude);
        $halfTerm = exp(-$exponent * $logEndpoint) / 2.0;
        $coefficients = [
            1.0 / 12.0,
            -1.0 / 720.0,
            1.0 / 30240.0,
            -1.0 / 1209600.0,
            1.0 / 47900160.0,
            -691.0 / 1307674368000.0,
            7.0 / 523069747200.0,
            -3617.0 / 10670622842880000.0,
        ];
        $correction = 0.0;
        foreach ($coefficients as $index => $coefficient) {
            $order = 2 * $index + 1;
            $logMagnitude = log(abs($coefficient));
            $sign = $coefficient < 0.0 ? -1.0 : 1.0;
            for ($factor = 0; $factor < $order; ++$factor) {
                $risingFactor = $exponent + $factor;
                if ($risingFactor === 0.0) {
                    $sign = 0.0;
                    break;
                }
                if ($risingFactor < 0.0) {
                    $sign = -$sign;
                }
                $logMagnitude += log(abs($risingFactor));
            }
            if ($sign !== 0.0) {
                $logMagnitude -= ($exponent + $order) * $logEndpoint;
                $correction += $sign * exp($logMagnitude);
            }
        }

        return self::finiteSpecialResult($sum + $tail + $halfTerm + $correction, 'hurwitzzeta');
    }

    /** @param list<int|float> $arguments */
    private static function zetaFunction(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if (!is_finite($exponent) || $exponent === 1.0) {
            throw new \DomainException('zeta() requires a finite real argument other than its pole at one.');
        }
        if ($exponent === 0.0) {
            return -0.5;
        }
        if ($exponent <= -1.0) {
            if (floor($exponent) === $exponent && fmod(abs($exponent), 2.0) === 0.0) {
                return 0.0;
            }

            $sine = sin(M_PI * fmod($exponent, 4.0) / 2.0);
            $logMagnitude = $exponent * log(2.0)
                + ($exponent - 1.0) * log(M_PI)
                + log(abs($sine))
                + self::logGammaPositive(1.0 - $exponent)
                + log(self::zetaFunction([1.0 - $exponent]));

            return self::finiteSpecialResult(($sine < 0.0 ? -1.0 : 1.0) * exp($logMagnitude), 'zeta');
        }

        $limit = 128;
        $sum = 0.0;
        for ($index = 1; $index <= $limit; ++$index) {
            $sum += $index ** (-$exponent);
        }
        $tail = $limit ** (1.0 - $exponent) / ($exponent - 1.0) - 0.5 * $limit ** (-$exponent);
        $bernoulli = [
            1 => 1.0 / 6.0,
            2 => -1.0 / 30.0,
            3 => 1.0 / 42.0,
            4 => -1.0 / 30.0,
            5 => 5.0 / 66.0,
            6 => -691.0 / 2730.0,
            7 => 7.0 / 6.0,
            8 => -3617.0 / 510.0,
        ];
        $correction = 0.0;
        foreach ($bernoulli as $index => $number) {
            $order = 2 * $index;
            $rising = 1.0;
            $factorial = 1.0;
            for ($factor = 0; $factor < $order - 1; ++$factor) {
                $rising *= $exponent + $factor;
            }
            for ($factor = 2; $factor <= $order; ++$factor) {
                $factorial *= $factor;
            }
            $correction += $number / $factorial * $rising * $limit ** (-$exponent - $order + 1.0);
        }

        return self::finiteSpecialResult($sum + $tail + $correction, 'zeta');
    }

    /** @param list<int|float> $arguments */
    private static function dirichletEtaFunction(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if (!\is_finite($exponent)) {
            throw new \DomainException('eta() requires a finite real argument.');
        }
        if ($exponent === 0.0) {
            return 0.5;
        }
        if ($exponent > 0.0) {
            // Euler-transform the alternating Dirichlet series. Its differences
            // decay rapidly even at s = 1, avoiding the zeta pole/cancellation.
            $differences = [];
            for ($index = 0; $index <= 64; ++$index) {
                $differences[] = ($index + 1.0) ** (-$exponent);
            }

            $sum = 0.0;
            $compensation = 0.0;
            $weight = 0.5;
            for ($order = 0; $order <= 64; ++$order) {
                $term = $differences[0] * $weight;
                $adjusted = $term - $compensation;
                $nextSum = $sum + $adjusted;
                $compensation = ($nextSum - $sum) - $adjusted;
                $sum = $nextSum;
                if ($order > 8 && \abs($term) <= \abs($sum) * 2.0e-16) {
                    break;
                }

                for ($index = 0, $last = \count($differences) - 1; $index < $last; ++$index) {
                    $differences[$index] -= $differences[$index + 1];
                }
                \array_pop($differences);
                $weight *= 0.5;
            }

            return self::finiteSpecialResult($sum, 'eta');
        }

        if (\floor($exponent) === $exponent && \fmod(\abs($exponent), 2.0) === 0.0) {
            return 0.0;
        }

        $power = (1.0 - $exponent) * \log(2.0);
        if ($power > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('eta() result exceeds the finite floating-point range.');
        }
        $factor = 1.0 - \exp($power);

        return self::finiteSpecialResult($factor * self::zetaFunction([$exponent]), 'eta');
    }

    /** @param list<int|float> $arguments */
    private static function dirichletBetaFunction(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if (!is_finite($exponent)) {
            throw new \DomainException('dirichletbeta() requires a finite real exponent.');
        }
        if ($exponent <= 0.0) {
            $scaleLogarithm = -$exponent * log(4.0);
            if ($scaleLogarithm > log(PHP_FLOAT_MAX)) {
                throw new \OverflowException('dirichletbeta() result exceeds the finite floating-point range.');
            }
            $difference = self::hurwitzZetaFunction([$exponent, 0.25])
                - self::hurwitzZetaFunction([$exponent, 0.75]);

            return self::finiteSpecialResult(exp($scaleLogarithm) * $difference, 'dirichletbeta');
        }

        $differences = [];
        for ($index = 0; $index <= 64; ++$index) {
            $differences[] = (2.0 * $index + 1.0) ** (-$exponent);
        }
        $sum = 0.0;
        $compensation = 0.0;
        $weight = 0.5;
        for ($order = 0; $order <= 64; ++$order) {
            $term = $differences[0] * $weight;
            $adjusted = $term - $compensation;
            $nextSum = $sum + $adjusted;
            $compensation = ($nextSum - $sum) - $adjusted;
            $sum = $nextSum;
            if ($order > 8 && abs($term) <= abs($sum) * 2.0e-16) {
                return self::finiteSpecialResult($sum, 'dirichletbeta');
            }

            for ($index = 0, $last = count($differences) - 1; $index < $last; ++$index) {
                $differences[$index] -= $differences[$index + 1];
            }
            array_pop($differences);
            $weight *= 0.5;
        }

        return self::finiteSpecialResult($sum, 'dirichletbeta');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDerivativeFunction(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if (!is_finite($exponent) || $exponent === 1.0) {
            throw new \DomainException('zetaprime() requires a finite real argument other than the pole at one.');
        }
        if ($exponent === 0.0) {
            return -0.5 * log(2.0 * M_PI);
        }
        if ($exponent <= -1.0) {
            $phase = M_PI * fmod($exponent, 4.0) / 2.0;
            if (floor($exponent) === $exponent && fmod(abs($exponent), 2.0) === 0.0) {
                $logMagnitude = $exponent * log(2.0)
                    + ($exponent - 1.0) * log(M_PI)
                    + log(M_PI / 2.0)
                    + self::logGammaPositive(1.0 - $exponent)
                    + log(self::zetaFunction([1.0 - $exponent]));

                return self::finiteSpecialResult((cos($phase) < 0.0 ? -1.0 : 1.0) * exp($logMagnitude), 'zetaprime');
            }

            $positiveExponent = 1.0 - $exponent;
            $logarithmicDerivative = log(2.0 * M_PI)
                + (M_PI / 2.0) * cos($phase) / sin($phase)
                - self::digammaFunction([$positiveExponent])
                - self::zetaDerivativeFunction([$positiveExponent]) / self::zetaFunction([$positiveExponent]);

            return self::finiteSpecialResult(
                self::zetaFunction([$exponent]) * $logarithmicDerivative,
                'zetaprime',
            );
        }

        $limit = 128;
        $logLimit = log($limit);
        $derivative = 0.0;
        for ($index = 1; $index <= $limit; ++$index) {
            $derivative -= log($index) * $index ** (-$exponent);
        }
        $power = $limit ** (1.0 - $exponent);
        $derivative += $power * (-$logLimit / ($exponent - 1.0) - 1.0 / (($exponent - 1.0) ** 2));
        $derivative += 0.5 * $logLimit * $limit ** (-$exponent);

        $bernoulli = [
            1 => 1.0 / 6.0,
            2 => -1.0 / 30.0,
            3 => 1.0 / 42.0,
            4 => -1.0 / 30.0,
            5 => 5.0 / 66.0,
            6 => -691.0 / 2730.0,
            7 => 7.0 / 6.0,
            8 => -3617.0 / 510.0,
        ];
        foreach ($bernoulli as $index => $number) {
            $order = 2 * $index;
            $rising = 1.0;
            $logRisingDerivative = 0.0;
            $factorial = 1.0;
            for ($factor = 0; $factor < $order - 1; ++$factor) {
                $rising *= $exponent + $factor;
                $logRisingDerivative += 1.0 / ($exponent + $factor);
            }
            for ($factor = 2; $factor <= $order; ++$factor) {
                $factorial *= $factor;
            }
            $term = $number / $factorial * $rising * $limit ** (-$exponent - $order + 1.0);
            $derivative += $term * ($logRisingDerivative - $logLimit);
        }

        return self::finiteSpecialResult($derivative, 'zetaprime');
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliNumber(array $arguments): float
    {
        $order = (float) $arguments[0];
        if (!is_finite($order) || floor($order) !== $order || $order < 0.0 || $order > 256.0) {
            throw new \DomainException('bernoulli() requires an integer order from 0 through 256.');
        }
        if ($order === 0.0) {
            return 1.0;
        }
        if ($order === 1.0) {
            return -0.5;
        }
        if ((int) $order % 2 === 1) {
            return 0.0;
        }

        $integerOrder = (int) $order;
        $halfOrder = intdiv($integerOrder, 2);
        $logMagnitude = log(2.0)
            + self::logGammaPositive($integerOrder + 1.0)
            + log(self::zetaFunction([$integerOrder]))
            - $integerOrder * log(2.0 * M_PI);
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('bernoulli() result is outside the finite floating-point range.');
        }

        $sign = $halfOrder % 2 === 1 ? 1.0 : -1.0;
        return self::finiteSpecialResult($sign * exp($logMagnitude), 'bernoulli');
    }

    /** @param list<int|float> $arguments */
    private static function eulerNumber(array $arguments): int
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'eulernumber');
        if ($order > 64) {
            throw new \DomainException('eulernumber() order must be an integer from 0 through 64.');
        }

        $numbers = [1];
        for ($degree = 1; $degree <= $order; ++$degree) {
            if ($degree % 2 === 1) {
                $numbers[$degree] = 0;
                continue;
            }

            $sum = 0;
            for ($index = 0; $index < $degree; $index += 2) {
                $coefficient = self::binomial([$degree, $index]);
                $previousNumber = $numbers[$index];
                if (
                    $previousNumber === PHP_INT_MIN
                    || $previousNumber > intdiv(PHP_INT_MAX, $coefficient)
                    || $previousNumber < intdiv(PHP_INT_MIN, $coefficient)
                ) {
                    throw new \OverflowException('eulernumber() result exceeds the host integer range.');
                }
                $term = $coefficient * $previousNumber;
                $sum = self::checkedIntegerSum($sum, $term, 'eulernumber()');
            }
            if ($sum === PHP_INT_MIN) {
                throw new \OverflowException('eulernumber() result exceeds the host integer range.');
            }
            $numbers[$degree] = -$sum;
        }

        return $numbers[$order];
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliPolynomial(array $arguments): float
    {
        $order = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (!is_finite($order) || floor($order) !== $order || $order < 0.0 || $order > 32.0 || !is_finite($value)) {
            throw new \DomainException('bernoullipoly() requires integer order 0 through 32 and a finite value.');
        }

        $integerOrder = (int) $order;
        $coefficient = 1.0;
        $power = 1.0;
        $sum = 0.0;
        for ($index = 0; $index <= $integerOrder; ++$index) {
            $sum += $coefficient * self::bernoulliNumber([$integerOrder - $index]) * $power;
            $power *= $value;
            if ($index < $integerOrder) {
                $coefficient *= ($integerOrder - $index) / ($index + 1.0);
            }
        }

        return self::finiteSpecialResult($sum, 'bernoullipoly');
    }

    /** @param list<int|float> $arguments */
    private static function digammaFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        self::requireGammaDerivativeArgument($value, 'digamma');
        if ($value < 0.5) {
            $reflected = self::digammaFunction([1.0 - $value]) - M_PI / tan(M_PI * $value);

            return self::finiteSpecialResult($reflected, 'digamma');
        }

        $result = 0.0;
        while ($value < 16.0) {
            $result -= 1.0 / $value;
            $value += 1.0;
        }
        $inverse = 1.0 / $value;
        $inverseSquared = $inverse * $inverse;
        $result += log($value) - 0.5 * $inverse - $inverseSquared * (
            1.0 / 12.0 - $inverseSquared * (1.0 / 120.0 - $inverseSquared * (1.0 / 252.0 - $inverseSquared / 240.0))
        );

        return self::finiteSpecialResult($result, 'digamma');
    }

    /** @param list<int|float> $arguments */
    private static function trigammaFunction(array $arguments): float
    {
        $value = (float) $arguments[0];
        self::requireGammaDerivativeArgument($value, 'trigamma');
        if ($value < 0.5) {
            $sine = sin(M_PI * $value);
            $reflected = (M_PI * M_PI) / ($sine * $sine) - self::trigammaFunction([1.0 - $value]);

            return self::finiteSpecialResult($reflected, 'trigamma');
        }

        $result = 0.0;
        while ($value < 16.0) {
            $result += 1.0 / ($value * $value);
            $value += 1.0;
        }
        $inverse = 1.0 / $value;
        $inverseSquared = $inverse * $inverse;
        $result += $inverse + 0.5 * $inverseSquared + $inverseSquared * $inverse / 6.0
            - $inverseSquared ** 2 * $inverse / 30.0
            + $inverseSquared ** 3 * $inverse / 42.0
            - $inverseSquared ** 4 * $inverse / 30.0;

        return self::finiteSpecialResult($result, 'trigamma');
    }

    private static function requireGammaDerivativeArgument(float $value, string $function): void
    {
        if (!is_finite($value) || ($value <= 0.0 && floor($value) === $value)) {
            throw new \DomainException($function . '() requires a finite non-pole real argument.');
        }
    }

    /** @param list<int|float> $arguments */
    private static function polygammaFunction(array $arguments): float
    {
        $order = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (!is_finite($order) || floor($order) !== $order || $order < 0.0 || $order > 32.0) {
            throw new \DomainException('polygamma() requires an integer order from 0 through 32.');
        }
        self::requireGammaDerivativeArgument($value, 'polygamma');
        $integerOrder = (int) $order;
        if ($integerOrder === 0) {
            return self::digammaFunction([$value]);
        }
        if ($integerOrder === 1) {
            return self::trigammaFunction([$value]);
        }

        $factorial = 1.0;
        for ($index = 2; $index <= $integerOrder; ++$index) {
            $factorial *= $index;
        }
        $seriesSign = $integerOrder % 2 === 0 ? -1.0 : 1.0;
        $recurrenceSign = -$seriesSign;
        $result = 0.0;
        while ($value <= 16.0) {
            $result -= $recurrenceSign * $factorial / ($value ** ($integerOrder + 1));
            $value += 1.0;
        }
        $termScale = $seriesSign * $factorial;
        $sum = 0.0;
        $index = 0;
        for (; $index < 200000; ++$index) {
            $term = $termScale / (($value + $index) ** ($integerOrder + 1));
            $sum += $term;
            if (abs($term) <= max(1.0, abs($sum)) * 1.0E-15) {
                break;
            }
        }
        $power = $integerOrder + 1;
        $tailBase = $value + $index + 1.0;
        $tail = ($tailBase ** (1 - $power)) / ($power - 1)
            + 0.5 * ($tailBase ** (-$power))
            + ($power / 12.0) * ($tailBase ** (-$power - 1));
        $sum += $termScale * $tail;

        return self::finiteSpecialResult($result + $sum, 'polygamma');
    }

    /** @param list<int|float> $arguments */
    private static function tetragammaFunction(array $arguments): float
    {
        return self::polygammaFunction([3, $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function pentagammaFunction(array $arguments): float
    {
        return self::polygammaFunction([4, $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function hexagammaFunction(array $arguments): float
    {
        return self::polygammaFunction([5, $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function besselJ(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselj');
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('besselj() requires a finite real argument.');
        }
        if ($value === 0.0) {
            return $order === 0 ? 1.0 : 0.0;
        }

        $sign = 1.0;
        if ($order < 0) {
            $order = -$order;
            if ($order % 2 !== 0) {
                $sign = -1.0;
            }
        }
        if ($value < 0.0) {
            if ($order % 2 !== 0) {
                $sign *= -1.0;
            }
            $value = -$value;
        }

        if ($value <= 20.0 || $order >= $value) {
            $result = self::besselSeries($order, $value, false);
        } else {
            [$previous, $current] = [
                self::besselJAsymptotic(0, $value),
                self::besselJAsymptotic(1, $value),
            ];
            if ($order === 0) {
                $result = $previous;
            } elseif ($order === 1) {
                $result = $current;
            } else {
                for ($index = 1; $index < $order; ++$index) {
                    [$previous, $current] = [$current, (2.0 * $index / $value) * $current - $previous];
                }
                $result = $current;
            }
        }
        return self::finiteSpecialResult($sign * $result, 'besselj');
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselI(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (is_finite($orderValue) && floor($orderValue) !== $orderValue) {
            $logResult = self::modifiedBesselIRealOrderLogarithm($orderValue, $value, 'besseli');
            if ($logResult > log(PHP_FLOAT_MAX)) {
                throw new \OverflowException('besseli() result exceeds the finite floating-point range.');
            }

            return self::finiteSpecialResult(exp($logResult), 'besseli');
        }
        $order = self::requireIntegerOrder($orderValue, 'besseli');
        if (!is_finite($value)) {
            throw new \DomainException('besseli() requires a finite real argument.');
        }
        if ($value === 0.0) {
            return $order === 0 ? 1.0 : 0.0;
        }

        $sign = 1.0;
        if ($order < 0) {
            $order = -$order;
        }
        if ($value < 0.0) {
            if ($order % 2 !== 0) {
                $sign *= -1.0;
            }
            $value = -$value;
        }

        $result = $value > 40.0 && $value > 16.0 * $order * $order
            ? self::besselIAsymptotic($order, $value)
            : self::besselSeries($order, $value, true);
        return self::finiteSpecialResult($sign * $result, 'besseli');
    }

    /** @param list<int|float> $arguments */
    private static function logModifiedBesselI(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (is_finite($orderValue) && floor($orderValue) !== $orderValue) {
            return self::modifiedBesselIRealOrderLogarithm($orderValue, $value, 'logbesseli');
        }
        $order = abs(self::requireIntegerOrder($orderValue, 'logbesseli'));
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logbesseli() requires a finite positive real argument.');
        }

        if ($value <= 40.0) {
            $quarter = ($value / 2.0) ** 2;
            $term = 1.0;
            $series = 1.0;
            for ($index = 1; $index <= 1000; ++$index) {
                $term *= $quarter / ($index * ($order + $index));
                $series += $term;
                if ($term <= $series * 1.0E-16) {
                    break;
                }
            }

            $logValue = $order * log($value / 2.0)
                - self::logGammaPositive($order + 1.0)
                + log($series);

            return self::finiteSpecialResult($logValue, 'logbesseli');
        }

        if ($value > 16.0 * $order * $order) {
            $mu = 4.0 * $order * $order;
            $inverse = 1.0 / (8.0 * $value);
            $first = ($mu - 1.0) * $inverse;
            $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
            $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
            $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
            $series = 1.0 - $first + $second - $third + $fourth;

            return self::finiteSpecialResult(
                $value - 0.5 * (log(2.0 * M_PI) + log($value)) + log($series),
                'logbesseli',
            );
        }

        $result = self::modifiedBesselI([$order, $value]);
        if ($result <= 0.0) {
            throw new \OverflowException('logbesseli() cannot take the logarithm of the computed Bessel value.');
        }

        return self::finiteSpecialResult(log($result), 'logbesseli');
    }

    /** @param list<int|float> $arguments */
    private static function scaledModifiedBesselI(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (!is_finite($orderValue) || $orderValue < 0.0 || $orderValue > 100000.0) {
            throw new \DomainException('ive() requires a non-negative real order no greater than 100000.');
        }
        if (!is_finite($value)) {
            throw new \DomainException('ive() requires a finite real argument.');
        }
        if (floor($orderValue) !== $orderValue && $value < 0.0) {
            throw new \DomainException('ive() requires a non-negative argument for non-integer orders.');
        }
        if ($value === 0.0) {
            return $orderValue === 0.0 ? 1.0 : 0.0;
        }

        $magnitude = abs($value);
        $logScaled = self::logScaledModifiedBesselIValue($orderValue, $magnitude);
        $sign = ($value < 0.0 && floor($orderValue) === $orderValue && ((int) $orderValue % 2) !== 0)
            ? -1.0
            : 1.0;

        return self::finiteSpecialResult($sign * exp($logScaled), 'ive');
    }

    private static function logScaledModifiedBesselIValue(float $order, float $value): float
    {
        if ($value > 40.0 && $value > 16.0 * $order * $order) {
            $mu = 4.0 * $order * $order;
            $inverse = 1.0 / (8.0 * $value);
            $first = ($mu - 1.0) * $inverse;
            $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
            $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
            $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
            $correction = 1.0 - $first + $second - $third + $fourth;
            if ($correction > 0.0) {
                return -0.5 * (log(2.0 * M_PI) + log($value)) + log($correction);
            }
        }

        return self::modifiedBesselIRealOrderLogarithm($order, $value, 'ive') - $value;
    }

    private static function modifiedBesselIRealOrderLogarithm(float $order, float $value, string $function): float
    {
        if (!is_finite($order) || $order < 0.0 || $order > 100000.0) {
            throw new \DomainException($function . '() requires a non-negative real order no greater than 100000.');
        }
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException($function . '() requires a finite positive real argument for real orders.');
        }

        if ($value > 40.0 && $value > 16.0 * $order * $order) {
            $mu = 4.0 * $order * $order;
            $inverse = 1.0 / (8.0 * $value);
            $first = ($mu - 1.0) * $inverse;
            $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
            $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
            $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
            $correction = 1.0 - $first + $second - $third + $fourth;
            if ($correction > 0.0) {
                return self::finiteSpecialResult(
                    $value - 0.5 * (log(2.0 * M_PI) + log($value)) + log($correction),
                    $function,
                );
            }
        }

        $logHalfValue = log($value) - log(2.0);
        $logTerm = $order * $logHalfValue - self::logGammaPositive($order + 1.0);
        $logSum = $logTerm;
        $logRatioBase = 2.0 * $logHalfValue;
        for ($index = 1; $index <= self::MAX_BESSEL_SERIES_TERMS; ++$index) {
            $logRatio = $logRatioBase - log($index) - log($index + $order);
            $logTerm += $logRatio;
            $logSum = self::stableLogSumExp([$logSum, $logTerm]);

            $nextIndex = $index + 1.0;
            $nextLogRatio = $logRatioBase - log($nextIndex) - log($nextIndex + $order);
            if ($nextLogRatio < -1.0E-8) {
                $logNextTerm = $logTerm + $nextLogRatio;
                $logTailBound = $logNextTerm - log1p(-exp($nextLogRatio));
                if ($logTailBound <= $logSum + log(1.0E-15)) {
                    return self::finiteSpecialResult($logSum, $function);
                }
            }
        }

        throw new \OverflowException($function . '() real-order series did not converge within the iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function besselY(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'bessely');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('bessely() requires a finite positive real argument.');
        }
        $sign = 1.0;
        if ($order < 0) {
            $order = -$order;
            if ($order % 2 !== 0) {
                $sign = -1.0;
            }
        }
        [$previous, $current] = $value <= 20.0
            ? self::besselYSeriesSeeds($value)
            : [self::besselYAsymptotic(0, $value), self::besselYAsymptotic(1, $value)];
        if ($order === 0) {
            return self::finiteSpecialResult($sign * $previous, 'bessely');
        }
        if ($order === 1) {
            return self::finiteSpecialResult($sign * $current, 'bessely');
        }
        for ($index = 1; $index < $order; ++$index) {
            [$previous, $current] = [$current, (2.0 * $index / $value) * $current - $previous];
        }

        return self::finiteSpecialResult($sign * $current, 'bessely');
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselK(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselk');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('besselk() requires a finite positive real argument.');
        }
        $order = abs($order);
        if ($value > 40.0 && $value > 16.0 * $order * $order) {
            return self::finiteSpecialResult(self::besselKAsymptotic($order, $value), 'besselk');
        }
        [$previous, $current] = $value <= 20.0
            ? self::besselKSeriesSeeds($value)
            : [self::besselKAsymptotic(0, $value), self::besselKAsymptotic(1, $value)];
        if ($order === 0) {
            return self::finiteSpecialResult($previous, 'besselk');
        }
        if ($order === 1) {
            return self::finiteSpecialResult($current, 'besselk');
        }
        for ($index = 1; $index < $order; ++$index) {
            [$previous, $current] = [$current, $previous + (2.0 * $index / $value) * $current];
        }

        return self::finiteSpecialResult($current, 'besselk');
    }

    /** @param list<int|float> $arguments */
    private static function besselJDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besseljprime');
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('besseljprime() requires a finite real argument.');
        }

        return self::finiteSpecialResult(
            (self::besselJ([$order - 1, $value]) - self::besselJ([$order + 1, $value])) / 2.0,
            'besseljprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function besselJSecondDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besseljsecond');
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('besseljsecond() requires a finite real argument.');
        }

        return self::finiteSpecialResult(
            (
                self::besselJ([$order - 2, $value])
                - 2.0 * self::besselJ([$order, $value])
                + self::besselJ([$order + 2, $value])
            ) / 4.0,
            'besseljsecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselIDerivative(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (is_finite($orderValue) && floor($orderValue) !== $orderValue) {
            $logResult = self::logModifiedBesselIDerivativeValue($orderValue, $value, 'besseliprime');
            if ($logResult > log(PHP_FLOAT_MAX)) {
                throw new \OverflowException('besseliprime() result exceeds the finite floating-point range.');
            }

            return self::finiteSpecialResult(exp($logResult), 'besseliprime');
        }
        $order = self::requireIntegerOrder($orderValue, 'besseliprime');
        if (!is_finite($value)) {
            throw new \DomainException('besseliprime() requires a finite real argument.');
        }

        return self::finiteSpecialResult(
            (self::modifiedBesselI([$order - 1, $value]) + self::modifiedBesselI([$order + 1, $value])) / 2.0,
            'besseliprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselISecondDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselisecond');
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('besselisecond() requires a finite real argument.');
        }

        return self::finiteSpecialResult(
            (
                self::modifiedBesselI([$order - 2, $value])
                + 2.0 * self::modifiedBesselI([$order, $value])
                + self::modifiedBesselI([$order + 2, $value])
            ) / 4.0,
            'besselisecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logModifiedBesselIDerivative(array $arguments): float
    {
        $order = (float) $arguments[0];
        if (is_finite($order) && floor($order) === $order) {
            $order = abs($order);
        }

        return self::logModifiedBesselIDerivativeValue($order, (float) $arguments[1], 'logbesseliprime');
    }

    private static function logModifiedBesselIDerivativeValue(float $order, float $value, string $function): float
    {
        if (!is_finite($order) || $order < 0.0 || $order > 100000.0) {
            throw new \DomainException($function . '() requires a non-negative real order no greater than 100000.');
        }
        $logCurrent = self::modifiedBesselIRealOrderLogarithm($order, $value, $function);
        $logNext = self::modifiedBesselIRealOrderLogarithm($order + 1.0, $value, $function);
        if ($order === 0.0) {
            return $logNext;
        }

        return self::finiteSpecialResult(
            self::stableLogSumExp([$logNext, log($order) - log($value) + $logCurrent]),
            $function,
        );
    }

    /** @param list<int|float> $arguments */
    private static function besselYDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselyprime');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('besselyprime() requires a finite positive real argument.');
        }

        return self::finiteSpecialResult(
            (self::besselY([$order - 1, $value]) - self::besselY([$order + 1, $value])) / 2.0,
            'besselyprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function besselYSecondDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselysecond');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('besselysecond() requires a finite positive real argument.');
        }

        return self::finiteSpecialResult(
            (
                self::besselY([$order - 2, $value])
                - 2.0 * self::besselY([$order, $value])
                + self::besselY([$order + 2, $value])
            ) / 4.0,
            'besselysecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselKDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselkprime');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('besselkprime() requires a finite positive real argument.');
        }

        return self::finiteSpecialResult(
            -(self::modifiedBesselK([$order - 1, $value]) + self::modifiedBesselK([$order + 1, $value])) / 2.0,
            'besselkprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function modifiedBesselKSecondDerivative(array $arguments): float
    {
        $order = self::requireIntegerOrder($arguments[0], 'besselksecond');
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('besselksecond() requires a finite positive real argument.');
        }

        return self::finiteSpecialResult(
            (
                self::modifiedBesselK([$order - 2, $value])
                + 2.0 * self::modifiedBesselK([$order, $value])
                + self::modifiedBesselK([$order + 2, $value])
            ) / 4.0,
            'besselksecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logModifiedBesselKDerivative(array $arguments): float
    {
        $order = abs(self::requireIntegerOrder($arguments[0], 'logbesselkprime'));
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logbesselkprime() requires a finite positive real argument.');
        }

        $logMagnitude = self::stableLogSumExp([
            self::logModifiedBesselK([$order - 1, $value]),
            self::logModifiedBesselK([$order + 1, $value]),
        ]) - log(2.0);

        return self::finiteSpecialResult($logMagnitude, 'logbesselkprime');
    }

    /** @param list<int|float> $arguments */
    private static function logModifiedBesselK(array $arguments): float
    {
        $order = abs(self::requireIntegerOrder($arguments[0], 'logbesselk'));
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logbesselk() requires a finite positive real argument.');
        }

        if ($value > 40.0 && $value > 16.0 * $order * $order) {
            $mu = 4.0 * $order * $order;
            $inverse = 1.0 / (8.0 * $value);
            $first = ($mu - 1.0) * $inverse;
            $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
            $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
            $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
            $series = 1.0 + $first + $second + $third + $fourth;

            return self::finiteSpecialResult(
                -$value + 0.5 * (log(M_PI) - log(2.0 * $value)) + log($series),
                'logbesselk',
            );
        }

        $result = self::modifiedBesselK([$order, $value]);
        if ($result <= 0.0) {
            throw new \OverflowException('logbesselk() cannot recover a logarithm after besselk() underflow.');
        }

        return self::finiteSpecialResult(log($result), 'logbesselk');
    }

    /** @param list<int|float> $arguments */
    private static function scaledModifiedBesselK(array $arguments): float
    {
        $order = abs(self::requireIntegerOrder($arguments[0], 'kve'));
        $value = (float) $arguments[1];
        if (!is_finite($value) || $value <= 0.0) {
            throw new \DomainException('kve() requires a finite positive real argument.');
        }

        if ($value > 40.0 && $value > 16.0 * $order * $order) {
            $mu = 4.0 * $order * $order;
            $inverse = 1.0 / (8.0 * $value);
            $first = ($mu - 1.0) * $inverse;
            $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
            $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
            $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
            $series = 1.0 + $first + $second + $third + $fourth;
            $logScaled = 0.5 * (log(M_PI) - log(2.0 * $value)) + log($series);
        } else {
            $logScaled = self::logModifiedBesselK([$order, $value]) + $value;
        }

        return self::finiteSpecialResult(exp($logScaled), 'kve');
    }

    /** @return array{0: float, 1: float} */
    private static function besselYSeriesSeeds(float $value): array
    {
        $quarter = ($value / 2.0) ** 2;
        $j0 = self::besselSeries(0, $value, false);
        $j1 = self::besselSeries(1, $value, false);
        $logTerm = log($value / 2.0) + 0.5772156649015328606;
        $series = 0.0;
        $derivativeSeries = 0.0;
        $term = 1.0;
        $harmonic = 0.0;
        for ($index = 1; $index <= 1000; ++$index) {
            $term *= -$quarter / ($index * $index);
            $harmonic += 1.0 / $index;
            $series -= $term * $harmonic;
            $derivativeSeries -= $term * $harmonic * (2.0 * $index / $value);
            if (abs($term) <= max(1.0, abs($series)) * 1.0E-16) {
                break;
            }
        }
        $factor = 2.0 / M_PI;
        $y0 = $factor * ($logTerm * $j0 + $series);
        $y1 = -$factor * ($j0 / $value - $logTerm * $j1 + $derivativeSeries);

        return [$y0, $y1];
    }

    /** @return array{0: float, 1: float} */
    private static function besselKSeriesSeeds(float $value): array
    {
        $quarter = ($value / 2.0) ** 2;
        $i0 = self::besselSeries(0, $value, true);
        $i1 = self::besselSeries(1, $value, true);
        $logTerm = log($value / 2.0) + 0.5772156649015328606;
        $series = 0.0;
        $derivativeSeries = 0.0;
        $term = 1.0;
        $harmonic = 0.0;
        for ($index = 1; $index <= 1000; ++$index) {
            $term *= $quarter / ($index * $index);
            $harmonic += 1.0 / $index;
            $series += $term * $harmonic;
            $derivativeSeries += $term * $harmonic * (2.0 * $index / $value);
            if (abs($term) <= max(1.0, abs($series)) * 1.0E-16) {
                break;
            }
        }
        $k0 = -$logTerm * $i0 + $series;
        $k1 = $i0 / $value + $logTerm * $i1 - $derivativeSeries;

        return [$k0, $k1];
    }

    private static function requireIntegerOrder(int|float $value, string $function): int
    {
        if (!is_finite((float) $value) || floor((float) $value) !== (float) $value || abs((float) $value) > 100000.0) {
            throw new \DomainException($function . '() currently requires a finite integer order.');
        }

        return (int) $value;
    }

    private static function besselSeries(int $order, float $value, bool $modified): float
    {
        $half = $value / 2.0;
        $term = 1.0;
        for ($index = 1; $index <= $order; ++$index) {
            $term *= $half / $index;
        }
        $sum = $term;
        $square = $half * $half;
        for ($index = 1; $index <= 1000; ++$index) {
            $ratio = $square / ($index * ($index + $order));
            $term *= $ratio;
            if (!$modified) {
                $term *= -1.0;
            }
            $sum += $term;
            if ($ratio < 1.0 && abs($term) <= max(PHP_FLOAT_MIN, abs($sum)) * 1.0E-15) {
                break;
            }
        }

        return $sum;
    }

    private static function besselJAsymptotic(int $order, float $value): float
    {
        $mu = 4.0 * $order * $order;
        $z = 8.0 * $value;
        $phase = $value - $order * M_PI / 2.0 - M_PI / 4.0;
        $first = ($mu - 1.0) / $z;
        $second = ($mu - 1.0) * ($mu - 9.0) / (2.0 * $z * $z);
        $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) / (24.0 * $z ** 4);
        $sineCorrection = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) / (6.0 * $z ** 3);
        $amplitude = sqrt(2.0 / (M_PI * $value));

        return $amplitude * ((1.0 - $second + $third) * cos($phase) - ($first - $sineCorrection) * sin($phase));
    }

    private static function besselYAsymptotic(int $order, float $value): float
    {
        $mu = 4.0 * $order * $order;
        $z = 8.0 * $value;
        $phase = $value - $order * M_PI / 2.0 - M_PI / 4.0;
        $first = ($mu - 1.0) / $z;
        $second = ($mu - 1.0) * ($mu - 9.0) / (2.0 * $z * $z);
        $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) / (24.0 * $z ** 4);
        $sineCorrection = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) / (6.0 * $z ** 3);
        $amplitude = sqrt(2.0 / (M_PI * $value));

        return $amplitude * ((1.0 - $second + $third) * sin($phase) + ($first - $sineCorrection) * cos($phase));
    }

    private static function besselKAsymptotic(int $order, float $value): float
    {
        $mu = 4.0 * $order * $order;
        $inverse = 1.0 / (8.0 * $value);
        $first = ($mu - 1.0) * $inverse;
        $second = ($mu - 1.0) * ($mu - 9.0) * $inverse ** 2 / 2.0;
        $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * $inverse ** 3 / 6.0;
        $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) * $inverse ** 4 / 24.0;
        $amplitude = sqrt(M_PI / (2.0 * $value)) * exp(-$value);

        return $amplitude * (1.0 + $first + $second + $third + $fourth);
    }

    private static function besselIAsymptotic(int $order, float $value): float
    {
        $mu = 4.0 * $order * $order;
        $z = 8.0 * $value;
        $first = ($mu - 1.0) / $z;
        $second = ($mu - 1.0) * ($mu - 9.0) / (2.0 * $z * $z);
        $third = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) / (6.0 * $z ** 3);
        $fourth = ($mu - 1.0) * ($mu - 9.0) * ($mu - 25.0) * ($mu - 49.0) / (24.0 * $z ** 4);
        $amplitude = exp($value) / sqrt(2.0 * M_PI * $value);

        return $amplitude * (1.0 - $first + $second - $third + $fourth);
    }

    private static function finiteSpecialResult(float $value, string $function): float
    {
        if (!is_finite($value)) {
            throw new \OverflowException($function . '() produced a non-finite result.');
        }

        return $value;
    }

    /** @param list<int|float> $arguments */
    private static function normalProbabilityDensity(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, 'normalpdf');
        $standardized = ($value - $mean) / $standardDeviation;
        if (!is_finite($standardized)) {
            return 0.0;
        }

        $exponential = exp(-0.5 * $standardized * $standardized);
        return self::finiteSpecialResult(
            ($exponential / sqrt(2.0 * M_PI)) / $standardDeviation,
            'normalpdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function normalLogProbabilityDensity(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, 'normallogpdf');
        $difference = $value - $mean;
        $standardized = \is_finite($difference)
            ? $difference / $standardDeviation
            : $value / $standardDeviation - $mean / $standardDeviation;
        if (!\is_finite($standardized) || \abs($standardized) > \sqrt(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('normallogpdf() result exceeds the finite floating-point range.');
        }

        $logDensity = -0.5 * $standardized * $standardized
            - \log($standardDeviation)
            - 0.5 * \log(2.0 * M_PI);

        return self::finiteSpecialResult($logDensity, 'normallogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function normalCumulativeDistribution(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, 'normalcdf');
        $difference = $value - $mean;
        if (!is_finite($difference)) {
            return $value < $mean ? 0.0 : 1.0;
        }

        $standardized = $difference / $standardDeviation;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 0.0 : 1.0;
        }

        return self::finiteSpecialResult(
            0.5 * self::complementaryErrorFunction([-($standardized / sqrt(2.0))]),
            'normalcdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function normalComplementaryCumulativeDistribution(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, 'normalccdf');
        $difference = $value - $mean;
        if (!is_finite($difference)) {
            return $value < $mean ? 1.0 : 0.0;
        }

        $standardized = $difference / $standardDeviation;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 1.0 : 0.0;
        }

        return self::finiteSpecialResult(
            0.5 * self::complementaryErrorFunction([$standardized / sqrt(2.0)]),
            'normalccdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function normalLogCumulativeDistribution(array $arguments): float
    {
        return self::normalLogTail($arguments, 'normallogcdf', false);
    }

    /** @param list<int|float> $arguments */
    private static function normalLogComplementaryCumulativeDistribution(array $arguments): float
    {
        return self::normalLogTail($arguments, 'normallogccdf', true);
    }

    /** @param list<int|float> $arguments */
    private static function normalHazard(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, 'normalhazard');
        $difference = $value - $mean;
        $standardized = is_finite($difference)
            ? $difference / $standardDeviation
            : $value / $standardDeviation - $mean / $standardDeviation;
        if (!is_finite($standardized)) {
            if ($value < $mean) {
                return 0.0;
            }
            throw new \OverflowException('normalhazard() exceeds the finite floating-point range.');
        }

        if ($standardized > 8.0) {
            $scaledTail = self::scaledComplementaryErrorFunction([$standardized / sqrt(2.0)]);
            $hazard = (sqrt(2.0 / M_PI) / $scaledTail) / $standardDeviation;

            return self::finiteSpecialResult($hazard, 'normalhazard');
        }

        $density = self::normalProbabilityDensity([$standardized]);
        $survival = self::normalComplementaryCumulativeDistribution([$standardized]);

        return self::finiteSpecialResult(($density / $survival) / $standardDeviation, 'normalhazard');
    }

    /** @param list<int|float> $arguments */
    private static function normalCumulativeHazard(array $arguments): float
    {
        return -self::normalLogTail($arguments, 'normalcumhazard', true);
    }

    /** @param list<int|float> $arguments */
    private static function normalLogTail(array $arguments, string $function, bool $complement): float
    {
        [$value, $mean, $standardDeviation] = self::normalArguments($arguments, $function);
        $difference = $value - $mean;
        $standardized = is_finite($difference)
            ? $difference / $standardDeviation
            : $value / $standardDeviation - $mean / $standardDeviation;
        if (!is_finite($standardized)) {
            $valueIsBelowMean = $standardized < 0.0;
            if ($valueIsBelowMean !== $complement) {
                throw new \OverflowException($function . '() log probability exceeds the finite floating-point range.');
            }

            return 0.0;
        }

        $erfcArgument = ($complement ? $standardized : -$standardized) / sqrt(2.0);
        $logProbability = self::logComplementaryErrorFunction([$erfcArgument]) - log(2.0);

        return self::finiteSpecialResult($logProbability, $function);
    }

    /** @param list<int|float> $arguments */
    private static function inverseNormalCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        $mean = (float) ($arguments[1] ?? 0.0);
        $standardDeviation = (float) ($arguments[2] ?? 1.0);
        if (
            !is_finite($probability)
            || $probability <= 0.0
            || $probability >= 1.0
            || !is_finite($mean)
            || !is_finite($standardDeviation)
            || $standardDeviation <= 0.0
        ) {
            throw new \DomainException(
                'normalinv() requires a probability strictly between 0 and 1, a finite mean, '
                . 'and a positive finite standard deviation.',
            );
        }

        $lowerTail = min($probability, 1.0 - $probability);
        $direction = $probability < 0.5 ? -1.0 : 1.0;
        $standardized = $direction * sqrt(2.0) * self::inverseComplementaryErrorFunction([2.0 * $lowerTail]);

        return self::finiteSpecialResult($mean + $standardDeviation * $standardized, 'normalinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseNormalLogCumulativeDistribution(array $arguments): float
    {
        return self::inverseNormalLogTail($arguments, 'normalinvlogcdf', false);
    }

    /** @param list<int|float> $arguments */
    private static function inverseNormalLogComplementaryCumulativeDistribution(array $arguments): float
    {
        return self::inverseNormalLogTail($arguments, 'normalinvlogccdf', true);
    }

    /** @param list<int|float> $arguments */
    private static function inverseNormalLogTail(array $arguments, string $function, bool $complement): float
    {
        $logProbability = (float) $arguments[0];
        [, $mean, $standardDeviation] = self::normalArguments(
            [0.0, $arguments[1] ?? 0.0, $arguments[2] ?? 1.0],
            $function,
        );
        if (!is_finite($logProbability) || $logProbability >= 0.0) {
            throw new \DomainException($function . '() requires a finite negative log probability.');
        }

        $logHalf = -log(2.0);
        if (!$complement) {
            if ($logProbability <= $logHalf) {
                $standardized = -sqrt(2.0) * self::inverseLogComplementaryErrorFunction([
                    $logProbability + log(2.0),
                ]);
            } else {
                $logUpperProbability = self::logOneMinusExponential([$logProbability]);
                $standardized = sqrt(2.0) * self::inverseLogComplementaryErrorFunction([
                    $logUpperProbability + log(2.0),
                ]);
            }
        } elseif ($logProbability <= $logHalf) {
            $standardized = sqrt(2.0) * self::inverseLogComplementaryErrorFunction([
                $logProbability + log(2.0),
            ]);
        } else {
            $logLowerProbability = self::logOneMinusExponential([$logProbability]);
            $standardized = -sqrt(2.0) * self::inverseLogComplementaryErrorFunction([
                $logLowerProbability + log(2.0),
            ]);
        }

        return self::finiteSpecialResult($mean + $standardDeviation * $standardized, $function);
    }

    /** @param list<int|float> $arguments */
    private static function exponentialProbabilityDensity(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentialpdf');
        if ($value < 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult($rate * exp(-$rate * $value), 'exponentialpdf');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialLogProbabilityDensity(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentiallogpdf');
        if ($value < 0.0) {
            throw new \DomainException('exponentiallogpdf() is undefined where the exponential density is zero.');
        }
        if ($value > 0.0 && $rate > PHP_FLOAT_MAX / $value) {
            throw new \OverflowException('exponentiallogpdf() is below the finite floating-point range.');
        }

        return self::finiteSpecialResult(log($rate) - $rate * $value, 'exponentiallogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialCumulativeDistribution(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentialcdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        return -expm1(-$rate * $value);
    }

    /** @param list<int|float> $arguments */
    private static function exponentialSurvivalFunction(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentialccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        return exp(-$rate * $value);
    }

    /** @param list<int|float> $arguments */
    private static function inverseExponentialCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        $rate = (float) $arguments[1];
        if (
            !is_finite($probability)
            || $probability < 0.0
            || $probability >= 1.0
            || !is_finite($rate)
            || $rate <= 0.0
        ) {
            throw new \DomainException('exponentialinv() requires a probability in [0, 1) and a positive finite rate.');
        }

        return -log1p(-$probability) / $rate;
    }

    /** @param list<int|float> $arguments */
    private static function inverseExponentialSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $rate] = self::exponentialArguments([0.0, $arguments[1]], 'exponentialccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('exponentialccinv() requires a survival probability in (0, 1].');
        }

        return self::finiteSpecialResult(-log($probability) / $rate, 'exponentialccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseExponentialQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $rate] = self::exponentialArguments([0.0, $arguments[1]], 'expinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('expinvprime() requires a probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(1.0 / ($rate * (1.0 - $probability)), 'expinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseExponentialSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $rate] = self::exponentialArguments([0.0, $arguments[1]], 'expccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('expccinvprime() requires a survival probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(-1.0 / ($rate * $probability), 'expccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialMean(array $arguments): float
    {
        [, $rate] = self::exponentialArguments([0.0, $arguments[0]], 'exponentialmean');

        return self::finiteSpecialResult(1.0 / $rate, 'exponentialmean');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialMedian(array $arguments): float
    {
        [, $rate] = self::exponentialArguments([0.0, $arguments[0]], 'exponentialmedian');

        return self::finiteSpecialResult(log(2.0) / $rate, 'exponentialmedian');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialMode(array $arguments): float
    {
        self::exponentialArguments([0.0, $arguments[0]], 'exponentialmode');

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function exponentialStandardDeviation(array $arguments): float
    {
        [, $rate] = self::exponentialArguments([0.0, $arguments[0]], 'exponentialstddev');

        return self::finiteSpecialResult(1.0 / $rate, 'exponentialstddev');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialDifferentialEntropy(array $arguments): float
    {
        [, $rate] = self::exponentialArguments([0.0, $arguments[0]], 'exponentialentropy');

        return self::finiteSpecialResult(1.0 - log($rate), 'exponentialentropy');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialHazard(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentialhazard');
        if ($value < 0.0) {
            throw new \DomainException('exponentialhazard() requires x >= 0.');
        }

        return $rate;
    }

    /** @param list<int|float> $arguments */
    private static function exponentialCumulativeHazard(array $arguments): float
    {
        [$value, $rate] = self::exponentialArguments($arguments, 'exponentialcumhazard');
        if ($value < 0.0) {
            throw new \DomainException('exponentialcumhazard() requires x >= 0.');
        }

        return self::finiteSpecialResult($value * $rate, 'exponentialcumhazard');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialVariance(array $arguments): float
    {
        [, $rate] = self::exponentialArguments([0.0, $arguments[0]], 'exponentialvariance');
        $reciprocalRate = 1.0 / $rate;

        return self::finiteSpecialResult($reciprocalRate * $reciprocalRate, 'exponentialvariance');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialSkewness(array $arguments): float
    {
        self::exponentialArguments([0.0, $arguments[0]], 'exponentialskewness');

        return 2.0;
    }

    /** @param list<int|float> $arguments */
    private static function exponentialExcessKurtosis(array $arguments): float
    {
        self::exponentialArguments([0.0, $arguments[0]], 'exponentialexcesskurtosis');

        return 6.0;
    }

    /** @param list<int|float> $arguments */
    private static function exponentialKurtosis(array $arguments): float
    {
        return 3.0 + self::exponentialExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function exponentialLogMomentGeneratingFunction(array $arguments): float
    {
        [$tilt, $rate] = self::exponentialArguments($arguments, 'exponentiallogmgf');
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logRatio = log(abs($tilt)) - log($rate);
        if ($tilt > 0.0) {
            if ($logRatio >= 0.0) {
                throw new \DomainException('exponentiallogmgf() requires t < rate.');
            }

            return -self::logOneMinusExponential([$logRatio]);
        }

        $logDenominator = $logRatio > 0.0
            ? $logRatio + log1p(exp(-$logRatio))
            : log1p(exp($logRatio));

        return self::finiteSpecialResult(-$logDenominator, 'exponentiallogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::exponentialLogMomentGeneratingFunction($arguments)),
            'exponentialmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function exponentialRawMoment(array $arguments): float
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'exponentialmoment');
        if ($order > 64) {
            throw new \DomainException('exponentialmoment() requires an integer order from 0 through 64.');
        }
        [, $rate] = self::exponentialArguments([0.0, $arguments[1]], 'exponentialmoment');
        if ($order === 0) {
            return 1.0;
        }

        $logMoment = self::logGammaPositive($order + 1.0) - $order * log($rate);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('exponentialmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'exponentialmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function exponentialArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $rate = (float) $arguments[1];
        if (!is_finite($value) || !is_finite($rate) || $rate <= 0.0) {
            throw new \DomainException($function . '() requires a finite value and positive finite rate.');
        }

        return [$value, $rate];
    }

    /** @param list<int|float> $arguments */
    private static function rayleighProbabilityDensity(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighpdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $standardized = $value / $scale;
        if (!is_finite($standardized) || $standardized > sqrt(-2.0 * log(PHP_FLOAT_MIN))) {
            return 0.0;
        }

        $logDensity = log($value) - 2.0 * log($scale) - 0.5 * $standardized * $standardized;
        return self::finiteSpecialResult(exp($logDensity), 'rayleighpdf');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighLogProbabilityDensity(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighlogpdf');
        if ($value <= 0.0) {
            throw new \DomainException('rayleighlogpdf() has no finite value at or below zero.');
        }
        $logRatio = log($value) - log($scale);
        $logExponent = 2.0 * $logRatio - log(2.0);
        if ($logExponent > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighlogpdf() is below the finite floating-point range.');
        }
        $logDensity = log($value) - 2.0 * log($scale) - exp($logExponent);

        return self::finiteSpecialResult($logDensity, 'rayleighlogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighCumulativeDistribution(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighcdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $standardized = $value / $scale;
        if (!is_finite($standardized) || $standardized > sqrt(-2.0 * log(PHP_FLOAT_MIN))) {
            return 1.0;
        }

        return -expm1(-0.5 * $standardized * $standardized);
    }

    /** @param list<int|float> $arguments */
    private static function rayleighSurvivalFunction(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        $standardized = $value / $scale;
        if (!is_finite($standardized) || $standardized > sqrt(-2.0 * log(PHP_FLOAT_MIN))) {
            return 0.0;
        }

        return exp(-0.5 * $standardized * $standardized);
    }

    /** @param list<int|float> $arguments */
    private static function rayleighLogCumulativeDistribution(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighlogcdf');
        if ($value <= 0.0) {
            throw new \DomainException('rayleighlogcdf() has no finite log probability for non-positive x.');
        }

        $logPower = 2.0 * (log($value) - log($scale)) - log(2.0);
        if ($logPower > log(PHP_FLOAT_MAX)) {
            return 0.0;
        }
        if ($logPower < -36.0) {
            return self::finiteSpecialResult($logPower, 'rayleighlogcdf');
        }

        return self::logOneMinusExponential([-exp($logPower)]);
    }

    /** @param list<int|float> $arguments */
    private static function rayleighLogSurvivalFunction(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighlogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $logPower = 2.0 * (log($value) - log($scale)) - log(2.0);
        if ($logPower > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighlogccdf() log probability is outside the finite range.');
        }

        return self::finiteSpecialResult(-exp($logPower), 'rayleighlogccdf');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRayleighCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        $scale = (float) $arguments[1];
        if (
            !is_finite($probability)
            || $probability < 0.0
            || $probability >= 1.0
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException('rayleighinv() requires a probability in [0, 1) and a positive finite scale.');
        }

        return self::finiteSpecialResult($scale * sqrt(-2.0 * log1p(-$probability)), 'rayleighinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRayleighSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $scale] = self::rayleighArguments([0.0, $arguments[1]], 'rayleighccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('rayleighccinv() requires a survival probability in (0, 1].');
        }

        return self::finiteSpecialResult($scale * sqrt(-2.0 * log($probability)), 'rayleighccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRayleighQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $scale] = self::rayleighArguments([0.0, $arguments[1]], 'rayleighinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('rayleighinvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseRayleighCumulativeDistribution([$probability, $scale]);
        $logDerivative = -self::rayleighLogProbabilityDensity([$quantile, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'rayleighinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseRayleighSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $scale] = self::rayleighArguments([0.0, $arguments[1]], 'rayleighccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'rayleighccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $quantile = self::inverseRayleighSurvivalFunction([$probability, $scale]);
        $logDerivative = -self::rayleighLogProbabilityDensity([$quantile, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'rayleighccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $scale] = self::rayleighArguments([0.0, $arguments[1]], 'rayleighlogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('rayleighlogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logMagnitude = log(abs($tilt)) + log($scale);
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            if ($tilt > 0.0) {
                throw new \OverflowException('rayleighlogmgf() exceeds the finite floating-point range.');
            }

            return self::finiteSpecialResult(-2.0 * $logMagnitude, 'rayleighlogmgf');
        }
        $magnitude = exp($logMagnitude);
        if ($magnitude === 0.0) {
            return 0.0;
        }
        if ($tilt < 0.0) {
            if ($magnitude >= 8.0) {
                return self::rayleighNegativeLogMomentGeneratingFunction($logMagnitude);
            }

            $mgf = 1.0 - $magnitude * sqrt(M_PI / 2.0)
                * self::scaledComplementaryErrorFunction([$magnitude / sqrt(2.0)]);

            return self::finiteSpecialResult(log($mgf), 'rayleighlogmgf');
        }

        $halfSquare = ($magnitude / sqrt(2.0)) ** 2;
        if (!is_finite($halfSquare)) {
            throw new \OverflowException('rayleighlogmgf() exceeds the finite floating-point range.');
        }
        $scaledErfc = self::scaledComplementaryErrorFunction([$magnitude / sqrt(2.0)]);
        $logScaledErfc = $halfSquare + log(2.0 - $scaledErfc * exp(-$halfSquare));
        $logPositiveTerm = log($magnitude) + 0.5 * log(M_PI / 2.0) + $logScaledErfc;

        return self::stableLogSumExp([0.0, $logPositiveTerm]);
    }

    private static function rayleighNegativeLogMomentGeneratingFunction(float $logMagnitude): float
    {
        $inverseSquare = exp(-2.0 * $logMagnitude);
        $term = 1.0;
        $sum = $term;
        for ($order = 1; $order <= 20; ++$order) {
            $term *= -(2.0 * $order + 1.0) * $inverseSquare;
            if (abs($term) > abs($sum)) {
                break;
            }
            $sum += $term;
            if (abs($term) <= abs($sum) * 1.0e-16) {
                break;
            }
        }

        return self::finiteSpecialResult(-2.0 * $logMagnitude + log($sum), 'rayleighlogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(exp(self::rayleighLogMomentGeneratingFunction($arguments)), 'rayleighmgf');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $scale] = self::rayleighArguments([0.0, $arguments[1]], 'rayleighmoment');
        if (!is_finite($order) || $order <= -2.0 || $order > 10000.0) {
            throw new \DomainException('rayleighmoment() requires a finite real order in (-2, 10000].');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $logMoment = $order * log($scale) + 0.5 * $order * log(2.0)
            + self::logGammaPositive(1.0 + 0.5 * $order);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'rayleighmoment');
    }

    /** @param list<int|float> $arguments
     *  @return array{0: float, 1: float}
     */
    private static function rayleighArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $scale = (float) $arguments[1];
        if (!is_finite($value) || !is_finite($scale) || $scale <= 0.0) {
            throw new \DomainException($function . '() requires a finite value and positive finite scale.');
        }

        return [$value, $scale];
    }

    /** @param list<int|float> $arguments */
    private static function rayleighMean(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighmean');

        return self::finiteSpecialResult($scale * sqrt(M_PI / 2.0), 'rayleighmean');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighVariance(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighvariance');
        $scaledDeviation = $scale * sqrt((4.0 - M_PI) / 2.0);

        return self::finiteSpecialResult($scaledDeviation * $scaledDeviation, 'rayleighvariance');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighMedian(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighmedian');

        return self::finiteSpecialResult($scale * sqrt(2.0 * log(2.0)), 'rayleighmedian');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighMode(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighmode');

        return $scale;
    }

    /** @param list<int|float> $arguments */
    private static function rayleighStandardDeviation(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighstddev');

        return self::finiteSpecialResult($scale * sqrt((4.0 - M_PI) / 2.0), 'rayleighstddev');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighDifferentialEntropy(array $arguments): float
    {
        [, $scale] = self::rayleighArguments([0.0, $arguments[0]], 'rayleighentropy');

        return self::finiteSpecialResult(
            1.0 + log($scale) - 0.5 * log(2.0) + 0.5 * 0.5772156649015329,
            'rayleighentropy',
        );
    }

    /** @param list<int|float> $arguments */
    private static function rayleighHazard(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighhazard');
        if ($value < 0.0) {
            throw new \DomainException('rayleighhazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        $logHazard = log($value) - 2.0 * log($scale);
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'rayleighhazard');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighCumulativeHazard(array $arguments): float
    {
        [$value, $scale] = self::rayleighArguments($arguments, 'rayleighcumhazard');
        if ($value < 0.0) {
            throw new \DomainException('rayleighcumhazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        $logCumulativeHazard = 2.0 * (log($value) - log($scale)) - log(2.0);
        if ($logCumulativeHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('rayleighcumhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logCumulativeHazard), 'rayleighcumhazard');
    }

    /** @param list<int|float> $arguments */
    private static function rayleighSkewness(array $arguments): float
    {
        self::rayleighArguments([0.0, $arguments[0]], 'rayleighskewness');

        return 2.0 * sqrt(M_PI) * (M_PI - 3.0) / ((4.0 - M_PI) ** 1.5);
    }

    /** @param list<int|float> $arguments */
    private static function rayleighExcessKurtosis(array $arguments): float
    {
        self::rayleighArguments([0.0, $arguments[0]], 'rayleighexcesskurtosis');

        return (-6.0 * M_PI * M_PI + 24.0 * M_PI - 16.0) / ((4.0 - M_PI) ** 2);
    }

    /** @param list<int|float> $arguments */
    private static function rayleighKurtosis(array $arguments): float
    {
        return 3.0 + self::rayleighExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function arcsineProbabilityDensity(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsinepdf');
        if ($value < 0.0 || $value > 1.0) {
            return 0.0;
        }
        if ($value === 0.0 || $value === 1.0) {
            throw new \DomainException('arcsinepdf() is singular at the support endpoints zero and one.');
        }

        return 1.0 / (M_PI * \sqrt($value) * \sqrt(1.0 - $value));
    }

    /** @param list<int|float> $arguments */
    private static function arcsineLogProbabilityDensity(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsinelogpdf');
        if ($value <= 0.0 || $value >= 1.0) {
            throw new \DomainException('arcsinelogpdf() has no finite log-density value outside the open support.');
        }

        return -log(M_PI) - 0.5 * log($value) - 0.5 * log1p(-$value);
    }

    /** @param list<int|float> $arguments */
    private static function arcsineCumulativeDistribution(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsinecdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        if ($value >= 1.0) {
            return 1.0;
        }

        if ($value > 0.5) {
            return 1.0 - (2.0 / M_PI) * \atan2(\sqrt(1.0 - $value), \sqrt($value));
        }

        return (2.0 / M_PI) * \asin(\sqrt($value));
    }

    /** @param list<int|float> $arguments */
    private static function arcsineSurvivalFunction(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsineccdf');
        if ($value <= 0.0) {
            return 1.0;
        }
        if ($value >= 1.0) {
            return 0.0;
        }

        if ($value <= 0.5) {
            return 1.0 - (2.0 / M_PI) * \asin(\sqrt($value));
        }

        return (2.0 / M_PI) * \asin(\sqrt(1.0 - $value));
    }

    /** @param list<int|float> $arguments */
    private static function arcsineLogCumulativeDistribution(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsinelogcdf');
        if ($value <= 0.0) {
            throw new \DomainException('arcsinelogcdf() is negative infinity at and below x = 0.');
        }
        if ($value >= 1.0) {
            return 0.0;
        }

        $root = \sqrt($value);
        $complementaryRoot = \sqrt(1.0 - $value);
        if ($value <= 0.5) {
            return log((2.0 / M_PI) * \atan2($root, $complementaryRoot));
        }

        $logComplement = log((2.0 / M_PI) * \atan2($complementaryRoot, $root));

        return log1p(-exp($logComplement));
    }

    /** @param list<int|float> $arguments */
    private static function arcsineLogSurvivalFunction(array $arguments): float
    {
        $value = self::arcsineArgument($arguments[0], 'arcsinelogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        if ($value >= 1.0) {
            throw new \DomainException('arcsinelogccdf() is negative infinity at and above x = 1.');
        }

        $root = \sqrt($value);
        $complementaryRoot = \sqrt(1.0 - $value);
        if ($value >= 0.5) {
            return log((2.0 / M_PI) * \atan2($complementaryRoot, $root));
        }

        $logCumulative = log((2.0 / M_PI) * \atan2($root, $complementaryRoot));

        return log1p(-exp($logCumulative));
    }

    /** @param list<int|float> $arguments */
    private static function inverseArcsineCumulativeDistribution(array $arguments): float
    {
        $probability = self::arcsineArgument($arguments[0], 'arcsineinv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('arcsineinv() requires a probability in [0, 1].');
        }
        if ($probability === 0.0 || $probability === 1.0) {
            return $probability;
        }

        if ($probability <= 0.5) {
            $sine = \sin((M_PI / 2.0) * $probability);

            return $sine * $sine;
        }
        $cosine = \cos((M_PI / 2.0) * (1.0 - $probability));

        return $cosine * $cosine;
    }

    private static function arcsineArgument(int|float $value, string $function): float
    {
        $argument = (float) $value;
        if (!\is_finite($argument)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }

        return $argument;
    }

    /** @param list<int|float> $arguments */
    private static function uniformProbabilityDensity(array $arguments): float
    {
        [$value, $minimum, $maximum] = self::uniformArguments($arguments, 'uniformpdf');
        if ($value < $minimum || $value > $maximum) {
            return 0.0;
        }

        return 1.0 / ($maximum - $minimum);
    }

    /** @param list<int|float> $arguments */
    private static function uniformLogProbabilityDensity(array $arguments): float
    {
        [$value, $minimum, $maximum] = self::uniformArguments($arguments, 'uniformlogpdf');
        if ($value < $minimum || $value > $maximum) {
            throw new \DomainException('uniformlogpdf() has no finite log-density outside the support.');
        }

        return -log($maximum - $minimum);
    }

    /** @param list<int|float> $arguments */
    private static function uniformCumulativeDistribution(array $arguments): float
    {
        [$value, $minimum, $maximum] = self::uniformArguments($arguments, 'uniformcdf');
        if ($value <= $minimum) {
            return 0.0;
        }
        if ($value >= $maximum) {
            return 1.0;
        }

        return ($value - $minimum) / ($maximum - $minimum);
    }

    /** @param list<int|float> $arguments */
    private static function uniformSurvivalFunction(array $arguments): float
    {
        [$value, $minimum, $maximum] = self::uniformArguments($arguments, 'uniformccdf');
        if ($value <= $minimum) {
            return 1.0;
        }
        if ($value >= $maximum) {
            return 0.0;
        }

        return ($maximum - $value) / ($maximum - $minimum);
    }

    /** @param list<int|float> $arguments */
    private static function inverseUniformCumulativeDistribution(array $arguments): float
    {
        [$probability, $minimum, $maximum] = self::uniformArguments($arguments, 'uniforminv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('uniforminv() requires a probability in [0, 1].');
        }

        return $minimum + ($maximum - $minimum) * $probability;
    }

    /** @param list<int|float> $arguments */
    private static function inverseUniformSurvivalFunction(array $arguments): float
    {
        [$probability, $minimum, $maximum] = self::uniformArguments($arguments, 'uniformccinv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('uniformccinv() requires a survival probability in [0, 1].');
        }

        return $maximum - ($maximum - $minimum) * $probability;
    }

    /** @param list<int|float> $arguments */
    private static function uniformMean(array $arguments): float
    {
        [, $minimum, $maximum] = self::uniformArguments([0.0, $arguments[0], $arguments[1]], 'uniformmean');

        return self::finiteSpecialResult($minimum / 2.0 + $maximum / 2.0, 'uniformmean');
    }

    /** @param list<int|float> $arguments */
    private static function uniformVariance(array $arguments): float
    {
        [, $minimum, $maximum] = self::uniformArguments([0.0, $arguments[0], $arguments[1]], 'uniformvariance');
        $scaledWidth = ($maximum - $minimum) / sqrt(12.0);

        return self::finiteSpecialResult($scaledWidth * $scaledWidth, 'uniformvariance');
    }

    /** @param list<int|float> $arguments */
    private static function uniformRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $minimum, $maximum] = self::uniformArguments(
            [0.0, $arguments[1], $arguments[2]],
            'uniformmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0.0 || $orderValue > 64.0) {
            throw new \DomainException('uniformmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }

        $order = (int) $orderValue;
        $midpoint = $minimum / 2.0 + $maximum / 2.0;
        $halfWidth = ($maximum - $minimum) / 2.0;
        $moment = 0.0;
        $coefficient = 1.0;
        for ($power = 0; $power <= intdiv($order, 2); ++$power) {
            if ($power > 0) {
                $previousEven = 2 * $power - 2;
                $coefficient *= (($order - $previousEven) * ($order - $previousEven - 1))
                    / ((2 * $power - 1) * (2 * $power));
            }
            $term = $coefficient * ($midpoint ** ($order - 2 * $power))
                * ($halfWidth ** (2 * $power)) / (2 * $power + 1);
            $moment += $term;
        }

        return self::finiteSpecialResult($moment, 'uniformmoment');
    }

    /** @param list<int|float> $arguments */
    private static function uniformMedian(array $arguments): float
    {
        [, $minimum, $maximum] = self::uniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'uniformmedian',
        );

        return self::finiteSpecialResult($minimum / 2.0 + $maximum / 2.0, 'uniformmedian');
    }

    /** @param list<int|float> $arguments */
    private static function uniformMode(array $arguments): float
    {
        [, $minimum, $maximum] = self::uniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'uniformmode',
        );

        return self::finiteSpecialResult($minimum / 2.0 + $maximum / 2.0, 'uniformmode');
    }

    /** @param list<int|float> $arguments */
    private static function uniformSkewness(array $arguments): float
    {
        self::uniformArguments([0.0, $arguments[0], $arguments[1]], 'uniformskewness');

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function uniformExcessKurtosis(array $arguments): float
    {
        self::uniformArguments([0.0, $arguments[0], $arguments[1]], 'uniformexcesskurtosis');

        return -6.0 / 5.0;
    }

    /** @param list<int|float> $arguments */
    private static function uniformKurtosis(array $arguments): float
    {
        return 3.0 + self::uniformExcessKurtosis($arguments);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function uniformArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $minimum = (float) $arguments[1];
        $maximum = (float) $arguments[2];
        $width = $maximum - $minimum;
        if (
            !is_finite($value)
            || !is_finite($minimum)
            || !is_finite($maximum)
            || !is_finite($width)
            || $width <= 0.0
        ) {
            throw new \DomainException($function . '() requires finite bounds with minimum < maximum.');
        }

        return [$value, $minimum, $maximum];
    }

    /** @param list<int|float> $arguments */
    private static function triangularProbabilityDensity(array $arguments): float
    {
        [$value, $minimum, $mode, $maximum, $width] = self::triangularArguments($arguments, 'triangularpdf');
        if ($value < $minimum || $value > $maximum) {
            return 0.0;
        }
        $position = ($value - $minimum) / $width;
        $modePosition = ($mode - $minimum) / $width;
        if ($position < $modePosition || $mode === $maximum) {
            $density = (2.0 / $width) * ($position / $modePosition);
        } else {
            $density = (2.0 / $width) * ((1.0 - $position) / (1.0 - $modePosition));
        }

        return self::finiteSpecialResult($density, 'triangularpdf');
    }

    /** @param list<int|float> $arguments */
    private static function triangularLogProbabilityDensity(array $arguments): float
    {
        [$value, $minimum, $mode, $maximum, $width] = self::triangularArguments($arguments, 'triangularlogpdf');
        if ($value < $minimum || $value > $maximum) {
            return -INF;
        }
        $position = ($value - $minimum) / $width;
        $modePosition = ($mode - $minimum) / $width;
        if ($position < $modePosition || $mode === $maximum) {
            if ($mode === $minimum && $value === $minimum) {
                return log(2.0 / $width);
            }
            if ($position === 0.0) {
                return -INF;
            }
            return log(2.0) + log($position) - log($width) - log($modePosition);
        }
        if ($mode === $maximum && $value === $maximum) {
            return log(2.0 / $width);
        }
        if ($position === 1.0) {
            return -INF;
        }
        return log(2.0) + log1p(-$position) - log($width) - log1p(-$modePosition);
    }

    /** @param list<int|float> $arguments */
    private static function triangularCumulativeDistribution(array $arguments): float
    {
        [$value, $minimum, $mode, $maximum, $width] = self::triangularArguments($arguments, 'triangularcdf');
        if ($value <= $minimum) {
            return 0.0;
        }
        if ($value >= $maximum) {
            return 1.0;
        }
        $position = ($value - $minimum) / $width;
        $modePosition = ($mode - $minimum) / $width;
        if ($position <= $modePosition) {
            return $position * ($position / $modePosition);
        }

        $upperFraction = 1.0 - $position;
        return 1.0 - $upperFraction * ($upperFraction / (1.0 - $modePosition));
    }

    /** @param list<int|float> $arguments */
    private static function triangularSurvivalFunction(array $arguments): float
    {
        [$value, $minimum, $mode, $maximum, $width] = self::triangularArguments($arguments, 'triangularccdf');
        if ($value <= $minimum) {
            return 1.0;
        }
        if ($value >= $maximum) {
            return 0.0;
        }
        $position = ($value - $minimum) / $width;
        $modePosition = ($mode - $minimum) / $width;
        if ($position >= $modePosition) {
            $upperFraction = 1.0 - $position;
            return $upperFraction * ($upperFraction / (1.0 - $modePosition));
        }

        return (($modePosition - $position) * ($modePosition + $position)
            + $modePosition * (1.0 - $modePosition)) / $modePosition;
    }

    /** @param list<int|float> $arguments */
    private static function inverseTriangularCumulativeDistribution(array $arguments): float
    {
        [$probability, $minimum, $mode, $maximum, $width] = self::triangularArguments(
            $arguments,
            'triangularinv',
        );
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('triangularinv() requires a probability in [0, 1].');
        }
        if ($probability === 0.0) {
            return $minimum;
        }
        if ($probability === 1.0) {
            return $maximum;
        }

        $modeProbability = ($mode - $minimum) / $width;
        if ($probability <= $modeProbability) {
            return $minimum + $width * sqrt($probability * $modeProbability);
        }

        return $maximum - $width * sqrt((1.0 - $probability) * (1.0 - $modeProbability));
    }

    /** @param list<int|float> $arguments */
    private static function triangularMean(array $arguments): float
    {
        [, $minimum, $mode, $maximum] = self::triangularArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'triangularmean',
        );

        return self::finiteSpecialResult(
            $minimum / 3.0 + $mode / 3.0 + $maximum / 3.0,
            'triangularmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function triangularVariance(array $arguments): float
    {
        [, $minimum, $mode, $maximum, $width] = self::triangularArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'triangularvariance',
        );
        $left = ($mode - $minimum) / $width;
        $right = ($maximum - $mode) / $width;
        $variance = ($width * $width / 18.0) * (1.0 - $left * $right);

        return self::finiteSpecialResult($variance, 'triangularvariance');
    }

    /** @param list<int|float> $arguments */
    private static function triangularMedian(array $arguments): float
    {
        [, $minimum, $mode, $maximum] = self::triangularArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'triangularmedian',
        );

        return self::inverseTriangularCumulativeDistribution([0.5, $minimum, $mode, $maximum]);
    }

    /** @param list<int|float> $arguments */
    private static function triangularMode(array $arguments): float
    {
        [, , $mode] = self::triangularArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'triangularmode',
        );

        return $mode;
    }

    /** @param list<int|float> $arguments */
    private static function triangularRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $minimum, $mode, $maximum, $width] = self::triangularArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'triangularmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0.0 || $orderValue > 32.0) {
            throw new \DomainException('triangularmoment() requires an integer order in [0, 32].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }

        $order = (int) $orderValue;
        $modePosition = ($mode - $minimum) / $width;
        $unitMoment = [];
        for ($power = 0; $power <= $order; ++$power) {
            if ($modePosition === 0.0) {
                $unitMoment[$power] = 2.0 / (($power + 1.0) * ($power + 2.0));
                continue;
            }
            if ($modePosition === 1.0) {
                $unitMoment[$power] = 2.0 / ($power + 2.0);
                continue;
            }
            $leftIntegral = 2.0 * ($modePosition ** ($power + 1)) / ($power + 2.0);
            $rightIntegral = 2.0 / (1.0 - $modePosition)
                * ((1.0 - $modePosition ** ($power + 1)) / ($power + 1.0)
                    - (1.0 - $modePosition ** ($power + 2)) / ($power + 2.0));
            $unitMoment[$power] = $leftIntegral + $rightIntegral;
        }
        $moment = 0.0;
        $coefficient = 1.0;
        for ($power = 0; $power <= $order; ++$power) {
            if ($power > 0) {
                $coefficient *= ($order - $power + 1.0) / $power;
            }
            $moment += $coefficient * ($minimum ** ($order - $power)) * ($width ** $power)
                * $unitMoment[$power];
        }

        return self::finiteSpecialResult($moment, 'triangularmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float, float, float}
     */
    private static function triangularArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $minimum = (float) $arguments[1];
        $mode = (float) $arguments[2];
        $maximum = (float) $arguments[3];
        $width = $maximum - $minimum;
        if (
            !is_finite($value)
            || !is_finite($minimum)
            || !is_finite($mode)
            || !is_finite($maximum)
            || !is_finite($width)
            || $width <= 0.0
            || $mode < $minimum
            || $mode > $maximum
        ) {
            throw new \DomainException($function . '() requires finite bounds with minimum <= mode <= maximum.');
        }

        return [$value, $minimum, $mode, $maximum, $width];
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale, $shape] = self::generalizedNormalArguments($arguments, 'generalizednormalpdf');
        $distance = abs($value - $location);
        $power = self::generalizedNormalPower($distance, $scale, $shape);
        if ($power === INF) {
            return 0.0;
        }

        $logDensity = log($shape) - log(2.0) - log($scale)
            - self::logGammaPositive(1.0 / $shape) - $power;

        return self::finiteSpecialResult(exp($logDensity), 'generalizednormalpdf');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalLogProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale, $shape] = self::generalizedNormalArguments(
            $arguments,
            'generalizednormallogpdf',
        );
        $power = self::generalizedNormalPower(abs($value - $location), $scale, $shape);
        $logDensity = log($shape) - log(2.0) - log($scale)
            - self::logGammaPositive(1.0 / $shape) - $power;

        return self::finiteSpecialResult($logDensity, 'generalizednormallogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale, $shape] = self::generalizedNormalArguments($arguments, 'generalizednormalcdf');
        if ($value === $location) {
            return 0.5;
        }

        $power = self::generalizedNormalPower(abs($value - $location), $scale, $shape);
        if ($power === INF) {
            return $value < $location ? 0.0 : 1.0;
        }

        $gammaShape = 1.0 / $shape;
        return $value < $location
            ? 0.5 * self::regularizedGammaUpperValue($gammaShape, $power)
            : 0.5 + 0.5 * self::regularizedGammaLower([$gammaShape, $power]);
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale, $shape] = self::generalizedNormalArguments($arguments, 'generalizednormalccdf');
        if ($value === $location) {
            return 0.5;
        }

        $power = self::generalizedNormalPower(abs($value - $location), $scale, $shape);
        if ($power === INF) {
            return $value < $location ? 1.0 : 0.0;
        }

        $gammaShape = 1.0 / $shape;
        return $value < $location
            ? 0.5 + 0.5 * self::regularizedGammaLower([$gammaShape, $power])
            : 0.5 * self::regularizedGammaUpperValue($gammaShape, $power);
    }

    /** @param list<int|float> $arguments */
    private static function inverseGeneralizedNormalCumulativeDistribution(array $arguments): float
    {
        [$probability, $location, $scale, $shape] = self::generalizedNormalArguments(
            $arguments,
            'generalizednormalinv',
        );
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('generalizednormalinv() requires a probability strictly between 0 and 1.');
        }
        if ($probability === 0.5) {
            return $location;
        }

        $gammaShape = 1.0 / $shape;
        $gammaTarget = $probability < 0.5 ? 2.0 * $probability : 2.0 * $probability - 1.0;
        $power = $probability < 0.5
            ? self::inverseRegularizedGammaUpperValue($gammaShape, $gammaTarget)
            : self::inverseRegularizedGammaValue($gammaShape, $gammaTarget);
        $logDistance = log($scale) + log($power) / $shape;
        if ($logDistance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('generalizednormalinv() quantile is outside the finite floating-point range.');
        }
        $distance = exp($logDistance);

        return self::finiteSpecialResult(
            $location + ($probability < 0.5 ? -$distance : $distance),
            'generalizednormalinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalMean(array $arguments): float
    {
        [, $location] = self::generalizedNormalArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'generalizednormalmean',
        );

        return $location;
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalMedian(array $arguments): float
    {
        return self::generalizedNormalMean($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalMode(array $arguments): float
    {
        return self::generalizedNormalMean($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalVariance(array $arguments): float
    {
        [, , $scale, $shape] = self::generalizedNormalArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'generalizednormalvariance',
        );
        $logVariance = 2.0 * log($scale)
            + self::logGammaPositive(3.0 / $shape) - self::logGammaPositive(1.0 / $shape);

        return self::finiteSpecialResult(exp($logVariance), 'generalizednormalvariance');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalStandardDeviation(array $arguments): float
    {
        return sqrt(self::generalizedNormalVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalEntropy(array $arguments): float
    {
        [, , $scale, $shape] = self::generalizedNormalArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'generalizednormalentropy',
        );

        return self::finiteSpecialResult(
            log(2.0) + log($scale) + self::logGammaPositive(1.0 / $shape) - log($shape) + 1.0 / $shape,
            'generalizednormalentropy',
        );
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalSkewness(array $arguments): float
    {
        self::generalizedNormalMean($arguments);

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalExcessKurtosis(array $arguments): float
    {
        [, , , $shape] = self::generalizedNormalArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'generalizednormalexcesskurtosis',
        );
        $logKurtosis = self::logGammaPositive(5.0 / $shape)
            + self::logGammaPositive(1.0 / $shape)
            - 2.0 * self::logGammaPositive(3.0 / $shape);

        return self::finiteSpecialResult(exp($logKurtosis) - 3.0, 'generalizednormalexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalKurtosis(array $arguments): float
    {
        return 3.0 + self::generalizedNormalExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function generalizedNormalRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $location, $scale, $shape] = self::generalizedNormalArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'generalizednormalmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0 || $orderValue > 32) {
            throw new \DomainException('generalizednormalmoment() requires an integer order in [0, 32].');
        }

        $order = (int) $orderValue;
        $moment = 0.0;
        $coefficient = 1.0;
        for ($centralOrder = 0; $centralOrder <= $order; ++$centralOrder) {
            if ($centralOrder > 0) {
                $coefficient *= ($order - $centralOrder + 1.0) / $centralOrder;
            }
            if ($centralOrder % 2 !== 0) {
                continue;
            }
            $centralMoment = $centralOrder === 0
                ? 1.0
                : exp(
                    $centralOrder * log($scale)
                    + self::logGammaPositive(($centralOrder + 1.0) / $shape)
                    - self::logGammaPositive(1.0 / $shape),
                );
            $moment += $coefficient * ($location ** ($order - $centralOrder)) * $centralMoment;
        }

        return self::finiteSpecialResult($moment, 'generalizednormalmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float, float}
     */
    private static function generalizedNormalArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $location = (float) $arguments[1];
        $scale = (float) $arguments[2];
        $shape = (float) $arguments[3];
        if (
            !is_finite($value)
            || !is_finite($location)
            || !is_finite($scale)
            || $scale <= 0.0
            || !is_finite($shape)
            || $shape < 1.0e-4
            || $shape > self::MAX_DISTRIBUTION_SHAPE
        ) {
            throw new \DomainException(
                $function . '() requires finite x and location, positive scale, and shape in [0.0001, 10000].',
            );
        }

        return [$value, $location, $scale, $shape];
    }

    private static function generalizedNormalPower(float $distance, float $scale, float $shape): float
    {
        if ($distance === 0.0) {
            return 0.0;
        }

        $logPower = $shape * (log($distance) - log($scale));
        if ($logPower > log(PHP_FLOAT_MAX)) {
            return INF;
        }

        return exp($logPower);
    }

    /** @param list<int|float> $arguments */
    private static function weibullProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibullpdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('weibullpdf() is singular at zero when shape is below 1.');
            }

            return $shape === 1.0
                ? self::finiteSpecialResult(1.0 / $scale, 'weibullhazard')
                : 0.0;
        }

        $ratio = $value / $scale;
        if (!is_finite($ratio)) {
            return 0.0;
        }
        $power = $shape * log($ratio);
        if ($power > log(PHP_FLOAT_MAX)) {
            return 0.0;
        }
        $hazardPower = exp($power);
        if (!is_finite($hazardPower)) {
            return 0.0;
        }
        $logDensity = log($shape) - log($scale) + ($shape - 1.0) * log($ratio) - $hazardPower;

        return self::finiteSpecialResult(exp($logDensity), 'weibullpdf');
    }

    /** @param list<int|float> $arguments */
    private static function weibullLogProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibulllogpdf');
        if ($value < 0.0) {
            throw new \DomainException('weibulllogpdf() is undefined where the Weibull density is zero.');
        }
        if ($value === 0.0) {
            if ($shape !== 1.0) {
                throw new \DomainException('weibulllogpdf() has no finite value at zero unless shape is one.');
            }

            return self::finiteSpecialResult(-log($scale), 'weibulllogpdf');
        }

        $logRatio = log($value) - log($scale);
        $logPower = $shape * $logRatio;
        if ($logPower > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibulllogpdf() is below the finite floating-point range.');
        }
        $logDensity = log($shape) - log($scale) + ($shape - 1.0) * $logRatio - exp($logPower);

        return self::finiteSpecialResult($logDensity, 'weibulllogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function weibullCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibullcdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        $power = self::weibullPower($value, $shape, $scale);

        return $power === INF ? 1.0 : -expm1(-$power);
    }

    /** @param list<int|float> $arguments */
    private static function weibullSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibullccdf');
        if ($value <= 0.0) {
            return 1.0;
        }
        $power = self::weibullPower($value, $shape, $scale);

        return $power === INF ? 0.0 : exp(-$power);
    }

    /** @param list<int|float> $arguments */
    private static function weibullLogCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibulllogcdf');
        if ($value <= 0.0) {
            throw new \DomainException('weibulllogcdf() has no finite log probability for non-positive x.');
        }

        $logPower = $shape * (log($value) - log($scale));
        if ($logPower > log(PHP_FLOAT_MAX)) {
            return 0.0;
        }
        if (!is_finite($logPower)) {
            throw new \OverflowException('weibulllogcdf() log probability is outside the finite range.');
        }
        if ($logPower < -36.0) {
            return self::finiteSpecialResult($logPower, 'weibulllogcdf');
        }

        $power = exp($logPower);

        return self::logOneMinusExponential([-$power]);
    }

    /** @param list<int|float> $arguments */
    private static function weibullLogSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibulllogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $logPower = $shape * (log($value) - log($scale));
        if ($logPower > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibulllogccdf() log probability is outside the finite range.');
        }

        return self::finiteSpecialResult(-exp($logPower), 'weibulllogccdf');
    }

    /** @param list<int|float> $arguments */
    private static function inverseWeibullCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[1], $arguments[2]], 'weibullinv');
        if (!is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('weibullinv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }
        $power = -log1p(-$probability);
        $logQuantile = log($scale) + log($power) / $shape;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'weibullinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseWeibullSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[1], $arguments[2]], 'weibullccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('weibullccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }
        $logQuantile = log($scale) + log(-log($probability)) / $shape;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullccinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'weibullccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseWeibullQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[1], $arguments[2]], 'weibullinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('weibullinvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseWeibullCumulativeDistribution([$probability, $shape, $scale]);
        $logDerivative = -self::weibullLogProbabilityDensity([$quantile, $shape, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'weibullinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseWeibullSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[1], $arguments[2]], 'weibullccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'weibullccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $quantile = self::inverseWeibullSurvivalFunction([$probability, $shape, $scale]);
        $logDerivative = -self::weibullLogProbabilityDensity([$quantile, $shape, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'weibullccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function weibullMode(array $arguments): float
    {
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[0], $arguments[1]], 'weibullmode');
        if ($shape <= 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            $scale * exp(log1p(-1.0 / $shape) / $shape),
            'weibullmode',
        );
    }

    /** @param list<int|float> $arguments */
    private static function weibullMean(array $arguments): float
    {
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[0], $arguments[1]], 'weibullmean');

        return self::weibullRawMoment([1.0, $shape, $scale]);
    }

    /** @param list<int|float> $arguments */
    private static function weibullMedian(array $arguments): float
    {
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[0], $arguments[1]], 'weibullmedian');

        return self::finiteSpecialResult(
            exp(log($scale) + log(log(2.0)) / $shape),
            'weibullmedian',
        );
    }

    /** @param list<int|float> $arguments */
    private static function weibullHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibullhazard');
        if ($value < 0.0) {
            throw new \DomainException('weibullhazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('weibullhazard() is singular at zero when shape is below 1.');
            }

            return $shape === 1.0 ? 1.0 / $scale : 0.0;
        }
        $logRatio = log($value) - log($scale);
        $logHazard = log($shape) - log($scale) + ($shape - 1.0) * $logRatio;
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'weibullhazard');
    }

    /** @param list<int|float> $arguments */
    private static function weibullCumulativeHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::weibullArguments($arguments, 'weibullcumhazard');
        if ($value < 0.0) {
            throw new \DomainException('weibullcumhazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        $logCumulativeHazard = $shape * (log($value) - log($scale));
        if ($logCumulativeHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullcumhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logCumulativeHazard), 'weibullcumhazard');
    }

    /** @param list<int|float> $arguments */
    private static function weibullVariance(array $arguments): float
    {
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[0], $arguments[1]], 'weibullvariance');
        $inverseShape = 1.0 / $shape;
        $logMean = log($scale) + self::logGammaPositive(1.0 + $inverseShape);
        if ($inverseShape < 1.0e-3) {
            $logGammaSeries = 0.12550966952474304;
            $logGammaSeries = -0.1440498967688461 + $inverseShape * $logGammaSeries;
            $logGammaSeries = 0.1695571769974082 + $inverseShape * $logGammaSeries;
            $logGammaSeries = -0.20738555102867398 + $inverseShape * $logGammaSeries;
            $logGammaSeries = 0.27058080842778455 + $inverseShape * $logGammaSeries;
            $logGammaSeries = -0.40068563438653143 + $inverseShape * $logGammaSeries;
            $logGammaSeries = 0.8224670334241132 + $inverseShape * $logGammaSeries;
            $logMean = log($scale) + $inverseShape * (-0.5772156649015329 + $inverseShape * $logGammaSeries);
            $zetaSeries = 31.879456059285;
            $zetaSeries = -18.150286992875 + $inverseShape * $zetaSeries;
            $zetaSeries = 10.512544973839 + $inverseShape * $zetaSeries;
            $zetaSeries = -6.2215665308602 + $inverseShape * $zetaSeries;
            $zetaSeries = 3.788131021060319 + $inverseShape * $zetaSeries;
            $zetaSeries = -2.4041138063191885 + $inverseShape * $zetaSeries;
            $zetaSeries = 1.6449340668482264 + $inverseShape * $zetaSeries;
            $logRelativeVariance = 2.0 * log($inverseShape) + log($zetaSeries);
        } else {
            $logSecondMomentRatio = self::logGammaPositive(1.0 + 2.0 * $inverseShape)
                - 2.0 * self::logGammaPositive(1.0 + $inverseShape);
            $logRelativeVariance = $logSecondMomentRatio < 1.0e-8
                ? log($logSecondMomentRatio)
                : log(expm1($logSecondMomentRatio));
        }
        $logVariance = 2.0 * $logMean + $logRelativeVariance;
        if ($logVariance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullvariance() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logVariance), 'weibullvariance');
    }

    /** @param list<int|float> $arguments */
    private static function weibullStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::weibullVariance($arguments)), 'weibullstddev');
    }

    /** @param list<int|float> $arguments */
    private static function weibullDifferentialEntropy(array $arguments): float
    {
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[0], $arguments[1]], 'weibullentropy');
        $entropy = 0.5772156649015329 * (1.0 - 1.0 / $shape) + log($scale) - log($shape) + 1.0;

        return self::finiteSpecialResult($entropy, 'weibullentropy');
    }

    /** @param list<int|float> $arguments */
    private static function weibullRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $shape, $scale] = self::weibullArguments([0.0, $arguments[1], $arguments[2]], 'weibullmoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('weibullmoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $gammaArgument = 1.0 + $order / $shape;
        if (!is_finite($gammaArgument)) {
            throw new \OverflowException('weibullmoment() exceeds the finite floating-point range.');
        }
        $logMoment = $order * log($scale) + self::logGammaPositive($gammaArgument);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('weibullmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'weibullmoment');
    }

    /** @param list<int|float> $arguments */
    private static function weibullSkewness(array $arguments): float
    {
        [, $shape] = self::weibullArguments([0.0, $arguments[0], 1.0], 'weibullskewness');
        $mean = self::weibullRawMoment([1.0, $shape, 1.0]);
        $second = self::weibullRawMoment([2.0, $shape, 1.0]);
        $third = self::weibullRawMoment([3.0, $shape, 1.0]);
        $variance = self::weibullVariance([$shape, 1.0]);
        $centralThird = $third - 3.0 * $mean * $second + 2.0 * $mean ** 3;

        return self::finiteSpecialResult($centralThird / ($variance ** 1.5), 'weibullskewness');
    }

    /** @param list<int|float> $arguments */
    private static function weibullExcessKurtosis(array $arguments): float
    {
        [, $shape] = self::weibullArguments([0.0, $arguments[0], 1.0], 'weibullexcesskurtosis');
        $mean = self::weibullRawMoment([1.0, $shape, 1.0]);
        $second = self::weibullRawMoment([2.0, $shape, 1.0]);
        $third = self::weibullRawMoment([3.0, $shape, 1.0]);
        $fourth = self::weibullRawMoment([4.0, $shape, 1.0]);
        $variance = self::weibullVariance([$shape, 1.0]);
        $centralFourth = $fourth - 4.0 * $mean * $third + 6.0 * $mean ** 2 * $second - 3.0 * $mean ** 4;

        return self::finiteSpecialResult($centralFourth / ($variance ** 2) - 3.0, 'weibullexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function weibullKurtosis(array $arguments): float
    {
        return 3.0 + self::weibullExcessKurtosis($arguments);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function weibullArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $shape = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($shape)
            || $shape <= 0.0
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException($function . '() requires a finite value and positive finite shape and scale.');
        }

        return [$value, $shape, $scale];
    }

    private static function weibullPower(float $value, float $shape, float $scale): float
    {
        $ratio = $value / $scale;
        if (!is_finite($ratio)) {
            return INF;
        }
        $logPower = $shape * log($ratio);
        if ($logPower > log(PHP_FLOAT_MAX)) {
            return INF;
        }

        return exp($logPower);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalProbabilityDensity(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, 'lognormalpdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $standardized = (log($value) - $mean) / $standardDeviation;
        $logDensity = -0.5 * $standardized * $standardized
            - 0.5 * log(2.0 * M_PI)
            - log($standardDeviation)
            - log($value);

        return self::finiteSpecialResult(exp($logDensity), 'lognormalpdf');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalLogProbabilityDensity(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, 'lognormallogpdf');
        if ($value <= 0.0) {
            throw new \DomainException('lognormallogpdf() has no finite log-density for non-positive x.');
        }

        $standardized = (log($value) - $mean) / $standardDeviation;
        $logDensity = -0.5 * $standardized * $standardized
            - 0.5 * log(2.0 * M_PI)
            - log($standardDeviation)
            - log($value);

        return self::finiteSpecialResult($logDensity, 'lognormallogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalCumulativeDistribution(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, 'lognormalcdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        return self::normalCumulativeDistribution([(log($value) - $mean) / $standardDeviation]);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalSurvivalFunction(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, 'lognormalccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        $standardized = (log($value) - $mean) / $standardDeviation;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 1.0 : 0.0;
        }

        return 0.5 * self::complementaryErrorFunction([$standardized / sqrt(2.0)]);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalLogCumulativeDistribution(array $arguments): float
    {
        return self::logNormalLogTail($arguments, 'lognormallogcdf', false);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalLogSurvivalFunction(array $arguments): float
    {
        return self::logNormalLogTail($arguments, 'lognormallogccdf', true);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalHazard(array $arguments): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, 'lognormalhazard');
        if ($value <= 0.0) {
            return 0.0;
        }

        $standardized = (log($value) - $mean) / $standardDeviation;
        if (!is_finite($standardized)) {
            if ($standardized < 0.0) {
                return 0.0;
            }
            $logDifference = log(abs(log($value) - $mean));
            $logHazard = $logDifference - 2.0 * log($standardDeviation) - log($value);
        } elseif ($standardized < -sqrt(PHP_FLOAT_MAX)) {
            return 0.0;
        } elseif ($standardized >= 0.0) {
            $logHazard = 0.5 * log(2.0 / M_PI) - log($standardDeviation) - log($value)
                - log(self::scaledComplementaryErrorFunction([$standardized / sqrt(2.0)]));
        } else {
            $logDensity = self::logNormalLogProbabilityDensity($arguments);
            $logSurvival = self::logNormalLogSurvivalFunction($arguments);
            $logHazard = $logDensity - $logSurvival;
        }

        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lognormalhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'lognormalhazard');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalCumulativeHazard(array $arguments): float
    {
        [$value] = self::logNormalArguments($arguments, 'lognormalcumhazard');
        if ($value <= 0.0) {
            return 0.0;
        }

        return -self::logNormalLogSurvivalFunction($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function logNormalLogTail(array $arguments, string $function, bool $complement): float
    {
        [$value, $mean, $standardDeviation] = self::logNormalArguments($arguments, $function);
        if ($value <= 0.0) {
            if (!$complement) {
                throw new \DomainException($function . '() log probability is singular for non-positive x.');
            }

            return 0.0;
        }

        $standardized = (log($value) - $mean) / $standardDeviation;
        if (!is_finite($standardized)) {
            $tailIsSmall = $complement ? $standardized > 0.0 : $standardized < 0.0;
            if ($tailIsSmall) {
                throw new \OverflowException($function . '() log probability exceeds the finite floating-point range.');
            }

            return 0.0;
        }

        return $complement
            ? self::normalLogComplementaryCumulativeDistribution([$standardized])
            : self::normalLogCumulativeDistribution([$standardized]);
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogNormalCumulativeDistribution(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments([1.0, $arguments[1], $arguments[2]], 'lognormalinv');
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('lognormalinv() requires a probability strictly between 0 and 1.');
        }

        $normalQuantile = self::inverseNormalCumulativeDistribution([$probability]);
        $logQuantile = $mean + $standardDeviation * $normalQuantile;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lognormalinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'lognormalinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogNormalSurvivalFunction(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[1], $arguments[2]],
            'lognormalccinv',
        );
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('lognormalccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        $standardized = self::inverseNormalLogComplementaryCumulativeDistribution([log($probability)]);
        $logQuantile = $mean + $standardDeviation * $standardized;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lognormalccinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'lognormalccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogNormalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[1], $arguments[2]],
            'lognormalinvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('lognormalinvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseLogNormalCumulativeDistribution([$probability, $mean, $standardDeviation]);
        $logDerivative = -self::logNormalLogProbabilityDensity([$quantile, $mean, $standardDeviation]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lognormalinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'lognormalinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogNormalSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[1], $arguments[2]],
            'lognormalccinvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'lognormalccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $quantile = self::inverseLogNormalSurvivalFunction([$probability, $mean, $standardDeviation]);
        $logDerivative = -self::logNormalLogProbabilityDensity([$quantile, $mean, $standardDeviation]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lognormalccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'lognormalccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalMean(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalmean',
        );
        $logMean = $mean + 0.5 * $standardDeviation * $standardDeviation;

        return self::finiteSpecialResult(exp($logMean), 'lognormalmean');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalMedian(array $arguments): float
    {
        [, $mean] = self::logNormalArguments([1.0, $arguments[0], $arguments[1]], 'lognormalmedian');

        return self::finiteSpecialResult(exp($mean), 'lognormalmedian');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalMode(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalmode',
        );
        $logMode = $mean - $standardDeviation * $standardDeviation;

        return self::finiteSpecialResult(exp($logMode), 'lognormalmode');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalDifferentialEntropy(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalentropy',
        );

        return self::finiteSpecialResult(
            $mean + log($standardDeviation) + 0.5 * (1.0 + log(2.0 * M_PI)),
            'lognormalentropy',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logNormalVariance(array $arguments): float
    {
        [, $mean, $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalvariance',
        );
        $varianceExponent = $standardDeviation * $standardDeviation;
        if (!is_finite($varianceExponent)) {
            throw new \OverflowException('lognormalvariance() exceeds the finite floating-point range.');
        }
        if ($varianceExponent === 0.0) {
            return 0.0;
        }
        $logExponentialMinusOne = $varianceExponent > 50.0
            ? $varianceExponent + log1p(-exp(-$varianceExponent))
            : log(expm1($varianceExponent));
        $logVariance = 2.0 * $mean + $varianceExponent + $logExponentialMinusOne;

        return self::finiteSpecialResult(exp($logVariance), 'lognormalvariance');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalSkewness(array $arguments): float
    {
        [, , $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalskewness',
        );
        $varianceExponent = $standardDeviation * $standardDeviation;
        $skewness = (exp($varianceExponent) + 2.0) * sqrt(expm1($varianceExponent));

        return self::finiteSpecialResult($skewness, 'lognormalskewness');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalExcessKurtosis(array $arguments): float
    {
        [, , $standardDeviation] = self::logNormalArguments(
            [1.0, $arguments[0], $arguments[1]],
            'lognormalexcesskurtosis',
        );
        $varianceExponent = $standardDeviation * $standardDeviation;
        $excessKurtosis = expm1(4.0 * $varianceExponent)
            + 2.0 * expm1(3.0 * $varianceExponent)
            + 3.0 * expm1(2.0 * $varianceExponent);

        return self::finiteSpecialResult($excessKurtosis, 'lognormalexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function logNormalKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(3.0 + self::logNormalExcessKurtosis($arguments), 'lognormalkurtosis');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function logNormalArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $mean = (float) $arguments[1];
        $standardDeviation = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($mean)
            || !is_finite($standardDeviation)
            || $standardDeviation <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires a finite value and mean, and a positive finite standard deviation.',
            );
        }

        return [$value, $mean, $standardDeviation];
    }

    /** @param list<int|float> $arguments */
    private static function logisticProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticpdf');
        $standardized = ($value - $location) / $scale;
        if (!is_finite($standardized)) {
            return 0.0;
        }
        $tail = exp(-abs($standardized));
        $denominator = $scale * (1.0 + $tail) ** 2;

        return self::finiteSpecialResult($tail / $denominator, 'logisticpdf');
    }

    /** @param list<int|float> $arguments */
    private static function logisticLogProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticlogpdf');
        $difference = $value - $location;
        if (is_finite($difference)) {
            $logMagnitude = $difference === 0.0 ? -INF : log(abs($difference)) - log($scale);
        } else {
            $logDifference = self::stableLogSumExp([log(abs($value)), log(abs($location))]);
            $logMagnitude = $logDifference - log($scale);
        }
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('logisticlogpdf() is below the finite floating-point range.');
        }
        $magnitude = $logMagnitude === -INF ? 0.0 : exp($logMagnitude);
        $logDensity = -log($scale) - $magnitude - 2.0 * log1p(exp(-$magnitude));

        return self::finiteSpecialResult($logDensity, 'logisticlogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function logisticCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticcdf');
        $standardized = ($value - $location) / $scale;
        if ($standardized >= 0.0) {
            $tail = exp(-$standardized);
            return 1.0 / (1.0 + $tail);
        }
        $tail = exp($standardized);

        return $tail / (1.0 + $tail);
    }

    /** @param list<int|float> $arguments */
    private static function logisticSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticccdf');
        $standardized = ($value - $location) / $scale;
        if ($standardized >= 0.0) {
            $tail = exp(-$standardized);
            return $tail / (1.0 + $tail);
        }
        $tail = exp($standardized);

        return 1.0 / (1.0 + $tail);
    }

    /** @param list<int|float> $arguments */
    private static function logisticLogCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticlogcdf');
        $standardized = ($value - $location) / $scale;
        if (!\is_finite($standardized)) {
            throw new \OverflowException('logisticlogcdf() result exceeds the finite floating-point range.');
        }

        return -self::softplus([-$standardized]);
    }

    /** @param list<int|float> $arguments */
    private static function logisticLogSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logisticlogccdf');
        $standardized = ($value - $location) / $scale;
        if (!\is_finite($standardized)) {
            throw new \OverflowException('logisticlogccdf() result exceeds the finite floating-point range.');
        }

        return -self::softplus([$standardized]);
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogisticCumulativeDistribution(array $arguments): float
    {
        [$probability, $location, $scale] = self::logisticArguments($arguments, 'logisticinv');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logisticinv() requires a probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(
            $location + $scale * (log($probability) - log1p(-$probability)),
            'logisticinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogisticSurvivalFunction(array $arguments): float
    {
        [$probability, $location, $scale] = self::logisticArguments($arguments, 'logisticccinv');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logisticccinv() requires a survival probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(
            $location + $scale * (log1p(-$probability) - log($probability)),
            'logisticccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogisticQuantileDerivative(array $arguments): float
    {
        [$probability, $location, $scale] = self::logisticArguments($arguments, 'logisticinvprime');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('logisticinvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseLogisticCumulativeDistribution([$probability, $location, $scale]);
        $logDerivative = -self::logisticLogProbabilityDensity([$quantile, $location, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('logisticinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'logisticinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogisticSurvivalQuantileDerivative(array $arguments): float
    {
        [$probability, $location, $scale] = self::logisticArguments($arguments, 'logisticccinvprime');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'logisticccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $quantile = self::inverseLogisticSurvivalFunction([$probability, $location, $scale]);
        $logDerivative = -self::logisticLogProbabilityDensity([$quantile, $location, $scale]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('logisticccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'logisticccinvprime');
    }

