    /** @param list<int|float> $arguments */
    private static function logisticHazard(array $arguments): float
    {
        [$value, $location, $scale] = self::logisticArguments($arguments, 'logistichazard');
        $standardized = ($value - $location) / $scale;
        $cdf = $standardized >= 0.0
            ? 1.0 / (1.0 + exp(-$standardized))
            : exp($standardized) / (1.0 + exp($standardized));

        return self::finiteSpecialResult($cdf / $scale, 'logistichazard');
