    /** @param list<int|float> $arguments */
    private static function logisticLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $location, $scale] = self::logisticArguments([0.0, $arguments[1], $arguments[2]], 'logisticlogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('logisticlogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logMagnitude = log(abs($tilt)) + log($scale);
        if ($logMagnitude >= 0.0) {
            throw new \DomainException('logisticlogmgf() requires |scale × t| < 1.');
        }

        $magnitude = exp($logMagnitude);
        $logScaleCorrection = $logMagnitude > log(0.5)
            ? log(M_PI) + $logMagnitude - log(sin(M_PI * -expm1($logMagnitude)))
            : -log(self::normalizedSinc([$magnitude]));

        return self::finiteSpecialResult($location * $tilt + $logScaleCorrection, 'logisticlogmgf');
    }

    /** @param list<int|float> $arguments */
