    {
        return self::finiteSpecialResult(exp(self::logisticLogMomentGeneratingFunction($arguments)), 'logisticmgf');
    }

    /** @param list<int|float> $arguments */
    private static function logisticRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $location, $scale] = self::logisticArguments([0.0, $arguments[1], $arguments[2]], 'logisticmoment');
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0 || $orderValue > 32) {
            throw new \DomainException('logisticmoment() requires an integer order in [0, 32].');
        }

        $order = (int) $orderValue;
        $moment = 0.0;
        $coefficient = 1.0;
        for ($centralOrder = 0; $centralOrder <= $order; ++$centralOrder) {
            if ($centralOrder > 0) {
                $coefficient *= ($order - $centralOrder + 1.0) / $centralOrder;
            }
            if ($centralOrder % 2 !== 0) {
                continue;
            }
            $centralMoment = $centralOrder === 0
                ? 1.0
                : 2.0 * (1.0 - 2.0 ** (1.0 - $centralOrder))
                    * exp(self::logGammaPositive($centralOrder + 1.0))
                    * self::zetaFunction([(float) $centralOrder])
                    * ($scale ** $centralOrder);
            $moment += $coefficient * ($location ** ($order - $centralOrder)) * $centralMoment;
        }

        return self::finiteSpecialResult($moment, 'logisticmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
