        $location = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($location)
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires finite value and location, and a positive finite scale.',
            );
        }

        return [$value, $location, $scale];
    }

