    /** @param list<int|float> $arguments */
    private static function laplaceLogProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale] = self::laplaceArguments($arguments, 'laplacelogpdf');
        $difference = $value - $location;
        $scaledDistance = is_finite($difference)
            ? abs($difference) / $scale
            : abs($value) / $scale + abs($location) / $scale;
        if (!is_finite($scaledDistance)) {
            throw new \OverflowException('laplacelogpdf() result exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(
            -$scaledDistance - log(2.0) - log($scale),
            'laplacelogpdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function laplaceCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::laplaceArguments($arguments, 'laplacecdf');
        $difference = $value - $location;
        if (!is_finite($difference)) {
            return $value < $location ? 0.0 : 1.0;
        }
        if ($difference < 0.0) {
            return 0.5 * exp($difference / $scale);
        }

        return 1.0 - 0.5 * exp(-$difference / $scale);
    }

    /** @param list<int|float> $arguments */
    private static function laplaceSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::laplaceArguments($arguments, 'laplaceccdf');
        $difference = $value - $location;
        if (!is_finite($difference)) {
            return $value < $location ? 1.0 : 0.0;
        }
        if ($difference < 0.0) {
            return 1.0 - 0.5 * exp($difference / $scale);
        }

        return 0.5 * exp(-$difference / $scale);
    }

    /** @param list<int|float> $arguments */
    private static function laplaceLogCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::laplaceArguments($arguments, 'laplacelogcdf');
        $difference = $value - $location;
        if (!\is_finite($difference)) {
            if ($value < $location) {
                return -INF;
            }
            return 0.0;
        }
        if ($difference < 0.0) {
            return self::finiteSpecialResult($difference / $scale - log(2.0), 'laplacelogcdf');
        }

        return log1p(-0.5 * exp(-$difference / $scale));
    }

    /** @param list<int|float> $arguments */
    private static function laplaceLogSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::laplaceArguments($arguments, 'laplacelogccdf');
        $difference = $value - $location;
        if (!\is_finite($difference)) {
            if ($value < $location) {
                return 0.0;
            }
            return -INF;
        }
        if ($difference >= 0.0) {
            return self::finiteSpecialResult(-$difference / $scale - log(2.0), 'laplacelogccdf');
        }

        return log1p(-0.5 * exp($difference / $scale));
    }

    /** @param list<int|float> $arguments */
    private static function inverseLaplaceCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $location, $scale] = self::laplaceArguments([0.0, $arguments[1], $arguments[2]], 'laplaceinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('laplaceinv() requires a probability strictly between 0 and 1.');
        }
        $offset = $probability < 0.5
            ? $scale * log(2.0 * $probability)
            : -$scale * log(2.0 * (1.0 - $probability));

        return self::finiteSpecialResult($location + $offset, 'laplaceinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLaplaceSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $location, $scale] = self::laplaceArguments([0.0, $arguments[1], $arguments[2]], 'laplaceccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('laplaceccinv() requires a survival probability strictly between 0 and 1.');
        }
        $offset = $probability <= 0.5
            ? -$scale * log(2.0 * $probability)
            : $scale * log(2.0) + $scale * log1p(-$probability);

        return self::finiteSpecialResult($location + $offset, 'laplaceccinv');
    }

