    /** @param list<int|float> $arguments */
    private static function laplaceLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $location, $scale] = self::laplaceArguments([0.0, $arguments[1], $arguments[2]], 'laplacelogmgf');
        if (!is_finite($tilt)) {
