        if (!is_finite($scaledTilt) || abs($scaledTilt) >= 1.0) {
            throw new \DomainException('laplacelogmgf() exists only when |t| < 1 / scale.');
        }

        return self::finiteSpecialResult(
            $location * $tilt - log1p(-$scaledTilt * $scaledTilt),
            'laplacelogmgf',
        );
    }

