        );
        if (!is_finite($tilt)) {
            throw new \DomainException('asymmetriclaplacelogmgf() requires a finite real argument.');
        }
        $leftProduct = $leftScale * $tilt;
        $rightProduct = $rightScale * $tilt;
        if (!is_finite($leftProduct) || !is_finite($rightProduct) || $leftProduct <= -1.0 || $rightProduct >= 1.0) {
            throw new \DomainException(
                'asymmetriclaplacelogmgf() exists only for -1 / leftScale < t < 1 / rightScale.',
            );
        }

        return self::finiteSpecialResult(
            $location * $tilt - log1p($leftProduct) - log1p(-$rightProduct),
            'asymmetriclaplacelogmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function asymmetricLaplaceMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::asymmetricLaplaceLogMomentGeneratingFunction($arguments)),
            'asymmetriclaplacemgf',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float, float, float, float, float}
     */
    private static function asymmetricLaplaceArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $location = (float) $arguments[1];
        $leftScale = (float) $arguments[2];
        $rightScale = (float) $arguments[3];
        if (
            !is_finite($value)
            || !is_finite($location)
            || !is_finite($leftScale)
            || $leftScale <= 0.0
            || !is_finite($rightScale)
            || $rightScale <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires finite x and location and positive finite left and right scales.',
            );
        }

        $largerScale = max($leftScale, $rightScale);
        $smallerScale = min($leftScale, $rightScale);
        $logNormalizer = log($largerScale) + log1p($smallerScale / $largerScale);
        $leftWeight = exp(log($leftScale) - $logNormalizer);
        $rightWeight = exp(log($rightScale) - $logNormalizer);

        return [$value, $location, $leftScale, $rightScale, $logNormalizer, $leftWeight, $rightWeight];
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionProbabilityDensity(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'fpdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($numeratorDegrees < 2.0) {
                throw new \DomainException('fpdf() is singular at zero when numerator degrees of freedom are below 2.');
            }
            if ($numeratorDegrees === 2.0) {
                return 1.0;
            }
            return 0.0;
        }

        $a = $numeratorDegrees / 2.0;
        $b = $denominatorDegrees / 2.0;
        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);
        $logOnePlusOdds = self::logOnePlusExp($logOdds);
        $logDensity = $a * (log($numeratorDegrees) - log($denominatorDegrees))
            + ($a - 1.0) * log($value)
            - ($a + $b) * $logOnePlusOdds
            - (self::logGammaPositive($a) + self::logGammaPositive($b) - self::logGammaPositive($a + $b));

        return self::finiteSpecialResult(exp($logDensity), 'fpdf');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionLogProbabilityDensity(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'flogpdf');
        if ($value < 0.0 || $value === 0.0 && $numeratorDegrees !== 2.0) {
            throw new \DomainException('flogpdf() has no finite log-density value at this x.');
        }

        $a = $numeratorDegrees / 2.0;
        $b = $denominatorDegrees / 2.0;
        if ($value === 0.0) {
            return 0.0;
        }

        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);
        $logOnePlusOdds = self::logOnePlusExp($logOdds);
        $logDensity = $a * (log($numeratorDegrees) - log($denominatorDegrees))
            + ($a - 1.0) * log($value)
            - ($a + $b) * $logOnePlusOdds
            - (self::logGammaPositive($a) + self::logGammaPositive($b) - self::logGammaPositive($a + $b));

        return self::finiteSpecialResult($logDensity, 'flogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionCumulativeDistribution(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'fcdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);
        $betaArgument = self::logisticUnitArgument($logOdds);

        return self::regularizedBetaValue($numeratorDegrees / 2.0, $denominatorDegrees / 2.0, $betaArgument);
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionSurvivalFunction(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'fccdf');
        if ($value <= 0.0) {
            return 1.0;
        }
        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);
        $betaArgument = self::logisticUnitArgument(-$logOdds);

        return self::regularizedBetaValue($denominatorDegrees / 2.0, $numeratorDegrees / 2.0, $betaArgument);
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionLogCumulativeDistribution(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'flogcdf');
        if ($value <= 0.0) {
            throw new \DomainException('flogcdf() is negative infinity for non-positive x.');
        }

        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);

        return self::regularizedBetaLogLowerFromLogs(
            $numeratorDegrees / 2.0,
            $denominatorDegrees / 2.0,
            -self::logOnePlusExp(-$logOdds),
            -self::logOnePlusExp($logOdds),
        );
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionLogSurvivalFunction(array $arguments): float
    {
        [$value, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments($arguments, 'flogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $logOdds = log($numeratorDegrees) + log($value) - log($denominatorDegrees);

        return self::regularizedBetaLogLowerFromLogs(
            $denominatorDegrees / 2.0,
            $numeratorDegrees / 2.0,
            -self::logOnePlusExp($logOdds),
            -self::logOnePlusExp(-$logOdds),
        );
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionHazard(array $arguments): float
    {
        [$value, $numeratorDegrees] = self::fDistributionArguments($arguments, 'fhazard');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($numeratorDegrees < 2.0) {
                throw new \DomainException(
                    'fhazard() is singular at zero when numerator degrees of freedom are below 2.',
                );
            }

            return $numeratorDegrees === 2.0 ? 1.0 : 0.0;
        }

        $logHazard = self::fDistributionLogProbabilityDensity($arguments)
            - self::fDistributionLogSurvivalFunction($arguments);
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('fhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'fhazard');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionCumulativeHazard(array $arguments): float
    {
        [$value] = self::fDistributionArguments($arguments, 'fcumhazard');
        if ($value < 0.0) {
            return 0.0;
        }

        return -self::fDistributionLogSurvivalFunction($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function inverseFDistributionCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'finv',
        );
        if (!is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('finv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }
        if ($probability <= 0.5) {
            $betaArgument = self::inverseRegularizedBetaValue(
                $numeratorDegrees / 2.0,
                $denominatorDegrees / 2.0,
                $probability,
            );
            if ($betaArgument >= 1.0) {
                throw new \OverflowException('finv() quantile is outside the finite floating-point range.');
            }
            $logOdds = log($betaArgument) - log1p(-$betaArgument);
        } else {
            $complementArgument = self::inverseRegularizedBetaValue(
                $denominatorDegrees / 2.0,
                $numeratorDegrees / 2.0,
                1.0 - $probability,
            );
            if ($complementArgument <= 0.0) {
                throw new \OverflowException('finv() quantile is outside the finite floating-point range.');
            }
            $logOdds = log1p(-$complementArgument) - log($complementArgument);
        }
        $logQuantile = log($denominatorDegrees) - log($numeratorDegrees) + $logOdds;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('finv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'finv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseFDistributionSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'fccinv',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('fccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        $betaArgument = self::inverseRegularizedBetaValue(
            $denominatorDegrees / 2.0,
            $numeratorDegrees / 2.0,
            $probability,
        );
        if ($betaArgument <= 0.0 || $betaArgument >= 1.0) {
            throw new \OverflowException('fccinv() quantile is outside the finite floating-point range.');
        }
        $logQuantile = log($denominatorDegrees) - log($numeratorDegrees)
            + log1p(-$betaArgument) - log($betaArgument);
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('fccinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'fccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseFDistributionQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'finvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('finvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseFDistributionCumulativeDistribution(
            [$probability, $numeratorDegrees, $denominatorDegrees],
        );
        $logDerivative = -self::fDistributionLogProbabilityDensity(
            [$quantile, $numeratorDegrees, $denominatorDegrees],
        );
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('finvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'finvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseFDistributionSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'fccinvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('fccinvprime() requires a survival probability strictly between 0 and 1.');
        }

        $quantile = self::inverseFDistributionSurvivalFunction(
            [$probability, $numeratorDegrees, $denominatorDegrees],
        );
        $logDerivative = -self::fDistributionLogProbabilityDensity(
            [$quantile, $numeratorDegrees, $denominatorDegrees],
        );
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('fccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'fccinvprime');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function fDistributionArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $numeratorDegrees = (float) $arguments[1];
        $denominatorDegrees = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($numeratorDegrees)
            || !is_finite($denominatorDegrees)
            || $numeratorDegrees <= 0.0
            || $denominatorDegrees <= 0.0
            || $numeratorDegrees + $denominatorDegrees > 20_000.0
        ) {
            throw new \DomainException(
                $function . '() requires finite x and positive degrees of freedom whose sum is at most 20000.',
            );
        }

        return [$value, $numeratorDegrees, $denominatorDegrees];
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionMean(array $arguments): float
    {
        [, , $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionmean',
        );
        if ($denominatorDegrees <= 2.0) {
            throw new \DomainException('fdistributionmean() exists only when denominator degrees exceed 2.');
        }

        return $denominatorDegrees / ($denominatorDegrees - 2.0);
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionMedian(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionmedian',
        );

        return self::inverseFDistributionCumulativeDistribution([0.5, $numeratorDegrees, $denominatorDegrees]);
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionMode(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionmode',
        );
        if ($numeratorDegrees <= 2.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            (($numeratorDegrees - 2.0) * $denominatorDegrees)
                / ($numeratorDegrees * ($denominatorDegrees + 2.0)),
            'fdistributionmode',
        );
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionDifferentialEntropy(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionentropy',
        );
        $alpha = $numeratorDegrees / 2.0;
        $beta = $denominatorDegrees / 2.0;
        $total = $alpha + $beta;
        $entropy = self::logGammaPositive($alpha) + self::logGammaPositive($beta)
            - self::logGammaPositive($total)
            - log($numeratorDegrees / $denominatorDegrees)
            - ($alpha - 1.0) * self::digammaFunction([$alpha])
            - ($beta + 1.0) * self::digammaFunction([$beta])
            + $total * self::digammaFunction([$total]);

        return self::finiteSpecialResult($entropy, 'fdistributionentropy');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionVariance(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionvariance',
        );
        if ($denominatorDegrees <= 4.0) {
            throw new \DomainException('fdistributionvariance() exists only when denominator degrees exceed 4.');
        }
        $numerator = 2.0 * $denominatorDegrees ** 2
            * ($numeratorDegrees + $denominatorDegrees - 2.0);
        $denominator = $numeratorDegrees * ($denominatorDegrees - 2.0) ** 2 * ($denominatorDegrees - 4.0);

        return self::finiteSpecialResult($numerator / $denominator, 'fdistributionvariance');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionSkewness(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionskewness',
        );
        if ($denominatorDegrees <= 6.0) {
            throw new \DomainException('fdistributionskewness() exists only when denominator degrees exceed 6.');
        }
        $skewness = (2.0 * $numeratorDegrees + $denominatorDegrees - 2.0)
            * sqrt(8.0 * ($denominatorDegrees - 4.0))
            / (($denominatorDegrees - 6.0)
                * sqrt($numeratorDegrees * ($numeratorDegrees + $denominatorDegrees - 2.0)));

        return self::finiteSpecialResult($skewness, 'fdistributionskewness');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionExcessKurtosis(array $arguments): float
    {
        [, $numeratorDegrees, $denominatorDegrees] = self::fDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'fdistributionexcesskurtosis',
        );
        if ($denominatorDegrees <= 8.0) {
            throw new \DomainException(
                'fdistributionexcesskurtosis() exists only when denominator degrees exceed 8.',
            );
        }
        $totalMinusTwo = $numeratorDegrees + $denominatorDegrees - 2.0;
        $numerator = 12.0 * (
            $numeratorDegrees * (5.0 * $denominatorDegrees - 22.0) * $totalMinusTwo
            + ($denominatorDegrees - 4.0) * ($denominatorDegrees - 2.0) ** 2
        );
        $denominator = $numeratorDegrees * ($denominatorDegrees - 6.0) * ($denominatorDegrees - 8.0)
            * $totalMinusTwo;
        if ($denominator === 0.0) {
            throw new \OverflowException('fdistributionexcesskurtosis() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult($numerator / $denominator, 'fdistributionexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function fDistributionKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::fDistributionExcessKurtosis($arguments),
            'fdistributionkurtosis',
        );
    }

    private static function logOnePlusExp(float $value): float
    {
        return $value > 0.0 ? $value + log1p(exp(-$value)) : log1p(exp($value));
    }

    private static function logisticUnitArgument(float $logOdds): float
    {
        if ($logOdds >= 0.0) {
            $tail = exp(-$logOdds);

            return 1.0 / (1.0 + $tail);
        }
        $odds = exp($logOdds);

        return $odds / (1.0 + $odds);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionProbabilityDensity(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );
        if ($value === 0.0) {
            if ($alpha < 1.0) {
                throw new \DomainException('betapdf() is singular at zero when alpha is below 1.');
            }

            return $alpha === 1.0 ? $beta : 0.0;
        }
        if ($value === 1.0) {
            if ($beta < 1.0) {
                throw new \DomainException('betapdf() is singular at one when beta is below 1.');
            }

            return $beta === 1.0 ? $alpha : 0.0;
        }
        $logBeta = self::logGammaPositive($alpha)
            + self::logGammaPositive($beta)
            - self::logGammaPositive($alpha + $beta);
        $logDensity = ($alpha - 1.0) * log($value)
            + ($beta - 1.0) * log1p(-$value)
            - $logBeta;

        return self::finiteSpecialResult(exp($logDensity), 'betapdf');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionLogProbabilityDensity(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );
        if ($value === 0.0) {
            if ($alpha !== 1.0) {
                throw new \DomainException('betalogpdf() has no finite value at zero unless alpha is one.');
            }

            return self::finiteSpecialResult(log($beta), 'betalogpdf');
        }
        if ($value === 1.0) {
            if ($beta !== 1.0) {
                throw new \DomainException('betalogpdf() has no finite value at one unless beta is one.');
            }

            return self::finiteSpecialResult(log($alpha), 'betalogpdf');
        }

        $logBeta = self::logGammaPositive($alpha)
            + self::logGammaPositive($beta)
            - self::logGammaPositive($alpha + $beta);
        $logDensity = ($alpha - 1.0) * log($value)
            + ($beta - 1.0) * log1p(-$value)
            - $logBeta;

        return self::finiteSpecialResult($logDensity, 'betalogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammapdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('gammapdf() is singular at zero when shape is below 1.');
            }
            if ($shape === 1.0) {
                return self::finiteSpecialResult(1.0 / $scale, 'gammapdf');
            }

            return 0.0;
        }
        $logDensity = ($shape - 1.0) * log($value)
            - $value / $scale
            - self::logGammaPositive($shape)
            - $shape * log($scale);

        return self::finiteSpecialResult(exp($logDensity), 'gammapdf');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionLogProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammalogpdf');
        if ($value < 0.0) {
            throw new \DomainException('gammalogpdf() is undefined where the gamma density is zero.');
        }
        if ($value === 0.0) {
            if ($shape !== 1.0) {
                throw new \DomainException('gammalogpdf() has no finite value at zero unless shape is one.');
            }

            return self::finiteSpecialResult(-log($scale), 'gammalogpdf');
        }

        $scaledValue = $value / $scale;
        if (!is_finite($scaledValue)) {
            throw new \OverflowException('gammalogpdf() is below the finite floating-point range.');
        }
        $logDensity = ($shape - 1.0) * log($value)
            - $scaledValue
            - self::logGammaPositive($shape)
            - $shape * log($scale);

        return self::finiteSpecialResult($logDensity, 'gammalogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammacdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        $standardized = $value / $scale;
        if (!is_finite($standardized)) {
            return 1.0;
        }

        return self::regularizedGammaLower([$shape, $standardized]);
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammaccdf');
        if ($value <= 0.0) {
            return 1.0;
        }
        $standardized = $value / $scale;
        if (!is_finite($standardized)) {
            return 0.0;
        }

        return self::regularizedGammaUpper([$shape, $standardized]);
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionLogCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammadistlogcdf');
        if ($value <= 0.0) {
            throw new \DomainException('gammadistlogcdf() has no finite log probability for non-positive x.');
        }

        $standardized = $value / $scale;
        if (!is_finite($standardized)) {
            return 0.0;
        }

        return self::regularizedGammaLowerLogValue(
            $shape,
            $standardized,
            log($value) - log($scale),
        );
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionLogSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammadistlogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $standardized = $value / $scale;
        if (!is_finite($standardized)) {
            throw new \OverflowException('gammadistlogccdf() log probability exceeds the finite range.');
        }

        return self::regularizedGammaUpperLogValue($shape, $standardized);
    }

    private static function regularizedGammaLowerLogValue(float $shape, float $value, float $logValue): float
    {
        if ($value === 0.0) {
            return self::finiteSpecialResult(
                $shape * $logValue - self::logGammaPositive($shape + 1.0),
                'gammadistlogcdf',
            );
        }
        if ($value >= $shape + 1.0) {
            return self::logOneMinusExponential([
                self::regularizedGammaUpperLogValue($shape, $value),
            ]);
        }

        $term = 1.0 / $shape;
        $sum = $term;
        for ($index = 1; $index <= 10000; ++$index) {
            $term *= $value / ($shape + $index);
            $sum += $term;
            if (abs($term) <= abs($sum) * 1.0E-15) {
                break;
            }
        }

        return self::finiteSpecialResult(
            -$value + $shape * $logValue - self::logGammaPositive($shape) + log($sum),
            'gammadistlogcdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseGammaDistributionCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::gammaDistributionArguments([0.0, $arguments[1], $arguments[2]], 'gammainv');
        if (!is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('gammainv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }
        $standardizedQuantile = $probability < 0.5
            ? self::inverseRegularizedGammaValue($shape, $probability)
            : self::inverseRegularizedGammaUpperValue($shape, 1.0 - $probability);

        return self::finiteSpecialResult($scale * $standardizedQuantile, 'gammainv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseGammaDistributionSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'gammaccinv',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('gammaccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            $scale * self::inverseRegularizedGammaUpperValue($shape, $probability),
            'gammaccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseGammaDistributionQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'gammadistinvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('gammadistinvprime() requires a probability strictly between 0 and 1.');
        }

        $derivative = self::inverseRegularizedGammaLowerDerivative([$shape, $probability]);

        return self::finiteSpecialResult($scale * $derivative, 'gammadistinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseGammaDistributionSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'gammadistccinvprime',
        );
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'gammadistccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $derivative = self::inverseRegularizedGammaUpperDerivative([$shape, $probability]);

        return self::finiteSpecialResult($scale * $derivative, 'gammadistccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionMean(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments([0.0, $arguments[0], $arguments[1]], 'gammadistmean');

        return self::finiteSpecialResult($shape * $scale, 'gammadistmean');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionMedian(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadistmedian',
        );

        return self::inverseGammaDistributionCumulativeDistribution([0.5, $shape, $scale]);
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionMode(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadistmode',
        );

        return $shape <= 1.0
            ? 0.0
            : self::finiteSpecialResult(($shape - 1.0) * $scale, 'gammadistmode');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionDifferentialEntropy(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadistentropy',
        );
        $entropy = $shape + log($scale) + self::logGammaPositive($shape)
            + (1.0 - $shape) * self::digammaFunction([$shape]);

        return self::finiteSpecialResult($entropy, 'gammadistentropy');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::gammaDistributionArguments($arguments, 'gammadisthazard');
        if ($value < 0.0) {
            throw new \DomainException('gammadisthazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('gammadisthazard() is singular at zero when shape is below 1.');
            }

            return $shape === 1.0
                ? self::finiteSpecialResult(1.0 / $scale, 'gammadisthazard')
                : 0.0;
        }
        if (!is_finite($value / $scale)) {
            return self::finiteSpecialResult(1.0 / $scale, 'gammadisthazard');
        }
        $logHazard = self::gammaDistributionLogProbabilityDensity($arguments)
            - self::gammaDistributionLogSurvivalFunction($arguments);
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('gammadisthazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'gammadisthazard');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionCumulativeHazard(array $arguments): float
    {
        [$value] = self::gammaDistributionArguments($arguments, 'gammadistcumhazard');
        if ($value < 0.0) {
            throw new \DomainException('gammadistcumhazard() requires x >= 0.');
        }

        return -self::gammaDistributionLogSurvivalFunction($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionVariance(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadistvariance',
        );
        $standardDeviation = sqrt($shape) * $scale;

        return self::finiteSpecialResult($standardDeviation * $standardDeviation, 'gammadistvariance');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionStandardDeviation(array $arguments): float
    {
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadiststddev',
        );

        return self::finiteSpecialResult(sqrt($shape) * $scale, 'gammadiststddev');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionSkewness(array $arguments): float
    {
        [, $shape] = self::gammaDistributionArguments([0.0, $arguments[0], $arguments[1]], 'gammadistskewness');

        return self::finiteSpecialResult(2.0 / sqrt($shape), 'gammadistskewness');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionExcessKurtosis(array $arguments): float
    {
        [, $shape] = self::gammaDistributionArguments(
            [0.0, $arguments[0], $arguments[1]],
            'gammadistexcesskurtosis',
        );

        return self::finiteSpecialResult(6.0 / $shape, 'gammadistexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(3.0 + self::gammaDistributionExcessKurtosis($arguments), 'gammadistkurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'gammadistlogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('gammadistlogmgf() requires a finite argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logScaleTilt = log($scale) + log(abs($tilt));
        if ($tilt > 0.0) {
            if ($logScaleTilt >= 0.0) {
                throw new \DomainException('gammadistlogmgf() requires t < 1/scale.');
            }
            $logDenominator = self::logOneMinusExponential([$logScaleTilt]);
        } else {
            $logDenominator = $logScaleTilt > 0.0
                ? $logScaleTilt + log1p(exp(-$logScaleTilt))
                : log1p(exp($logScaleTilt));
        }

        return self::finiteSpecialResult(-$shape * $logDenominator, 'gammadistlogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::gammaDistributionLogMomentGeneratingFunction($arguments)),
            'gammadistmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function gammaDistributionRawMoment(array $arguments): float
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'gammadistmoment');
        if ($order > 64) {
            throw new \DomainException('gammadistmoment() requires an integer order from 0 through 64.');
        }
        [, $shape, $scale] = self::gammaDistributionArguments(
            [0.0, $arguments[1], $arguments[2]],
            'gammadistmoment',
        );
        if ($order === 0) {
            return 1.0;
        }

        $logMoment = $order * log($scale);
        for ($index = 0; $index < $order; ++$index) {
            $logMoment += log($shape + $index);
        }
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('gammadistmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'gammadistmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function gammaDistributionArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $shape = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($shape)
            || $shape <= 0.0
            || $shape > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires finite x, shape in (0, 10000], and positive finite scale.',
            );
        }

        return [$value, $shape, $scale];
    }

    /** @param list<int|float> $arguments */
    private static function cauchyProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchypdf');
        $difference = $value - $location;
        $standardized = $difference / $scale;
        if (!is_finite($standardized)) {
            return 0.0;
        }
        $logSquaredTerm = abs($standardized) <= 1.0
            ? log1p($standardized * $standardized)
            : 2.0 * log(abs($standardized)) + log1p(1.0 / ($standardized * $standardized));

        return self::finiteSpecialResult(
            exp(-log(M_PI) - log($scale) - $logSquaredTerm),
            'cauchypdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function cauchyLogProbabilityDensity(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchylogpdf');
        $difference = $value - $location;
        if (is_finite($difference)) {
            $logMagnitude = $difference === 0.0 ? -INF : log(abs($difference)) - log($scale);
        } else {
            $logMagnitude = self::stableLogSumExp([log(abs($value)), log(abs($location))]) - log($scale);
        }
        $twiceLogMagnitude = 2.0 * $logMagnitude;
        $logSquaredTerm = $twiceLogMagnitude <= 0.0
            ? log1p(exp($twiceLogMagnitude))
            : $twiceLogMagnitude + log1p(exp(-$twiceLogMagnitude));

        return self::finiteSpecialResult(-log(M_PI) - log($scale) - $logSquaredTerm, 'cauchylogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchycdf');
        $standardized = ($value - $location) / $scale;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 0.0 : 1.0;
        }
        if ($standardized >= 0.0) {
            return 0.5 + atan($standardized) / M_PI;
        }

        return atan2(1.0, -$standardized) / M_PI;
    }

    /** @param list<int|float> $arguments */
    private static function cauchySurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchyccdf');
        $standardized = ($value - $location) / $scale;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 1.0 : 0.0;
        }
        if ($standardized >= 0.0) {
            return atan2(1.0, $standardized) / M_PI;
        }

        return 0.5 - atan($standardized) / M_PI;
    }

    /** @param list<int|float> $arguments */
    private static function cauchyLogCumulativeDistribution(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchylogcdf');
        $logMagnitude = self::cauchyLogStandardizedMagnitude($value, $location, $scale);
        if ($value < $location) {
            return self::finiteSpecialResult(self::cauchyLogSmallTail($logMagnitude), 'cauchylogcdf');
        }

        return self::finiteSpecialResult(log1p(-exp(self::cauchyLogSmallTail($logMagnitude))), 'cauchylogcdf');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyLogSurvivalFunction(array $arguments): float
    {
        [$value, $location, $scale] = self::cauchyArguments($arguments, 'cauchylogccdf');
        $logMagnitude = self::cauchyLogStandardizedMagnitude($value, $location, $scale);
        if ($value > $location) {
            return self::finiteSpecialResult(self::cauchyLogSmallTail($logMagnitude), 'cauchylogccdf');
        }

        return self::finiteSpecialResult(log1p(-exp(self::cauchyLogSmallTail($logMagnitude))), 'cauchylogccdf');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyHazard(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::cauchyLogProbabilityDensity($arguments) - self::cauchyLogSurvivalFunction($arguments)),
            'cauchyhazard',
        );
    }

    /** @param list<int|float> $arguments */
    private static function cauchyCumulativeHazard(array $arguments): float
    {
        return self::finiteSpecialResult(-self::cauchyLogSurvivalFunction($arguments), 'cauchycumhazard');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyCharacteristicReal(array $arguments): float
    {
        [$tilt, $location, $scale] = self::cauchyArguments($arguments, 'cauchycharfuncreal');
        $phase = $location * $tilt;
        if (!is_finite($phase)) {
            throw new \OverflowException('cauchycharfuncreal() phase exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp(-$scale * abs($tilt)) * cos($phase), 'cauchycharfuncreal');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyCharacteristicImaginary(array $arguments): float
    {
        [$tilt, $location, $scale] = self::cauchyArguments($arguments, 'cauchycharfuncimag');
        $phase = $location * $tilt;
        if (!is_finite($phase)) {
            throw new \OverflowException('cauchycharfuncimag() phase exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp(-$scale * abs($tilt)) * sin($phase), 'cauchycharfuncimag');
    }

    /** @param list<int|float> $arguments */
    private static function cauchyAbsoluteMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, , $scale] = self::cauchyArguments([0.0, $arguments[1], $arguments[2]], 'cauchyabsmoment');
        if (!is_finite($order) || $order < 0.0 || $order >= 1.0) {
            throw new \DomainException('cauchyabsmoment() requires a finite absolute-moment order in [0, 1).');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            exp($order * log($scale) - log(cos(M_PI * $order / 2.0))),
            'cauchyabsmoment',
        );
    }

    private static function cauchyLogStandardizedMagnitude(float $value, float $location, float $scale): float
    {
        $difference = $value - $location;
        if ($difference === 0.0) {
            return -INF;
        }
        $logDifference = is_finite($difference)
            ? log(abs($difference))
            : self::stableLogSumExp([log(abs($value)), log(abs($location))]);

        return $logDifference - log($scale);
    }

    private static function cauchyLogSmallTail(float $logMagnitude): float
    {
        if ($logMagnitude === -INF) {
            return log(0.5);
        }
        if ($logMagnitude > 350.0) {
            return -$logMagnitude - log(M_PI);
        }
        $standardized = exp($logMagnitude);

        return log(atan2(1.0, $standardized)) - log(M_PI);
    }

    /** @param list<int|float> $arguments */
    private static function inverseCauchyCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $location, $scale] = self::cauchyArguments([0.0, $arguments[1], $arguments[2]], 'cauchyinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('cauchyinv() requires a probability strictly between 0 and 1.');
        }
        if ($probability === 0.5) {
            return $location;
        }
        $tailProbability = min($probability, 1.0 - $probability);
        $distance = $scale / tan(M_PI * $tailProbability);
        $quantile = $probability < 0.5 ? $location - $distance : $location + $distance;

        return self::finiteSpecialResult($quantile, 'cauchyinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseCauchySurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $location, $scale] = self::cauchyArguments([0.0, $arguments[1], $arguments[2]], 'cauchyccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('cauchyccinv() requires a survival probability strictly between 0 and 1.');
        }
        if ($probability === 0.5) {
            return $location;
        }
        $tailProbability = min($probability, 1.0 - $probability);
        $distance = $scale / tan(M_PI * $tailProbability);
        $quantile = $probability < 0.5 ? $location + $distance : $location - $distance;

        return self::finiteSpecialResult($quantile, 'cauchyccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseCauchyQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, , $scale] = self::cauchyArguments([0.0, $arguments[1], $arguments[2]], 'cauchyinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('cauchyinvprime() requires a probability strictly between 0 and 1.');
        }

        return self::cauchyInverseQuantileDerivativeValue($probability, $scale, 'cauchyinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseCauchySurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, , $scale] = self::cauchyArguments([0.0, $arguments[1], $arguments[2]], 'cauchyccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'cauchyccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        return -self::cauchyInverseQuantileDerivativeValue($probability, $scale, 'cauchyccinvprime');
    }

    private static function cauchyInverseQuantileDerivativeValue(
        float $probability,
        float $scale,
        string $function,
    ): float {
        $logDerivative = log($scale) - log(M_PI) - log($probability) - log1p(-$probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), $function);
    }

    /** @param list<int|float> $arguments */
    private static function cauchyMedian(array $arguments): float
    {
        [, $location] = self::cauchyArguments([0.0, $arguments[0], $arguments[1]], 'cauchymedian');

        return $location;
    }

    /** @param list<int|float> $arguments */
    private static function cauchyMode(array $arguments): float
    {
        [, $location] = self::cauchyArguments([0.0, $arguments[0], $arguments[1]], 'cauchymode');

        return $location;
    }

    /** @param list<int|float> $arguments */
    private static function cauchyDifferentialEntropy(array $arguments): float
    {
        [, , $scale] = self::cauchyArguments([0.0, $arguments[0], $arguments[1]], 'cauchyentropy');

        return self::finiteSpecialResult(log(4.0 * M_PI) + log($scale), 'cauchyentropy');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function cauchyArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $location = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($location)
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires finite value and location, and a positive finite scale.',
            );
        }

        return [$value, $location, $scale];
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticpdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('loglogisticpdf() is singular at zero when shape is below 1.');
            }

            return $shape === 1.0
                ? self::finiteSpecialResult(1.0 / $scale, 'loglogisticpdf')
                : 0.0;
        }

        $logRatio = \log($value) - \log($scale);
        $logOdds = $shape * $logRatio;
        $logOddsTerm = $logOdds > 0.0
            ? -$logOdds - 2.0 * \log1p(\exp(-$logOdds))
            : $logOdds - 2.0 * \log1p(\exp($logOdds));
        $logDensity = \log($shape) - \log($value) + $logOddsTerm;

        return self::finiteSpecialResult(\exp($logDensity), 'loglogisticpdf');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticLogProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticlogpdf');
        if ($value < 0.0) {
            return -INF;
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                return INF;
            }
            return $shape === 1.0 ? -log($scale) : -INF;
        }

        $logOdds = $shape * (log($value) - log($scale));
        $logOddsTerm = $logOdds > 0.0
            ? -$logOdds - 2.0 * log1p(exp(-$logOdds))
            : $logOdds - 2.0 * log1p(exp($logOdds));

        return log($shape) - log($value) + $logOddsTerm;
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticcdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        $logOdds = $shape * (\log($value) - \log($scale));

        return self::logisticUnitArgument($logOdds);
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        $logOdds = $shape * (\log($value) - \log($scale));

        return self::logisticUnitArgument(-$logOdds);
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticLogCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticlogcdf');
        if ($value <= 0.0) {
            return -INF;
        }
        $logOdds = $shape * (log($value) - log($scale));
        return $logOdds >= 0.0
            ? -log1p(exp(-$logOdds))
            : $logOdds - log1p(exp($logOdds));
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticLogSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticlogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        $logOdds = $shape * (log($value) - log($scale));
        return $logOdds >= 0.0
            ? -$logOdds - log1p(exp(-$logOdds))
            : -log1p(exp($logOdds));
    }

    /** @param list<int|float> $arguments */
    private static function inverseLogLogisticCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[1], $arguments[2]], 'loglogisticinv');
        if (!\is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('loglogisticinv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }

        $logQuantile = \log($scale)
            + (\log($probability) - \log1p(-$probability)) / $shape;
        if ($logQuantile > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('loglogisticinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(\exp($logQuantile), 'loglogisticinv');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $shape, $scale] = self::logLogisticArguments(
            [0.0, $arguments[1], $arguments[2]],
            'loglogisticmoment',
        );
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('loglogisticmoment() requires an integer order from 0 through 64.');
        }
        if ($order >= $shape) {
            throw new \DomainException(
                'loglogisticmoment() exists only when the log-logistic shape exceeds the order.',
            );
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $ratio = $order / $shape;
        $logShapeFactor = $ratio < 0.5
            ? -log(self::normalizedSinc([$ratio]))
            : log(M_PI) + log($ratio) - log(sin(M_PI * (($shape - $order) / $shape)));
        $logMoment = $order * log($scale) + $logShapeFactor;
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('loglogisticmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'loglogisticmoment');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticMean(array $arguments): float
    {
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticmean');

        return self::logLogisticRawMoment([1.0, $shape, $scale]);
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticMedian(array $arguments): float
    {
        [, , $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticmedian');

        return $scale;
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticMode(array $arguments): float
    {
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticmode');
        if ($shape <= 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            exp(log($scale) + (log($shape - 1.0) - log($shape + 1.0)) / $shape),
            'loglogisticmode',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticVariance(array $arguments): float
    {
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticvariance');
        if ($shape <= 2.0) {
            throw new \DomainException('loglogisticvariance() exists only when shape exceeds 2.');
        }
        $logVariance = 2.0 * log($scale) + self::logLogisticRelativeVariance($shape);
        if ($logVariance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('loglogisticvariance() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logVariance), 'loglogisticvariance');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticStandardDeviation(array $arguments): float
    {
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticstddev');
        if ($shape <= 2.0) {
            throw new \DomainException('loglogisticstddev() exists only when shape exceeds 2.');
        }

        return self::finiteSpecialResult(
            exp(log($scale) + 0.5 * self::logLogisticRelativeVariance($shape)),
            'loglogisticstddev',
        );
    }

    private static function logLogisticRelativeVariance(float $shape): float
    {
        $angle = M_PI / $shape;
        if ($angle < 1.0e-3) {
            $angleSquared = $angle * $angle;
            $relativeVarianceFactor = 1.0 / 3.0 + (11.0 / 45.0) * $angleSquared
                + (38.0 / 315.0) * $angleSquared * $angleSquared;

            return 2.0 * log($angle) + log($relativeVarianceFactor);
        }
        $sine = sin($angle);
        $relativeVariance = ($angle / $sine) * (1.0 / cos($angle) - $angle / $sine);

        return log($relativeVariance);
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticDifferentialEntropy(array $arguments): float
    {
        [, $shape, $scale] = self::logLogisticArguments([0.0, $arguments[0], $arguments[1]], 'loglogisticentropy');

        return self::finiteSpecialResult(2.0 + log($scale) - log($shape), 'loglogisticentropy');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogistichazard');
        if ($value < 0.0) {
            throw new \DomainException('loglogistichazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            if ($shape < 1.0) {
                throw new \DomainException('loglogistichazard() is singular at zero when shape is below 1.');
            }

            return $shape === 1.0
                ? self::finiteSpecialResult(1.0 / $scale, 'loglogistichazard')
                : 0.0;
        }
        $logRatio = log($value) - log($scale);
        $logPower = $shape * $logRatio;
        if ($logPower > 36.0) {
            $logHazard = log($shape) - log($value) - log1p(exp(-$logPower));
        } else {
            $logSoftplus = max($logPower, 0.0) + log1p(exp(-abs($logPower)));
            $logHazard = log($shape) - log($scale) + ($shape - 1.0) * $logRatio - $logSoftplus;
        }
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('loglogistichazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'loglogistichazard');
    }

    /** @param list<int|float> $arguments */
    private static function logLogisticCumulativeHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::logLogisticArguments($arguments, 'loglogisticcumhazard');
        if ($value < 0.0) {
            throw new \DomainException('loglogisticcumhazard() requires x >= 0.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        $logPower = $shape * (log($value) - log($scale));
        $cumulativeHazard = max($logPower, 0.0) + log1p(exp(-abs($logPower)));

        return self::finiteSpecialResult($cumulativeHazard, 'loglogisticcumhazard');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function logLogisticArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $shape = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !\is_finite($value)
            || !\is_finite($shape)
            || $shape <= 0.0
            || !\is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException($function . '() requires finite x and positive finite shape and scale.');
        }

        return [$value, $shape, $scale];
    }

    /** @param list<int|float> $arguments */
    private static function paretoProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretopdf');
        if ($value < $minimum) {
            return 0.0;
        }
        $logRatio = log($value) - log($minimum);
        $logDensity = log($shape) - log($minimum) - ($shape + 1.0) * $logRatio;

        return self::finiteSpecialResult(exp($logDensity), 'paretopdf');
    }

    /** @param list<int|float> $arguments */
    private static function paretoLogProbabilityDensity(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretologpdf');
        if ($value < $minimum) {
            return -INF;
        }
        $logRatio = log($value) - log($minimum);

        return log($shape) - log($minimum) - ($shape + 1.0) * $logRatio;
    }

    /** @param list<int|float> $arguments */
    private static function paretoCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretocdf');
        if ($value < $minimum) {
            return 0.0;
        }
        if ($value === $minimum) {
            return 0.0;
        }
        $logSurvival = -$shape * (log($value) - log($minimum));

        return $logSurvival === -INF ? 1.0 : -expm1($logSurvival);
    }

    /** @param list<int|float> $arguments */
    private static function paretoSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretoccdf');
        if ($value <= $minimum) {
            return 1.0;
        }
        $logSurvival = -$shape * (log($value) - log($minimum));

        return exp($logSurvival);
    }

    /** @param list<int|float> $arguments */
    private static function paretoLogCumulativeDistribution(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretologcdf');
        if ($value <= $minimum) {
            return -INF;
        }
        $logSurvival = -$shape * (log($value) - log($minimum));

        return self::logOneMinusExponential([$logSurvival]);
    }

    /** @param list<int|float> $arguments */
    private static function paretoLogSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretologccdf');
        if ($value <= $minimum) {
            return 0.0;
        }

        return -$shape * (log($value) - log($minimum));
    }

