    private static function inverseParetoCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[1], $arguments[2]], 'paretoinv');
        if (!is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
