    /** @param list<int|float> $arguments */
    private static function inverseParetoSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[1], $arguments[2]], 'paretoccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('paretoccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return $minimum;
        }

        $logQuantile = log($minimum) - log($probability) / $shape;
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
