    /** @param list<int|float> $arguments */
    private static function inverseParetoQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[1], $arguments[2]], 'paretoinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('paretoinvprime() requires a probability strictly between 0 and 1.');
        }

        $logDerivative = log($minimum) - log($shape)
            - (1.0 / $shape + 1.0) * log1p(-$probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('paretoinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'paretoinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseParetoSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[1], $arguments[2]], 'paretoccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'paretoccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $logDerivative = log($minimum) - log($shape)
            - (1.0 / $shape + 1.0) * log($probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('paretoccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'paretoccinvprime');
