    /** @param list<int|float> $arguments */
    private static function paretoRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[1], $arguments[2]], 'paretomoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('paretomoment() requires an integer order from 0 through 64.');
        }
        if ($order >= $shape) {
            throw new \DomainException('paretomoment() exists only when the Pareto shape exceeds the order.');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $logMoment = log($shape) + $order * log($minimum) - log($shape - $order);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('paretomoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'paretomoment');
    }

    /** @param list<int|float> $arguments */
    private static function paretoMean(array $arguments): float
    {
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretomean');

        return self::paretoRawMoment([1.0, $shape, $minimum]);
    }

    /** @param list<int|float> $arguments */
    private static function paretoMedian(array $arguments): float
    {
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretomedian');

        return self::finiteSpecialResult(exp(log($minimum) + log(2.0) / $shape), 'paretomedian');
    }

    /** @param list<int|float> $arguments */
    private static function paretoMode(array $arguments): float
    {
        [, , $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretomode');

        return $minimum;
    }

    /** @param list<int|float> $arguments */
    private static function paretoVariance(array $arguments): float
    {
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretovariance');
        if ($shape <= 2.0) {
            throw new \DomainException('paretovariance() exists only when shape exceeds 2.');
        }
        $logVariance = log($shape) + 2.0 * log($minimum)
            - 2.0 * log($shape - 1.0) - log($shape - 2.0);
        if ($logVariance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('paretovariance() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logVariance), 'paretovariance');
    }

    /** @param list<int|float> $arguments */
    private static function paretoStandardDeviation(array $arguments): float
    {
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretostddev');
        if ($shape <= 2.0) {
            throw new \DomainException('paretostddev() exists only when shape exceeds 2.');
        }

        return self::finiteSpecialResult(
            exp(0.5 * (log($shape) + 2.0 * log($minimum) - 2.0 * log($shape - 1.0) - log($shape - 2.0))),
            'paretostddev',
        );
    }

    /** @param list<int|float> $arguments */
    private static function paretoSkewness(array $arguments): float
    {
        [, $shape] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretoskewness');
        if ($shape <= 3.0) {
            throw new \DomainException('paretoskewness() exists only when shape exceeds 3.');
        }

        return self::finiteSpecialResult(
            2.0 * ($shape + 1.0) / ($shape - 3.0) * sqrt(($shape - 2.0) / $shape),
            'paretoskewness',
        );
    }

    /** @param list<int|float> $arguments */
    private static function paretoExcessKurtosis(array $arguments): float
    {
        [, $shape] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretoexcesskurtosis');
        if ($shape <= 4.0) {
            throw new \DomainException('paretoexcesskurtosis() exists only when shape exceeds 4.');
        }

        return self::finiteSpecialResult(
            6.0 * ($shape ** 3 + $shape ** 2 - 6.0 * $shape - 2.0)
                / ($shape * ($shape - 3.0) * ($shape - 4.0)),
            'paretoexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function paretoKurtosis(array $arguments): float
    {
        return 3.0 + self::paretoExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function paretoDifferentialEntropy(array $arguments): float
    {
        [, $shape, $minimum] = self::paretoArguments([0.0, $arguments[0], $arguments[1]], 'paretoentropy');

        return self::finiteSpecialResult(log($minimum) - log($shape) + 1.0 + 1.0 / $shape, 'paretoentropy');
    }

    /** @param list<int|float> $arguments */
    private static function paretoHazard(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretohazard');
        if ($value < $minimum) {
