        return self::finiteSpecialResult($shape / $value, 'paretohazard');
    }

    /** @param list<int|float> $arguments */
    private static function paretoCumulativeHazard(array $arguments): float
    {
        [$value, $shape, $minimum] = self::paretoArguments($arguments, 'paretocumhazard');
        if ($value <= $minimum) {
            return 0.0;
        }

        return self::finiteSpecialResult($shape * (log($value) - log($minimum)), 'paretocumhazard');
    }

