        $logDensity = \log($shape) - \log($scale)
            - ($shape + 1.0) * self::logOnePlusRatio($value, $scale);

        return self::finiteSpecialResult(\exp($logDensity), 'lomaxpdf');
    }

    /** @param list<int|float> $arguments */
