    /** @param list<int|float> $arguments */
    private static function lomaxLogSurvivalFunction(array $arguments): float
    {
        [$value, $shape, $scale] = self::lomaxArguments($arguments, 'lomaxlogccdf');
        if ($value <= 0.0) {
