    /** @param list<int|float> $arguments */
    private static function inverseLomaxCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[1], $arguments[2]], 'lomaxinv');
        if (!\is_finite($probability) || $probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('lomaxinv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }

        $exponent = -\log1p(-$probability) / $shape;
        $logExpm1 = $exponent > 50.0 ? $exponent : \log(\expm1($exponent));
        $logQuantile = \log($scale) + $logExpm1;
        if ($logQuantile > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(\exp($logQuantile), 'lomaxinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLomaxSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[1], $arguments[2]], 'lomaxccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('lomaxccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        $power = -log($probability) / $shape;

        return self::finiteSpecialResult($scale * expm1($power), 'lomaxccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLomaxQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[1], $arguments[2]], 'lomaxinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('lomaxinvprime() requires a probability strictly between 0 and 1.');
        }

        $logDerivative = log($scale) - log($shape)
            - (1.0 / $shape + 1.0) * log1p(-$probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxinvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'lomaxinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLomaxSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[1], $arguments[2]], 'lomaxccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'lomaxccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $logDerivative = log($scale) - log($shape)
            - (1.0 / $shape + 1.0) * log($probability);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'lomaxccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[1], $arguments[2]], 'lomaxmoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('lomaxmoment() requires an integer order from 0 through 64.');
        }
        if ($order >= $shape) {
            throw new \DomainException('lomaxmoment() exists only when the Lomax shape exceeds the order.');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $logMoment = $order * log($scale) + self::logGammaPositive($order + 1.0);
        for ($factor = 1; $factor <= $order; ++$factor) {
            $logMoment -= log($shape - $factor);
        }
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'lomaxmoment');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxMean(array $arguments): float
    {
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxmean');

        return self::lomaxRawMoment([1.0, $shape, $scale]);
    }

    /** @param list<int|float> $arguments */
    private static function lomaxMedian(array $arguments): float
    {
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxmedian');
        $logRatio = log(2.0) / $shape;

        return self::finiteSpecialResult(exp(log($scale) + log(expm1($logRatio))), 'lomaxmedian');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxMode(array $arguments): float
    {
        self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxmode');

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function lomaxVariance(array $arguments): float
    {
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxvariance');
        if ($shape <= 2.0) {
            throw new \DomainException('lomaxvariance() exists only when shape exceeds 2.');
        }
        $logVariance = log($shape) + 2.0 * log($scale)
            - 2.0 * log($shape - 1.0) - log($shape - 2.0);
        if ($logVariance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxvariance() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logVariance), 'lomaxvariance');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxStandardDeviation(array $arguments): float
    {
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxstddev');
        if ($shape <= 2.0) {
            throw new \DomainException('lomaxstddev() exists only when shape exceeds 2.');
        }

        return self::finiteSpecialResult(
            exp(0.5 * (log($shape) + 2.0 * log($scale) - 2.0 * log($shape - 1.0) - log($shape - 2.0))),
            'lomaxstddev',
        );
    }

    /** @param list<int|float> $arguments */
    private static function lomaxSkewness(array $arguments): float
    {
        [, $shape] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'pareto2skewness');

        return self::paretoSkewness([$shape, 1.0]);
    }

    /** @param list<int|float> $arguments */
    private static function lomaxExcessKurtosis(array $arguments): float
    {
        [, $shape] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'pareto2excesskurtosis');

        return self::paretoExcessKurtosis([$shape, 1.0]);
    }

    /** @param list<int|float> $arguments */
    private static function lomaxKurtosis(array $arguments): float
    {
        return 3.0 + self::lomaxExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function lomaxDifferentialEntropy(array $arguments): float
    {
        [, $shape, $scale] = self::lomaxArguments([0.0, $arguments[0], $arguments[1]], 'lomaxentropy');

        return self::finiteSpecialResult(log($scale) - log($shape) + 1.0 + 1.0 / $shape, 'lomaxentropy');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::lomaxArguments($arguments, 'lomaxhazard');
        if ($value < 0.0) {
            return 0.0;
        }
        $logDenominator = self::stableLogSumExp([log($scale), $value === 0.0 ? -INF : log($value)]);
        $logHazard = log($shape) - $logDenominator;
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('lomaxhazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'lomaxhazard');
    }

    /** @param list<int|float> $arguments */
    private static function lomaxCumulativeHazard(array $arguments): float
    {
        [$value, $shape, $scale] = self::lomaxArguments($arguments, 'lomaxcumhazard');
        if ($value <= 0.0) {
            return 0.0;
        }
        $logRatio = self::stableLogSumExp([log($scale), log($value)]) - log($scale);

        return self::finiteSpecialResult($shape * $logRatio, 'lomaxcumhazard');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function lomaxArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $shape = (float) $arguments[1];
        $scale = (float) $arguments[2];
        if (
            !\is_finite($value)
            || !\is_finite($shape)
            || $shape <= 0.0
            || !\is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException($function . '() requires finite x and positive finite shape and scale.');
        }

        return [$value, $shape, $scale];
    }

    private static function logOnePlusRatio(float $numerator, float $denominator): float
    {
        if ($numerator <= $denominator) {
            return \log1p($numerator / $denominator);
        }

        $logRatio = \log($numerator) - \log($denominator);

        return $logRatio + \log1p(\exp(-$logRatio));
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionCumulativeDistribution(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );

        return self::regularizedBetaLower([$alpha, $beta, $value]);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionSurvivalFunction(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );

        return self::regularizedBetaUpper([$alpha, $beta, $value]);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionLogCumulativeDistribution(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );
        if ($value === 1.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            throw new \DomainException('betalogcdf() is negative infinity at x = 0.');
        }

        return self::regularizedBetaLogLowerValue($alpha, $beta, $value);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionLogSurvivalFunction(array $arguments): float
    {
        [$alpha, $beta, $value] = self::requireIncompleteBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
        );
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value === 1.0) {
            throw new \DomainException('betalogccdf() is negative infinity at x = 1.');
        }

        return self::regularizedBetaLogLowerValue($beta, $alpha, 1.0 - $value);
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaDistributionCumulativeDistribution(array $arguments): float
    {
        [$alpha, $beta, $probability] = self::requireInverseBetaArguments(
            [$arguments[1], $arguments[2], $arguments[0]],
            'betainv',
        );

        return self::finiteSpecialResult(
            self::inverseRegularizedBetaValue($alpha, $beta, $probability),
            'betainv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaDistributionSurvivalFunction(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters([$arguments[1], $arguments[2]], 'betaccinv');
        $probability = (float) $arguments[0];
        if (!is_finite($probability) || $probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('betaccinv() requires a survival probability in [0, 1].');
        }

        return self::finiteSpecialResult(
            self::inverseRegularizedBetaUpperValue($alpha, $beta, $probability),
            'betaccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaDistributionQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [$alpha, $beta] = self::betaDistributionMomentParameters([$arguments[1], $arguments[2]], 'betainvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('betainvprime() requires a probability strictly between 0 and 1.');
        }

        $quantile = self::inverseBetaDistributionCumulativeDistribution([$probability, $alpha, $beta]);
        $logDerivative = -self::betaDistributionLogProbabilityDensity([$quantile, $alpha, $beta]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('betainvprime() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logDerivative), 'betainvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaDistributionSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [$alpha, $beta] = self::betaDistributionMomentParameters([$arguments[1], $arguments[2]], 'betaccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'betaccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        $quantile = self::inverseBetaDistributionSurvivalFunction([$probability, $alpha, $beta]);
        $logDerivative = -self::betaDistributionLogProbabilityDensity([$quantile, $alpha, $beta]);
        if ($logDerivative > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('betaccinvprime() exceeds the finite floating-point range.');
        }

        return -self::finiteSpecialResult(exp($logDerivative), 'betaccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionMean(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betamean');

        return $alpha / ($alpha + $beta);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionMedian(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betamedian');
        if ($alpha === $beta) {
            return 0.5;
        }

        return self::inverseRegularizedBetaValue($alpha, $beta, 0.5);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionMode(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betamode');
        if ($alpha <= 1.0 || $beta <= 1.0) {
            throw new \DomainException('betamode() requires both shape parameters to exceed 1.');
        }
        if ($alpha === $beta) {
            return 0.5;
        }

        return ($alpha - 1.0) / ($alpha + $beta - 2.0);
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionDifferentialEntropy(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betaentropy');
        if ($alpha === 1.0 && $beta === 1.0) {
            return 0.0;
        }
        if ($alpha === 0.5 && $beta === 0.5) {
            return log(M_PI / 4.0);
        }
        $total = $alpha + $beta;
        $entropy = self::logGammaPositive($alpha) + self::logGammaPositive($beta)
            - self::logGammaPositive($total)
            - ($alpha - 1.0) * self::digammaFunction([$alpha])
            - ($beta - 1.0) * self::digammaFunction([$beta])
            + ($total - 2.0) * self::digammaFunction([$total]);

        return self::finiteSpecialResult($entropy, 'betaentropy');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionVariance(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betavariance');
        $total = $alpha + $beta;
        $leftFraction = $alpha / $total;
        $rightFraction = $beta / $total;

        return self::finiteSpecialResult($leftFraction * $rightFraction / ($total + 1.0), 'betavariance');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionSkewness(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betaskewness');
        if ($alpha === $beta) {
            return 0.0;
        }
        $total = $alpha + $beta;
        $difference = abs($beta - $alpha);
        $logMagnitude = log(2.0) + log($difference) + 0.5 * log($total + 1.0)
            - log($total + 2.0) - 0.5 * log($alpha) - 0.5 * log($beta);
        $magnitude = exp($logMagnitude);

        return self::finiteSpecialResult(($beta > $alpha ? 1.0 : -1.0) * $magnitude, 'betaskewness');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionExcessKurtosis(array $arguments): float
    {
        [$alpha, $beta] = self::betaDistributionMomentParameters($arguments, 'betaexcesskurtosis');
        $total = $alpha + $beta;
        $difference = abs($alpha - $beta);
        $ratio = $difference === 0.0
            ? 0.0
            : exp(2.0 * log($difference) - log($alpha) - log($beta));
        $excessKurtosis = 6.0 * ($ratio * ($total + 1.0) - ($total + 2.0))
            / (($total + 2.0) * ($total + 3.0));

        return self::finiteSpecialResult($excessKurtosis, 'betaexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function betaDistributionKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::betaDistributionExcessKurtosis($arguments),
            'betakurtosis',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function betaDistributionMomentParameters(array $arguments, string $function): array
    {
        [$alpha, $beta] = self::requireIncompleteBetaArguments([$arguments[0], $arguments[1], 0.5]);
        if (!is_finite($alpha + $beta)) {
            throw new \DomainException($function . '() requires finite positive shape parameters.');
        }

        return [$alpha, $beta];
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyProbabilityDensity(array $arguments): float
    {
        [$value, $alpha, $beta] = self::kumaraswamyArguments($arguments, 'kumaraswamypdf');
        if ($value < 0.0 || $value > 1.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($alpha < 1.0) {
                throw new \DomainException('kumaraswamypdf() is singular at zero when alpha is below 1.');
            }

            return $alpha === 1.0 ? $beta : 0.0;
        }
        if ($value === 1.0) {
            if ($beta < 1.0) {
                throw new \DomainException('kumaraswamypdf() is singular at one when beta is below 1.');
            }

            return $beta === 1.0 ? $alpha : 0.0;
        }

        $logDensity = log($alpha) + log($beta) + ($alpha - 1.0) * log($value)
            + ($beta - 1.0) * self::kumaraswamyLogOneMinusPower($value, $alpha);

        return self::finiteSpecialResult(exp($logDensity), 'kumaraswamypdf');
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyLogProbabilityDensity(array $arguments): float
    {
        [$value, $alpha, $beta] = self::kumaraswamyArguments($arguments, 'kumaraswamylogpdf');
        if ($value < 0.0 || $value > 1.0) {
            return -INF;
        }
        if ($value === 0.0) {
            return $alpha < 1.0 ? INF : ($alpha === 1.0 ? log($beta) : -INF);
        }
        if ($value === 1.0) {
            return $beta < 1.0 ? INF : ($beta === 1.0 ? log($alpha) : -INF);
        }

        return log($alpha) + log($beta) + ($alpha - 1.0) * log($value)
            + ($beta - 1.0) * self::kumaraswamyLogOneMinusPower($value, $alpha);
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyCumulativeDistribution(array $arguments): float
    {
        [$value, $alpha, $beta] = self::kumaraswamyArguments($arguments, 'kumaraswamycdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        if ($value >= 1.0) {
            return 1.0;
        }

        $logSurvival = $beta * self::kumaraswamyLogOneMinusPower($value, $alpha);

        return -expm1($logSurvival);
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamySurvivalFunction(array $arguments): float
    {
        [$value, $alpha, $beta] = self::kumaraswamyArguments($arguments, 'kumaraswamyccdf');
        if ($value <= 0.0) {
            return 1.0;
        }
        if ($value >= 1.0) {
            return 0.0;
        }

        return exp($beta * self::kumaraswamyLogOneMinusPower($value, $alpha));
    }

    /** @param list<int|float> $arguments */
    private static function inverseKumaraswamyCumulativeDistribution(array $arguments): float
    {
        [$probability, $alpha, $beta] = self::kumaraswamyArguments($arguments, 'kumaraswamyinv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('kumaraswamyinv() requires a probability in [0, 1].');
        }
        if ($probability === 0.0 || $probability === 1.0) {
            return $probability;
        }

        $oneMinusPower = -expm1(log1p(-$probability) / $beta);
        if ($oneMinusPower === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(exp(log($oneMinusPower) / $alpha), 'kumaraswamyinv');
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyMean(array $arguments): float
    {
        return self::kumaraswamyRawMoment([1.0, $arguments[0], $arguments[1]]);
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyMedian(array $arguments): float
    {
        return self::inverseKumaraswamyCumulativeDistribution([0.5, $arguments[0], $arguments[1]]);
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyMode(array $arguments): float
    {
        [, $alpha, $beta] = self::kumaraswamyArguments([0.0, $arguments[0], $arguments[1]], 'kumaraswamymode');
        if ($alpha < 1.0 && $beta < 1.0) {
            throw new \DomainException('kumaraswamymode() is not unique when both shape parameters are below 1.');
        }
        if ($alpha <= 1.0) {
            return 0.0;
        }
        if ($beta <= 1.0) {
            return 1.0;
        }

        return (($alpha - 1.0) / ($alpha * $beta - 1.0)) ** (1.0 / $alpha);
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyVariance(array $arguments): float
    {
        [, $alpha, $beta] = self::kumaraswamyArguments([0.0, $arguments[0], $arguments[1]], 'kumaraswamyvariance');
        $logMean = self::kumaraswamyLogRawMoment(1.0, $alpha, $beta);
        $logSecondMoment = self::kumaraswamyLogRawMoment(2.0, $alpha, $beta);
        $relativeSecondMoment = $logSecondMoment - 2.0 * $logMean;
        if ($relativeSecondMoment <= 0.0) {
            return 0.0;
        }

        $logVariance = 2.0 * $logMean + log(expm1($relativeSecondMoment));
        if ($logVariance > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('kumaraswamyvariance() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logVariance), 'kumaraswamyvariance');
    }

    /** @param list<int|float> $arguments */
    private static function kumaraswamyRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $alpha, $beta] = self::kumaraswamyArguments([0.0, $arguments[1], $arguments[2]], 'kumaraswamymoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('kumaraswamymoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            exp(self::kumaraswamyLogRawMoment($order, $alpha, $beta)),
            'kumaraswamymoment',
        );
    }

    private static function kumaraswamyLogRawMoment(float $order, float $alpha, float $beta): float
    {
        return self::logGammaPositive(1.0 + $order / $alpha)
            + self::logGammaPositive(1.0 + $beta)
            - self::logGammaPositive(1.0 + $beta + $order / $alpha);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float}
     */
    private static function kumaraswamyArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $alpha = (float) $arguments[1];
        $beta = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($alpha)
            || $alpha <= 0.0
            || $alpha > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($beta)
            || $beta <= 0.0
            || $beta > self::MAX_DISTRIBUTION_SHAPE
        ) {
            throw new \DomainException(
                $function . '() requires a finite value and positive finite alpha and beta in (0, 10000].',
            );
        }

        return [$value, $alpha, $beta];
    }

    private static function kumaraswamyLogOneMinusPower(float $value, float $alpha): float
    {
        return log(-expm1($alpha * log($value)));
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeProbabilityDensity(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimepdf');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($alpha < 1.0) {
                throw new \DomainException('betaprimepdf() is singular at zero when alpha is below 1.');
            }

            return $alpha === 1.0 ? $beta : 0.0;
        }

        $logDensity = ($alpha - 1.0) * log($value)
            - ($alpha + $beta) * log1p($value)
            - (self::logGammaPositive($alpha) + self::logGammaPositive($beta)
                - self::logGammaPositive($alpha + $beta));

        return self::finiteSpecialResult(exp($logDensity), 'betaprimepdf');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeLogProbabilityDensity(array $arguments): float
    {
        $function = 'betaprime' . 'logpdf';
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, $function);
        if ($value < 0.0) {
            throw new \DomainException($function . '() is undefined where the beta-prime density is zero.');
        }
        if ($value === 0.0) {
            if ($alpha !== 1.0) {
                throw new \DomainException($function . '() has no finite value at zero unless alpha is one.');
            }

            return self::finiteSpecialResult(log($beta), $function);
        }

        $logBeta = self::logGammaPositive($alpha)
            + self::logGammaPositive($beta)
            - self::logGammaPositive($alpha + $beta);
        $logDensity = ($alpha - 1.0) * log($value)
            - ($alpha + $beta) * log1p($value)
            - $logBeta;

        return self::finiteSpecialResult($logDensity, $function);
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeCumulativeDistribution(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimecdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        return self::regularizedBetaValue($alpha, $beta, self::logisticUnitArgument(log($value)));
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeSurvivalFunction(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimeccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        return self::regularizedBetaValue($beta, $alpha, self::logisticUnitArgument(-log($value)));
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeLogCumulativeDistribution(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimelogcdf');
        if ($value <= 0.0) {
            return -\INF;
        }

        return self::regularizedBetaLogLowerValue($alpha, $beta, self::logisticUnitArgument(log($value)));
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeLogSurvivalFunction(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimelogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        return self::regularizedBetaLogLowerValue($beta, $alpha, self::logisticUnitArgument(-log($value)));
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeHazard(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimehazard');
        if ($value < 0.0) {
            return 0.0;
        }
        $logDensity = self::betaPrimeLogProbabilityDensity([$value, $alpha, $beta]);
        $logSurvival = self::betaPrimeLogSurvivalFunction([$value, $alpha, $beta]);
        if ($logDensity - $logSurvival > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('betaprimehazard() result exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(\exp($logDensity - $logSurvival), 'betaprimehazard');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeCumulativeHazard(array $arguments): float
    {
        [$value, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimecumhazard');
        if ($value <= 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            -self::betaPrimeLogSurvivalFunction([$value, $alpha, $beta]),
            'betaprimecumhazard',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaPrimeCumulativeDistribution(array $arguments): float
    {
        [$probability, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimeinv');
        if ($probability < 0.0 || $probability >= 1.0) {
            throw new \DomainException('betaprimeinv() requires a probability in [0, 1).');
        }
        if ($probability === 0.0) {
            return 0.0;
        }

        if ($probability <= 0.5) {
            $betaArgument = self::inverseRegularizedBetaValue($alpha, $beta, $probability);
            if ($betaArgument >= 1.0) {
                throw new \OverflowException('betaprimeinv() quantile is outside the finite floating-point range.');
            }
            $logQuantile = log($betaArgument) - log1p(-$betaArgument);
        } else {
            $complementArgument = self::inverseRegularizedBetaValue($beta, $alpha, 1.0 - $probability);
            if ($complementArgument <= 0.0) {
                throw new \OverflowException('betaprimeinv() quantile is outside the finite floating-point range.');
            }
            $logQuantile = log1p(-$complementArgument) - log($complementArgument);
        }
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('betaprimeinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'betaprimeinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaPrimeSurvivalFunction(array $arguments): float
    {
        [$probability, $alpha, $beta] = self::betaPrimeArguments($arguments, 'beta2ccinv');
        if ($probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('beta2ccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        $betaArgument = self::inverseRegularizedBetaValue($beta, $alpha, $probability);
        if ($betaArgument <= 0.0 || $betaArgument >= 1.0) {
            throw new \OverflowException('beta2ccinv() quantile is outside the finite floating-point range.');
        }
        $logQuantile = log1p(-$betaArgument) - log($betaArgument);
        if ($logQuantile > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('beta2ccinv() quantile is outside the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logQuantile), 'beta2ccinv');
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaPrimeQuantileDerivative(array $arguments): float
    {
        [$probability, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimeinvprime');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('betaprimeinvprime() requires a probability strictly between 0 and 1.');
        }
        $quantile = self::inverseBetaPrimeCumulativeDistribution([$probability, $alpha, $beta]);
        $logDerivative = -self::betaPrimeLogProbabilityDensity([$quantile, $alpha, $beta]);
        if ($logDerivative > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('betaprimeinvprime() result exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(\exp($logDerivative), 'betaprimeinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaPrimeSurvivalQuantileDerivative(array $arguments): float
    {
        [$probability, $alpha, $beta] = self::betaPrimeArguments($arguments, 'betaprimeccinvprime');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'betaprimeccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }
        $quantile = self::inverseBetaPrimeSurvivalFunction([$probability, $alpha, $beta]);
        $logDerivative = -self::betaPrimeLogProbabilityDensity([$quantile, $alpha, $beta]);
        if ($logDerivative > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException(
                'betaprimeccinvprime() result exceeds the finite floating-point range.',
            );
        }

        return self::finiteSpecialResult(-\exp($logDerivative), 'betaprimeccinvprime');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[1], $arguments[2]], 'betaprimemoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('betaprimemoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }
        if ($beta <= $order) {
            throw new \DomainException('betaprimemoment() exists only when beta is greater than the requested order.');
        }

        $logMoment = self::logGammaPositive($alpha + $order)
            - self::logGammaPositive($alpha)
            + self::logGammaPositive($beta - $order)
            - self::logGammaPositive($beta);

        return self::finiteSpecialResult(exp($logMoment), 'betaprimemoment');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeMean(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[0], $arguments[1]], 'betaprimemean');
        if ($beta <= 1.0) {
            throw new \DomainException('betaprimemean() exists only when beta is greater than 1.');
        }

        return self::finiteSpecialResult(exp(log($alpha) - log($beta - 1.0)), 'betaprimemean');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeMedian(array $arguments): float
    {
        return self::inverseBetaPrimeCumulativeDistribution([0.5, $arguments[0], $arguments[1]]);
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeMode(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[0], $arguments[1]], 'betaprimemode');
        if ($alpha <= 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(($alpha - 1.0) / ($beta + 1.0), 'betaprimemode');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeVariance(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[0], $arguments[1]], 'betaprimevariance');
        if ($beta <= 2.0) {
            throw new \DomainException('betaprimevariance() exists only when beta is greater than 2.');
        }

        $logVariance = log($alpha) + log($alpha + $beta - 1.0)
            - log($beta - 2.0) - 2.0 * log($beta - 1.0);

        return self::finiteSpecialResult(exp($logVariance), 'betaprimevariance');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::betaPrimeVariance($arguments)), 'betaprimestddev');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeSkewness(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[0], $arguments[1]], 'betaprimeskewness');
        if ($beta <= 3.0) {
            throw new \DomainException('betaprimeskewness() exists only when beta is greater than 3.');
        }

        $skewness = 2.0 * (2.0 * $alpha + $beta - 1.0) * sqrt($beta - 2.0)
            / (($beta - 3.0) * sqrt($alpha * ($alpha + $beta - 1.0)));

        return self::finiteSpecialResult($skewness, 'betaprimeskewness');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeExcessKurtosis(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments(
            [0.0, $arguments[0], $arguments[1]],
            'betaprimeexcesskurtosis',
        );
        if ($beta <= 4.0) {
            throw new \DomainException('betaprimeexcesskurtosis() exists only when beta is greater than 4.');
        }

        $shapeProduct = $alpha * ($alpha + $beta - 1.0);
        $numerator = $shapeProduct * (5.0 * $beta - 11.0) + ($beta - 1.0) ** 2 * ($beta - 2.0);
        $denominator = $shapeProduct * ($beta - 3.0) * ($beta - 4.0);

        return self::finiteSpecialResult(6.0 * ($numerator / $denominator), 'betaprimeexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::betaPrimeExcessKurtosis($arguments),
            'betaprimekurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function betaPrimeDifferentialEntropy(array $arguments): float
    {
        [, $alpha, $beta] = self::betaPrimeArguments([0.0, $arguments[0], $arguments[1]], 'betaprimeentropy');
        $total = $alpha + $beta;
        $entropy = self::logGammaPositive($alpha) + self::logGammaPositive($beta)
            - self::logGammaPositive($total)
            - ($alpha - 1.0) * self::digammaFunction([$alpha])
            - ($beta + 1.0) * self::digammaFunction([$beta])
            + $total * self::digammaFunction([$total]);

        return self::finiteSpecialResult($entropy, 'betaprimeentropy');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float, 2: float}
     */
    private static function betaPrimeArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $alpha = (float) $arguments[1];
        $beta = (float) $arguments[2];
        if (
            !is_finite($value)
            || !is_finite($alpha)
            || !is_finite($beta)
            || $alpha <= 0.0
            || $beta <= 0.0
            || $alpha + $beta > 10_000.0
        ) {
            throw new \DomainException(
                $function . '() requires finite x and positive shape parameters whose sum is at most 10000.',
            );
        }

        return [$value, $alpha, $beta];
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareProbabilityDensity(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chisquarepdf');
        if ($value < 0.0 || ($value === 0.0 && $degreesOfFreedom < 2.0)) {
            if ($value < 0.0) {
                return 0.0;
            }
            if ($degreesOfFreedom < 2.0) {
                throw new \DomainException('chisquarepdf() is singular at zero when degrees of freedom are below 2.');
            }
        }
        if ($value === 0.0 && $degreesOfFreedom === 2.0) {
            return 0.5;
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $shape = $degreesOfFreedom / 2.0;
        $logDensity = ($shape - 1.0) * log($value)
            - $value / 2.0
            - $shape * log(2.0)
            - self::logGammaPositive($shape);

        return self::finiteSpecialResult(exp($logDensity), 'chisquarepdf');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareLogProbabilityDensity(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chilogpdf');
        if ($value < 0.0 || $value === 0.0 && $degreesOfFreedom !== 2.0) {
            throw new \DomainException('chilogpdf() has no finite log-density value at this x.');
        }
        if ($value === 0.0) {
            return -log(2.0);
        }

        $shape = $degreesOfFreedom / 2.0;
        $logDensity = ($shape - 1.0) * log($value)
            - $value / 2.0
            - $shape * log(2.0)
            - self::logGammaPositive($shape);

        return self::finiteSpecialResult($logDensity, 'chilogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareCumulativeDistribution(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chisquarecdf');
        if ($value <= 0.0) {
            return 0.0;
        }

        return self::regularizedGammaLower([$degreesOfFreedom / 2.0, $value / 2.0]);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareComplementaryCumulativeDistribution(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chisquareccdf');
        if ($value <= 0.0) {
            return 1.0;
        }

        return self::regularizedGammaUpper([$degreesOfFreedom / 2.0, $value / 2.0]);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareLogSurvivalFunction(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chisquarelogccdf');
        if ($value <= 0.0) {
            return 0.0;
        }
        $standardized = $value / 2.0;

        return self::regularizedGammaUpperLogValue($degreesOfFreedom / 2.0, $standardized);
    }

    /** @param list<int|float> $arguments */
    private static function inverseChiSquareCumulativeDistribution(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[1]], 'chisquareinv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('chisquareinv() requires a probability in [0, 1].');
        }
        if ($probability === 0.0) {
            return 0.0;
        }
        if ($probability === 1.0) {
            throw new \DomainException('chisquareinv() has no finite quantile at probability 1.');
        }

        return self::finiteSpecialResult(
            2.0 * self::inverseRegularizedGammaValue($degreesOfFreedom / 2.0, $probability),
            'chisquareinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseChiSquareSurvivalFunction(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[1]], 'chiccinv');
        if (!is_finite($probability) || $probability <= 0.0 || $probability > 1.0) {
            throw new \DomainException('chiccinv() requires a survival probability in (0, 1].');
        }
        if ($probability === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            2.0 * self::inverseRegularizedGammaUpperValue($degreesOfFreedom / 2.0, $probability),
            'chiccinv',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseChiSquareQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[1]], 'chisquareinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('chisquareinvprime() requires a probability strictly between 0 and 1.');
        }

        return self::finiteSpecialResult(
            2.0 * self::inverseRegularizedGammaLowerDerivative([$degreesOfFreedom / 2.0, $probability]),
            'chisquareinvprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseChiSquareSurvivalQuantileDerivative(array $arguments): float
    {
        $probability = (float) $arguments[0];
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[1]], 'chisquareccinvprime');
        if (!is_finite($probability) || $probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException(
                'chisquareccinvprime() requires a survival probability strictly between 0 and 1.',
            );
        }

        return self::finiteSpecialResult(
            2.0 * self::inverseRegularizedGammaUpperDerivative([$degreesOfFreedom / 2.0, $probability]),
            'chisquareccinvprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[1]], 'chisquarelogmgf');
        if (!is_finite($tilt) || $tilt >= 0.5) {
            throw new \DomainException('chisquarelogmgf() requires a finite t < 1/2.');
        }

        return self::finiteSpecialResult(-0.5 * $degreesOfFreedom * log1p(-2.0 * $tilt), 'chisquarelogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(exp(self::chiSquareLogMomentGeneratingFunction($arguments)), 'chisquaremgf');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareMean(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquaremean');

        return $degreesOfFreedom;
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareVariance(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquarevariance');

        return 2.0 * $degreesOfFreedom;
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareStandardDeviation(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquarestddev');

        return sqrt(2.0 * $degreesOfFreedom);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareMedian(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquaremedian');

        return self::inverseChiSquareCumulativeDistribution([0.5, $degreesOfFreedom]);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareMode(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquaremode');

        return max($degreesOfFreedom - 2.0, 0.0);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareDifferentialEntropy(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquareentropy');
        $halfDegrees = $degreesOfFreedom / 2.0;
        $entropy = $halfDegrees + log(2.0) + self::logGammaPositive($halfDegrees)
            + (1.0 - $halfDegrees) * self::digammaFunction([$halfDegrees]);

        return self::finiteSpecialResult($entropy, 'chisquareentropy');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareHazard(array $arguments): float
    {
        [$value, $degreesOfFreedom] = self::chiSquareArguments($arguments, 'chisquarehazard');
        if ($value < 0.0) {
            return 0.0;
        }
        if ($value === 0.0) {
            if ($degreesOfFreedom < 2.0) {
                throw new \DomainException(
                    'chisquarehazard() is singular at zero when degrees of freedom are below 2.',
                );
            }

            return $degreesOfFreedom === 2.0 ? 0.5 : 0.0;
        }
        $logHazard = self::chiSquareLogProbabilityDensity($arguments)
            - self::chiSquareLogSurvivalFunction($arguments);
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('chisquarehazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'chisquarehazard');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareCumulativeHazard(array $arguments): float
    {
        [$value] = self::chiSquareArguments($arguments, 'chisquarecumhazard');
        if ($value < 0.0) {
            return 0.0;
        }

        return -self::chiSquareLogSurvivalFunction($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareSkewness(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquareskewness');

        return self::finiteSpecialResult(sqrt(8.0) / sqrt($degreesOfFreedom), 'chisquareskewness');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareExcessKurtosis(array $arguments): float
    {
        [, $degreesOfFreedom] = self::chiSquareArguments([0.0, $arguments[0]], 'chisquareexcesskurtosis');

        return self::finiteSpecialResult(12.0 / $degreesOfFreedom, 'chisquareexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function chiSquareKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::chiSquareExcessKurtosis($arguments),
            'chisquarekurtosis',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: float}
     */
    private static function chiSquareArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $degreesOfFreedom = (float) $arguments[1];
        if (
            !is_finite($value)
            || !is_finite($degreesOfFreedom)
            || $degreesOfFreedom <= 0.0
            || $degreesOfFreedom > 2.0 * self::MAX_DISTRIBUTION_SHAPE
        ) {
            throw new \DomainException($function . '() requires a finite value and degrees of freedom in (0, 20000].');
        }

        return [$value, $degreesOfFreedom];
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float}
     */
    private static function normalArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $mean = (float) ($arguments[1] ?? 0.0);
        $standardDeviation = (float) ($arguments[2] ?? 1.0);
        if (!is_finite($value) || !is_finite($mean) || !is_finite($standardDeviation) || $standardDeviation <= 0.0) {
            throw new \DomainException(
                $function . '() requires a finite value and mean, and a positive finite standard deviation.',
            );
        }

        return [$value, $mean, $standardDeviation];
    }

    /** @param list<int|float> $arguments */
    private static function studentTProbabilityDensity(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::studentTLogProbabilityDensity($arguments)),
            'studenttpdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function studentTLogProbabilityDensity(array $arguments): float
    {
        [$value, $degreesOfFreedom, $mean, $scale] = self::studentTArguments($arguments, 'studenttlogpdf');
        $difference = $value - $mean;
        $logStandardizedMagnitude = is_finite($difference)
            ? ($difference === 0.0 ? -INF : log(abs($difference)) - log($scale))
            : log(max(abs($value), abs($mean))) + log(2.0) - log($scale);
        $logSquareRatio = 2.0 * $logStandardizedMagnitude - log($degreesOfFreedom);
        $logKernel = $logSquareRatio > 0.0
            ? $logSquareRatio + log1p(exp(-$logSquareRatio))
            : log1p(exp($logSquareRatio));

        $logDensity = self::logGammaPositive(($degreesOfFreedom + 1.0) / 2.0)
            - self::logGammaPositive($degreesOfFreedom / 2.0)
            - 0.5 * (log($degreesOfFreedom) + log(M_PI))
            - (($degreesOfFreedom + 1.0) / 2.0) * $logKernel
            - log($scale);

        return self::finiteSpecialResult($logDensity, 'studenttlogpdf');
    }

    /** @param list<int|float> $arguments */
    private static function studentTCumulativeDistribution(array $arguments): float
    {
        [$value, $degreesOfFreedom, $mean, $scale] = self::studentTArguments($arguments, 'studenttcdf');
        $difference = $value - $mean;
        if (!is_finite($difference)) {
            return $value < $mean ? 0.0 : 1.0;
        }

        $standardized = $difference / $scale;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 0.0 : 1.0;
        }
        if ($standardized === 0.0) {
            return 0.5;
        }

        $tail = self::studentTUpperTail(abs($standardized), $degreesOfFreedom);
        return self::finiteSpecialResult($standardized < 0.0 ? $tail : 1.0 - $tail, 'studenttcdf');
    }

    /** @param list<int|float> $arguments */
    private static function studentTComplementaryCumulativeDistribution(array $arguments): float
    {
        [$value, $degreesOfFreedom, $mean, $scale] = self::studentTArguments($arguments, 'studenttccdf');
        $difference = $value - $mean;
        if (!is_finite($difference)) {
            return $value < $mean ? 1.0 : 0.0;
        }

        $standardized = $difference / $scale;
        if (!is_finite($standardized)) {
            return $standardized < 0.0 ? 1.0 : 0.0;
        }
        if ($standardized === 0.0) {
            return 0.5;
        }

        $tail = self::studentTUpperTail(abs($standardized), $degreesOfFreedom);
        return self::finiteSpecialResult($standardized > 0.0 ? $tail : 1.0 - $tail, 'studenttccdf');
    }

    /** @param list<int|float> $arguments */
    private static function studentTLogCumulativeDistribution(array $arguments): float
    {
        return self::studentTLogTail($arguments, 'studenttlogcdf', false);
    }

    /** @param list<int|float> $arguments */
    private static function studentTLogComplementaryCumulativeDistribution(array $arguments): float
    {
        return self::studentTLogTail($arguments, 'studenttlogccdf', true);
    }

    /** @param list<int|float> $arguments */
    private static function studentTLogTail(array $arguments, string $function, bool $complement): float
    {
        [$value, $degreesOfFreedom, $mean, $scale] = self::studentTArguments($arguments, $function);
        $difference = $value - $mean;
        if (!is_finite($difference)) {
            $valueIsBelowMean = $value < $mean;
            if ($valueIsBelowMean !== $complement) {
                throw new \OverflowException($function . '() log probability exceeds the finite floating-point range.');
            }

            return 0.0;
        }

        $standardized = $difference / $scale;
        if (!is_finite($standardized)) {
            $valueIsBelowMean = $standardized < 0.0;
            if ($valueIsBelowMean !== $complement) {
                throw new \OverflowException($function . '() log probability exceeds the finite floating-point range.');
            }

            return 0.0;
        }
        if ($standardized === 0.0) {
            return -log(2.0);
        }

        $logSmallTail = self::studentTLogUpperTail(abs($standardized), $degreesOfFreedom);
        $requestedTailIsSmall = ($standardized < 0.0) !== $complement;
        $result = $requestedTailIsSmall
            ? $logSmallTail
            : self::logOneMinusExponential([$logSmallTail]);

        return self::finiteSpecialResult($result, $function);
    }

    private static function studentTLogUpperTail(float $standardized, float $degreesOfFreedom): float
    {
        if ($standardized === 0.0) {
            return -log(2.0);
        }

        $logDegrees = log($degreesOfFreedom);
        $logSquaredValue = 2.0 * log($standardized);
        $maximumLog = max($logDegrees, $logSquaredValue);
        $logDenominator = $maximumLog + log1p(exp(min($logDegrees, $logSquaredValue) - $maximumLog));
        $logRatio = $logDegrees - $logDenominator;
        $ratio = exp($logRatio);
        $left = $degreesOfFreedom / 2.0;
        $right = 0.5;
        $threshold = ($left + 1.0) / ($left + $right + 2.0);

        if ($ratio > $threshold) {
            return log(0.5 * self::regularizedBetaValue($left, $right, $ratio));
        }

        $logFactor = self::logGammaPositive($left + $right)
            - self::logGammaPositive($left)
            - self::logGammaPositive($right)
            + $left * $logRatio
            + $right * log1p(-$ratio);
        $logRegularizedBeta = $logFactor
            + log(self::incompleteBetaContinuedFraction($left, $right, $ratio))
            - log($left);

        return self::finiteSpecialResult($logRegularizedBeta - log(2.0), 'studenttlogccdf');
    }

    /** @param list<int|float> $arguments */
    private static function inverseStudentTCumulativeDistribution(array $arguments): float
    {
        [$probability, $degreesOfFreedom, $mean, $scale] = self::studentTArguments($arguments, 'studenttinv');
        if ($probability <= 0.0 || $probability >= 1.0) {
            throw new \DomainException('studenttinv() requires a probability strictly between 0 and 1.');
        }
        if ($probability === 0.5) {
            return $mean;
        }

        $tailProbability = 2.0 * min($probability, 1.0 - $probability);
        if ($tailProbability > 0.5) {
            // Near the median, solve the complementary small beta tail to avoid
            // subtracting a value close to one when recovering t squared.
            $complementRatio = self::inverseRegularizedBetaValue(
                0.5,
                $degreesOfFreedom / 2.0,
                1.0 - $tailProbability,
            );
            $squaredQuantile = $degreesOfFreedom * ($complementRatio / (1.0 - $complementRatio));
        } else {
            $ratio = self::inverseRegularizedBetaValue(
                $degreesOfFreedom / 2.0,
                0.5,
                $tailProbability,
            );
            if ($ratio <= 0.0) {
                throw new \OverflowException('studenttinv() quantile is outside the finite floating-point range.');
            }
            $squaredQuantile = $degreesOfFreedom * ((1.0 - $ratio) / $ratio);
        }

        $standardized = sqrt($squaredQuantile);
        $direction = $probability < 0.5 ? -1.0 : 1.0;
        return self::finiteSpecialResult($mean + $direction * $scale * $standardized, 'studenttinv');
    }

    /** @param list<int|float> $arguments */
    private static function studentTMean(array $arguments): float
    {
        [$degreesOfFreedom, $mean] = self::studentTMomentParameters($arguments, 'studenttmean');
        if ($degreesOfFreedom <= 1.0) {
            throw new \DomainException('studenttmean() exists only when degrees of freedom exceed 1.');
        }

        return $mean;
    }

    /** @param list<int|float> $arguments */
    private static function studentTVariance(array $arguments): float
    {
        [$degreesOfFreedom, , $scale] = self::studentTMomentParameters($arguments, 'studenttvariance');
        $standardDeviation = self::studentTStandardDeviationFromParameters(
            $degreesOfFreedom,
            $scale,
            'studenttvariance',
        );

        return self::finiteSpecialResult($standardDeviation * $standardDeviation, 'studenttvariance');
    }

    /** @param list<int|float> $arguments */
    private static function studentTStandardDeviation(array $arguments): float
    {
        [$degreesOfFreedom, , $scale] = self::studentTMomentParameters($arguments, 'studenttstddev');

        return self::studentTStandardDeviationFromParameters($degreesOfFreedom, $scale, 'studenttstddev');
    }

    /** @param list<int|float> $arguments */
    private static function studentTMedian(array $arguments): float
    {
        [, $mean] = self::studentTMomentParameters($arguments, 'studenttmedian');

        return $mean;
    }

    /** @param list<int|float> $arguments */
    private static function studentTEntropy(array $arguments): float
    {
        [$degreesOfFreedom, , $scale] = self::studentTMomentParameters($arguments, 'studenttentropy');
        $halfDegrees = $degreesOfFreedom / 2.0;
        $halfNextDegrees = ($degreesOfFreedom + 1.0) / 2.0;
        $entropy = self::logGammaPositive($halfDegrees)
            + 0.5 * log($degreesOfFreedom * M_PI)
            - self::logGammaPositive($halfNextDegrees)
            + $halfNextDegrees * (
                self::digammaFunction([$halfNextDegrees]) - self::digammaFunction([$halfDegrees])
            )
            + log($scale);

        return self::finiteSpecialResult($entropy, 'studenttentropy');
    }

    /** @param list<int|float> $arguments */
    private static function studentTHazard(array $arguments): float
    {
        $logHazard = self::studentTLogProbabilityDensity($arguments)
            - self::studentTLogComplementaryCumulativeDistribution($arguments);
        if ($logHazard > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('studentthazard() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logHazard), 'studentthazard');
    }

    /** @param list<int|float> $arguments */
    private static function studentTCumulativeHazard(array $arguments): float
    {
        return self::finiteSpecialResult(
            -self::studentTLogComplementaryCumulativeDistribution($arguments),
            'studenttcumhazard',
        );
    }

    /** @param list<int|float> $arguments */
    private static function studentTSkewness(array $arguments): float
    {
        [$degreesOfFreedom] = self::studentTMomentParameters($arguments, 'studenttskewness');
        if ($degreesOfFreedom <= 3.0) {
            throw new \DomainException('studenttskewness() exists only when degrees of freedom exceed 3.');
        }

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function studentTExcessKurtosis(array $arguments): float
    {
        [$degreesOfFreedom] = self::studentTMomentParameters($arguments, 'studenttexcesskurtosis');
        if ($degreesOfFreedom <= 4.0) {
            throw new \DomainException('studenttexcesskurtosis() exists only when degrees of freedom exceed 4.');
        }

        return 6.0 / ($degreesOfFreedom - 4.0);
    }

    /** @param list<int|float> $arguments */
    private static function studentTKurtosis(array $arguments): float
    {
        return 3.0 + self::studentTExcessKurtosis($arguments);
    }

    private static function studentTStandardDeviationFromParameters(
        float $degreesOfFreedom,
        float $scale,
        string $function,
    ): float {
        if ($degreesOfFreedom <= 2.0) {
            throw new \DomainException($function . '() exists only when degrees of freedom exceed 2.');
        }

        return self::finiteSpecialResult(
            $scale * sqrt($degreesOfFreedom / ($degreesOfFreedom - 2.0)),
            $function,
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float}
     */
    private static function studentTMomentParameters(array $arguments, string $function): array
    {
        [, $degreesOfFreedom, $mean, $scale] = self::studentTArguments(
            [0.0, $arguments[0], $arguments[1] ?? 0.0, $arguments[2] ?? 1.0],
            $function,
        );

        return [$degreesOfFreedom, $mean, $scale];
    }

    private static function studentTUpperTail(float $standardized, float $degreesOfFreedom): float
    {
        $ratio = $degreesOfFreedom / ($degreesOfFreedom + $standardized * $standardized);
        if ($ratio <= 0.0) {
            return 0.0;
        }
        if ($ratio >= 1.0) {
            return 0.5;
        }

        return 0.5 * self::regularizedBetaValue($degreesOfFreedom / 2.0, 0.5, $ratio);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, float, float}
     */
    private static function studentTArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $degreesOfFreedom = (float) $arguments[1];
        $mean = (float) ($arguments[2] ?? 0.0);
        $scale = (float) ($arguments[3] ?? 1.0);
        if (
            !is_finite($value)
            || !is_finite($degreesOfFreedom)
            || $degreesOfFreedom <= 0.0
            || $degreesOfFreedom > self::MAX_STUDENT_T_DEGREES_OF_FREEDOM
            || !is_finite($mean)
            || !is_finite($scale)
            || $scale <= 0.0
        ) {
            throw new \DomainException(
                $function . '() requires a finite value, degrees of freedom in (0, 19999], a finite mean, '
                . 'and a positive finite scale.',
            );
        }

        return [$value, $degreesOfFreedom, $mean, $scale];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialProbabilityMass(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomialpmf');
        if ($outcome < 0.0 || $outcome > $trials || floor($outcome) !== $outcome) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            exp(self::betaBinomialLogMass((int) $outcome, $trials, $alpha, $beta)),
            'betabinomialpmf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialLogProbabilityMassFunction(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomiallogpmf');
        if ($outcome < 0.0 || $outcome > $trials || floor($outcome) !== $outcome) {
            return -INF;
        }

        return self::betaBinomialLogMass((int) $outcome, $trials, $alpha, $beta);
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialCumulativeDistribution(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomialcdf');
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome >= $trials) {
            return 1.0;
        }

        return self::betaBinomialTailValues((int) floor($outcome), $trials, $alpha, $beta)[0];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialComplementaryDistribution(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomialccdf');
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome >= $trials) {
            return 0.0;
        }

        return self::betaBinomialTailValues((int) floor($outcome), $trials, $alpha, $beta)[1];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomiallogcdf');
        if ($outcome < 0.0) {
            throw new \DomainException('betabinomiallogcdf() is negative infinity below the support.');
        }
        if ($outcome >= $trials) {
            return 0.0;
        }

        return self::betaBinomialLogTailValues((int) floor($outcome), $trials, $alpha, $beta)[0];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialLogComplementaryDistribution(array $arguments): float
    {
        [$outcome, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomiallogccdf');
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome >= $trials) {
            throw new \DomainException('betabinomiallogccdf() is negative infinity at the end of the support.');
        }

        return self::betaBinomialLogTailValues((int) floor($outcome), $trials, $alpha, $beta)[1];
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaBinomialCumulativeDistribution(array $arguments): int
    {
        [$target, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomialinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('betabinomialinv() requires a cumulative probability in [0, 1].');
        }
        if ($target === 0.0) {
            return 0;
        }
        if ($target === 1.0) {
            return $trials;
        }

        $lower = 0;
        $upper = $trials;
        while ($lower < $upper) {
            $middle = intdiv($lower + $upper, 2);
            if (self::betaBinomialTailValues($middle, $trials, $alpha, $beta)[0] >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseBetaBinomialComplementaryDistribution(array $arguments): int
    {
        [$target, $trials, $alpha, $beta] = self::betaBinomialArguments($arguments, 'betabinomialccinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('betabinomialccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0 || $trials === 0) {
            return 0;
        }
        if ($target === 0.0) {
            return $trials;
        }

        $lower = 0;
        $upper = $trials;
        while ($lower < $upper) {
            $middle = intdiv($lower + $upper, 2);
            if (self::betaBinomialTailValues($middle, $trials, $alpha, $beta)[1] <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, int, float, float}
     */
    private static function betaBinomialArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $trialValue = (float) $arguments[1];
        $alpha = (float) $arguments[2];
        $beta = (float) $arguments[3];
        if (
            !is_finite($outcome)
            || !is_finite($trialValue)
            || floor($trialValue) !== $trialValue
            || $trialValue < 0.0
            || $trialValue >= self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($alpha)
            || $alpha <= 0.0
            || $alpha > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($beta)
            || $beta <= 0.0
            || $beta > self::MAX_DISTRIBUTION_SHAPE
        ) {
            throw new \DomainException(
                $function . '() requires a finite outcome, trials in [0, 9999], '
                . 'and positive alpha and beta in (0, 10000].',
            );
        }

        return [$outcome, (int) $trialValue, $alpha, $beta];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialMean(array $arguments): float
    {
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'betabinomialmean',
        );

        return $trials * $alpha / ($alpha + $beta);
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialVariance(array $arguments): float
    {
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'betabinomialvariance',
        );
        $shapeTotal = $alpha + $beta;

        return $trials * $alpha * $beta * ($shapeTotal + $trials)
            / ($shapeTotal * $shapeTotal * ($shapeTotal + 1.0));
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialStandardDeviation(array $arguments): float
    {
        return sqrt(self::betaBinomialVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialMedian(array $arguments): int
    {
        return self::inverseBetaBinomialCumulativeDistribution([0.5, $arguments[0], $arguments[1], $arguments[2]]);
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialMode(array $arguments): int
    {
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'betabinomialmode',
        );
        $mode = 0;
        $maximumLogMass = self::betaBinomialLogMass(0, $trials, $alpha, $beta);
        for ($successes = 1; $successes <= $trials; ++$successes) {
            $logMass = self::betaBinomialLogMass($successes, $trials, $alpha, $beta);
            $tieTolerance = 32.0 * PHP_FLOAT_EPSILON * max(1.0, abs($maximumLogMass), abs($logMass));
            if ($logMass >= $maximumLogMass - $tieTolerance) {
                $maximumLogMass = $logMass;
                $mode = $successes;
            }
        }

        return $mode;
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialEntropy(array $arguments): float
    {
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'betabinomialentropy',
        );
        if ($trials === 0) {
            return 0.0;
        }
        $entropy = 0.0;
        for ($successes = 0; $successes <= $trials; ++$successes) {
            $logMass = self::betaBinomialLogMass($successes, $trials, $alpha, $beta);
            $probability = exp($logMass);
            if ($probability > 0.0) {
                $entropy -= $probability * $logMass;
            }
        }

        return self::finiteSpecialResult($entropy, 'betabinomialentropy');
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'betabinomialmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0.0 || $orderValue > 64.0) {
            throw new \DomainException('betabinomialmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }
        if ($trials === 0) {
            return 0.0;
        }
        $order = (int) $orderValue;
        $logTerms = [];
        for ($successes = 1; $successes <= $trials; ++$successes) {
            $logTerms[] = $order * log($successes)
                + self::betaBinomialLogMass($successes, $trials, $alpha, $beta);
        }
        $logMoment = self::stableLogSumExp($logTerms);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('betabinomialmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'betabinomialmoment');
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'betabinomiallogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('betabinomiallogmgf() requires a finite real argument.');
        }
        if ($trials === 0 || $tilt === 0.0) {
            return 0.0;
        }

        $tiltedLogMasses = [];
        for ($successes = 0; $successes <= $trials; ++$successes) {
            $tiltContribution = $successes * $tilt;
            if (is_infinite($tiltContribution) && $tiltContribution > 0.0) {
                throw new \OverflowException('betabinomiallogmgf() exceeds the finite float range.');
            }
            $tiltedLogMasses[] = self::betaBinomialLogMass($successes, $trials, $alpha, $beta)
                + $tiltContribution;
        }

        return self::stableLogSumExp($tiltedLogMasses);
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::betaBinomialLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'betabinomialmgf');
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialSkewness(array $arguments): float
    {
        return self::betaBinomialStandardizedMoments($arguments, 'betabinomialskewness')[0];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialExcessKurtosis(array $arguments): float
    {
        return self::betaBinomialStandardizedMoments($arguments, 'betabinomialexcesskurtosis')[1];
    }

    /** @param list<int|float> $arguments */
    private static function betaBinomialKurtosis(array $arguments): float
    {
        return 3.0 + self::betaBinomialExcessKurtosis($arguments);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function betaBinomialStandardizedMoments(array $arguments, string $function): array
    {
        [, $trials, $alpha, $beta] = self::betaBinomialArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            $function,
        );
        $mean = $trials * $alpha / ($alpha + $beta);
        $logMasses = [];
        for ($successes = 0; $successes <= $trials; ++$successes) {
            $logMasses[] = self::betaBinomialLogMass($successes, $trials, $alpha, $beta);
        }
        $logNormalizer = self::stableLogSumExp($logMasses);
        $variance = 0.0;
        $thirdCentralMoment = 0.0;
        $fourthCentralMoment = 0.0;
        foreach ($logMasses as $successes => $logMass) {
            $difference = $successes - $mean;
            $probability = exp($logMass - $logNormalizer);
            $squaredDifference = $difference * $difference;
            $variance += $squaredDifference * $probability;
            $thirdCentralMoment += $squaredDifference * $difference * $probability;
            $fourthCentralMoment += $squaredDifference * $squaredDifference * $probability;
        }
        if ($variance === 0.0) {
            throw new \DomainException($function . '() is undefined for a degenerate distribution.');
        }

        return [
            self::finiteSpecialResult(
                $thirdCentralMoment / ($variance * sqrt($variance)),
                'betabinomialskewness',
            ),
            self::finiteSpecialResult(
                $fourthCentralMoment / ($variance * $variance) - 3.0,
                'betabinomialexcesskurtosis',
            ),
        ];
    }

    private static function betaBinomialLogMass(int $successes, int $trials, float $alpha, float $beta): float
    {
        return self::logGammaPositive($trials + 1.0)
            - self::logGammaPositive($successes + 1.0)
            - self::logGammaPositive($trials - $successes + 1.0)
            + self::logBetaFunction([$successes + $alpha, $trials - $successes + $beta])
            - self::logBetaFunction([$alpha, $beta]);
    }

    /** @return array{float, float} */
    private static function betaBinomialTailValues(
        int $threshold,
        int $trials,
        float $alpha,
        float $beta,
    ): array {
        [$logLower, $logUpper] = self::betaBinomialLogTailValues($threshold, $trials, $alpha, $beta);

        return [
            self::finiteSpecialResult(exp($logLower), 'betabinomialcdf'),
            self::finiteSpecialResult(exp($logUpper), 'betabinomialccdf'),
        ];
    }

    /** @return array{float, float} */
    private static function betaBinomialLogTailValues(
        int $threshold,
        int $trials,
        float $alpha,
        float $beta,
    ): array {
        $logMasses = [];
        $maximum = -INF;
        for ($successes = 0; $successes <= $trials; ++$successes) {
            $logMass = self::betaBinomialLogMass($successes, $trials, $alpha, $beta);
            $logMasses[] = $logMass;
            $maximum = max($maximum, $logMass);
        }

        $total = 0.0;
        $lower = 0.0;
        $upper = 0.0;
        foreach ($logMasses as $successes => $logMass) {
            $mass = exp($logMass - $maximum);
            $total += $mass;
            if ($successes <= $threshold) {
                $lower += $mass;
            } else {
                $upper += $mass;
            }
        }

        return [log($lower) - log($total), log($upper) - log($total)];
    }

    /** @param list<int|float> $arguments */
    private static function zipfProbabilityMass(array $arguments): float
    {
        [$outcome, $exponent, $maximum] = self::zipfArguments($arguments, 'zipfpmf');
        if ($outcome < 1.0 || $outcome > $maximum || floor($outcome) !== $outcome) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            ($outcome ** (-$exponent)) / self::zipfNormalizer($exponent, $maximum),
            'zipfpmf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function zipfLogProbabilityMass(array $arguments): float
    {
        [$outcome, $exponent, $maximum] = self::zipfArguments($arguments, 'zipflogpmf');
        if ($outcome < 1.0 || $outcome > $maximum || floor($outcome) !== $outcome) {
            return -INF;
        }

        return -$exponent * log($outcome) - log(self::zipfNormalizer($exponent, $maximum));
    }

    /** @param list<int|float> $arguments */
    private static function zipfCumulativeDistribution(array $arguments): float
    {
        [$outcome, $exponent, $maximum] = self::zipfArguments($arguments, 'zipfcdf');
        if ($outcome < 1.0) {
            return 0.0;
        }
        if ($outcome >= $maximum) {
            return 1.0;
        }

        $sum = 0.0;
        $limit = (int) floor($outcome);
        for ($rank = 1; $rank <= $limit; ++$rank) {
            $sum += $rank ** (-$exponent);
        }

        return self::finiteSpecialResult($sum / self::zipfNormalizer($exponent, $maximum), 'zipfcdf');
    }

    /** @param list<int|float> $arguments */
    private static function zipfComplementaryDistribution(array $arguments): float
    {
        [$outcome, $exponent, $maximum] = self::zipfArguments($arguments, 'zipfccdf');
        if ($outcome < 1.0) {
            return 1.0;
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        $sum = 0.0;
        for ($rank = (int) floor($outcome) + 1; $rank <= $maximum; ++$rank) {
            $sum += $rank ** (-$exponent);
        }

        return self::finiteSpecialResult($sum / self::zipfNormalizer($exponent, $maximum), 'zipfccdf');
    }

    /** @param list<int|float> $arguments */
    private static function inverseZipfCumulativeDistribution(array $arguments): int
    {
        [$target, $exponent, $maximum] = self::zipfArguments($arguments, 'zipfinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('zipfinv() requires a cumulative probability in [0, 1].');
        }
        if ($target === 0.0) {
            return 1;
        }
        if ($target === 1.0) {
            return $maximum;
        }

        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $cumulative = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $cumulative += ($rank ** (-$exponent)) / $normalizer;
            if ($cumulative >= $target) {
                return $rank;
            }
        }

        return $maximum;
    }

    /** @param list<int|float> $arguments */
    private static function inverseZipfComplementaryDistribution(array $arguments): int
    {
        [$target, $exponent, $maximum] = self::zipfArguments($arguments, 'zipfccinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('zipfccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0) {
            return 1;
        }
        if ($target === 0.0) {
            return $maximum;
        }

        $lower = 1;
        $upper = $maximum;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::zipfComplementaryDistribution([$middle, $exponent, $maximum]) <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float, int}
     */
    private static function zipfArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $exponent = (float) $arguments[1];
        $maximum = (float) $arguments[2];
        if (
            !is_finite($outcome)
            || !is_finite($exponent)
            || $exponent < 0.0
            || !is_finite($maximum)
            || floor($maximum) !== $maximum
            || $maximum < 1.0
            || $maximum > self::MAX_DISTRIBUTION_SHAPE
        ) {
            throw new \DomainException(
                $function . '() requires a finite outcome, exponent ≥ 0, and integer support size in [1, 10000].',
            );
        }

        return [$outcome, $exponent, (int) $maximum];
    }

    /** @param list<int|float> $arguments */
    private static function zipfMean(array $arguments): float
    {
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[0], $arguments[1]], 'zipfmean');
        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $mean = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $mean += $rank * ($rank ** (-$exponent)) / $normalizer;
        }

        return self::finiteSpecialResult($mean, 'zipfmean');
    }

    /** @param list<int|float> $arguments */
    private static function zipfVariance(array $arguments): float
    {
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[0], $arguments[1]], 'zipfvariance');
        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $mean = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $mean += $rank * ($rank ** (-$exponent)) / $normalizer;
        }
        $variance = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $probability = ($rank ** (-$exponent)) / $normalizer;
            $variance += ($rank - $mean) ** 2 * $probability;
        }

        return self::finiteSpecialResult($variance, 'zipfvariance');
    }

    /** @param list<int|float> $arguments */
    private static function zipfStandardDeviation(array $arguments): float
    {
        return sqrt(self::zipfVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function zipfMedian(array $arguments): int
    {
        return self::inverseZipfCumulativeDistribution([0.5, $arguments[0], $arguments[1]]);
    }

    /** @param list<int|float> $arguments */
    private static function zipfMode(array $arguments): int
    {
        self::zipfArguments([1.0, $arguments[0], $arguments[1]], 'zipfmode');

        return 1;
    }

    /** @param list<int|float> $arguments */
    private static function zipfEntropy(array $arguments): float
    {
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[0], $arguments[1]], 'zipfentropy');
        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $entropy = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $probability = ($rank ** (-$exponent)) / $normalizer;
            $entropy -= $probability * log($probability);
        }

        return self::finiteSpecialResult($entropy, 'zipfentropy');
    }

    /** @param list<int|float> $arguments */
    private static function zipfSkewness(array $arguments): float
    {
        return self::zipfStandardizedMoments($arguments, 'zipfskewness')[0];
    }

    /** @param list<int|float> $arguments */
    private static function zipfExcessKurtosis(array $arguments): float
    {
        return self::zipfStandardizedMoments($arguments, 'zipfexcesskurtosis')[1];
    }

    /** @param list<int|float> $arguments */
    private static function zipfKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(3.0 + self::zipfExcessKurtosis($arguments), 'zipfkurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function zipfRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[1], $arguments[2]], 'zipfmoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('zipfmoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }

        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $moment = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $moment += ($rank ** $order) * ($rank ** (-$exponent)) / $normalizer;
        }

        return self::finiteSpecialResult($moment, 'zipfmoment');
    }

    /** @param list<int|float> $arguments */
    private static function zipfLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[1], $arguments[2]], 'zipflogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('zipflogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logNormalizer = log(self::zipfNormalizer($exponent, $maximum));
        $logTerms = [];
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $tiltContribution = $rank * $tilt;
            if ($tiltContribution === INF) {
                throw new \OverflowException('zipflogmgf() exceeds the finite floating-point range.');
            }
            $logTerms[] = -$exponent * log((float) $rank) + $tiltContribution - $logNormalizer;
        }

        return self::stableLogSumExp($logTerms);
    }

    /** @param list<int|float> $arguments */
    private static function zipfMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(exp(self::zipfLogMomentGeneratingFunction($arguments)), 'zipfmgf');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function zipfStandardizedMoments(array $arguments, string $function): array
    {
        [, $exponent, $maximum] = self::zipfArguments([1.0, $arguments[0], $arguments[1]], $function);
        if ($maximum === 1) {
            throw new \DomainException($function . '() is undefined for a degenerate distribution.');
        }

        $normalizer = self::zipfNormalizer($exponent, $maximum);
        $mean = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $mean += $rank * ($rank ** (-$exponent)) / $normalizer;
        }
        $variance = 0.0;
        $thirdCentralMoment = 0.0;
        $fourthCentralMoment = 0.0;
        for ($rank = 1; $rank <= $maximum; ++$rank) {
            $difference = $rank - $mean;
            $probability = ($rank ** (-$exponent)) / $normalizer;
            $squaredDifference = $difference * $difference;
            $variance += $squaredDifference * $probability;
            $thirdCentralMoment += $squaredDifference * $difference * $probability;
            $fourthCentralMoment += $squaredDifference * $squaredDifference * $probability;
        }
        if ($variance === 0.0) {
            throw new \DomainException($function . '() is undefined for a degenerate distribution.');
        }

        return [
            self::finiteSpecialResult($thirdCentralMoment / ($variance * sqrt($variance)), 'zipfskewness'),
            self::finiteSpecialResult($fourthCentralMoment / ($variance * $variance) - 3.0, 'zipfexcesskurtosis'),
        ];
    }

    private static function zipfNormalizer(float $exponent, int $maximum): float
    {
        return $exponent === 0.0
            ? (float) $maximum
            : self::harmonicNumber([$maximum, $exponent]);
    }

    /** @param list<int|float> $arguments */
    private static function benfordProbabilityMass(array $arguments): float
    {
        [$digit, $base] = self::benfordArguments($arguments, 'benfordpmf');
        if ($digit < 1.0 || $digit >= $base || floor($digit) !== $digit) {
            return 0.0;
        }

        return log1p(1.0 / $digit) / log((float) $base);
    }

    /** @param list<int|float> $arguments */
    private static function benfordLogProbabilityMass(array $arguments): float
    {
        [$digit, $base] = self::benfordArguments($arguments, 'benfordlogpmf');
        if ($digit < 1.0 || $digit >= $base || floor($digit) !== $digit) {
            return -INF;
        }

        return log(log1p(1.0 / $digit)) - log(log((float) $base));
    }

    /** @param list<int|float> $arguments */
    private static function benfordCumulativeDistribution(array $arguments): float
    {
        [$threshold, $base] = self::benfordArguments($arguments, 'benfordcdf');
        if ($threshold < 1.0) {
            return 0.0;
        }
        $digit = floor($threshold);
        if ($digit >= $base - 1) {
            return 1.0;
        }

        return log1p($digit) / log((float) $base);
    }

    /** @param list<int|float> $arguments */
    private static function benfordComplementaryDistribution(array $arguments): float
    {
        [$threshold, $base] = self::benfordArguments($arguments, 'benfordccdf');
        if ($threshold < 1.0) {
            return 1.0;
        }
        $digit = floor($threshold);
        if ($digit >= $base - 1) {
            return 0.0;
        }

        return (log((float) $base) - log1p($digit)) / log((float) $base);
    }

    /** @param list<int|float> $arguments */
    private static function inverseBenfordCumulativeDistribution(array $arguments): int
    {
        [$probability, $base] = self::benfordArguments($arguments, 'benfordinv');
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('benfordinv() requires a cumulative probability in [0, 1].');
        }
        if ($probability === 0.0) {
            return 1;
        }
        if ($probability === 1.0) {
            return $base - 1;
        }

        $lower = 1;
        $upper = $base - 1;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            $cumulative = self::benfordCumulativeDistribution([$middle, $base]);
            if ($cumulative >= $probability || $probability - $cumulative <= 2.0 * PHP_FLOAT_EPSILON) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseBenfordComplementaryDistribution(array $arguments): int
    {
        [$target, $base] = self::benfordArguments($arguments, 'benfordccinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('benfordccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0) {
            return 1;
        }
        if ($target === 0.0) {
            return $base - 1;
        }

        $lower = 1;
        $upper = $base - 1;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::benfordComplementaryDistribution([$middle, $base]) <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function benfordMean(array $arguments): float
    {
        [, $base] = self::benfordArguments([0.0, $arguments[0] ?? 10.0], 'benfordmean');
        $maximumDigit = $base - 1;
        $meanNumerator = $maximumDigit * log((float) $base)
            - self::logGammaPositive((float) $base);

        return self::finiteSpecialResult($meanNumerator / log((float) $base), 'benfordmean');
    }

    /** @param list<int|float> $arguments */
    private static function benfordMedian(array $arguments): int
    {
        $base = (float) ($arguments[0] ?? 10.0);

        return self::inverseBenfordCumulativeDistribution([0.5, $base]);
    }

    /** @param list<int|float> $arguments */
    private static function benfordMode(array $arguments): int
    {
        self::benfordArguments([0.0, $arguments[0] ?? 10.0], 'benfordmode');

        return 1;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, int}
     */
    private static function benfordArguments(array $arguments, string $function): array
    {
        $value = (float) $arguments[0];
        $base = (float) ($arguments[1] ?? 10.0);
        if (
            !is_finite($value)
            || !is_finite($base)
            || floor($base) !== $base
            || $base < 2.0
            || $base > self::MAX_NUMBER_THEORY_INPUT
        ) {
            throw new \DomainException(
                $function . '() requires a finite value and an integer base in [2, 1000000000000].',
            );
        }

        return [$value, (int) $base];
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionProbabilityMass(array $arguments): float
    {
        [$outcome, $exponent] = self::zetaDistributionArguments($arguments, 'zetapmf');
        if ($outcome < 1.0 || floor($outcome) !== $outcome) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            exp(-$exponent * log($outcome) - log(self::zetaFunction([$exponent]))),
            'zetapmf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionLogProbabilityMass(array $arguments): float
    {
        [$outcome, $exponent] = self::zetaDistributionArguments($arguments, 'zetalogpmf');
        if ($outcome < 1.0 || floor($outcome) !== $outcome) {
            return -INF;
        }

        return -$exponent * log($outcome) - log(self::zetaFunction([$exponent]));
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionCumulativeDistribution(array $arguments): float
    {
        [$outcome, $exponent] = self::zetaDistributionArguments($arguments, 'zetacdf');
        if ($outcome < 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            1.0 - self::zetaDistributionTail((float) floor($outcome), $exponent),
            'zetacdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionComplementaryDistribution(array $arguments): float
    {
        [$outcome, $exponent] = self::zetaDistributionArguments($arguments, 'zetaccdf');
        if ($outcome < 1.0) {
            return 1.0;
        }

        return self::zetaDistributionTail((float) floor($outcome), $exponent);
    }

    /** @param list<int|float> $arguments */
    private static function inverseZetaDistributionCumulativeDistribution(array $arguments): int
    {
        [$target, $exponent] = self::zetaDistributionArguments($arguments, 'zetainv');
        if ($target < 0.0 || $target >= 1.0) {
            throw new \DomainException('zetainv() requires a cumulative probability in [0, 1).');
        }
        if ($target === 0.0) {
            return 1;
        }

        $targetTail = 1.0 - $target;
        $lower = 1;
        $upper = 1;
        while (self::zetaDistributionTail((float) $upper, $exponent) > $targetTail) {
            if ($upper > intdiv(PHP_INT_MAX, 2)) {
                throw new \OverflowException('zetainv() quantile exceeds the host integer range.');
            }
            $lower = $upper + 1;
            $upper *= 2;
        }

        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::zetaDistributionTail((float) $middle, $exponent) <= $targetTail) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseZetaDistributionComplementaryDistribution(array $arguments): int
    {
        [$target, $exponent] = self::zetaDistributionArguments($arguments, 'zetaccinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('zetaccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0) {
            return 1;
        }
        if ($target === 0.0) {
            throw new \DomainException('zetaccinv() has no finite quantile at survival probability 0.');
        }

        $lower = 1;
        $upper = 1;
        while (self::zetaDistributionTail((float) $upper, $exponent) > $target) {
            if ($upper > intdiv(PHP_INT_MAX, 2)) {
                throw new \OverflowException('zetaccinv() quantile exceeds the host integer range.');
            }
            $lower = $upper + 1;
            $upper *= 2;
        }

        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::zetaDistributionTail((float) $middle, $exponent) <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionMean(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        self::zetaDistributionArguments([1.0, $exponent], 'zetamean');
        if ($exponent <= 2.0) {
            throw new \DomainException('zetamean() exists only when the exponent is greater than 2.');
        }

        return self::finiteSpecialResult(
            self::zetaFunction([$exponent - 1.0]) / self::zetaFunction([$exponent]),
            'zetamean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionVariance(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        self::zetaDistributionArguments([1.0, $exponent], 'zetavariance');
        if ($exponent <= 3.0) {
            throw new \DomainException('zetavariance() exists only when the exponent is greater than 3.');
        }

        if ($exponent > 8.0) {
            return self::zetaDistributionDirectVariance($exponent);
        }

        $firstMoment = self::zetaDistributionMean([$exponent]);
        $secondMoment = self::finiteSpecialResult(
            self::zetaFunction([$exponent - 2.0]) / self::zetaFunction([$exponent]),
            'zetavariance',
        );

        return self::finiteSpecialResult($secondMoment - $firstMoment * $firstMoment, 'zetavariance');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::zetaDistributionVariance($arguments)), 'zetastddev');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionMedian(array $arguments): int
    {
        return self::inverseZetaDistributionCumulativeDistribution([0.5, $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionMode(array $arguments): int
    {
        self::zetaDistributionArguments([1.0, $arguments[0]], 'zetamode');

        return 1;
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionEntropy(array $arguments): float
    {
        [, $exponent] = self::zetaDistributionArguments([1.0, $arguments[0]], 'zetaentropy');
        $normalizer = self::zetaFunction([$exponent]);
        $logarithmicDerivative = self::zetaDerivativeFunction([$exponent]) / $normalizer;
        $entropy = log($normalizer) - $exponent * $logarithmicDerivative;

        return self::finiteSpecialResult($entropy, 'zetaentropy');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        $exponent = (float) $arguments[1];
        self::zetaDistributionArguments([1.0, $exponent], 'zetamoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('zetamoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }
        if ($exponent <= $order + 1.0) {
            throw new \DomainException('zetamoment() exists only when the exponent is greater than order + 1.');
        }

        return self::finiteSpecialResult(
            self::zetaFunction([$exponent - $order]) / self::zetaFunction([$exponent]),
            'zetamoment',
        );
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionSkewness(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if ($exponent <= 4.0) {
            throw new \DomainException('zetaskewness() exists only when the exponent is greater than 4.');
        }
        if ($exponent > 8.0) {
            [, $variance, $thirdCentralMoment] = self::zetaDistributionDirectCentralMoments($exponent);

            return self::finiteSpecialResult(
                $thirdCentralMoment / ($variance ** 1.5),
                'zetaskewness',
            );
        }
        $mean = self::zetaDistributionRawMoment([1.0, $exponent]);
        $second = self::zetaDistributionRawMoment([2.0, $exponent]);
        $third = self::zetaDistributionRawMoment([3.0, $exponent]);
        $variance = $second - $mean * $mean;
        $centralThird = $third - 3.0 * $mean * $second + 2.0 * $mean ** 3;

        return self::finiteSpecialResult($centralThird / ($variance ** 1.5), 'zetaskewness');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionExcessKurtosis(array $arguments): float
    {
        $exponent = (float) $arguments[0];
        if ($exponent <= 5.0) {
            throw new \DomainException('zetaexcesskurtosis() exists only when the exponent is greater than 5.');
        }
        if ($exponent > 8.0) {
            [, $variance, , $fourthCentralMoment] = self::zetaDistributionDirectCentralMoments($exponent);

            return self::finiteSpecialResult(
                $fourthCentralMoment / ($variance ** 2) - 3.0,
                'zetaexcesskurtosis',
            );
        }
        $mean = self::zetaDistributionRawMoment([1.0, $exponent]);
        $second = self::zetaDistributionRawMoment([2.0, $exponent]);
        $third = self::zetaDistributionRawMoment([3.0, $exponent]);
        $fourth = self::zetaDistributionRawMoment([4.0, $exponent]);
        $variance = $second - $mean * $mean;
        $centralFourth = $fourth - 4.0 * $mean * $third + 6.0 * $mean ** 2 * $second - 3.0 * $mean ** 4;

        return self::finiteSpecialResult($centralFourth / ($variance ** 2) - 3.0, 'zetaexcesskurtosis');
    }

    /** @return array{float, float, float, float} */
    private static function zetaDistributionDirectCentralMoments(float $exponent): array
    {
        $normalizer = self::zetaFunction([$exponent]);
        $mean = 0.0;
        for ($rank = 1; $rank <= 10_000; ++$rank) {
            $mean += ($rank ** (1.0 - $exponent)) / $normalizer;
        }

        $variance = 0.0;
        $thirdCentralMoment = 0.0;
        $fourthCentralMoment = 0.0;
        for ($rank = 1; $rank <= 10_000; ++$rank) {
            $probability = ($rank ** (-$exponent)) / $normalizer;
            $difference = $rank - $mean;
            $squaredDifference = $difference * $difference;
            $variance += $squaredDifference * $probability;
            $thirdCentralMoment += $squaredDifference * $difference * $probability;
            $fourthCentralMoment += $squaredDifference * $squaredDifference * $probability;
        }

        return [$mean, $variance, $thirdCentralMoment, $fourthCentralMoment];
    }

    private static function zetaDistributionDirectVariance(float $exponent): float
    {
        [, $variance] = self::zetaDistributionDirectCentralMoments($exponent);

        return self::finiteSpecialResult($variance, 'zetavariance');
    }

    /** @param list<int|float> $arguments */
    private static function zetaDistributionKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(3.0 + self::zetaDistributionExcessKurtosis($arguments), 'zetakurtosis');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function zetaDistributionArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $exponent = (float) $arguments[1];
        if (!is_finite($outcome) || !is_finite($exponent) || $exponent <= 1.0) {
            throw new \DomainException($function . '() requires a finite outcome and exponent greater than 1.');
        }

        return [$outcome, $exponent];
    }

    private static function zetaDistributionTail(float $outcome, float $exponent): float
    {
        $tail = self::hurwitzZetaFunction([$exponent, $outcome + 1.0]) / self::zetaFunction([$exponent]);

        return self::finiteSpecialResult($tail, 'zetaccdf');
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformProbabilityMass(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformpmf');
        if (floor($outcome) !== $outcome || $outcome < $minimum || $outcome > $maximum) {
            return 0.0;
        }

        return 1.0 / ($maximum - $minimum + 1);
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformLogProbabilityMass(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformlogpmf');
        if (floor($outcome) !== $outcome || $outcome < $minimum || $outcome > $maximum) {
            return -INF;
        }

        return -log((float) ($maximum - $minimum + 1));
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformCumulativeDistribution(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformcdf');
        if ($outcome < $minimum) {
            return 0.0;
        }
        if ($outcome >= $maximum) {
            return 1.0;
        }

        return (floor($outcome) - $minimum + 1.0) / ($maximum - $minimum + 1);
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformComplementaryDistribution(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformccdf');
        if ($outcome < $minimum) {
            return 1.0;
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        return ($maximum - floor($outcome)) / ($maximum - $minimum + 1);
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformlogcdf');
        if ($outcome < $minimum) {
            throw new \DomainException('discreteuniformlogcdf() is negative infinity below the support.');
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        return log(floor($outcome) - $minimum + 1.0) - log($maximum - $minimum + 1.0);
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformLogComplementaryDistribution(array $arguments): float
    {
        [$outcome, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformlogccdf');
        if ($outcome < $minimum) {
            return 0.0;
        }
        if ($outcome >= $maximum) {
            throw new \DomainException('discreteuniformlogccdf() is negative infinity at the end of the support.');
        }

        return log($maximum - floor($outcome)) - log($maximum - $minimum + 1.0);
    }

    /** @param list<int|float> $arguments */
    private static function inverseDiscreteUniformCumulativeDistribution(array $arguments): int
    {
        [$target, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniforminv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('discreteuniforminv() requires a cumulative probability in [0, 1].');
        }
        if ($target === 0.0) {
            return $minimum;
        }
        if ($target === 1.0) {
            return $maximum;
        }

        $lower = $minimum;
        $upper = $maximum;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::discreteUniformCumulativeDistribution([$middle, $minimum, $maximum]) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseDiscreteUniformComplementaryDistribution(array $arguments): int
    {
        [$target, $minimum, $maximum] = self::discreteUniformArguments($arguments, 'discreteuniformccinv');
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('discreteuniformccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0) {
            return $minimum;
        }
        if ($target === 0.0) {
            return $maximum;
        }

        $quantile = (int) ceil($maximum - $target * ($maximum - $minimum + 1.0));
        $quantile = min($maximum, max($minimum, $quantile));
        while (
            $quantile > $minimum
            && self::discreteUniformComplementaryDistribution([$quantile - 1, $minimum, $maximum]) <= $target
        ) {
            --$quantile;
        }
        while (
            $quantile < $maximum
            && self::discreteUniformComplementaryDistribution([$quantile, $minimum, $maximum]) > $target
        ) {
            ++$quantile;
        }

        return $quantile;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceProbabilityMass(array $arguments): float
    {
        [$outcome, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplacepmf');
        if (floor($outcome) !== $outcome) {
            return 0.0;
        }
        if ($decay === 0.0) {
            return $outcome === 0.0 ? 1.0 : 0.0;
        }

        return self::finiteSpecialResult(
            ((1.0 - $decay) / (1.0 + $decay)) * ($decay ** abs($outcome)),
            'discretelaplacepmf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceLogProbabilityMass(array $arguments): float
    {
        [$outcome, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplacelogpmf');
        if (floor($outcome) !== $outcome) {
            return -INF;
        }
        if ($decay === 0.0) {
            return $outcome === 0.0 ? 0.0 : -INF;
        }

        return log1p(-$decay) - log1p($decay) + abs($outcome) * log($decay);
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceCumulativeDistribution(array $arguments): float
    {
        [$outcome, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplacecdf');
        if ($outcome < 0.0) {
            return $decay === 0.0 ? 0.0 : self::finiteSpecialResult(
                ($decay ** (-floor($outcome))) / (1.0 + $decay),
                'discretelaplacecdf',
            );
        }
        if ($decay === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            1.0 - ($decay ** (floor($outcome) + 1.0)) / (1.0 + $decay),
            'discretelaplacecdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceComplementaryDistribution(array $arguments): float
    {
        [$outcome, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplaceccdf');
        if ($outcome < 0.0) {
            return $decay === 0.0 ? 1.0 : self::finiteSpecialResult(
                1.0 - ($decay ** (-floor($outcome))) / (1.0 + $decay),
                'discretelaplaceccdf',
            );
        }
        if ($decay === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            ($decay ** (floor($outcome) + 1.0)) / (1.0 + $decay),
            'discretelaplaceccdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseDiscreteLaplaceCumulativeDistribution(array $arguments): int
    {
        [$target, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplaceinv');
        if ($target <= 0.0 || $target >= 1.0) {
            throw new \DomainException('discretelaplaceinv() requires a probability strictly between zero and one.');
        }
        if ($decay === 0.0) {
            return 0;
        }

        if ($target <= $decay / (1.0 + $decay)) {
            $candidate = -floor(log($target * (1.0 + $decay)) / log($decay));
        } elseif ($target <= 1.0 / (1.0 + $decay)) {
            return 0;
        } else {
            $candidate = ceil(log((1.0 - $target) * (1.0 + $decay)) / log($decay)) - 1.0;
        }
        if ($candidate < PHP_INT_MIN || $candidate >= PHP_INT_MAX) {
            throw new \OverflowException('discretelaplaceinv() quantile exceeds the host integer range.');
        }
        $quantile = (int) $candidate;
        while (
            $quantile > PHP_INT_MIN
            && self::discreteLaplaceCumulativeDistribution([$quantile - 1, $decay]) >= $target
        ) {
            --$quantile;
        }
        while (self::discreteLaplaceCumulativeDistribution([$quantile, $decay]) < $target) {
            if ($quantile >= PHP_INT_MAX) {
                throw new \OverflowException('discretelaplaceinv() quantile exceeds the host integer range.');
            }
            ++$quantile;
        }

        return $quantile;
    }

    /** @param list<int|float> $arguments */
    private static function inverseDiscreteLaplaceComplementaryDistribution(array $arguments): int
    {
        [$target, $decay] = self::discreteLaplaceArguments($arguments, 'discretelaplaceccinv');
        if (!is_finite($target) || $target < 0.0 || $target >= 1.0) {
            throw new \DomainException(
                'discretelaplaceccinv() requires a survival probability in [0, 1); '
                . 'probability 1 has no finite quantile.',
            );
        }
        if ($decay === 0.0) {
            return 0;
        }
        if ($target === 0.0) {
            throw new \DomainException('discretelaplaceccinv() has no finite quantile at survival probability 0.');
        }

        if ($target < $decay / (1.0 + $decay)) {
            $candidate = ceil(log($target * (1.0 + $decay)) / log($decay)) - 1.0;
        } elseif ($target < 1.0 / (1.0 + $decay)) {
            return 0;
        } else {
            $candidate = -floor(log((1.0 - $target) * (1.0 + $decay)) / log($decay));
        }
        if ($candidate < PHP_INT_MIN || $candidate >= PHP_INT_MAX) {
            throw new \OverflowException('discretelaplaceccinv() quantile exceeds the host integer range.');
        }
        $quantile = (int) $candidate;
        while (
            $quantile > PHP_INT_MIN
            && self::discreteLaplaceComplementaryDistribution([$quantile - 1, $decay]) <= $target
        ) {
            --$quantile;
        }
        while (self::discreteLaplaceComplementaryDistribution([$quantile, $decay]) > $target) {
            if ($quantile >= PHP_INT_MAX) {
                throw new \OverflowException('discretelaplaceccinv() quantile exceeds the host integer range.');
            }
            ++$quantile;
        }

        return $quantile;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceMean(array $arguments): float
    {
        self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplacemean');

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceVariance(array $arguments): float
    {
        [, $decay] = self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplacevariance');

        return self::finiteSpecialResult(
            (2.0 * $decay) / ((1.0 - $decay) * (1.0 - $decay)),
            'discretelaplacevariance',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::discreteLaplaceVariance($arguments)), 'discretelaplacestddev');
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceMedian(array $arguments): int
    {
        self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplacemedian');

        return 0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceMode(array $arguments): int
    {
        self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplacemode');

        return 0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceEntropy(array $arguments): float
    {
        [, $decay] = self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplaceentropy');
        if ($decay === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            log1p($decay) - log1p(-$decay) - (2.0 * $decay * log($decay)) / (1.0 - $decay * $decay),
            'discretelaplaceentropy',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $decay] = self::discreteLaplaceArguments([0.0, $arguments[1]], 'discretelapacemoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('discretelapacemoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }
        if ($decay === 0.0 || fmod($order, 2.0) === 1.0) {
            return 0.0;
        }

        $orderInt = (int) $order;
        $eulerian = [1.0];
        for ($degree = 2; $degree <= $orderInt; ++$degree) {
            $next = array_fill(0, $degree, 0.0);
            foreach ($eulerian as $index => $coefficient) {
                $next[$index] += ($index + 1.0) * $coefficient;
                $next[$index + 1] += ($degree - 1.0 - $index) * $coefficient;
            }
            $eulerian = $next;
        }
        $polynomial = 0.0;
        for ($index = count($eulerian) - 1; $index >= 0; --$index) {
            $polynomial = $polynomial * $decay + $eulerian[$index];
        }
        $logMoment = log(2.0) + log($decay) + log($polynomial)
            - log1p($decay) - $order * log1p(-$decay);

        return self::finiteSpecialResult(exp($logMoment), 'discretelapacemoment');
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceSkewness(array $arguments): float
    {
        self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplaceskewness');

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceExcessKurtosis(array $arguments): float
    {
        [, $decay] = self::discreteLaplaceArguments([0.0, $arguments[0]], 'discretelaplaceexcesskurtosis');
        if ($decay === 0.0) {
            throw new \DomainException('discretelaplaceexcesskurtosis() is undefined for a degenerate distribution.');
        }
        $variance = self::discreteLaplaceVariance([$decay]);
        $fourthMoment = self::discreteLaplaceRawMoment([4.0, $decay]);

        return self::finiteSpecialResult(
            $fourthMoment / ($variance * $variance) - 3.0,
            'discretelaplaceexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::discreteLaplaceExcessKurtosis($arguments),
            'discretelaplacekurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $decay] = self::discreteLaplaceArguments([0.0, $arguments[1]], 'discretelaplacelogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('discretelaplacelogmgf() requires a finite real argument.');
        }
        if ($decay === 0.0 || $tilt === 0.0) {
            return 0.0;
        }
        if (abs($tilt) >= -log($decay)) {
            throw new \DomainException('discretelaplacelogmgf() exists only when |t| < -log(decay).');
        }

        $logDecay = log($decay);

        return self::finiteSpecialResult(
            2.0 * log1p(-$decay)
                - log1p(-exp($logDecay + abs($tilt)))
                - log1p(-exp($logDecay - abs($tilt))),
            'discretelaplacelogmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteLaplaceMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(
            exp(self::discreteLaplaceLogMomentGeneratingFunction($arguments)),
            'discretelaplacemgf',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function discreteLaplaceArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $decay = (float) $arguments[1];
        if (!is_finite($outcome) || !is_finite($decay) || $decay < 0.0 || $decay >= 1.0) {
            throw new \DomainException($function . '() requires a finite outcome and decay parameter in [0, 1).');
        }

        return [$outcome, $decay];
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, int, int}
     */
    private static function discreteUniformArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $minimum = (float) $arguments[1];
        $maximum = (float) $arguments[2];
        if (
            !is_finite($outcome)
            || !is_finite($minimum)
            || floor($minimum) !== $minimum
            || abs($minimum) > self::MAX_NUMBER_THEORY_INPUT
            || !is_finite($maximum)
            || floor($maximum) !== $maximum
            || abs($maximum) > self::MAX_NUMBER_THEORY_INPUT
            || $minimum > $maximum
        ) {
            throw new \DomainException(
                $function . '() requires a finite outcome and ordered integer bounds '
                . 'in [-1000000000000, 1000000000000].',
            );
        }

        return [$outcome, (int) $minimum, (int) $maximum];
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformMean(array $arguments): float
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformmean',
        );

        return ($minimum + $maximum) / 2.0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformVariance(array $arguments): float
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformvariance',
        );
        $supportSize = $maximum - $minimum + 1;

        return ($supportSize * $supportSize - 1.0) / 12.0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::discreteUniformVariance($arguments)), 'discreteuniformstddev');
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformEntropy(array $arguments): float
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformentropy',
        );

        return log((float) ($maximum - $minimum + 1));
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformSkewness(array $arguments): float
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformskewness',
        );
        if ($minimum === $maximum) {
            throw new \DomainException('discreteuniformskewness() is undefined for a degenerate distribution.');
        }

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformExcessKurtosis(array $arguments): float
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformexcesskurtosis',
        );
        $supportSize = (float) ($maximum - $minimum + 1);
        if ($supportSize === 1.0) {
            throw new \DomainException('discreteuniformexcesskurtosis() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            -6.0 * ($supportSize * $supportSize + 1.0) / (5.0 * ($supportSize * $supportSize - 1.0)),
            'discreteuniformexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(
            3.0 + self::discreteUniformExcessKurtosis($arguments),
            'discreteuniformkurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[1], $arguments[2]],
            'discreteuniformmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0 || $orderValue > 64) {
            throw new \DomainException('discreteuniformmoment() requires an integer order in [0, 64].');
        }

        $order = (int) $orderValue;
        if ($order === 0) {
            return 1.0;
        }

        $supportSize = $maximum - $minimum + 1;
        $sum = 0.0;
        for ($outcome = $minimum; $outcome <= $maximum; ++$outcome) {
            $term = (float) $outcome ** $order;
            if (!is_finite($term) || !is_finite($sum + $term)) {
                throw new \OverflowException('discreteuniformmoment() exceeds the finite floating-point range.');
            }
            $sum += $term;
        }

        return self::finiteSpecialResult($sum / $supportSize, 'discreteuniformmoment');
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformMedian(array $arguments): int
    {
        [, $minimum, $maximum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformmedian',
        );

        $supportSize = $maximum - $minimum + 1;

        return $minimum + intdiv($supportSize - 1, 2);
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformMode(array $arguments): int
    {
        [, $minimum] = self::discreteUniformArguments(
            [0.0, $arguments[0], $arguments[1]],
            'discreteuniformmode',
        );

        return $minimum;
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformLogMomentGeneratingFunction(array $arguments): float
    {
        [$tilt, $minimum, $maximum] = self::discreteUniformArguments(
            [$arguments[0], $arguments[1], $arguments[2]],
            'discreteuniformlogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('discreteuniformlogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $supportSize = $maximum - $minimum + 1;
        if ($supportSize === 1) {
            return self::finiteSpecialResult($tilt * $minimum, 'discreteuniformlogmgf');
        }

        if ($tilt > 0.0) {
            $leadingTerm = $tilt * $maximum;
            $scaledSpan = -$tilt * $supportSize;
            $scaledTilt = -$tilt;
        } else {
            $leadingTerm = $tilt * $minimum;
            $scaledSpan = $tilt * $supportSize;
            $scaledTilt = $tilt;
        }
        if (!is_finite($leadingTerm)) {
            throw new \OverflowException('discreteuniformlogmgf() exceeds the finite float range.');
        }
        $spanCorrection = is_infinite($scaledSpan)
            ? 0.0
            : self::logOneMinusExponential([$scaledSpan]);
        $stepCorrection = self::logOneMinusExponential([$scaledTilt]);

        return self::finiteSpecialResult(
            $leadingTerm + $spanCorrection - $stepCorrection - log((float) $supportSize),
            'discreteuniformlogmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function discreteUniformMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::discreteUniformLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'discreteuniformmgf');
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliMean(array $arguments): float
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoullimean',
        );

        return $successProbability;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliVariance(array $arguments): float
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoullivariance',
        );

        return $successProbability * (1.0 - $successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliStandardDeviation(array $arguments): float
    {
        return sqrt(self::bernoulliVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliEntropy(array $arguments): float
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoullientropy',
        );
        if ($successProbability === 0.0 || $successProbability === 1.0) {
            return 0.0;
        }

        $failureProbability = 1.0 - $successProbability;

        return -$successProbability * log($successProbability) - $failureProbability * log($failureProbability);
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliSkewness(array $arguments): float
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoulliskewness',
        );
        $variance = $successProbability * (1.0 - $successProbability);
        if ($variance === 0.0) {
            throw new \DomainException('bernoulliskewness() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            (1.0 - 2.0 * $successProbability) / sqrt($variance),
            'bernoulliskewness',
        );
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliExcessKurtosis(array $arguments): float
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoulliexcesskurtosis',
        );
        $variance = $successProbability * (1.0 - $successProbability);
        if ($variance === 0.0) {
            throw new \DomainException('bernoulliexcesskurtosis() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult((1.0 - 6.0 * $variance) / $variance, 'bernoulliexcesskurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliKurtosis(array $arguments): float
    {
        return self::finiteSpecialResult(3.0 + self::bernoulliExcessKurtosis($arguments), 'bernoullikurtosis');
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[1]],
            'bernoullimoment',
        );
        if (!is_finite($order) || floor($order) !== $order || $order < 0.0 || $order > 64.0) {
            throw new \DomainException('bernoullimoment() requires an integer order in [0, 64].');
        }

        return $order === 0.0 ? 1.0 : $successProbability;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliMedian(array $arguments): int
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoullimedian',
        );

        return $successProbability <= 0.5 ? 0 : 1;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliMode(array $arguments): int
    {
        [, $successProbability] = self::bernoulliDistributionArguments(
            [0.0, $arguments[0]],
            'bernoullimode',
        );

        return $successProbability > 0.5 ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliLogMomentGeneratingFunction(array $arguments): float
    {
        [$tilt, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoullilogmgf');
        if ($successProbability === 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            return $tilt;
        }

        return self::stableLogSumExp([
            log1p(-$successProbability),
            log($successProbability) + $tilt,
        ]);
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::bernoulliLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'bernoullimgf');
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliProbabilityMass(array $arguments): float
    {
        [$outcome, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoullipmf');
        if (($outcome !== 0.0 && $outcome !== 1.0)) {
            return 0.0;
        }

        return $outcome === 1.0 ? $successProbability : 1.0 - $successProbability;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliLogProbabilityMass(array $arguments): float
    {
        [$outcome, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoullilogpmf');
        if ($outcome === 1.0) {
            return $successProbability === 0.0 ? -INF : log($successProbability);
        }
        if ($outcome === 0.0) {
            return $successProbability === 1.0 ? -INF : log1p(-$successProbability);
        }

        return -INF;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliCumulativeDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoullicdf');
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome < 1.0) {
            return 1.0 - $successProbability;
        }

        return 1.0;
    }

    /** @param list<int|float> $arguments */
    private static function bernoulliComplementaryDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoulliccdf');
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome < 1.0) {
            return $successProbability;
        }

        return 0.0;
    }

    /** @param list<int|float> $arguments */
    private static function inverseBernoulliDistribution(array $arguments): int
    {
        [$target, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoulliinv');
        if ($target < 0.0 || $target > 1.0) {
            throw new \DomainException('bernoulliinv() requires a cumulative probability in [0, 1].');
        }

        return $target <= 1.0 - $successProbability ? 0 : 1;
    }

    /** @param list<int|float> $arguments */
    private static function inverseBernoulliComplementaryDistribution(array $arguments): int
    {
        [$target, $successProbability] = self::bernoulliDistributionArguments($arguments, 'bernoulliccinv');
        if ($target < 0.0 || $target >= 1.0) {
            throw new \DomainException(
                'bernoulliccinv() requires a strict upper-tail probability in [0, 1); '
                . 'probability 1 has no finite quantile.',
            );
        }

        return $target >= $successProbability ? 0 : 1;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function bernoulliDistributionArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $successProbability = (float) $arguments[1];
        if (
            !is_finite($outcome)
            || !is_finite($successProbability)
            || $successProbability < 0.0
            || $successProbability > 1.0
        ) {
            throw new \DomainException($function . '() requires a finite outcome and probability in [0, 1].');
        }

        return [$outcome, $successProbability];
    }

    /** @param list<int|float> $arguments */
    private static function binomialProbabilityMass(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomialpmf');
        $successes = (float) $arguments[0];
        if (!is_finite($successes)) {
            throw new \DomainException('binomialpmf() requires a finite outcome value.');
        }
        if ($successes < 0.0 || $successes > $trials || floor($successes) !== $successes) {
            return 0.0;
        }

        $successCount = (int) $successes;
        if ($successProbability === 0.0) {
            return $successCount === 0 ? 1.0 : 0.0;
        }
        if ($successProbability === 1.0) {
            return $successCount === $trials ? 1.0 : 0.0;
        }

        $logMass = self::logGammaPositive($trials + 1.0)
            - self::logGammaPositive($successCount + 1.0)
            - self::logGammaPositive($trials - $successCount + 1.0)
            + $successCount * log($successProbability)
            + ($trials - $successCount) * log1p(-$successProbability);

        return self::finiteSpecialResult(exp($logMass), 'binomialpmf');
    }

    /** @param list<int|float> $arguments */
    private static function binomialLogProbabilityMass(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomiallogpmf');
        $successes = (float) $arguments[0];
        if (!is_finite($successes)) {
            throw new \DomainException('binomiallogpmf() requires a finite outcome value.');
        }
        if ($successes < 0.0 || $successes > $trials || floor($successes) !== $successes) {
            return -INF;
        }

        $successCount = (int) $successes;
        if ($successProbability === 0.0) {
            return $successCount === 0 ? 0.0 : -INF;
        }
        if ($successProbability === 1.0) {
            return $successCount === $trials ? 0.0 : -INF;
        }

        return self::logGammaPositive($trials + 1.0)
            - self::logGammaPositive($successCount + 1.0)
            - self::logGammaPositive($trials - $successCount + 1.0)
            + $successCount * log($successProbability)
            + ($trials - $successCount) * log1p(-$successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function multinomialMarginalMean(array $arguments): float
    {
        [$trials, $probability] = self::multinomialMarginalParameters($arguments, 'multinomialmean');

        return $trials * $probability;
    }

    /** @param list<int|float> $arguments */
    private static function multinomialMarginalVariance(array $arguments): float
    {
        [$trials, $probability] = self::multinomialMarginalParameters($arguments, 'multinomialvariance');

        return $trials * $probability * (1.0 - $probability);
    }

    /** @param list<int|float> $arguments */
    private static function multinomialMarginalStandardDeviation(array $arguments): float
    {
        return sqrt(self::multinomialMarginalVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function multinomialMarginalRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [$trials, $probability] = self::multinomialMarginalParameters(
            [$arguments[1], $arguments[2]],
            'multinomialmoment',
        );
        if (!is_finite($order) || floor($order) !== $order || $order < 0.0 || $order > 64.0) {
            throw new \DomainException('multinomialmoment() requires an integer order in [0, 64].');
        }

        return self::binomialRawMoment([$order, $trials, $probability]);
    }

    /** @param list<int|float> $arguments */
    private static function multinomialCategoryCovariance(array $arguments): float
    {
        [$trials, $firstProbability] = self::multinomialMarginalParameters(
            [$arguments[0], $arguments[1]],
            'multinomialcovariance',
        );
        $secondProbability = (float) $arguments[2];
        if (!is_finite($secondProbability) || $secondProbability < 0.0 || $secondProbability > 1.0) {
            throw new \DomainException('multinomialcovariance() requires category probabilities in [0, 1].');
        }
        if ($firstProbability + $secondProbability > 1.0) {
            throw new \DomainException(
                'multinomialcovariance() requires distinct category probabilities summing to at most 1.',
            );
        }

        return -$trials * $firstProbability * $secondProbability;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{int, float}
     */
    private static function multinomialMarginalParameters(array $arguments, string $function): array
    {
        return self::binomialParameters([0.0, $arguments[0], $arguments[1]], $function);
    }

    /** @param list<int|float> $arguments Alternating outcome and probability pairs. */
    private static function multinomialProbabilityMass(array $arguments): float
    {
        if (count($arguments) % 2 !== 0) {
            throw new \DomainException('multinomialpmf() requires outcome/probability pairs.');
        }

        $outcomes = [];
        $probabilities = [];
        $probabilityTotal = 0.0;
        foreach (array_chunk($arguments, 2) as [$outcome, $probability]) {
            $outcome = (float) $outcome;
            $probability = (float) $probability;
            if ($probability < 0.0 || $probability > 1.0) {
                throw new \DomainException('multinomialpmf() probabilities must be in [0, 1].');
            }

            $outcomes[] = $outcome;
            $probabilities[] = $probability;
            $probabilityTotal += $probability;
        }

        if (abs($probabilityTotal - 1.0) > 1.0e-12) {
            throw new \DomainException('multinomialpmf() probabilities must sum to 1.');
        }

        $totalCount = 0;
        foreach ($outcomes as $outcome) {
            if (!is_finite($outcome)) {
                throw new \DomainException('multinomialpmf() requires finite outcome counts.');
            }
            if ($outcome < 0.0 || floor($outcome) !== $outcome) {
                return 0.0;
            }
            if ($outcome > 10_000.0 - $totalCount) {
                throw new \DomainException('multinomialpmf() supports at most 10000 total trials.');
            }
            $totalCount += (int) $outcome;
        }

        $logMass = self::logGammaPositive($totalCount + 1.0);
        foreach ($outcomes as $index => $outcome) {
            $count = (int) $outcome;
            $logMass -= self::logGammaPositive($count + 1.0);
            $probability = $probabilities[$index];
            if ($count > 0) {
                if ($probability === 0.0) {
                    return 0.0;
                }
                $logMass += $count * log($probability);
            }
        }

        return self::finiteSpecialResult(exp($logMass), 'multinomialpmf');
    }

    /** @param list<int|float> $arguments Alternating outcome and probability pairs. */
    private static function multinomialLogProbabilityMass(array $arguments): float
    {
        if (count($arguments) % 2 !== 0) {
            throw new \DomainException('multinomiallogpmf() requires outcome/probability pairs.');
        }

        $outcomes = [];
        $probabilities = [];
        $probabilityTotal = 0.0;
        foreach (array_chunk($arguments, 2) as [$outcome, $probability]) {
            $outcome = (float) $outcome;
            $probability = (float) $probability;
            if (!is_finite($probability) || $probability < 0.0 || $probability > 1.0) {
                throw new \DomainException('multinomiallogpmf() probabilities must be finite and in [0, 1].');
            }

            $outcomes[] = $outcome;
            $probabilities[] = $probability;
            $probabilityTotal += $probability;
        }
        if (abs($probabilityTotal - 1.0) > 1.0e-12) {
            throw new \DomainException('multinomiallogpmf() probabilities must sum to 1.');
        }

        $totalCount = 0;
        foreach ($outcomes as $outcome) {
            if (!is_finite($outcome)) {
                throw new \DomainException('multinomiallogpmf() requires finite outcome counts.');
            }
            if ($outcome < 0.0 || floor($outcome) !== $outcome) {
                return -INF;
            }
            if ($outcome > 10_000.0 - $totalCount) {
                throw new \DomainException('multinomiallogpmf() supports at most 10000 total trials.');
            }
            $totalCount += (int) $outcome;
        }

        $logMass = self::logGammaPositive($totalCount + 1.0);
        foreach ($outcomes as $index => $outcome) {
            $count = (int) $outcome;
            $logMass -= self::logGammaPositive($count + 1.0);
            $probability = $probabilities[$index];
            if ($count > 0) {
                if ($probability === 0.0) {
                    return -INF;
                }
                $logMass += $count * log($probability);
            }
        }

        return $logMass;
    }

    /** @param list<int|float> $arguments */
    private static function binomialCumulativeDistribution(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomialcdf');
        $outcome = (float) $arguments[0];
        if (!is_finite($outcome)) {
            throw new \DomainException('binomialcdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome >= $trials) {
            return 1.0;
        }
        if ($successProbability === 0.0) {
            return 1.0;
        }
        if ($successProbability === 1.0) {
            return 0.0;
        }

        $successCount = (int) floor($outcome);
        $result = self::regularizedBetaValue(
            $trials - $successCount,
            $successCount + 1.0,
            1.0 - $successProbability,
        );
        return self::finiteSpecialResult($result, 'binomialcdf');
    }

    /** @param list<int|float> $arguments */
    private static function binomialComplementaryCumulativeDistribution(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomialccdf');
        $outcome = (float) $arguments[0];
        if (!is_finite($outcome)) {
            throw new \DomainException('binomialccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome >= $trials) {
            return 0.0;
        }
        if ($successProbability === 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            return 1.0;
        }

        $successCount = (int) floor($outcome);
        $result = self::regularizedBetaValue(
            $successCount + 1.0,
            $trials - $successCount,
            $successProbability,
        );
        return self::finiteSpecialResult($result, 'binomialccdf');
    }

    /** @param list<int|float> $arguments */
    private static function binomialLogCumulativeDistribution(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomlogcdf');
        $outcome = (float) $arguments[0];
        if (!is_finite($outcome)) {
            throw new \DomainException('binomlogcdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            throw new \DomainException('binomlogcdf() is negative infinity below the support.');
        }
        if ($outcome >= $trials || $successProbability === 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            throw new \DomainException('binomlogcdf() is negative infinity below the success count.');
        }

        $successCount = (int) floor($outcome);

        return self::regularizedBetaLogLowerFromLogs(
            $trials - $successCount,
            $successCount + 1.0,
            log1p(-$successProbability),
            log($successProbability),
        );
    }

    /** @param list<int|float> $arguments */
    private static function binomialLogComplementaryCumulativeDistribution(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomlogccdf');
        $outcome = (float) $arguments[0];
        if (!is_finite($outcome)) {
            throw new \DomainException('binomlogccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome >= $trials || $successProbability === 1.0) {
            throw new \DomainException('binomlogccdf() is negative infinity at the end of the support.');
        }
        if ($successProbability === 0.0) {
            throw new \DomainException('binomlogccdf() is negative infinity when p = 0.');
        }

        $successCount = (int) floor($outcome);

        return self::regularizedBetaLogLowerFromLogs(
            $successCount + 1.0,
            $trials - $successCount,
            log($successProbability),
            log1p(-$successProbability),
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseBinomialCumulativeDistribution(array $arguments): int
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomialinv');
        $target = (float) $arguments[0];
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('binomialinv() requires a cumulative probability in [0, 1].');
        }
        if ($target === 0.0 || $trials === 0 || $successProbability === 0.0) {
            return 0;
        }
        if ($successProbability === 1.0) {
            return $trials;
        }

        $lower = 0;
        $upper = $trials;
        while ($lower < $upper) {
            $middle = intdiv($lower + $upper, 2);
            if (self::binomialCumulativeValue($middle, $trials, $successProbability) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseBinomialComplementaryCumulativeDistribution(array $arguments): int
    {
        [$trials, $successProbability] = self::binomialParameters($arguments, 'binomialccinv');
        $target = (float) $arguments[0];
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('binomialccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0 || $trials === 0 || $successProbability === 0.0) {
            return 0;
        }
        if ($target === 0.0 || $successProbability === 1.0) {
            return $trials;
        }

        $lower = 0;
        $upper = $trials;
        while ($lower < $upper) {
            $middle = intdiv($lower + $upper, 2);
            if (
                self::binomialComplementaryCumulativeDistribution(
                    [$middle, $trials, $successProbability],
                ) <= $target
            ) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{int, float}
     */
    private static function binomialParameters(array $arguments, string $function): array
    {
        $trialValue = (float) $arguments[1];
        $successProbability = (float) $arguments[2];
        if (
            !is_finite($trialValue)
            || floor($trialValue) !== $trialValue
            || $trialValue < 0.0
            || $trialValue >= self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($successProbability)
            || $successProbability < 0.0
            || $successProbability > 1.0
        ) {
            throw new \DomainException(
                $function . '() requires an integer trial count in [0, 9999] and success probability in [0, 1].',
            );
        }

        return [(int) $trialValue, $successProbability];
    }

    /** @param list<int|float> $arguments */
    private static function binomialMean(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialmean',
        );

        return $trials * $successProbability;
    }

    /** @param list<int|float> $arguments */
    private static function binomialVariance(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialvariance',
        );

        return $trials * $successProbability * (1.0 - $successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function binomialStandardDeviation(array $arguments): float
    {
        return sqrt(self::binomialVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function binomialMedian(array $arguments): int
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialmedian',
        );
        $median = self::inverseBinomialCumulativeDistribution([0.5, $trials, $successProbability]);
        if ($median > 0 && self::binomialCumulativeValue($median - 1, $trials, $successProbability) >= 0.5) {
            return $median - 1;
        }

        return $median;
    }

    /** @param list<int|float> $arguments */
    private static function binomialMode(array $arguments): int
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialmode',
        );

        return (int) floor(($trials + 1) * $successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function binomialRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[1], $arguments[2]],
            'binomialmoment',
        );
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0.0 || $orderValue > 64.0) {
            throw new \DomainException('binomialmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }
        if ($trials === 0 || $successProbability === 0.0) {
            return 0.0;
        }

        $order = (int) $orderValue;
        $maximumFactorialOrder = min($order, $trials);
        $stirling = array_fill(0, $order + 1, 0.0);
        $stirling[0] = 1.0;
        for ($degree = 1; $degree <= $order; ++$degree) {
            for ($index = $degree; $index >= 1; --$index) {
                $stirling[$index] = $stirling[$index - 1] + $index * $stirling[$index];
            }
            $stirling[0] = 0.0;
        }

        $logTerms = [];
        for ($factorialOrder = 1; $factorialOrder <= $maximumFactorialOrder; ++$factorialOrder) {
            $logFallingFactorial = 0.0;
            for ($offset = 0; $offset < $factorialOrder; ++$offset) {
                $logFallingFactorial += log($trials - $offset);
            }
            $logTerms[] = log($stirling[$factorialOrder])
                + $logFallingFactorial
                + $factorialOrder * log($successProbability);
        }
        $logMoment = self::stableLogSumExp($logTerms);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('binomialmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'binomialmoment');
    }

    /** @param list<int|float> $arguments */
    private static function binomialSkewness(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialskewness',
        );
        $variance = $trials * $successProbability * (1.0 - $successProbability);
        if ($variance === 0.0) {
            throw new \DomainException('binomialskewness() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult((1.0 - 2.0 * $successProbability) / sqrt($variance), 'binomialskewness');
    }

    /** @param list<int|float> $arguments */
    private static function binomialExcessKurtosis(array $arguments): float
    {
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[0], $arguments[1]],
            'binomialexcesskurtosis',
        );
        $variance = $trials * $successProbability * (1.0 - $successProbability);
        if ($variance === 0.0) {
            throw new \DomainException('binomialexcesskurtosis() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            (1.0 - 6.0 * $successProbability * (1.0 - $successProbability)) / $variance,
            'binomialexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function binomialKurtosis(array $arguments): float
    {
        return 3.0 + self::binomialExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function binomialLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [$trials, $successProbability] = self::binomialParameters(
            [0.0, $arguments[1], $arguments[2]],
            'binomiallogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('binomiallogmgf() requires a finite real argument.');
        }
        if ($trials === 0 || $successProbability === 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            return self::finiteSpecialResult($trials * $tilt, 'binomiallogmgf');
        }

        $singleTrialLogMgf = self::stableLogSumExp([
            log1p(-$successProbability),
            log($successProbability) + $tilt,
        ]);

        return self::finiteSpecialResult($trials * $singleTrialLogMgf, 'binomiallogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function binomialMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::binomialLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'binomialmgf');
    }

    private static function binomialCumulativeValue(int $successCount, int $trials, float $successProbability): float
    {
        if ($successCount < 0) {
            return 0.0;
        }
        if ($successCount >= $trials || $successProbability === 0.0) {
            return 1.0;
        }
        if ($successProbability === 1.0) {
            return 0.0;
        }

        return self::regularizedBetaValue(
            $trials - $successCount,
            $successCount + 1.0,
            1.0 - $successProbability,
        );
    }

    /** @param list<int|float> $arguments */
    private static function poissonProbabilityMass(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poissonpmf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poissonpmf() requires a finite outcome value.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return 0.0;
        }

        return self::poissonMassValue((int) $outcome, $rate);
    }

    /** @param list<int|float> $arguments */
    private static function poissonLogProbabilityMass(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poissonlogpmf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poissonlogpmf() requires a finite outcome value.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return -INF;
        }
        if ($rate === 0.0) {
            return $outcome === 0.0 ? 0.0 : -INF;
        }

        return -$rate + $outcome * log($rate) - self::logGammaPositive($outcome + 1.0);
    }

    /** @param list<int|float> $arguments */
    private static function poissonCumulativeDistribution(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poissoncdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poissoncdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome > PHP_INT_MAX) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            self::poissonCumulativeValue((int) floor($outcome), $rate),
            'poissoncdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function poissonComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poissonccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poissonccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome > PHP_INT_MAX) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::poissonComplementaryValue((int) floor($outcome), $rate),
            'poissonccdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function poissonLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poilogcdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poilogcdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            throw new \DomainException('poilogcdf() is negative infinity below the support.');
        }
        if ($outcome > PHP_INT_MAX || $rate === 0.0) {
            return 0.0;
        }

        return self::regularizedGammaUpperLogValue((int) floor($outcome) + 1.0, $rate);
    }

    /** @param list<int|float> $arguments */
    private static function poissonLogComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $rate] = self::poissonArguments($arguments, 'poilogccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('poilogccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome > PHP_INT_MAX || $rate === 0.0) {
            throw new \DomainException('poilogccdf() is negative infinity for this threshold and rate.');
        }

        return self::regularizedGammaLowerLogValue(
            (int) floor($outcome) + 1.0,
            $rate,
            log($rate),
        );
    }

    /** @param list<int|float> $arguments */
    private static function inversePoissonCumulativeDistribution(array $arguments): int
    {
        [$target, $rate] = self::poissonArguments($arguments, 'poissoninv');
        if (!is_finite($target) || $target < 0.0 || $target >= 1.0) {
            throw new \DomainException('poissoninv() requires a cumulative probability in [0, 1).');
        }
        if ($target === 0.0 || $rate === 0.0) {
            return 0;
        }

        $lower = 0;
        $upper = (int) ceil($rate + 20.0 * sqrt($rate + 1.0) + 20.0);
        while ($lower < $upper) {
            $middle = intdiv($lower + $upper, 2);
            if (self::poissonCumulativeValue($middle, $rate) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inversePoissonComplementaryCumulativeDistribution(array $arguments): int
    {
        [$target, $rate] = self::poissonArguments($arguments, 'poissonccinv');
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('poissonccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0 || $rate === 0.0) {
            return 0;
        }
        if ($target === 0.0) {
            throw new \DomainException('poissonccinv() has no finite quantile at survival probability 0.');
        }

        $lower = 0;
        $upper = max(1, (int) ceil($rate));
        while (self::poissonComplementaryValue($upper, $rate) > $target) {
            if ($upper > intdiv(PHP_INT_MAX, 2)) {
                throw new \OverflowException('poissonccinv() quantile is outside the finite integer range.');
            }
            $upper *= 2;
        }
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::poissonComplementaryValue($middle, $rate) <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function poissonArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $rate = (float) $arguments[1];
        if (!is_finite($rate) || $rate < 0.0 || $rate > self::MAX_POISSON_RATE) {
            throw new \DomainException(
                $function . '() requires a finite Poisson rate in [0, 1000000].',
            );
        }

        return [$outcome, $rate];
    }

    /** @param list<int|float> $arguments */
    private static function poissonMean(array $arguments): float
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonmean');

        return $rate;
    }

    /** @param list<int|float> $arguments */
    private static function poissonVariance(array $arguments): float
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonvariance');

        return $rate;
    }

    /** @param list<int|float> $arguments */
    private static function poissonStandardDeviation(array $arguments): float
    {
        return sqrt(self::poissonVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function poissonRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $rate] = self::poissonArguments([0.0, $arguments[1]], 'poissonmoment');
        if (!is_finite($orderValue) || floor($orderValue) !== $orderValue || $orderValue < 0.0 || $orderValue > 64.0) {
            throw new \DomainException('poissonmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }
        if ($rate === 0.0) {
            return 0.0;
        }

        $order = (int) $orderValue;
        $stirling = array_fill(0, $order + 1, 0.0);
        $stirling[0] = 1.0;
        for ($degree = 1; $degree <= $order; ++$degree) {
            for ($index = $degree; $index >= 1; --$index) {
                $stirling[$index] = $stirling[$index - 1] + $index * $stirling[$index];
            }
            $stirling[0] = 0.0;
        }

        $logTerms = [];
        for ($factorialOrder = 1; $factorialOrder <= $order; ++$factorialOrder) {
            if ($stirling[$factorialOrder] > 0.0) {
                $logTerms[] = log($stirling[$factorialOrder]) + $factorialOrder * log($rate);
            }
        }
        $logMoment = self::stableLogSumExp($logTerms);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('poissonmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'poissonmoment');
    }

    /** @param list<int|float> $arguments */
    private static function poissonMedian(array $arguments): int
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonmedian');
        $median = self::inversePoissonCumulativeDistribution([0.5, $rate]);
        if ($median > 0 && self::poissonCumulativeValue($median - 1, $rate) >= 0.5 - 4.0 * PHP_FLOAT_EPSILON) {
            return $median - 1;
        }

        return $median;
    }

    /** @param list<int|float> $arguments */
    private static function poissonMode(array $arguments): int
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonmode');

        return (int) floor($rate);
    }

    /** @param list<int|float> $arguments */
    private static function poissonSkewness(array $arguments): float
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonskewness');
        if ($rate === 0.0) {
            throw new \DomainException('poissonskewness() is undefined when the rate is zero.');
        }

        return 1.0 / sqrt($rate);
    }

    /** @param list<int|float> $arguments */
    private static function poissonExcessKurtosis(array $arguments): float
    {
        [, $rate] = self::poissonArguments([0.0, $arguments[0]], 'poissonexcesskurtosis');
        if ($rate === 0.0) {
            throw new \DomainException('poissonexcesskurtosis() is undefined when the rate is zero.');
        }

        return 1.0 / $rate;
    }

    /** @param list<int|float> $arguments */
    private static function poissonKurtosis(array $arguments): float
    {
        return 3.0 + self::poissonExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function poissonLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $rate] = self::poissonArguments([0.0, $arguments[1]], 'poissonlogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('poissonlogmgf() requires a finite real argument.');
        }
        if ($rate === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult($rate * expm1($tilt), 'poissonlogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function poissonMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::poissonLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'poissonmgf');
    }

    private static function poissonMassValue(int $outcome, float $rate): float
    {
        if ($rate === 0.0) {
            return $outcome === 0 ? 1.0 : 0.0;
        }

        $logMass = -$rate + $outcome * log($rate) - self::logGammaPositive($outcome + 1.0);
        return self::finiteSpecialResult(exp($logMass), 'poissonpmf');
    }

    /** @param list<int|float> $arguments */
    private static function geometricProbabilityMass(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geometricpmf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geometricpmf() requires a finite outcome value.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            return $outcome === 0.0 ? 1.0 : 0.0;
        }

        return self::finiteSpecialResult(
            exp(log($successProbability) + (int) $outcome * log1p(-$successProbability)),
            'geometricpmf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricLogProbabilityMass(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geometriclogpmf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geometriclogpmf() requires a finite outcome value.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return -INF;
        }
        if ($successProbability === 1.0) {
            return $outcome === 0.0 ? 0.0 : -INF;
        }

        return log($successProbability) + $outcome * log1p(-$successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function geometricCumulativeDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geometriccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geometriccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0 || $outcome >= PHP_INT_MAX) {
            return 1.0;
        }

        return -expm1((floor($outcome) + 1.0) * log1p(-$successProbability));
    }

    /** @param list<int|float> $arguments */
    private static function geometricComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geometricccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geometricccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($successProbability === 1.0 || $outcome >= PHP_INT_MAX) {
            return 0.0;
        }

        return exp((floor($outcome) + 1.0) * log1p(-$successProbability));
    }

    /** @param list<int|float> $arguments */
    private static function geometricLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geomlogcdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geomlogcdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            throw new \DomainException('geomlogcdf() is negative infinity below the support.');
        }
        if ($successProbability === 1.0 || $outcome >= PHP_INT_MAX) {
            return 0.0;
        }

        return log(-expm1((floor($outcome) + 1.0) * log1p(-$successProbability)));
    }

    /** @param list<int|float> $arguments */
    private static function geometricLogComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $successProbability] = self::geometricArguments($arguments, 'geomlogccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('geomlogccdf() requires a finite outcome value.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($successProbability === 1.0 || $outcome >= PHP_INT_MAX) {
            throw new \DomainException('geomlogccdf() is negative infinity at this threshold.');
        }

        return (floor($outcome) + 1.0) * log1p(-$successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function inverseGeometricCumulativeDistribution(array $arguments): int
    {
        [$target, $successProbability] = self::geometricArguments($arguments, 'geometricinv');
        if (!is_finite($target) || $target < 0.0 || $target >= 1.0) {
            throw new \DomainException('geometricinv() requires a cumulative probability in [0, 1).');
        }
        if ($target === 0.0 || $successProbability === 1.0) {
            return 0;
        }

        $quantile = ceil(log1p(-$target) / log1p(-$successProbability)) - 1.0;
        if (!is_finite($quantile) || $quantile > PHP_INT_MAX) {
            throw new \OverflowException('geometricinv() quantile exceeds the host integer range.');
        }

        return max(0, (int) $quantile);
    }

    /** @param list<int|float> $arguments */
    private static function inverseGeometricComplementaryCumulativeDistribution(array $arguments): int
    {
        [$target, $successProbability] = self::geometricArguments($arguments, 'geometricccinv');
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('geometricccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0 || $successProbability === 1.0) {
            return 0;
        }
        if ($target === 0.0) {
            throw new \DomainException('geometricccinv() has no finite quantile at survival probability 0.');
        }

        $quantile = ceil(log($target) / log1p(-$successProbability)) - 1.0;
        if (!is_finite($quantile) || $quantile > PHP_INT_MAX) {
            throw new \OverflowException('geometricccinv() quantile exceeds the host integer range.');
        }

        return max(0, (int) $quantile);
    }

    /** @param list<int|float> $arguments */
    private static function geometricMeanFailures(array $arguments): float
    {
        [, $successProbability] = self::geometricArguments([0.0, $arguments[0]], 'geometricdistributionmean');

        return self::finiteSpecialResult(
            (1.0 - $successProbability) / $successProbability,
            'geometricdistributionmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricVariance(array $arguments): float
    {
        [, $successProbability] = self::geometricArguments([0.0, $arguments[0]], 'geometricvariance');

        return self::finiteSpecialResult(
            ((1.0 - $successProbability) / $successProbability) / $successProbability,
            'geometricvariance',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(sqrt(self::geometricVariance($arguments)), 'geometricstddev');
    }

    /** @param list<int|float> $arguments */
    private static function geometricMedian(array $arguments): int
    {
        return self::inverseGeometricCumulativeDistribution([0.5, $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function geometricMode(array $arguments): int
    {
        self::geometricArguments([0.0, $arguments[0]], 'geometricmode');

        return 0;
    }

    /** @param list<int|float> $arguments */
    private static function geometricEntropy(array $arguments): float
    {
        [, $successProbability] = self::geometricArguments([0.0, $arguments[0]], 'geometricentropy');
        if ($successProbability === 1.0) {
            return 0.0;
        }
        $failureProbability = 1.0 - $successProbability;

        return self::finiteSpecialResult(
            -log($successProbability) - ($failureProbability / $successProbability) * log($failureProbability),
            'geometricentropy',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricRawMoment(array $arguments): float
    {
        $order = (float) $arguments[0];
        [, $successProbability] = self::geometricArguments([0.0, $arguments[1]], 'geometricmoment');
        if (!is_finite($order) || $order < 0.0 || $order > 64.0 || floor($order) !== $order) {
            throw new \DomainException('geometricmoment() requires an integer order from 0 through 64.');
        }
        if ($order === 0.0) {
            return 1.0;
        }
        if ($successProbability === 1.0) {
            return 0.0;
        }

        $orderInt = (int) $order;
        $eulerian = [1.0];
        for ($degree = 2; $degree <= $orderInt; ++$degree) {
            $next = array_fill(0, $degree, 0.0);
            foreach ($eulerian as $index => $coefficient) {
                $next[$index] += ($index + 1.0) * $coefficient;
                $next[$index + 1] += ($degree - 1.0 - $index) * $coefficient;
            }
            $eulerian = $next;
        }
        $polynomial = 0.0;
        $failureProbability = 1.0 - $successProbability;
        for ($index = count($eulerian) - 1; $index >= 0; --$index) {
            $polynomial = $polynomial * $failureProbability + $eulerian[$index];
        }
        $logMoment = log($failureProbability) + log($polynomial) - $order * log($successProbability);

        return self::finiteSpecialResult(exp($logMoment), 'geometricmoment');
    }

    /** @param list<int|float> $arguments */
    private static function geometricLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $successProbability] = self::geometricArguments([0.0, $arguments[1]], 'geometriclogmgf');
        if (!is_finite($tilt)) {
            throw new \DomainException('geometriclogmgf() requires a finite real argument.');
        }
        if ($successProbability === 1.0 || $tilt === 0.0) {
            return 0.0;
        }

        $logFailureProbability = log1p(-$successProbability);
        if ($tilt >= -$logFailureProbability) {
            throw new \DomainException('geometriclogmgf() exists only when t < -log(1 - p).');
        }

        return self::finiteSpecialResult(
            log($successProbability) - log1p(-exp($logFailureProbability + $tilt)),
            'geometriclogmgf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricMomentGeneratingFunction(array $arguments): float
    {
        return self::finiteSpecialResult(exp(self::geometricLogMomentGeneratingFunction($arguments)), 'geometricmgf');
    }

    /** @param list<int|float> $arguments */
    private static function geometricSkewness(array $arguments): float
    {
        [, $successProbability] = self::geometricArguments([0.0, $arguments[0]], 'geometricskewness');
        if ($successProbability === 1.0) {
            throw new \DomainException('geometricskewness() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            (2.0 - $successProbability) / sqrt(1.0 - $successProbability),
            'geometricskewness',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricExcessKurtosis(array $arguments): float
    {
        [, $successProbability] = self::geometricArguments([0.0, $arguments[0]], 'geometricexcesskurtosis');
        if ($successProbability === 1.0) {
            throw new \DomainException('geometricexcesskurtosis() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            (6.0 - 6.0 * $successProbability + $successProbability * $successProbability)
                / (1.0 - $successProbability),
            'geometricexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function geometricKurtosis(array $arguments): float
    {
        return 3.0 + self::geometricExcessKurtosis($arguments);
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function geometricArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $successProbability = (float) $arguments[1];
        if (!is_finite($successProbability) || $successProbability <= 0.0 || $successProbability > 1.0) {
            throw new \DomainException($function . '() requires success probability in (0, 1].');
        }

        return [$outcome, $successProbability];
    }

    private static function poissonCumulativeValue(int $outcome, float $rate): float
    {
        if ($rate === 0.0) {
            return 1.0;
        }
        if ($outcome < $rate) {
            $term = self::poissonMassValue($outcome, $rate);
            if ($term === 0.0) {
                return 0.0;
            }
            $sum = $term;
            $count = $outcome;
            for ($iteration = 0; $count > 0 && $iteration < 100_000; ++$iteration) {
                $term *= $count / $rate;
                $sum += $term;
                --$count;
                if ($term === 0.0 || $term <= $sum * 1.0E-15) {
                    break;
                }
            }
            return $sum;
        }

        return 1.0 - self::poissonUpperTailValue($outcome, $rate);
    }

    private static function poissonComplementaryValue(int $outcome, float $rate): float
    {
        if ($rate === 0.0) {
            return 0.0;
        }
        if ($outcome < $rate) {
            return 1.0 - self::poissonCumulativeValue($outcome, $rate);
        }

        return self::poissonUpperTailValue($outcome, $rate);
    }

    private static function poissonUpperTailValue(int $outcome, float $rate): float
    {
        if ($outcome === PHP_INT_MAX) {
            return 0.0;
        }

        $count = $outcome + 1;
        $term = self::poissonMassValue($count, $rate);
        if ($term === 0.0) {
            return 0.0;
        }
        $sum = $term;
        for ($iteration = 0; $iteration < 100_000 && $count < PHP_INT_MAX; ++$iteration) {
            $term *= $rate / ($count + 1.0);
            $sum += $term;
            ++$count;
            if ($term === 0.0 || $term <= $sum * 1.0E-15) {
                break;
            }
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialProbabilityMass(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomialpmf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativebinomialpmf() requires a finite failure count.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return 0.0;
        }
        if ($successProbability === 1.0) {
            return $outcome === 0.0 ? 1.0 : 0.0;
        }

        $failures = (int) $outcome;
        $logMass = self::logGammaPositive((float) $failures + $requiredSuccesses)
            - self::logGammaPositive($requiredSuccesses)
            - self::logGammaPositive((float) $failures + 1.0)
            + $requiredSuccesses * log($successProbability)
            + $failures * log1p(-$successProbability);

        return self::finiteSpecialResult(exp($logMass), 'negativebinomialpmf');
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialLogProbabilityMass(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomiallogpmf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativebinomiallogpmf() requires a finite failure count.');
        }
        if ($outcome < 0.0 || floor($outcome) !== $outcome || $outcome > PHP_INT_MAX) {
            return -INF;
        }
        if ($successProbability === 1.0) {
            return $outcome === 0.0 ? 0.0 : -INF;
        }

        $failures = (int) $outcome;
        return self::logGammaPositive((float) $failures + $requiredSuccesses)
            - self::logGammaPositive($requiredSuccesses)
            - self::logGammaPositive((float) $failures + 1.0)
            + $requiredSuccesses * log($successProbability)
            + $failures * log1p(-$successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialCumulativeDistribution(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomialcdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativebinomialcdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome > PHP_INT_MAX) {
            return 1.0;
        }
        if ($successProbability === 1.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            self::negativeBinomialCumulativeValue((int) floor($outcome), $requiredSuccesses, $successProbability),
            'negativebinomialcdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomialccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativebinomialccdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome > PHP_INT_MAX || $successProbability === 1.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            self::negativeBinomialComplementaryValue(
                (int) floor($outcome),
                $requiredSuccesses,
                $successProbability,
            ),
            'negativebinomialccdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'nbinomlogcdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('nbinomlogcdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            throw new \DomainException('nbinomlogcdf() is negative infinity below the support.');
        }
        if ($outcome > PHP_INT_MAX || $successProbability === 1.0) {
            return 0.0;
        }

        $failures = (int) floor($outcome);

        return self::regularizedBetaLogLowerFromLogs(
            $requiredSuccesses,
            $failures + 1.0,
            log($successProbability),
            log1p(-$successProbability),
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialLogComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'nbinomlogccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('nbinomlogccdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        if ($outcome > PHP_INT_MAX || $successProbability === 1.0) {
            throw new \DomainException('nbinomlogccdf() is negative infinity at the end of its support.');
        }

        $failures = (int) floor($outcome);

        return self::regularizedBetaLogLowerFromLogs(
            $failures + 1.0,
            $requiredSuccesses,
            log1p(-$successProbability),
            log($successProbability),
        );
    }

    /** @param list<int|float> $arguments */
    private static function inverseNegativeBinomialCumulativeDistribution(array $arguments): int
    {
        [$target, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomialinv',
        );
        if (!is_finite($target) || $target < 0.0 || $target >= 1.0) {
            throw new \DomainException('negativebinomialinv() requires a cumulative probability in [0, 1).');
        }
        if ($target === 0.0 || $successProbability === 1.0) {
            return 0;
        }

        $lower = 0;
        $upper = 0;
        while (self::negativeBinomialCumulativeValue($upper, $requiredSuccesses, $successProbability) < $target) {
            if ($upper === 0) {
                $upper = 1;
                continue;
            }
            if ($upper > intdiv(PHP_INT_MAX, 2)) {
                $upper = PHP_INT_MAX;
                if (self::negativeBinomialCumulativeValue($upper, $requiredSuccesses, $successProbability) < $target) {
                    throw new \OverflowException(
                        'negativebinomialinv() quantile is outside the finite integer range.',
                    );
                }
                break;
            }
            $upper *= 2;
        }

        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::negativeBinomialCumulativeValue($middle, $requiredSuccesses, $successProbability) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseNegativeBinomialComplementaryCumulativeDistribution(array $arguments): int
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            $arguments,
            'negativebinomialccinv',
        );
        $target = (float) $arguments[0];
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('negativebinomialccinv() requires a survival probability in [0, 1].');
        }
        if ($target === 1.0 || $successProbability === 1.0) {
            return 0;
        }
        if ($target === 0.0) {
            throw new \DomainException(
                'negativebinomialccinv() has no finite quantile at survival probability 0.',
            );
        }

        $lower = 0;
        $upper = 0;
        while (self::negativeBinomialComplementaryValue($upper, $requiredSuccesses, $successProbability) > $target) {
            if ($upper === 0) {
                $upper = 1;
                continue;
            }
            if ($upper > intdiv(PHP_INT_MAX, 2)) {
                $upper = PHP_INT_MAX;
                if (
                    self::negativeBinomialComplementaryValue($upper, $requiredSuccesses, $successProbability)
                    > $target
                ) {
                    throw new \OverflowException(
                        'negativebinomialccinv() quantile is outside the finite integer range.',
                    );
                }
                break;
            }
            $upper *= 2;
        }

        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::negativeBinomialComplementaryValue($middle, $requiredSuccesses, $successProbability) <= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialMean(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialmean',
        );

        return self::finiteSpecialResult(
            $requiredSuccesses * (1.0 - $successProbability) / $successProbability,
            'negativebinomialmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialVariance(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialvariance',
        );

        return self::finiteSpecialResult(
            $requiredSuccesses * (1.0 - $successProbability) / ($successProbability * $successProbability),
            'negativebinomialvariance',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialStandardDeviation(array $arguments): float
    {
        return self::finiteSpecialResult(
            sqrt(self::negativeBinomialVariance($arguments)),
            'negativebinomialstddev',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialSkewness(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialskewness',
        );
        if ($successProbability === 1.0) {
            throw new \DomainException('negativebinomialskewness() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            (2.0 - $successProbability) / sqrt($requiredSuccesses * (1.0 - $successProbability)),
            'negativebinomialskewness',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialExcessKurtosis(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialexcesskurtosis',
        );
        if ($successProbability === 1.0) {
            throw new \DomainException('negativebinomialexcesskurtosis() is undefined for a degenerate distribution.');
        }

        return self::finiteSpecialResult(
            6.0 / $requiredSuccesses + $successProbability * $successProbability
                / ($requiredSuccesses * (1.0 - $successProbability)),
            'negativebinomialexcesskurtosis',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialKurtosis(array $arguments): float
    {
        return 3.0 + self::negativeBinomialExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialMedian(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialmedian',
        );

        $median = self::inverseNegativeBinomialCumulativeDistribution(
            [0.5, $requiredSuccesses, $successProbability],
        );
        if ($median > 0.0) {
            $precedingCumulative = self::negativeBinomialCumulativeDistribution(
                [$median - 1.0, $requiredSuccesses, $successProbability],
            );
            if ($precedingCumulative >= 0.5 - 4.0 * PHP_FLOAT_EPSILON) {
                return $median - 1.0;
            }
        }

        return $median;
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialMode(array $arguments): float
    {
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[0], $arguments[1]],
            'negativebinomialmode',
        );
        $mode = ($requiredSuccesses - 1.0) * ((1.0 - $successProbability) / $successProbability);
        if (!is_finite($mode)) {
            throw new \OverflowException('negativebinomialmode() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(floor($mode), 'negativebinomialmode');
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[1], $arguments[2]],
            'negativebinomialmoment',
        );
        if (
            !is_finite($orderValue)
            || floor($orderValue) !== $orderValue
            || $orderValue < 0.0
            || $orderValue > 64.0
        ) {
            throw new \DomainException('negativebinomialmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }
        if ($successProbability === 1.0) {
            return 0.0;
        }

        $order = (int) $orderValue;
        $stirling = array_fill(0, $order + 1, 0.0);
        $stirling[0] = 1.0;
        for ($degree = 1; $degree <= $order; ++$degree) {
            for ($index = $degree; $index >= 1; --$index) {
                $stirling[$index] = $stirling[$index - 1] + $index * $stirling[$index];
            }
            $stirling[0] = 0.0;
        }

        $logFailureOdds = log1p(-$successProbability) - log($successProbability);
        $logTerms = [];
        for ($factorialOrder = 1; $factorialOrder <= $order; ++$factorialOrder) {
            $logRisingFactorial = 0.0;
            for ($offset = 0; $offset < $factorialOrder; ++$offset) {
                $logRisingFactorial += log($requiredSuccesses + $offset);
            }
            $logTerms[] = log($stirling[$factorialOrder])
                + $logRisingFactorial
                + $factorialOrder * $logFailureOdds;
        }

        $maximumLogTerm = max($logTerms);
        $scaledSum = 0.0;
        foreach ($logTerms as $logTerm) {
            $scaledSum += exp($logTerm - $maximumLogTerm);
        }
        $logMoment = $maximumLogTerm + log($scaledSum);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('negativebinomialmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'negativebinomialmoment');
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $requiredSuccesses, $successProbability] = self::negativeBinomialArguments(
            [0.0, $arguments[1], $arguments[2]],
            'negativebinomiallogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('negativebinomiallogmgf() requires a finite real argument.');
        }
        if ($successProbability === 1.0) {
            return 0.0;
        }

        $logFailureTilt = log1p(-$successProbability) + $tilt;
        if ($logFailureTilt >= 0.0) {
            throw new \DomainException(
                'negativebinomiallogmgf() diverges unless t < -log(1 - p).',
            );
        }
        $logMgf = $requiredSuccesses * (
            log($successProbability) - self::logOneMinusExponential([$logFailureTilt])
        );

        return self::finiteSpecialResult($logMgf, 'negativebinomiallogmgf');
    }

    /** @param list<int|float> $arguments */
    private static function negativeBinomialMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::negativeBinomialLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'negativebinomialmgf');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, int, float}
     */
    private static function negativeBinomialArguments(array $arguments, string $function): array
    {
        $outcome = (float) $arguments[0];
        $requiredSuccessesValue = (float) $arguments[1];
        $successProbability = (float) $arguments[2];
        if (
            !is_finite($requiredSuccessesValue)
            || floor($requiredSuccessesValue) !== $requiredSuccessesValue
            || $requiredSuccessesValue < 1.0
            || $requiredSuccessesValue > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($successProbability)
            || $successProbability <= 0.0
            || $successProbability > 1.0
        ) {
            throw new \DomainException(
                $function . '() requires an integer success count in [1, 10000] and success probability in (0, 1].',
            );
        }

        return [$outcome, (int) $requiredSuccessesValue, $successProbability];
    }

    private static function negativeBinomialCumulativeValue(
        int $failures,
        int $requiredSuccesses,
        float $successProbability,
    ): float {
        if ($requiredSuccesses === 1) {
            return -expm1(($failures + 1.0) * log1p(-$successProbability));
        }

        return self::regularizedBetaValue($requiredSuccesses, $failures + 1.0, $successProbability);
    }

    private static function negativeBinomialComplementaryValue(
        int $failures,
        int $requiredSuccesses,
        float $successProbability,
    ): float {
        if ($requiredSuccesses === 1) {
            return exp(($failures + 1.0) * log1p(-$successProbability));
        }

        return self::regularizedBetaValue($failures + 1.0, $requiredSuccesses, 1.0 - $successProbability);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricProbabilityMass(array $arguments): float
    {
        [$failures, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometricpmf',
        );
        if (
            !is_finite($failures) || floor($failures) !== $failures || $failures < 0.0
            || $failures > $population - $successes
        ) {
            return 0.0;
        }

        return self::negativeHypergeometricMassValue((int) $failures, $population, $successes, $required);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricLogProbabilityMass(array $arguments): float
    {
        [$failures, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometriclogpmf',
        );
        if (
            !is_finite($failures)
            || floor($failures) !== $failures
            || $failures < 0.0
            || $failures > $population - $successes
        ) {
            return -INF;
        }

        return self::negativeHypergeometricLogMass((int) $failures, $population, $successes, $required);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometriccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativehypergeometriccdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        $maximum = $population - $successes;
        if ($outcome >= $maximum) {
            return 1.0;
        }

        $sum = 0.0;
        for ($x = 0; $x <= (int) floor($outcome); ++$x) {
            $sum += self::negativeHypergeometricMassValue($x, $population, $successes, $required);
        }

        return self::finiteSpecialResult($sum, 'negativehypergeometriccdf');
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometricccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativehypergeometricccdf() requires a finite failure count.');
        }
        $maximum = $population - $successes;
        if ($outcome < 0.0) {
            return 1.0;
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        $sum = 0.0;
        for ($x = (int) floor($outcome) + 1; $x <= $maximum; ++$x) {
            $sum += self::negativeHypergeometricMassValue($x, $population, $successes, $required);
        }

        return self::finiteSpecialResult($sum, 'negativehypergeometricccdf');
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometriclogcdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativehypergeometriclogcdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            throw new \DomainException('negativehypergeometriclogcdf() is negative infinity below the support.');
        }
        $maximum = $population - $successes;
        if ($outcome >= $maximum) {
            return 0.0;
        }

        return self::negativeHypergeometricLogTailValue(
            0,
            (int) floor($outcome),
            $population,
            $successes,
            $required,
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricLogComplementaryDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometriclogccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('negativehypergeometriclogccdf() requires a finite failure count.');
        }
        if ($outcome < 0.0) {
            return 0.0;
        }
        $maximum = $population - $successes;
        if ($outcome >= $maximum) {
            throw new \DomainException('negativehypergeometriclogccdf() is negative infinity at the support end.');
        }

        return self::negativeHypergeometricLogTailValue(
            (int) floor($outcome) + 1,
            $maximum,
            $population,
            $successes,
            $required,
        );
    }

    private static function negativeHypergeometricLogTailValue(
        int $minimum,
        int $maximum,
        int $population,
        int $successes,
        int $required,
    ): float {
        $logMasses = [];
        $largestLogMass = -INF;
        for ($failures = $minimum; $failures <= $maximum; ++$failures) {
            $logMass = self::negativeHypergeometricLogMass($failures, $population, $successes, $required);
            $logMasses[] = $logMass;
            $largestLogMass = max($largestLogMass, $logMass);
        }

        $scaledSum = 0.0;
        foreach ($logMasses as $logMass) {
            $scaledSum += exp($logMass - $largestLogMass);
        }

        return self::finiteSpecialResult(
            $largestLogMass + log($scaledSum),
            'negativehypergeometriclogcdf',
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricMean(array $arguments): float
    {
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'negativehypergeometricmean',
        );

        return $required * ($population - $successes) / ($successes + 1.0);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricVariance(array $arguments): float
    {
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'negativehypergeometricvariance',
        );

        return $required * ($population + 1.0) * ($population - $successes)
            / (($successes + 1.0) * ($successes + 2.0))
            * (1.0 - $required / ($successes + 1.0));
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricStandardDeviation(array $arguments): float
    {
        return sqrt(self::negativeHypergeometricVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricMedian(array $arguments): int
    {
        return self::inverseNegativeHypergeometricCumulativeDistribution(
            [0.5, $arguments[0], $arguments[1], $arguments[2]],
        );
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricMode(array $arguments): int
    {
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'negativehypergeometricmode',
        );
        $maximum = $population - $successes;
        $mode = 0;
        $maximumLogMass = self::negativeHypergeometricLogMass(0, $population, $successes, $required);
        for ($failures = 1; $failures <= $maximum; ++$failures) {
            $logMass = self::negativeHypergeometricLogMass($failures, $population, $successes, $required);
            $tieTolerance = 32.0 * PHP_FLOAT_EPSILON * max(1.0, abs($maximumLogMass), abs($logMass));
            if ($logMass >= $maximumLogMass - $tieTolerance) {
                $maximumLogMass = max($maximumLogMass, $logMass);
                $mode = $failures;
            }
        }

        return $mode;
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricEntropy(array $arguments): float
    {
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'negativehypergeometricentropy',
        );
        $maximum = $population - $successes;
        if ($maximum === 0) {
            return 0.0;
        }
        $logMasses = [];
        for ($failures = 0; $failures <= $maximum; ++$failures) {
            $logMasses[] = self::negativeHypergeometricLogMass($failures, $population, $successes, $required);
        }
        $normalizer = self::stableLogSumExp($logMasses);
        $entropy = 0.0;
        foreach ($logMasses as $logMass) {
            $probability = exp($logMass - $normalizer);
            $entropy -= $probability * ($logMass - $normalizer);
        }

        return self::finiteSpecialResult($entropy, 'negativehypergeometricentropy');
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricSkewness(array $arguments): float
    {
        return self::negativeHypergeometricStandardizedMoments($arguments, 'negativehypergeometricskewness')[0];
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricExcessKurtosis(array $arguments): float
    {
        return self::negativeHypergeometricStandardizedMoments($arguments, 'negativehypergeometricexcesskurtosis')[1];
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricKurtosis(array $arguments): float
    {
        return 3.0 + self::negativeHypergeometricExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'negativehypergeometricmoment',
        );
        if (
            !is_finite($orderValue)
            || floor($orderValue) !== $orderValue
            || $orderValue < 0.0
            || $orderValue > 64.0
        ) {
            throw new \DomainException('negativehypergeometricmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }

        $maximum = $population - $successes;
        if ($maximum === 0) {
            return 0.0;
        }

        $order = (int) $orderValue;
        $logMasses = [];
        $logMomentTerms = [];
        for ($failures = 0; $failures <= $maximum; ++$failures) {
            $logMass = self::negativeHypergeometricLogMass($failures, $population, $successes, $required);
            $logMasses[] = $logMass;
            if ($failures > 0) {
                $logMomentTerms[] = $logMass + $order * log($failures);
            }
        }

        $logMoment = self::stableLogSumExp($logMomentTerms) - self::stableLogSumExp($logMasses);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('negativehypergeometricmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'negativehypergeometricmoment');
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricLogMgf(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'negativehypergeometriclogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('negativehypergeometriclogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        $logTerms = [];
        $maximum = $population - $successes;
        for ($failures = 0; $failures <= $maximum; ++$failures) {
            $tiltContribution = $tilt * $failures;
            if (!is_finite($tiltContribution)) {
                throw new \OverflowException('negativehypergeometriclogmgf() exceeds the finite range.');
            }
            $logTerms[] = self::negativeHypergeometricLogMass(
                $failures,
                $population,
                $successes,
                $required,
            ) + $tiltContribution;
        }

        return self::stableLogSumExp($logTerms);
    }

    /** @param list<int|float> $arguments */
    private static function negativeHypergeometricMgf(array $arguments): float
    {
        $logMgf = self::negativeHypergeometricLogMgf($arguments);
        if ($logMgf > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('negativehypergeometricmgf() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMgf), 'negativehypergeometricmgf');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function negativeHypergeometricStandardizedMoments(array $arguments, string $function): array
    {
        [, $population, $successes, $required] = self::negativeHypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            $function,
        );
        $mean = $required * ($population - $successes) / ($successes + 1.0);
        $logMasses = [];
        for ($failures = 0; $failures <= $population - $successes; ++$failures) {
            $logMasses[] = self::negativeHypergeometricLogMass($failures, $population, $successes, $required);
        }
        $normalizer = self::stableLogSumExp($logMasses);
        $variance = 0.0;
        $thirdCentralMoment = 0.0;
        $fourthCentralMoment = 0.0;
        foreach ($logMasses as $failures => $logMass) {
            $probability = exp($logMass - $normalizer);
            $deviation = $failures - $mean;
            $squared = $deviation * $deviation;
            $variance += $probability * $squared;
            $thirdCentralMoment += $probability * $squared * $deviation;
            $fourthCentralMoment += $probability * $squared * $squared;
        }
        if ($variance === 0.0) {
            throw new \DomainException($function . '() is undefined for a degenerate distribution.');
        }

        return [
            self::finiteSpecialResult($thirdCentralMoment / ($variance * sqrt($variance)), $function),
            self::finiteSpecialResult($fourthCentralMoment / ($variance * $variance) - 3.0, $function),
        ];
    }

    /** @param list<int|float> $arguments */
    private static function inverseNegativeHypergeometricCumulativeDistribution(array $arguments): int
    {
        [$target, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometricinv',
        );
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('negativehypergeometricinv() requires a probability in [0, 1].');
        }
        $lower = 0;
        $upper = $population - $successes;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::negativeHypergeometricCumulativeValue($middle, $population, $successes, $required) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseNegativeHypergeometricComplementaryDistribution(array $arguments): int
    {
        [$target, $population, $successes, $required] = self::negativeHypergeometricArguments(
            $arguments,
            'negativehypergeometricccinv',
        );
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException(
                'negativehypergeometricccinv() requires a survival probability in [0, 1].',
            );
        }
        $maximum = $population - $successes;
        if ($target === 1.0) {
            return 0;
        }
        if ($target === 0.0) {
            return $maximum;
        }

        $lower = 0;
        $upper = $maximum;
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (
                self::negativeHypergeometricComplementaryCumulativeDistribution(
                    [$middle, $population, $successes, $required],
                ) <= $target
            ) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: int, 2: int, 3: int}
     */
    private static function negativeHypergeometricArguments(array $arguments, string $function): array
    {
        $population = (float) $arguments[1];
        $successes = (float) $arguments[2];
        $required = (float) $arguments[3];
        if (
            !is_finite($population) || floor($population) !== $population
            || $population < 1.0 || $population > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($successes) || floor($successes) !== $successes
            || $successes < 1.0 || $successes > $population
            || !is_finite($required) || floor($required) !== $required
            || $required < 1.0 || $required > $successes
        ) {
            throw new \DomainException(
                $function . '() requires integer counts 1 ≤ required successes ≤ successes ≤ population ≤ 10000.',
            );
        }

        return [(float) $arguments[0], (int) $population, (int) $successes, (int) $required];
    }

    private static function negativeHypergeometricMassValue(
        int $failures,
        int $population,
        int $successes,
        int $required,
    ): float {
        return self::finiteSpecialResult(
            exp(self::negativeHypergeometricLogMass($failures, $population, $successes, $required)),
            'negativehypergeometricpmf',
        );
    }

    private static function negativeHypergeometricLogMass(
        int $failures,
        int $population,
        int $successes,
        int $required,
    ): float {
        return self::logGammaPositive($failures + $required)
            - self::logGammaPositive($failures + 1.0)
            - self::logGammaPositive($required)
            + self::logGammaPositive($population - $required - $failures + 1.0)
            - self::logGammaPositive($successes - $required + 1.0)
            - self::logGammaPositive($population - $successes - $failures + 1.0)
            - self::logGammaPositive($population + 1.0)
            + self::logGammaPositive($successes + 1.0)
            + self::logGammaPositive($population - $successes + 1.0);
    }

    private static function negativeHypergeometricCumulativeValue(
        int $outcome,
        int $population,
        int $successes,
        int $required,
    ): float {
        $sum = 0.0;
        for ($x = 0; $x <= $outcome; ++$x) {
            $sum += self::negativeHypergeometricMassValue($x, $population, $successes, $required);
        }

        return self::finiteSpecialResult($sum, 'negativehypergeometriccdf');
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricProbabilityMass(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments($arguments, 'hypergeometricpmf');
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if (!is_finite($outcome) || floor($outcome) !== $outcome || $outcome < $minimum || $outcome > $maximum) {
            return 0.0;
        }

        return self::hypergeometricMassValue((int) $outcome, $population, $successes, $draws);
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricLogProbabilityMass(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments(
            $arguments,
            'hypergeometriclogpmf',
        );
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if (!is_finite($outcome) || floor($outcome) !== $outcome || $outcome < $minimum || $outcome > $maximum) {
            return -INF;
        }

        return self::hypergeometricLogMass((int) $outcome, $population, $successes, $draws);
    }

    /** @param list<int|float> $arguments */
    private static function multivariateHypergeometricMean(array $arguments): float
    {
        return self::hypergeometricMean($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function multivariateHypergeometricVariance(array $arguments): float
    {
        return self::hypergeometricVariance($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function multivariateHypergeometricStandardDeviation(array $arguments): float
    {
        return self::hypergeometricStandardDeviation($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function multivariateHypergeometricRawMoment(array $arguments): float
    {
        return self::hypergeometricRawMoment($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function multivariateHypergeometricCategoryCovariance(array $arguments): float
    {
        [, $population, $firstCategory, $draws] = self::hypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[3]],
            'multivariatehypergeometriccovariance',
        );
        [, , $secondCategory] = self::hypergeometricArguments(
            [0.0, $population, $arguments[2], $draws],
            'multivariatehypergeometriccovariance',
        );
        if ($firstCategory + $secondCategory > $population) {
            throw new \DomainException(
                'multivariatehypergeometriccovariance() requires distinct category populations totaling at most N.',
            );
        }
        if ($population <= 1) {
            return 0.0;
        }

        return -$draws * ($population - $draws) * $firstCategory * $secondCategory
            / ($population * $population * ($population - 1.0));
    }

    /** @param list<int|float> $arguments Alternating observed-count and category-population pairs. */
    private static function multivariateHypergeometricProbabilityMass(array $arguments): float
    {
        $counts = [];
        $populations = [];
        $totalPopulation = 0;
        $totalDraws = 0;
        $outsideSupport = false;

        foreach (array_chunk($arguments, 2) as [$countValue, $populationValue]) {
            $count = (float) $countValue;
            $population = (float) $populationValue;
            if (
                !is_finite($population)
                || floor($population) !== $population
                || $population < 0.0
                || $population > self::MAX_DISTRIBUTION_SHAPE
            ) {
                throw new \DomainException(
                    'multivariatehypergeometricpmf() requires integer category populations in [0, 10000].',
                );
            }
            if (!is_finite($count)) {
                throw new \DomainException('multivariatehypergeometricpmf() requires finite observed counts.');
            }
            if ($count < 0.0 || floor($count) !== $count || $count > $population) {
                $outsideSupport = true;
            }

            $counts[] = $count;
            $populations[] = (int) $population;
            $totalPopulation += (int) $population;
            if ($totalPopulation > self::MAX_DISTRIBUTION_SHAPE) {
                throw new \DomainException(
                    'multivariatehypergeometricpmf() supports at most 10000 total population items.',
                );
            }
            if ($count >= 0.0 && floor($count) === $count && $count <= $population) {
                $totalDraws += (int) $count;
            }
        }

        if ($outsideSupport) {
            return 0.0;
        }

        $logMass = -self::logGammaPositive($totalPopulation + 1.0)
            + self::logGammaPositive($totalDraws + 1.0)
            + self::logGammaPositive($totalPopulation - $totalDraws + 1.0);
        foreach ($counts as $index => $count) {
            $population = $populations[$index];
            $count = (int) $count;
            $logMass += self::logGammaPositive($population + 1.0)
                - self::logGammaPositive($count + 1.0)
                - self::logGammaPositive($population - $count + 1.0);
        }

        return self::finiteSpecialResult(exp($logMass), 'multivariatehypergeometricpmf');
    }

    /** @param list<int|float> $arguments Alternating observed-count and category-population pairs. */
    private static function multivariateHypergeometricLogProbabilityMass(array $arguments): float
    {
        if (count($arguments) % 2 !== 0) {
            throw new \DomainException('multivariatehypergeometriclogpmf() requires count/population pairs.');
        }
        $counts = [];
        $populations = [];
        $totalPopulation = 0;
        $totalDraws = 0;
        foreach (array_chunk($arguments, 2) as [$countValue, $populationValue]) {
            $count = (float) $countValue;
            $population = (float) $populationValue;
            if (
                !is_finite($population)
                || floor($population) !== $population
                || $population < 0.0
                || $population > self::MAX_DISTRIBUTION_SHAPE
            ) {
                throw new \DomainException(
                    'multivariatehypergeometriclogpmf() requires integer category populations in [0, 10000].',
                );
            }
            if (!is_finite($count)) {
                throw new \DomainException('multivariatehypergeometriclogpmf() requires finite observed counts.');
            }
            if ($count < 0.0 || floor($count) !== $count || $count > $population) {
                return -INF;
            }
            $counts[] = (int) $count;
            $populations[] = (int) $population;
            $totalPopulation += (int) $population;
            $totalDraws += (int) $count;
            if ($totalPopulation > self::MAX_DISTRIBUTION_SHAPE) {
                throw new \DomainException(
                    'multivariatehypergeometriclogpmf() supports at most 10000 total population items.',
                );
            }
        }

        $logMass = -self::logGammaPositive($totalPopulation + 1.0)
            + self::logGammaPositive($totalDraws + 1.0)
            + self::logGammaPositive($totalPopulation - $totalDraws + 1.0);
        foreach ($counts as $index => $count) {
            $population = $populations[$index];
            $logMass += self::logGammaPositive($population + 1.0)
                - self::logGammaPositive($count + 1.0)
                - self::logGammaPositive($population - $count + 1.0);
        }

        return $logMass;
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments($arguments, 'hypergeometriccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('hypergeometriccdf() requires a finite outcome.');
        }
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($outcome < $minimum) {
            return 0.0;
        }
        if ($outcome >= $maximum) {
            return 1.0;
        }

        $sum = 0.0;
        for ($k = $minimum; $k <= (int) floor($outcome); ++$k) {
            $sum += self::hypergeometricMassValue($k, $population, $successes, $draws);
        }

        return self::finiteSpecialResult($sum, 'hypergeometriccdf');
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricComplementaryCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments($arguments, 'hypergeometricccdf');
        if (!is_finite($outcome)) {
            throw new \DomainException('hypergeometricccdf() requires a finite outcome.');
        }
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($outcome < $minimum) {
            return 1.0;
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        $sum = 0.0;
        for ($k = max($minimum, (int) floor($outcome) + 1); $k <= $maximum; ++$k) {
            $sum += self::hypergeometricMassValue($k, $population, $successes, $draws);
        }

        return self::finiteSpecialResult($sum, 'hypergeometricccdf');
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricLogCumulativeDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments(
            $arguments,
            'hypergeomlogcdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('hypergeomlogcdf() requires a finite outcome.');
        }
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($outcome < $minimum) {
            throw new \DomainException('hypergeomlogcdf() is negative infinity below the support.');
        }
        if ($outcome >= $maximum) {
            return 0.0;
        }

        return self::hypergeometricLogTailValue(
            $minimum,
            (int) floor($outcome),
            $population,
            $successes,
            $draws,
        );
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricLogComplementaryDistribution(array $arguments): float
    {
        [$outcome, $population, $successes, $draws] = self::hypergeometricArguments(
            $arguments,
            'hypergeomlogccdf',
        );
        if (!is_finite($outcome)) {
            throw new \DomainException('hypergeomlogccdf() requires a finite outcome.');
        }
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($outcome < $minimum) {
            return 0.0;
        }
        if ($outcome >= $maximum) {
            throw new \DomainException('hypergeomlogccdf() is negative infinity at the end of the support.');
        }

        return self::hypergeometricLogTailValue(
            max($minimum, (int) floor($outcome) + 1),
            $maximum,
            $population,
            $successes,
            $draws,
        );
    }

    private static function hypergeometricLogTailValue(
        int $minimum,
        int $maximum,
        int $population,
        int $successes,
        int $draws,
    ): float {
        $logMasses = [];
        $largestLogMass = -INF;
        for ($outcome = $minimum; $outcome <= $maximum; ++$outcome) {
            $logMass = self::hypergeometricLogMass($outcome, $population, $successes, $draws);
            $logMasses[] = $logMass;
            $largestLogMass = max($largestLogMass, $logMass);
        }

        $scaledSum = 0.0;
        foreach ($logMasses as $logMass) {
            $scaledSum += exp($logMass - $largestLogMass);
        }

        return self::finiteSpecialResult($largestLogMass + log($scaledSum), 'hypergeomlogcdf');
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricMean(array $arguments): float
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'hypergeometricmean',
        );

        return $population === 0 ? 0.0 : $draws * $successes / $population;
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricVariance(array $arguments): float
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            'hypergeometricvariance',
        );
        if ($population <= 1) {
            return 0.0;
        }

        return $draws * $successes * ($population - $successes) * ($population - $draws)
            / ($population * $population * ($population - 1.0));
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricStandardDeviation(array $arguments): float
    {
        return sqrt(self::hypergeometricVariance($arguments));
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricEntropy(array $arguments): float
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'hypergeometricentropy',
        );
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($minimum === $maximum) {
            return 0.0;
        }
        $logMasses = [];
        for ($outcome = $minimum; $outcome <= $maximum; ++$outcome) {
            $logMasses[] = self::hypergeometricLogMass($outcome, $population, $successes, $draws);
        }
        $normalizer = self::stableLogSumExp($logMasses);
        $entropy = 0.0;
        foreach ($logMasses as $logMass) {
            $probability = exp($logMass - $normalizer);
            $entropy -= $probability * ($logMass - $normalizer);
        }

        return self::finiteSpecialResult($entropy, 'hypergeometricentropy');
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricSkewness(array $arguments): float
    {
        return self::hypergeometricStandardizedMoments($arguments, 'hypergeometricskewness')[0];
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricExcessKurtosis(array $arguments): float
    {
        return self::hypergeometricStandardizedMoments($arguments, 'hypergeometricexcesskurtosis')[1];
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricKurtosis(array $arguments): float
    {
        return 3.0 + self::hypergeometricExcessKurtosis($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricRawMoment(array $arguments): float
    {
        $orderValue = (float) $arguments[0];
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0, $arguments[1], $arguments[2], $arguments[3]],
            'hypergeometricmoment',
        );
        if (
            !is_finite($orderValue)
            || floor($orderValue) !== $orderValue
            || $orderValue < 0.0
            || $orderValue > 64.0
        ) {
            throw new \DomainException('hypergeometricmoment() requires an integer order in [0, 64].');
        }
        if ($orderValue === 0.0) {
            return 1.0;
        }

        $order = (int) $orderValue;
        $maximumFactorialOrder = min($order, $successes, $draws);
        if ($maximumFactorialOrder === 0) {
            return 0.0;
        }

        $stirling = array_fill(0, $order + 1, 0.0);
        $stirling[0] = 1.0;
        for ($degree = 1; $degree <= $order; ++$degree) {
            for ($index = $degree; $index >= 1; --$index) {
                $stirling[$index] = $stirling[$index - 1] + $index * $stirling[$index];
            }
            $stirling[0] = 0.0;
        }

        $logTerms = [];
        for ($factorialOrder = 1; $factorialOrder <= $maximumFactorialOrder; ++$factorialOrder) {
            $logDrawFallingFactorial = 0.0;
            $logSuccessFallingFactorial = 0.0;
            $logPopulationFallingFactorial = 0.0;
            for ($offset = 0; $offset < $factorialOrder; ++$offset) {
                $logDrawFallingFactorial += log($draws - $offset);
                $logSuccessFallingFactorial += log($successes - $offset);
                $logPopulationFallingFactorial += log($population - $offset);
            }
            $logTerms[] = log($stirling[$factorialOrder])
                + $logDrawFallingFactorial
                + $logSuccessFallingFactorial
                - $logPopulationFallingFactorial;
        }

        $maximumLogTerm = max($logTerms);
        $scaledSum = 0.0;
        foreach ($logTerms as $logTerm) {
            $scaledSum += exp($logTerm - $maximumLogTerm);
        }
        $logMoment = $maximumLogTerm + log($scaledSum);
        if ($logMoment > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('hypergeometricmoment() exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(exp($logMoment), 'hypergeometricmoment');
    }

    /**
     * @param list<int|float> $arguments
     * @return array{float, float}
     */
    private static function hypergeometricStandardizedMoments(array $arguments, string $function): array
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0, $arguments[0], $arguments[1], $arguments[2]],
            $function,
        );
        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        $mean = $population === 0 ? 0.0 : $draws * $successes / $population;
        $logMasses = [];
        for ($outcome = $minimum; $outcome <= $maximum; ++$outcome) {
            $logMasses[] = self::hypergeometricLogMass($outcome, $population, $successes, $draws);
        }
        $normalizer = self::stableLogSumExp($logMasses);
        $variance = 0.0;
        $thirdCentralMoment = 0.0;
        $fourthCentralMoment = 0.0;
        foreach ($logMasses as $index => $logMass) {
            $probability = exp($logMass - $normalizer);
            $deviation = ($minimum + $index) - $mean;
            $squared = $deviation * $deviation;
            $variance += $probability * $squared;
            $thirdCentralMoment += $probability * $squared * $deviation;
            $fourthCentralMoment += $probability * $squared * $squared;
        }
        if ($variance === 0.0) {
            throw new \DomainException($function . '() is undefined for a degenerate distribution.');
        }

        return [
            self::finiteSpecialResult($thirdCentralMoment / ($variance * sqrt($variance)), $function),
            self::finiteSpecialResult($fourthCentralMoment / ($variance * $variance) - 3.0, $function),
        ];
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricLogMomentGeneratingFunction(array $arguments): float
    {
        $tilt = (float) $arguments[0];
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0.0, $arguments[1], $arguments[2], $arguments[3]],
            'hypergeometriclogmgf',
        );
        if (!is_finite($tilt)) {
            throw new \DomainException('hypergeometriclogmgf() requires a finite real argument.');
        }
        if ($tilt === 0.0) {
            return 0.0;
        }

        [$minimum, $maximum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($minimum === $maximum) {
            return self::finiteSpecialResult($tilt * $minimum, 'hypergeometriclogmgf');
        }

        $tiltedLogMasses = [];
        for ($outcome = $minimum; $outcome <= $maximum; ++$outcome) {
            $tiltContribution = $tilt * $outcome;
            if (!is_finite($tiltContribution)) {
                throw new \OverflowException('hypergeometriclogmgf() exceeds the finite float range.');
            }
            $tiltedLogMasses[] = self::hypergeometricLogMass(
                $outcome,
                $population,
                $successes,
                $draws,
            ) + $tiltContribution;
        }

        return self::stableLogSumExp($tiltedLogMasses);
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricMomentGeneratingFunction(array $arguments): float
    {
        $logMgf = self::hypergeometricLogMomentGeneratingFunction($arguments);

        return self::finiteSpecialResult(exp($logMgf), 'hypergeometricmgf');
    }

    /** @param list<int|float> $arguments */
    private static function inverseHypergeometricCumulativeDistribution(array $arguments): int
    {
        [$target, $population, $successes, $draws] = self::hypergeometricArguments($arguments, 'hypergeometricinv');
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('hypergeometricinv() requires a cumulative probability in [0, 1].');
        }
        [$lower, $upper] = self::hypergeometricSupport($population, $successes, $draws);
        if ($target === 0.0) {
            return $lower;
        }
        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (self::hypergeometricCumulativeValue($middle, $population, $successes, $draws) >= $target) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function inverseHypergeometricComplementaryCumulativeDistribution(array $arguments): int
    {
        [$target, $population, $successes, $draws] = self::hypergeometricArguments(
            $arguments,
            'hypergeometricccinv',
        );
        if (!is_finite($target) || $target < 0.0 || $target > 1.0) {
            throw new \DomainException('hypergeometricccinv() requires a survival probability in [0, 1].');
        }
        [$lower, $upper] = self::hypergeometricSupport($population, $successes, $draws);
        if ($target === 1.0) {
            return $lower;
        }
        if ($target === 0.0) {
            return $upper;
        }

        while ($lower < $upper) {
            $middle = $lower + intdiv($upper - $lower, 2);
            if (
                self::hypergeometricComplementaryCumulativeDistribution(
                    [$middle, $population, $successes, $draws],
                ) <= $target
            ) {
                $upper = $middle;
            } else {
                $lower = $middle + 1;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricMedian(array $arguments): int
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'hypergeometricmedian',
        );
        $median = self::inverseHypergeometricCumulativeDistribution([0.5, $population, $successes, $draws]);
        [$minimum] = self::hypergeometricSupport($population, $successes, $draws);
        if ($median > $minimum) {
            $precedingCumulative = self::hypergeometricCumulativeValue(
                $median - 1,
                $population,
                $successes,
                $draws,
            );
            if ($precedingCumulative >= 0.5 - 4.0 * PHP_FLOAT_EPSILON) {
                return $median - 1;
            }
        }

        return $median;
    }

    /** @param list<int|float> $arguments */
    private static function hypergeometricMode(array $arguments): int
    {
        [, $population, $successes, $draws] = self::hypergeometricArguments(
            [0.0, $arguments[0], $arguments[1], $arguments[2]],
            'hypergeometricmode',
        );

        return (int) floor((($draws + 1.0) * ($successes + 1.0)) / ($population + 2.0));
    }

    /**
     * @param list<int|float> $arguments
     * @return array{0: float, 1: int, 2: int, 3: int}
     */
    private static function hypergeometricArguments(array $arguments, string $function): array
    {
        $populationValue = (float) $arguments[1];
        $successesValue = (float) $arguments[2];
        $drawsValue = (float) $arguments[3];
        if (
            !is_finite($populationValue) || floor($populationValue) !== $populationValue
            || $populationValue < 0.0 || $populationValue > self::MAX_DISTRIBUTION_SHAPE
            || !is_finite($successesValue) || floor($successesValue) !== $successesValue
            || $successesValue < 0.0 || $successesValue > $populationValue
            || !is_finite($drawsValue) || floor($drawsValue) !== $drawsValue
            || $drawsValue < 0.0 || $drawsValue > $populationValue
        ) {
            throw new \DomainException(
                $function . '() requires integer counts with 0 ≤ successes, draws ≤ population ≤ 10000.',
            );
        }

        return [(float) $arguments[0], (int) $populationValue, (int) $successesValue, (int) $drawsValue];
    }

    /** @return array{int, int} */
    private static function hypergeometricSupport(int $population, int $successes, int $draws): array
    {
        return [max(0, $draws - ($population - $successes)), min($draws, $successes)];
    }

    private static function hypergeometricMassValue(int $outcome, int $population, int $successes, int $draws): float
    {
        return self::finiteSpecialResult(
            exp(self::hypergeometricLogMass($outcome, $population, $successes, $draws)),
            'hypergeometricpmf',
        );
    }

    private static function hypergeometricLogMass(int $outcome, int $population, int $successes, int $draws): float
    {
        $failures = $population - $successes;
        return self::logGammaPositive($successes + 1.0)
            - self::logGammaPositive($outcome + 1.0)
            - self::logGammaPositive($successes - $outcome + 1.0)
            + self::logGammaPositive($failures + 1.0)
            - self::logGammaPositive($draws - $outcome + 1.0)
            - self::logGammaPositive($failures - $draws + $outcome + 1.0)
            - self::logGammaPositive($population + 1.0)
            + self::logGammaPositive($draws + 1.0)
            + self::logGammaPositive($population - $draws + 1.0);
    }

    private static function hypergeometricCumulativeValue(
        int $outcome,
        int $population,
        int $successes,
        int $draws,
    ): float {
        [$minimum] = self::hypergeometricSupport($population, $successes, $draws);
        $sum = 0.0;
        for ($k = $minimum; $k <= $outcome; ++$k) {
            $sum += self::hypergeometricMassValue($k, $population, $successes, $draws);
        }

        return $sum;
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function sine(array $arguments): float
    {
        return \sin($arguments[0]);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function cosine(array $arguments): float
    {
        return \cos($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function tangent(array $arguments): float
    {
        $cosine = \cos($arguments[0]);
        if (\abs($cosine) <= 1.0E-15) {
            throw new \DomainException('tan() is undefined where cosine is zero.');
        }

        return \sin($arguments[0]) / $cosine;
    }

    /** @param list<int|float> $arguments */
    private static function secant(array $arguments): float
    {
        $cosine = \cos($arguments[0]);
        if (\abs($cosine) <= 1.0E-15) {
            throw new \DomainException('sec() is undefined where cosine is zero.');
        }

        return 1.0 / $cosine;
    }

    /** @param list<int|float> $arguments */
    private static function cosecant(array $arguments): float
    {
        $sine = \sin($arguments[0]);
        if (\abs($sine) <= 1.0E-15) {
            throw new \DomainException('csc() is undefined where sine is zero.');
        }

        return 1.0 / $sine;
    }

    /** @param list<int|float> $arguments */
    private static function cotangent(array $arguments): float
    {
        $sine = \sin($arguments[0]);
        if (\abs($sine) <= 1.0E-15) {
            throw new \DomainException('cot() is undefined where sine is zero.');
        }

        return \cos($arguments[0]) / $sine;
    }

    /** @param list<int|float> $arguments */
    private static function arcSecant(array $arguments): float
    {
        if (\abs($arguments[0]) < 1.0) {
            throw new \DomainException('asec() requires an argument with absolute value greater than or equal to one.');
        }

        return \acos(1.0 / $arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcCosecant(array $arguments): float
    {
        if (\abs($arguments[0]) < 1.0) {
            throw new \DomainException('acsc() requires an argument with absolute value greater than or equal to one.');
        }

        return \asin(1.0 / $arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcCotangent(array $arguments): float
    {
        return \atan2(1.0, $arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicSecant(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value <= 0.0 || $value > 1.0) {
            throw new \DomainException(
                'asech() requires a finite argument strictly greater than zero and at most one.',
            );
        }

        return \acosh(1.0 / $value);
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicCosecant(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value == 0.0) {
            throw new \DomainException('acsch() requires a finite non-zero argument.');
        }

        $absolute = abs($value);
        if ($absolute < 1.0 / sqrt(\PHP_FLOAT_MAX)) {
            $sign = $value < 0.0 ? -1.0 : 1.0;
            return self::finiteSpecialResult($sign * (log(2.0) - log($absolute)), 'acsch');
        }

        return \asinh(1.0 / $value);
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicCotangent(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || abs($value) <= 1.0) {
            throw new \DomainException('acoth() requires a finite argument with absolute value greater than one.');
        }

        return \atanh(1.0 / $value);
    }

    /** @param list<int|float> $arguments */
    private static function arcSine(array $arguments): float
    {
        self::requireClosedUnitInterval($arguments[0], 'asin');
        return \asin($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcCosine(array $arguments): float
    {
        self::requireClosedUnitInterval($arguments[0], 'acos');
        return \acos($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcTangent(array $arguments): float
    {
        return \atan($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSine(array $arguments): float
    {
        return \sinh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicCosine(array $arguments): float
    {
        return \cosh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicTangent(array $arguments): float
    {
        return \tanh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSecant(array $arguments): float
    {
        $value = (float) $arguments[0];
        $absolute = \abs($value);
        if ($absolute > 20.0) {
            $decay = \exp(-$absolute);
            $result = 2.0 * $decay / (1.0 + $decay * $decay);

            return self::finiteSpecialResult($result, 'sech');
        }

        return self::finiteSpecialResult(1.0 / \cosh($value), 'sech');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicCosecant(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value == 0.0) {
            throw new \DomainException('csch() is undefined at zero.');
        }

        $absolute = \abs($value);
        if ($absolute <= 20.0) {
            return self::finiteSpecialResult(1.0 / \sinh($value), 'csch');
        }

        $decay = \exp(-$absolute);
        $result = 2.0 * $decay / (1.0 - $decay * $decay);
        if ($value < 0.0) {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, 'csch');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicCotangent(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value == 0.0) {
            throw new \DomainException('coth() is undefined at zero.');
        }

        $absolute = \abs($value);
        if ($absolute <= 20.0) {
            return self::finiteSpecialResult(\cosh($value) / \sinh($value), 'coth');
        }

        $decay = \exp(-$absolute);
        $result = (1.0 + $decay * $decay) / (1.0 - $decay * $decay);
        if ($value < 0.0) {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, 'coth');
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicSine(array $arguments): float
    {
        return \asinh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicCosine(array $arguments): float
    {
        if ($arguments[0] < 1) {
            throw new \DomainException('acosh() requires an argument greater than or equal to one.');
        }

        return \acosh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcHyperbolicTangent(array $arguments): float
    {
        if ($arguments[0] <= -1 || $arguments[0] >= 1) {
            throw new \DomainException('atanh() requires an argument strictly between -1 and 1.');
        }

        return \atanh($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function gudermannian(array $arguments): float
    {
        $value = (float) $arguments[0];

        return 2.0 * \atan(\tanh($value / 2.0));
    }

    /** @param list<int|float> $arguments */
    private static function inverseGudermannian(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value <= -M_PI / 2.0 || $value >= M_PI / 2.0) {
            throw new \DomainException('invgd() requires an argument strictly between -pi/2 and pi/2.');
        }

        return self::finiteSpecialResult(\asinh(\tan($value)), 'invgd');
    }

    /** @param list<int|float> $arguments */
    private static function gudermannianDerivative(array $arguments): float
    {
        $value = self::requireFiniteGudermannianArgument($arguments, 'gdprime');

        return self::hyperbolicSecant([$value]);
    }

    /** @param list<int|float> $arguments */
    private static function gudermannianSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteGudermannianArgument($arguments, 'gdsecond');

        return -self::hyperbolicSecant([$value]) * tanh($value);
    }

    /** @param list<int|float> $arguments */
    private static function inverseGudermannianDerivative(array $arguments): float
    {
        $value = self::requireFiniteGudermannianArgument($arguments, 'invgdprime');
        self::requireInverseGudermannianDomain($value, 'invgdprime');

        return self::finiteSpecialResult(1.0 / cos($value), 'invgdprime');
    }

    /** @param list<int|float> $arguments */
    private static function inverseGudermannianSecondDerivative(array $arguments): float
    {
        $value = self::requireFiniteGudermannianArgument($arguments, 'invgdsecond');
        self::requireInverseGudermannianDomain($value, 'invgdsecond');
        $cosine = cos($value);

        return self::finiteSpecialResult(sin($value) / ($cosine * $cosine), 'invgdsecond');
    }

    /** @param list<int|float> $arguments */
    private static function requireFiniteGudermannianArgument(array $arguments, string $function): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }

        return $value;
    }

    private static function requireInverseGudermannianDomain(float $value, string $function): void
    {
        if ($value <= -M_PI / 2.0 || $value >= M_PI / 2.0) {
            throw new \DomainException($function . '() requires an argument strictly between -pi/2 and pi/2.');
        }
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function exponential(array $arguments): float
    {
        return \exp($arguments[0]);
    }

    /**
     * Evaluate a real Lambert-W branch. The optional second argument selects
     * branch 0 (the default) or branch -1 on the interval [-1/e, 0).
     *
     * @param list<int|float> $arguments
     */
    private static function lambertW(array $arguments): float
    {
        $value = (float) $arguments[0];
        $branch = isset($arguments[1]) ? (float) $arguments[1] : 0.0;
        if (
            !is_finite($value)
            || !is_finite($branch)
            || floor($branch) !== $branch
            || !in_array((int) $branch, [0, -1], true)
        ) {
            throw new \DomainException('lambertw() supports finite real values and branches 0 or -1.');
        }
        $branch = (int) $branch;
        $critical = -1.0 / M_E;
        if ($branch === 0 && $value < $critical) {
            throw new \DomainException(
                'lambertw() principal branch requires an argument greater than or equal to -1/e.',
            );
        }
        if ($branch === -1 && ($value < $critical || $value >= 0.0)) {
            throw new \DomainException('lambertw() branch -1 requires an argument in [-1/e, 0).');
        }
        if ($value === $critical) {
            return -1.0;
        }
        if ($value === 0.0) {
            return 0.0;
        }

        if ($branch === -1) {
            $logValue = log(-$value);
            $estimate = $logValue - log(-$logValue);
            if ($value < -0.25) {
                $estimate = -1.0 - sqrt(2.0 * (1.0 + M_E * $value));
            }
        } elseif ($value < 1.0) {
            $estimate = $value;
        } else {
            $estimate = log($value);
            $estimate -= log(max(1.0, $estimate));
        }

        for ($iteration = 0; $iteration < 100; ++$iteration) {
            $exponential = exp($estimate);
            $residual = $estimate * $exponential - $value;
            $denominator = $exponential * ($estimate + 1.0);
            if (abs($estimate + 1.0) > 1.0e-12) {
                $denominator -= (($estimate + 2.0) * $residual) / (2.0 * $estimate + 2.0);
            }
            if (!is_finite($denominator) || abs($denominator) <= 1.0e-15) {
                $denominator = $exponential * ($estimate + 1.0);
            }
            if (!is_finite($denominator) || abs($denominator) <= 1.0e-15) {
                throw new \OverflowException('lambertw() failed to converge to a finite result.');
            }
            $delta = $residual / $denominator;
            $estimate -= $delta;
            if (!is_finite($estimate)) {
                throw new \OverflowException('lambertw() produced a non-finite result.');
            }
            if (abs($delta) <= 1.0e-13 * max(1.0, abs($estimate))) {
                return $estimate;
            }
        }

        if (abs($estimate * exp($estimate) - $value) <= 1.0e-10 * max(1.0, abs($value))) {
            return $estimate;
        }
        throw new \OverflowException('lambertw() failed to converge to a finite result.');
    }

    /** @param list<int|float> $arguments */
    private static function lambertWDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        $branch = isset($arguments[1]) ? (float) $arguments[1] : 0.0;
        $lambertValue = self::lambertW([$value, $branch]);
        if ($lambertValue === -1.0) {
            throw new \DomainException('lambertwprime() is singular at the branch point -1/e.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(
            ($lambertValue / $value) / (1.0 + $lambertValue),
            'lambertwprime',
        );
    }

    /** @param list<int|float> $arguments */
    private static function lambertWSecondDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        $branch = isset($arguments[1]) ? (float) $arguments[1] : 0.0;
        $lambertValue = self::lambertW([$value, $branch]);
        if ($lambertValue === -1.0) {
            throw new \DomainException('lambertwsecond() is singular at the branch point -1/e.');
        }
        if ($value === 0.0) {
            return -2.0;
        }

        $scaledLambertValue = $lambertValue / $value;
        $onePlusLambertValue = 1.0 + $lambertValue;
        return self::finiteSpecialResult(
            -$scaledLambertValue * $scaledLambertValue * ($lambertValue + 2.0)
                / ($onePlusLambertValue * $onePlusLambertValue * $onePlusLambertValue),
            'lambertwsecond',
        );
    }

    /** @param list<int|float> $arguments */
    private static function lambertWThirdDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        $branch = isset($arguments[1]) ? (float) $arguments[1] : 0.0;
        $lambertValue = self::lambertW([$value, $branch]);
        if ($lambertValue === -1.0) {
            throw new \DomainException('lambertwthird() is singular at the branch point -1/e.');
        }
        if ($value === 0.0) {
            return 9.0;
        }

        $scaledLambertValue = $lambertValue / $value;
        $onePlusLambertValue = 1.0 + $lambertValue;
        return self::finiteSpecialResult(
            $scaledLambertValue ** 3 * (2.0 * $lambertValue ** 2 + 8.0 * $lambertValue + 9.0)
                / ($onePlusLambertValue ** 5),
            'lambertwthird',
        );
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function naturalLogarithm(array $arguments): float
    {
        $value = $arguments[0];

        if ($value <= 0) {
            throw new \DomainException(
                'ln() requires a positive argument.',
            );
        }

        return \log($value);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function logarithm(array $arguments): float
    {
        $value = $arguments[0];
        $base = $arguments[1];

        if (
            $value <= 0
            || $base <= 0
            || $base === 1
            || $base === 1.0
        ) {
            throw new \DomainException(
                'log() requires a positive value and a positive base other than one.',
            );
        }

        return \log($value, $base);
    }

    /** @param list<int|float> $arguments */
    private static function logBaseTen(array $arguments): float
    {
        if ($arguments[0] <= 0) {
            throw new \DomainException('log10() requires a positive argument.');
        }

        return \log10($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function logBaseTwo(array $arguments): float
    {
        if ($arguments[0] <= 0) {
            throw new \DomainException('log2() requires a positive argument.');
        }

        return \log($arguments[0], 2.0);
    }

    /** @param list<int|float> $arguments */
    private static function logOnePlus(array $arguments): float
    {
        if ($arguments[0] <= -1.0) {
            throw new \DomainException('log1p() requires an argument greater than -1.');
        }

        return \log1p($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function logOnePlusMinusX(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value <= -1.0) {
            throw new \DomainException('log1pmx() requires a finite argument greater than -1.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        if (\abs($value) < 1.0e-3) {
            $term = -0.5 * $value * $value;
            $sum = $term;
            for ($order = 3; $order <= 40; ++$order) {
                $term *= -$value * (($order - 1) / $order);
                $sum += $term;
            }

            return self::finiteSpecialResult($sum, 'log1pmx');
        }

        return self::finiteSpecialResult(\log1p($value) - $value, 'log1pmx');
    }

    /** @param list<int|float> $arguments */
    private static function logOnePlusMinusXDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value <= -1.0) {
            throw new \DomainException('log1pmxprime() requires a finite argument greater than -1.');
        }

        return self::finiteSpecialResult(-$value / (1.0 + $value), 'log1pmxprime');
    }

    /** @param list<int|float> $arguments */
    private static function logOneMinusExponential(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value >= 0.0) {
            throw new \DomainException('log1mexp() requires a finite argument less than zero.');
        }

        $result = $value < -\log(2.0)
            ? \log1p(-\exp($value))
            : \log(-\expm1($value));

        return self::finiteSpecialResult($result, 'log1mexp');
    }

    /** @param list<int|float> $arguments */
    private static function logOneMinusExponentialDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value >= 0.0) {
            throw new \DomainException('log1mexpprime() requires a finite argument less than zero.');
        }

        return self::finiteSpecialResult(-1.0 / expm1(-$value), 'log1mexpprime');
    }

    /** @param list<int|float> $arguments */
    private static function logAddExp(array $arguments): float
    {
        return self::stableLogSumExp($arguments);
    }

    /** @param list<int|float> $arguments */
    private static function stableLogSumExp(array $arguments): float
    {
        if ($arguments === []) {
            throw new \LogicException('logsumexp() requires at least one argument.');
        }
        $maximum = (float) \max($arguments);
        $sum = 0.0;
        $compensation = 0.0;
        foreach ($arguments as $argument) {
            $term = \exp((float) $argument - $maximum);
            $adjusted = $term - $compensation;
            $nextSum = $sum + $adjusted;
            $compensation = ($nextSum - $sum) - $adjusted;
            $sum = $nextSum;
        }
        if ($maximum === \PHP_FLOAT_MAX && \count($arguments) > 1) {
            throw new \OverflowException('logsumexp() produced a non-finite result.');
        }

        return self::finiteSpecialResult($maximum + \log($sum), 'logsumexp');
    }

    /** @param list<int|float> $arguments */
    private static function logSubtractExp(array $arguments): float
    {
        $minuend = (float) $arguments[0];
        $subtrahend = (float) $arguments[1];
        if ($minuend <= $subtrahend) {
            throw new \DomainException('logsubexp() requires the first argument to be greater than the second.');
        }

        return self::finiteSpecialResult(
            $minuend + \log(-\expm1($subtrahend - $minuend)),
            'logsubexp',
        );
    }

    /** @param list<int|float> $arguments */
    private static function expMinusOne(array $arguments): float
    {
        return \expm1($arguments[0]);
    }

    /** @param list<int|float> $arguments */
    private static function arcTangentTwo(array $arguments): float
    {
        if ($arguments[0] == 0 && $arguments[1] == 0) {
            throw new \DomainException('atan2() is undefined when both arguments are zero.');
        }

        return \atan2($arguments[0], $arguments[1]);
    }

    /** @param list<int|float> $arguments */
    private static function hypotenuse(array $arguments): float
    {
        return \hypot($arguments[0], $arguments[1]);
    }

    /** @param list<int|float> $arguments */
    private static function sign(array $arguments): int
    {
        return $arguments[0] <=> 0;
    }

    /** @param list<int|float> $arguments */
    private static function minimum(array $arguments): int|float
    {
        return \min(...$arguments);
    }

    /** @param list<int|float> $arguments */
    private static function maximum(array $arguments): int|float
    {
        return \max(...$arguments);
    }

    /** @param list<int|float> $arguments */
    private static function clamp(array $arguments): int|float
    {
        [$value, $minimum, $maximum] = $arguments;
        if ($minimum > $maximum) {
            throw new \DomainException('clamp() requires the minimum to be no greater than the maximum.');
        }

        return \min(\max($value, $minimum), $maximum);
    }

    /** @param list<int|float> $arguments */
    private static function linearInterpolation(array $arguments): float
    {
        [$start, $end, $fraction] = \array_map(static fn (int|float $value): float => (float) $value, $arguments);
        if ($fraction === 0.0) {
            return $start;
        }
        if ($fraction === 1.0) {
            return $end;
        }

        $result = ($start < 0.0) !== ($end < 0.0)
            ? (1.0 - $fraction) * $start + $fraction * $end
            : $start + $fraction * ($end - $start);

        return self::finiteSpecialResult($result, 'lerp');
    }

    /** @param list<int|float> $arguments */
    private static function inverseLinearInterpolation(array $arguments): float
    {
        [$start, $end, $value] = \array_map(static fn (int|float $number): float => (float) $number, $arguments);
        if ($start === $end) {
            throw new \DomainException('invlerp() requires distinct endpoints.');
        }

        $scale = \max(\abs($start), \abs($end), \abs($value));
        if ($scale === 0.0) {
            return 0.0;
        }

        return self::finiteSpecialResult(
            (($value / $scale) - ($start / $scale)) / (($end / $scale) - ($start / $scale)),
            'invlerp',
        );
    }

    /** @param list<int|float> $arguments */
    private static function sum(array $arguments): int|float
    {
        if (self::allIntegers($arguments)) {
            try {
                $total = 0;
                foreach ($arguments as $argument) {
                    if (\is_int($argument)) {
                        $total = self::checkedIntegerSum($total, $argument, 'sum()');
                    }
                }

                return $total;
            } catch (\OverflowException) {
                // Promote to a compensated float sum below.
            }
        }

        $total = 0.0;
        $compensation = 0.0;
        foreach ($arguments as $argument) {
            $value = (float) $argument;
            $next = $total + $value;
            $compensation += \abs($total) >= \abs($value)
                ? ($total - $next) + $value
                : ($value - $next) + $total;
            $total = $next;
        }

        return self::finiteSpecialResult($total + $compensation, 'sum');
    }

    /** @param list<int|float> $arguments */
    private static function product(array $arguments): int|float
    {
        if (\in_array(0, $arguments, true)) {
            return 0;
        }
        if (self::allIntegers($arguments)) {
            $product = 1;
            foreach ($arguments as $argument) {
                if (!\is_int($argument)) {
                    continue;
                }
                if (
                    ($argument > 0 && $product > 0 && $product > intdiv(\PHP_INT_MAX, $argument))
                    || ($argument > 0 && $product < 0 && $product < intdiv(\PHP_INT_MIN, $argument))
                    || ($argument < 0 && $product > 0 && $argument < intdiv(\PHP_INT_MIN, $product))
                    || ($argument < 0 && $product < 0 && $argument < intdiv(\PHP_INT_MAX, $product))
                ) {
                    throw new \OverflowException('product() result exceeds the host integer range.');
                }
                $product *= $argument;
            }

            return $product;
        }

        $product = 1.0;
        foreach ($arguments as $argument) {
            $product *= (float) $argument;
            if (!\is_finite($product)) {
                throw new \OverflowException('product() produced a non-finite result.');
            }
        }

        return $product;
    }

    /** @param list<int|float> $arguments */
    private static function allIntegers(array $arguments): bool
    {
        foreach ($arguments as $argument) {
            if (!\is_int($argument)) {
                return false;
            }
        }

        return true;
    }

    /** @param list<int|float> $arguments */
    private static function arithmeticMean(array $arguments): float
    {
        $scale = 0.0;
        foreach ($arguments as $value) {
            $scale = \max($scale, \abs((float) $value));
        }
        if ($scale === 0.0) {
            return 0.0;
        }

        $normalizedSum = 0.0;
        foreach ($arguments as $value) {
            $normalizedSum += (float) $value / $scale;
        }

        return self::finiteSpecialResult($scale * ($normalizedSum / \count($arguments)), 'mean');
    }

    /** @param list<int|float> $arguments */
    private static function powerMean(array $arguments): float
    {
        $order = (float) $arguments[0];
        if (!\is_finite($order)) {
            throw new \DomainException('powermean() requires a finite order.');
        }
        $values = \array_slice($arguments, 1);
        foreach ($values as $value) {
            if ($value < 0.0) {
                throw new \DomainException('powermean() requires non-negative arguments.');
            }
        }
        if ($order === 0.0) {
            return self::geometricMean($values);
        }
        if ($order < 0.0 && \in_array(0, $values, true)) {
            throw new \DomainException('powermean() requires positive arguments for a negative order.');
        }

        $minimum = \min(...$values);
        $maximum = \max(...$values);
        if ($minimum === $maximum) {
            return (float) $maximum;
        }
        $scale = $order > 0.0 ? (float) $maximum : (float) $minimum;
        if ($scale === 0.0) {
            return 0.0;
        }
        if (\abs($order) < 1.0e-100) {
            return self::geometricMean($values);
        }

        $exponentialOffsetSum = 0.0;
        foreach ($values as $value) {
            $logRatio = $value === 0 ? -\INF : \log((float) $value / $scale);
            $exponentialOffsetSum += \expm1($order * $logRatio);
        }
        $logMean = \log1p($exponentialOffsetSum / \count($values)) / $order;
        $logResult = \log($scale) + $logMean;
        if ($logResult >= \log(\PHP_FLOAT_MAX)) {
            return \PHP_FLOAT_MAX;
        }

        return self::finiteSpecialResult(\exp($logResult), 'powermean');
    }

    /** @param list<int|float> $arguments */
    private static function geometricMean(array $arguments): float
    {
        $logarithmSum = 0.0;
        foreach ($arguments as $value) {
            if ($value < 0) {
                throw new \DomainException('geometricmean() requires non-negative arguments.');
            }
            if ($value == 0) {
                return 0.0;
            }

            $logarithmSum += \log((float) $value);
        }

        return self::finiteSpecialResult(\exp($logarithmSum / \count($arguments)), 'geometricmean');
    }

    /** @param list<int|float> $arguments */
    private static function harmonicMean(array $arguments): float
    {
        $minimum = \min(...$arguments);
        if ($minimum < 0) {
            throw new \DomainException('harmonicmean() requires non-negative arguments.');
        }
        if ($minimum == 0) {
            return 0.0;
        }

        $scaledReciprocalSum = 0.0;
        foreach ($arguments as $value) {
            $scaledReciprocalSum += (float) $minimum / (float) $value;
        }

        return self::finiteSpecialResult(
            (float) $minimum * (\count($arguments) / $scaledReciprocalSum),
            'harmonicmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function quadraticMean(array $arguments): float
    {
        $scale = 0.0;
        foreach ($arguments as $value) {
            $scale = \max($scale, \abs((float) $value));
        }
        if ($scale === 0.0) {
            return 0.0;
        }

        $normalizedSquareSum = 0.0;
        foreach ($arguments as $value) {
            $normalized = (float) $value / $scale;
            $normalizedSquareSum += $normalized * $normalized;
        }

        return self::finiteSpecialResult(
            $scale * \sqrt($normalizedSquareSum / \count($arguments)),
            'quadraticmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logarithmicMean(array $arguments): float
    {
        $left = (float) $arguments[0];
        $right = (float) $arguments[1];
        if (!\is_finite($left) || !\is_finite($right) || $left <= 0.0 || $right <= 0.0) {
            throw new \DomainException('logarithmicmean() requires finite positive arguments.');
        }
        if ($left === $right) {
            return $left;
        }

        $smaller = \min($left, $right);
        $larger = \max($left, $right);
        $difference = $larger - $smaller;
        $relativeDifference = $difference / $smaller;
        $logarithmDifference = $relativeDifference <= 0.01
            ? \log1p($relativeDifference)
            : \log($larger) - \log($smaller);

        return self::finiteSpecialResult($difference / $logarithmDifference, 'logarithmicmean');
    }

    /** @param list<int|float> $arguments */
    private static function median(array $arguments): float
    {
        \sort($arguments, SORT_NUMERIC);
        $middle = intdiv(\count($arguments), 2);
        if (\count($arguments) % 2 === 1) {
            return (float) $arguments[$middle];
        }

        return self::finiteSpecialResult(
            (float) $arguments[$middle - 1] / 2.0 + (float) $arguments[$middle] / 2.0,
            'median',
        );
    }

    /** @param list<int|float> $arguments */
    private static function quantile(array $arguments): float
    {
        $probability = (float) $arguments[0];
        if ($probability < 0.0 || $probability > 1.0) {
            throw new \DomainException('quantile() probability must be in [0, 1].');
        }

        return self::sampleQuantile($probability, \array_slice($arguments, 1));
    }

    /** @param list<int|float> $arguments */
    private static function interquartileRange(array $arguments): float
    {
        $firstQuartile = self::sampleQuantile(0.25, $arguments);
        $thirdQuartile = self::sampleQuantile(0.75, $arguments);

        return self::finiteSpecialResult($thirdQuartile - $firstQuartile, 'iqr');
    }

    /** @param list<int|float> $arguments */
    private static function medianAbsoluteDeviation(array $arguments): float
    {
        $median = self::median($arguments);
        $deviations = [];
        foreach ($arguments as $value) {
            $deviations[] = \abs((float) $value - $median);
        }

        return self::median($deviations);
    }

    /** @param list<int|float> $arguments */
    private static function meanAbsoluteDeviation(array $arguments): float
    {
        $scale = self::maximumAbsoluteValue($arguments);
        if ($scale === 0.0) {
            return 0.0;
        }

        $normalizedValues = [];
        $normalizedSum = 0.0;
        foreach ($arguments as $value) {
            $normalized = (float) $value / $scale;
            $normalizedValues[] = $normalized;
            $normalizedSum += $normalized;
        }
        $normalizedMean = $normalizedSum / \count($arguments);
        $deviationSum = 0.0;
        foreach ($normalizedValues as $value) {
            $deviationSum += \abs($value - $normalizedMean);
        }

        return self::finiteSpecialResult($scale * ($deviationSum / \count($arguments)), 'meanabsolutedeviation');
    }

    /** @param list<int|float> $arguments */
    private static function standardErrorOfMean(array $arguments): float
    {
        return self::finiteSpecialResult(
            self::sampleStandardDeviation($arguments) / \sqrt(\count($arguments)),
            'standarderror',
        );
    }

    /** @param list<int|float> $arguments */
    private static function coefficientOfVariation(array $arguments): float
    {
        $mean = self::arithmeticMean($arguments);
        if ($mean === 0.0) {
            throw new \DomainException('coefficientvariation() is undefined when the arithmetic mean is zero.');
        }

        return self::finiteSpecialResult(self::populationStandardDeviation($arguments) / \abs($mean), 'rsd');
    }

    /** @param list<int|float> $values */
    private static function sampleQuantile(float $probability, array $values): float
    {
        \sort($values, SORT_NUMERIC);
        $position = (\count($values) - 1) * $probability;
        $lowerIndex = (int) \floor($position);
        $upperIndex = (int) \ceil($position);
        $lowerValue = (float) $values[$lowerIndex];
        if ($lowerIndex === $upperIndex) {
            return $lowerValue;
        }

        $fraction = $position - $lowerIndex;
        $upperValue = (float) $values[$upperIndex];

        return self::finiteSpecialResult(
            $lowerValue * (1.0 - $fraction) + $upperValue * $fraction,
            'quantile',
        );
    }

    /** @param list<int|float> $arguments */
    private static function skewness(array $arguments): float
    {
        [$skewness] = self::standardizedCentralMoments($arguments);

        return $skewness;
    }

    /** @param list<int|float> $arguments */
    private static function centralMoment(array $arguments): float
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'centralmoment');
        if ($order > 16) {
            throw new \DomainException('centralmoment() order must be an integer in [0, 16].');
        }
        if ($order === 0) {
            return 1.0;
        }
        if ($order === 1) {
            return 0.0;
        }

        $values = \array_slice($arguments, 1);
        $scale = self::maximumAbsoluteValue($values);
        if ($scale === 0.0) {
            return 0.0;
        }

        $normalizedValues = [];
        $sum = 0.0;
        foreach ($values as $value) {
            $normalized = (float) $value / $scale;
            $normalizedValues[] = $normalized;
            $sum += $normalized;
        }
        $mean = $sum / \count($normalizedValues);
        $moment = 0.0;
        foreach ($normalizedValues as $value) {
            $moment += \pow($value - $mean, $order);
        }
        $moment /= \count($normalizedValues);
        if ($moment === 0.0) {
            return 0.0;
        }

        $logMagnitude = $order * \log($scale) + \log(\abs($moment));
        if ($logMagnitude > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('centralmoment() produced a non-finite result.');
        }

        $result = \exp($logMagnitude);
        if ($moment < 0.0) {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, 'centralmoment');
    }

    /** @param list<int|float> $arguments */
    private static function kurtosis(array $arguments): float
    {
        [, $kurtosis] = self::standardizedCentralMoments($arguments);

        return $kurtosis;
    }

    /** @param list<int|float> $arguments */
    private static function excessKurtosis(array $arguments): float
    {
        [, $kurtosis] = self::standardizedCentralMoments($arguments);

        return $kurtosis - 3.0;
    }

    /** @param list<int|float> $arguments */
    private static function sampleSkewness(array $arguments): float
    {
        [$populationSkewness] = self::standardizedCentralMoments($arguments);
        $count = \count($arguments);
        $correction = \sqrt($count * ($count - 1)) / ($count - 2);

        return self::finiteSpecialResult($correction * $populationSkewness, 'sampleskewness');
    }

    /** @param list<int|float> $arguments */
    private static function sampleExcessKurtosis(array $arguments): float
    {
        [, $populationKurtosis] = self::standardizedCentralMoments($arguments);
        $count = \count($arguments);
        $correction = ($count - 1) / (($count - 2) * ($count - 3));
        $adjusted = $correction * (($count + 1) * $populationKurtosis - 3 * ($count - 1));

        return self::finiteSpecialResult($adjusted, 'sampleexcesskurtosis');
    }

    /**
     * @param list<int|float> $values
     * @return array{float, float}
     */
    private static function standardizedCentralMoments(array $values): array
    {
        $scale = self::maximumAbsoluteValue($values);
        if ($scale === 0.0) {
            throw new \DomainException('skewness() and kurtosis() are undefined for zero-variance data.');
        }

        $normalizedValues = [];
        $normalizedSum = 0.0;
        foreach ($values as $value) {
            $normalized = (float) $value / $scale;
            $normalizedValues[] = $normalized;
            $normalizedSum += $normalized;
        }
        $mean = $normalizedSum / \count($normalizedValues);

        $secondMoment = 0.0;
        $thirdMoment = 0.0;
        $fourthMoment = 0.0;
        foreach ($normalizedValues as $value) {
            $centered = $value - $mean;
            $square = $centered * $centered;
            $secondMoment += $square;
            $thirdMoment += $square * $centered;
            $fourthMoment += $square * $square;
        }
        $count = \count($normalizedValues);
        $secondMoment /= $count;
        if ($secondMoment === 0.0) {
            throw new \DomainException('skewness() and kurtosis() are undefined for zero-variance data.');
        }

        $thirdMoment /= $count;
        $fourthMoment /= $count;

        return [
            self::finiteSpecialResult($thirdMoment / ($secondMoment * \sqrt($secondMoment)), 'skewness'),
            self::finiteSpecialResult($fourthMoment / ($secondMoment * $secondMoment), 'kurtosis'),
        ];
    }

    /** @param list<int|float> $arguments */
    private static function populationVariance(array $arguments): float
    {
        $normalizedVariance = self::normalizedVariance($arguments, false);
        if ($normalizedVariance === 0.0) {
            return 0.0;
        }

        $scale = self::maximumAbsoluteValue($arguments);
        $standardDeviation = $scale * \sqrt($normalizedVariance);

        return self::finiteSpecialResult($standardDeviation * $standardDeviation, 'variance');
    }

    /** @param list<int|float> $arguments */
    private static function sampleVariance(array $arguments): float
    {
        $normalizedVariance = self::normalizedVariance($arguments, true);
        if ($normalizedVariance === 0.0) {
            return 0.0;
        }

        $scale = self::maximumAbsoluteValue($arguments);
        $standardDeviation = $scale * \sqrt($normalizedVariance);

        return self::finiteSpecialResult($standardDeviation * $standardDeviation, 'samplevariance');
    }

    /** @param list<int|float> $arguments */
    private static function populationStandardDeviation(array $arguments): float
    {
        $normalizedVariance = self::normalizedVariance($arguments, false);
        $scale = self::maximumAbsoluteValue($arguments);

        return self::finiteSpecialResult($scale * \sqrt($normalizedVariance), 'stddev');
    }

    /** @param list<int|float> $arguments */
    private static function sampleStandardDeviation(array $arguments): float
    {
        $normalizedVariance = self::normalizedVariance($arguments, true);
        $scale = self::maximumAbsoluteValue($arguments);

        return self::finiteSpecialResult($scale * \sqrt($normalizedVariance), 'samplestddev');
    }

    /** @param list<int|float> $arguments */
    private static function populationCovariance(array $arguments): float
    {
        return self::covariance($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function sampleCovariance(array $arguments): float
    {
        return self::covariance($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function pearsonCorrelation(array $arguments): float
    {
        [$x, $y] = self::pairedObservations($arguments, 'correlation');
        $scaleX = self::maximumAbsoluteValue($x);
        $scaleY = self::maximumAbsoluteValue($y);
        if ($scaleX === 0.0 || $scaleY === 0.0) {
            throw new \DomainException('correlation() is undefined when either variable has zero variance.');
        }

        [$normalizedCovariance, $varianceX, $varianceY] = self::normalizedCovariance($x, $y, false);
        if ($varianceX === 0.0 || $varianceY === 0.0) {
            throw new \DomainException('correlation() is undefined when either variable has zero variance.');
        }
        $correlation = $normalizedCovariance / (\sqrt($varianceX) * \sqrt($varianceY));

        return self::finiteSpecialResult($correlation, 'correlation');
    }

    /** @param list<int|float> $arguments */
    private static function weightedCovariance(array $arguments): float
    {
        [$covariance, , , $scaleX, $scaleY] = self::weightedPairedStatistics($arguments, 'weightedcovariance');
        if ($covariance === 0.0 || $scaleX === 0.0 || $scaleY === 0.0) {
            return 0.0;
        }

        $logMagnitude = \log($scaleX) + \log($scaleY) + \log(\abs($covariance));
        if ($logMagnitude > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException('weightedcovariance() produced a non-finite result.');
        }
        $result = \exp($logMagnitude);
        if ($covariance < 0.0) {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, 'weightedcovariance');
    }

    /** @param list<int|float> $arguments */
    private static function weightedCorrelation(array $arguments): float
    {
        [$covariance, $varianceX, $varianceY] = self::weightedPairedStatistics($arguments, 'weightedcorrelation');
        if ($varianceX === 0.0 || $varianceY === 0.0) {
            throw new \DomainException('weightedcorrelation() is undefined when either variable has zero variance.');
        }

        return self::finiteSpecialResult(
            $covariance / (\sqrt($varianceX) * \sqrt($varianceY)),
            'weightedcorrelation',
        );
    }

    /** @param list<int|float> $arguments
     *  @return array{float, float, float, float, float}
     */
    private static function weightedPairedStatistics(array $arguments, string $function): array
    {
        if (\count($arguments) % 3 !== 0) {
            throw new \DomainException($function . '() requires interleaved x/y/weight triplets.');
        }

        $x = [];
        $y = [];
        $weights = [];
        $weightScale = 0.0;
        foreach (\array_chunk($arguments, 3) as [$xValue, $yValue, $weightValue]) {
            $weight = (float) $weightValue;
            if ($weight < 0.0) {
                throw new \DomainException($function . '() requires non-negative weights.');
            }
            $x[] = (float) $xValue;
            $y[] = (float) $yValue;
            $weights[] = $weight;
            $weightScale = \max($weightScale, $weight);
        }
        if ($weightScale === 0.0) {
            throw new \DomainException($function . '() requires at least one positive weight.');
        }

        $scaleX = self::maximumAbsoluteValue($x);
        $scaleY = self::maximumAbsoluteValue($y);
        if ($scaleX === 0.0 || $scaleY === 0.0) {
            return [0.0, 0.0, 0.0, $scaleX, $scaleY];
        }

        $normalizedX = \array_map(static fn (float $value): float => $value / $scaleX, $x);
        $normalizedY = \array_map(static fn (float $value): float => $value / $scaleY, $y);
        $normalizedWeights = \array_map(static fn (float $weight): float => $weight / $weightScale, $weights);
        $weightTotal = \array_sum($normalizedWeights);
        $meanX = 0.0;
        $meanY = 0.0;
        foreach ($normalizedWeights as $index => $weight) {
            $meanX += $normalizedX[$index] * $weight;
            $meanY += $normalizedY[$index] * $weight;
        }
        $meanX /= $weightTotal;
        $meanY /= $weightTotal;

        $covariance = 0.0;
        $varianceX = 0.0;
        $varianceY = 0.0;
        foreach ($normalizedWeights as $index => $weight) {
            $dx = $normalizedX[$index] - $meanX;
            $dy = $normalizedY[$index] - $meanY;
            $covariance += $weight * $dx * $dy;
            $varianceX += $weight * $dx * $dx;
            $varianceY += $weight * $dy * $dy;
        }

        return [
            $covariance / $weightTotal,
            $varianceX / $weightTotal,
            $varianceY / $weightTotal,
            $scaleX,
            $scaleY,
        ];
    }

    /** @param list<int|float> $arguments */
    private static function covariance(array $arguments, bool $sample): float
    {
        [$x, $y] = self::pairedObservations($arguments, $sample ? 'samplecovariance' : 'covariance');
        [$normalizedCovariance] = self::normalizedCovariance($x, $y, $sample);
        if ($normalizedCovariance === 0.0) {
            return 0.0;
        }

        $scaleX = self::maximumAbsoluteValue($x);
        $scaleY = self::maximumAbsoluteValue($y);
        $logMagnitude = \log($scaleX) + \log($scaleY) + \log(\abs($normalizedCovariance));
        if ($logMagnitude > \log(\PHP_FLOAT_MAX)) {
            $function = $sample ? 'samplecovariance' : 'covariance';
            throw new \OverflowException($function . '() produced a non-finite result.');
        }
        $result = \exp($logMagnitude);
        if ($normalizedCovariance < 0.0) {
            $result = -$result;
        }

        return self::finiteSpecialResult($result, $sample ? 'samplecovariance' : 'covariance');
    }

    /** @param list<int|float> $arguments
     *  @return array{list<float>, list<float>}
     */
    private static function pairedObservations(array $arguments, string $function): array
    {
        if (\count($arguments) % 2 !== 0) {
            throw new \DomainException($function . '() requires interleaved x/y pairs.');
        }
        $x = [];
        $y = [];
        foreach (\array_chunk($arguments, 2) as [$xValue, $yValue]) {
            $x[] = (float) $xValue;
            $y[] = (float) $yValue;
        }

        return [$x, $y];
    }

    /**
     * @param list<float> $x
     * @param list<float> $y
     *  @return array{float, float, float}
     */
    private static function normalizedCovariance(array $x, array $y, bool $sample): array
    {
        $scaleX = self::maximumAbsoluteValue($x);
        $scaleY = self::maximumAbsoluteValue($y);
        if ($scaleX === 0.0 || $scaleY === 0.0) {
            return [0.0, 0.0, 0.0];
        }
        $normalizedX = \array_map(static fn (float $value): float => $value / $scaleX, $x);
        $normalizedY = \array_map(static fn (float $value): float => $value / $scaleY, $y);
        $count = \count($x);
        $meanX = \array_sum($normalizedX) / $count;
        $meanY = \array_sum($normalizedY) / $count;
        $covariance = 0.0;
        $varianceX = 0.0;
        $varianceY = 0.0;
        foreach ($normalizedX as $index => $xValue) {
            $dx = $xValue - $meanX;
            $dy = $normalizedY[$index] - $meanY;
            $covariance += $dx * $dy;
            $varianceX += $dx * $dx;
            $varianceY += $dy * $dy;
        }
        $denominator = $sample ? $count - 1 : $count;

        return [$covariance / $denominator, $varianceX / $denominator, $varianceY / $denominator];
    }

    /** @param list<int|float> $arguments */
    private static function normalizedVariance(array $arguments, bool $sample): float
    {
        $count = \count($arguments);
        if ($sample && $count < 2) {
            throw new \DomainException('sample statistics require at least two observations.');
        }

        $scale = self::maximumAbsoluteValue($arguments);
        if ($scale === 0.0) {
            return 0.0;
        }

        $mean = 0.0;
        $sumOfSquares = 0.0;
        foreach ($arguments as $index => $value) {
            $normalized = (float) $value / $scale;
            $delta = $normalized - $mean;
            $mean += $delta / ($index + 1);
            $sumOfSquares += $delta * ($normalized - $mean);
        }

        return \max(0.0, $sumOfSquares / ($sample ? $count - 1 : $count));
    }

    /** @param list<int|float> $values */
    private static function maximumAbsoluteValue(array $values): float
    {
        $maximum = 0.0;
        foreach ($values as $value) {
            $maximum = \max($maximum, \abs((float) $value));
        }

        return $maximum;
    }

    /** @param list<int|float> $arguments */
    private static function weightedArithmeticMean(array $arguments): float
    {
        $pairs = self::weightedPairs($arguments, 'weightedmean');
        $maximumWeight = self::maximumWeight($pairs);
        $scale = 0.0;
        $totalWeight = 0.0;
        foreach ($pairs as [$value, $weight]) {
            if ($weight == 0) {
                continue;
            }
            $scale = \max($scale, \abs((float) $value));
            $totalWeight += (float) $weight / $maximumWeight;
        }
        if ($scale === 0.0) {
            return 0.0;
        }

        $weightedSum = 0.0;
        foreach ($pairs as [$value, $weight]) {
            if ($weight != 0) {
                $weightedSum += ((float) $weight / $maximumWeight) * ((float) $value / $scale);
            }
        }

        return self::finiteSpecialResult($scale * ($weightedSum / $totalWeight), 'weightedmean');
    }

    /** @param list<int|float> $arguments */
    private static function weightedGeometricMean(array $arguments): float
    {
        $pairs = self::weightedPairs($arguments, 'weightedgeometricmean', true);
        $maximumWeight = self::maximumWeight($pairs);
        $totalWeight = 0.0;
        $weightedLogSum = 0.0;
        foreach ($pairs as [$value, $weight]) {
            if ($weight == 0) {
                continue;
            }
            if ($value == 0) {
                return 0.0;
            }
            $normalizedWeight = (float) $weight / $maximumWeight;
            $totalWeight += $normalizedWeight;
            $weightedLogSum += $normalizedWeight * \log((float) $value);
        }

        return self::finiteSpecialResult(\exp($weightedLogSum / $totalWeight), 'weightedgeometricmean');
    }

    /** @param list<int|float> $arguments */
    private static function weightedHarmonicMean(array $arguments): float
    {
        $pairs = self::weightedPairs($arguments, 'weightedharmonicmean', true);
        $logWeights = [];
        $logReciprocalTerms = [];
        foreach ($pairs as [$value, $weight]) {
            if ($weight == 0) {
                continue;
            }
            if ($value == 0) {
                return 0.0;
            }
            $logWeight = \log((float) $weight);
            $logWeights[] = $logWeight;
            $logReciprocalTerms[] = $logWeight - \log((float) $value);
        }
        if ($logWeights === [] || $logReciprocalTerms === []) {
            throw new \LogicException('weightedharmonicmean() requires at least one positive-weight term.');
        }

        return self::finiteSpecialResult(
            \exp(self::logSumExp($logWeights) - self::logSumExp($logReciprocalTerms)),
            'weightedharmonicmean',
        );
    }

    /** @param list<int|float> $arguments */
    private static function weightedQuadraticMean(array $arguments): float
    {
        $pairs = self::weightedPairs($arguments, 'weightedquadraticmean');
        $maximumWeight = self::maximumWeight($pairs);
        $scale = 0.0;
        $totalWeight = 0.0;
        foreach ($pairs as [$value, $weight]) {
            if ($weight == 0) {
                continue;
            }
            $scale = \max($scale, \abs((float) $value));
            $totalWeight += (float) $weight / $maximumWeight;
        }
        if ($scale === 0.0) {
            return 0.0;
        }

        $weightedSquareSum = 0.0;
        foreach ($pairs as [$value, $weight]) {
            if ($weight == 0) {
                continue;
            }
            $normalized = (float) $value / $scale;
            $weightedSquareSum += ((float) $weight / $maximumWeight) * $normalized * $normalized;
        }

        return self::finiteSpecialResult(
            $scale * \sqrt($weightedSquareSum / $totalWeight),
            'weightedquadraticmean',
        );
    }

    /**
     * @param list<int|float> $arguments
     * @return list<array{int|float, int|float}>
     */
    private static function weightedPairs(array $arguments, string $function, bool $nonNegativeValues = false): array
    {
        if (\count($arguments) % 2 !== 0) {
            throw new \DomainException($function . '() requires alternating value/weight pairs.');
        }

        $pairs = [];
        $hasPositiveWeight = false;
        for ($index = 0; $index < \count($arguments); $index += 2) {
            $value = $arguments[$index];
            $weight = $arguments[$index + 1];
            if ($weight < 0) {
                throw new \DomainException($function . '() requires non-negative weights.');
            }
            if ($nonNegativeValues && $value < 0) {
                throw new \DomainException($function . '() requires non-negative values.');
            }
            $hasPositiveWeight = $hasPositiveWeight || $weight > 0;
            $pairs[] = [$value, $weight];
        }
        if (!$hasPositiveWeight) {
            throw new \DomainException($function . '() requires a positive total weight.');
        }

        return $pairs;
    }

    /** @param list<array{int|float, int|float}> $pairs */
    private static function maximumWeight(array $pairs): float
    {
        $maximum = 0.0;
        foreach ($pairs as [, $weight]) {
            $maximum = \max($maximum, (float) $weight);
        }

        return $maximum;
    }

    /** @param non-empty-list<float> $values */
    private static function logSumExp(array $values): float
    {
        $maximum = \max(...$values);
        $scaledSum = 0.0;
        foreach ($values as $value) {
            $scaledSum += \exp($value - $maximum);
        }

        return $maximum + \log($scaledSum);
    }

    private static function requireClosedUnitInterval(int|float $value, string $function): void
    {
        if ($value < -1 || $value > 1) {
            throw new \DomainException($function . '() requires an argument between -1 and 1.');
        }
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function floor(array $arguments): float
    {
        return \floor($arguments[0]);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function ceiling(array $arguments): float
    {
        return \ceil($arguments[0]);
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function round(array $arguments): float
    {
        return \round(
            $arguments[0],
            0,
            \PHP_ROUND_HALF_UP,
        );
    }

    /** @param list<int|float> $arguments */
    private static function modulo(array $arguments): int
    {
        $dividend = self::requireInteger($arguments[0], 'mod');
        $divisor = self::requireInteger($arguments[1], 'mod');
        if ($divisor === 0) {
            throw new \DomainException('mod() divisor must not be zero.');
        }
        if ($dividend === \PHP_INT_MIN && $divisor === -1) {
            return 0;
        }

        return $dividend % $divisor;
    }

    /** @param list<int|float> $arguments */
    private static function greatestCommonDivisor(array $arguments): int
    {
        $left = self::requireInteger($arguments[0], 'gcd');
        $right = self::requireInteger($arguments[1], 'gcd');
        if (
            ($left === \PHP_INT_MIN && ($right === 0 || $right === \PHP_INT_MIN))
            || ($right === \PHP_INT_MIN && $left === 0)
        ) {
            throw new \OverflowException('gcd() result exceeds the host integer range.');
        }

        while ($right !== 0) {
            $remainder = $left === \PHP_INT_MIN && $right === -1
                ? 0
                : $left % $right;
            [$left, $right] = [$right, $remainder];
        }

        return abs($left);
    }

    /** @param list<int|float> $arguments */
    private static function leastCommonMultiple(array $arguments): int
    {
        $left = self::requireInteger($arguments[0], 'lcm');
        $right = self::requireInteger($arguments[1], 'lcm');
        if ($left === 0 || $right === 0) {
            return 0;
        }
        if ($left === \PHP_INT_MIN || $right === \PHP_INT_MIN) {
            throw new \OverflowException('lcm() result exceeds the host integer range.');
        }

        $left = abs($left);
        $right = abs($right);
        $divisor = self::greatestCommonDivisor([$left, $right]);
        $reduced = intdiv($left, $divisor);
        if ($reduced > intdiv(\PHP_INT_MAX, $right)) {
            throw new \OverflowException('lcm() result exceeds the host integer range.');
        }

        return $reduced * $right;
    }

    /** @param list<int|float> $arguments */
    private static function multiplicativeOrder(array $arguments): int
    {
        $base = self::requireInteger($arguments[0], 'multiplicativeorder');
        $modulus = self::requireNonNegativeInteger($arguments[1], 'multiplicativeorder');
        if ($modulus < 2 || $modulus > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                'multiplicativeorder() modulus must be an integer from 2 through '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $base %= $modulus;
        if ($base < 0) {
            $base += $modulus;
        }
        if (self::greatestCommonDivisor([$base, $modulus]) !== 1) {
            throw new \DomainException('multiplicativeorder() requires the base and modulus to be coprime.');
        }

        $order = self::eulerTotient([$modulus]);
        foreach (self::primeFactorization($order) as $prime => $_exponent) {
            while ($order % $prime === 0) {
                $candidate = intdiv($order, $prime);
                if (self::modularPower($base, $candidate, $modulus) !== 1) {
                    break;
                }
                $order = $candidate;
            }
        }

        return $order;
    }

    /** @param list<int|float> $arguments */
    private static function isPrimitiveRoot(array $arguments): int
    {
        $base = self::requireInteger($arguments[0], 'isprimitiveroot');
        $modulus = self::requireNonNegativeInteger($arguments[1], 'isprimitiveroot');
        if ($modulus < 2 || $modulus > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                'isprimitiveroot() modulus must be an integer from 2 through '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $base %= $modulus;
        if ($base < 0) {
            $base += $modulus;
        }
        if (self::greatestCommonDivisor([$base, $modulus]) !== 1) {
            return 0;
        }

        return self::multiplicativeOrder([$base, $modulus]) === self::eulerTotient([$modulus]) ? 1 : 0;
    }

    private static function modularPower(int $base, int $exponent, int $modulus): int
    {
        $result = 1;
        while ($exponent > 0) {
            if ($exponent % 2 === 1) {
                $result = self::modularProduct($result, $base, $modulus);
            }
            $exponent = intdiv($exponent, 2);
            if ($exponent > 0) {
                $base = self::modularProduct($base, $base, $modulus);
            }
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function modularInverse(array $arguments): int
    {
        $base = self::requireInteger($arguments[0], 'modinverse');
        $modulus = self::requireNonNegativeInteger($arguments[1], 'modinverse');
        if ($modulus < 2 || $modulus > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                'modinverse() modulus must be an integer from 2 through '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $base %= $modulus;
        if ($base < 0) {
            $base += $modulus;
        }
        $oldRemainder = $base;
        $remainder = $modulus;
        $oldCoefficient = 1;
        $coefficient = 0;
        while ($remainder !== 0) {
            $quotient = intdiv($oldRemainder, $remainder);
            [$oldRemainder, $remainder] = [
                $remainder,
                $oldRemainder - $quotient * $remainder,
            ];
            [$oldCoefficient, $coefficient] = [
                $coefficient,
                $oldCoefficient - $quotient * $coefficient,
            ];
        }

        if ($oldRemainder !== 1) {
            throw new \DomainException('modinverse() requires the base and modulus to be coprime.');
        }

        return (($oldCoefficient % $modulus) + $modulus) % $modulus;
    }

    private static function modularProduct(int $left, int $right, int $modulus): int
    {
        $product = 0;
        while ($right > 0) {
            if ($right % 2 === 1) {
                $product = $product >= $modulus - $left
                    ? $product - ($modulus - $left)
                    : $product + $left;
            }
            $right = intdiv($right, 2);
            if ($right > 0) {
                $left = $left >= $modulus - $left
                    ? $left - ($modulus - $left)
                    : $left + $left;
            }
        }

        return $product;
    }

    /** @param list<int|float> $arguments */
    private static function jacobiSymbol(array $arguments): int
    {
        $numerator = self::requireInteger($arguments[0], 'jacobisymbol');
        $modulus = self::requireNonNegativeInteger($arguments[1], 'jacobisymbol');
        if ($modulus < 1 || $modulus > self::MAX_NUMBER_THEORY_INPUT || $modulus % 2 === 0) {
            throw new \DomainException(
                'jacobisymbol() requires an odd positive modulus no greater than '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $numerator %= $modulus;
        if ($numerator < 0) {
            $numerator += $modulus;
        }
        $symbol = 1;
        while ($numerator !== 0) {
            while ($numerator % 2 === 0) {
                $numerator = intdiv($numerator, 2);
                $modulusModuloEight = $modulus % 8;
                if ($modulusModuloEight === 3 || $modulusModuloEight === 5) {
                    $symbol = -$symbol;
                }
            }

            [$numerator, $modulus] = [$modulus, $numerator];
            if ($numerator % 4 === 3 && $modulus % 4 === 3) {
                $symbol = -$symbol;
            }
            $numerator %= $modulus;
        }

        return $modulus === 1 ? $symbol : 0;
    }

    /** @param list<int|float> $arguments */
    private static function legendreSymbol(array $arguments): int
    {
        $modulus = self::requireNonNegativeInteger($arguments[1], 'legendresymbol');
        if ($modulus < 3 || $modulus % 2 === 0 || $modulus > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                'legendresymbol() requires an odd prime modulus no greater than '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }
        if (self::isPrime([$modulus]) !== 1) {
            throw new \DomainException('legendresymbol() requires an odd prime modulus.');
        }

        return self::jacobiSymbol([$arguments[0], $modulus]);
    }

    /** @param list<int|float> $arguments */
    private static function kroneckerSymbol(array $arguments): int
    {
        $numerator = self::requireInteger($arguments[0], 'kroneckersymbol');
        $denominator = self::requireInteger($arguments[1], 'kroneckersymbol');
        if ($denominator === 0) {
            return $numerator === 1 || $numerator === -1 ? 1 : 0;
        }
        if (
            $denominator > self::MAX_NUMBER_THEORY_INPUT
            || $denominator < -self::MAX_NUMBER_THEORY_INPUT
        ) {
            throw new \DomainException(
                'kroneckersymbol() denominator magnitude must not exceed '
                . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $sign = 1;
        if ($denominator < 0) {
            $denominator = -$denominator;
            if ($numerator < 0) {
                $sign = -1;
            }
        }

        $powerOfTwo = 0;
        while ($denominator % 2 === 0) {
            $denominator = intdiv($denominator, 2);
            ++$powerOfTwo;
        }
        if ($powerOfTwo > 0 && $numerator % 2 === 0) {
            return 0;
        }

        $twoSymbol = 1;
        if ($powerOfTwo % 2 === 1) {
            $numeratorModuloEight = (($numerator % 8) + 8) % 8;
            $twoSymbol = ($numeratorModuloEight === 1 || $numeratorModuloEight === 7) ? 1 : -1;
        }

        return $sign * $twoSymbol * self::jacobiSymbol([$numerator, $denominator]);
    }

    /** @param list<int|float> $arguments */
    private static function eulerTotient(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'totient');
        $result = $number;
        foreach (array_keys(self::primeFactorization($number)) as $prime) {
            $result = intdiv($result, $prime) * ($prime - 1);
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function cototient(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'cototient');
        $totient = self::eulerTotient([$number]);

        return $number - $totient;
    }

    /** @param list<int|float> $arguments */
    private static function jordanTotient(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'jordan');
        $order = self::requireNonNegativeInteger($arguments[1], 'jordan');
        if ($order < 1 || $order > 64) {
            throw new \DomainException('jordan() order must be an integer in [1, 64].');
        }

        $result = 1;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            $primePowerMinusOne = 0;
            for ($power = 0; $power < $order; ++$power) {
                $primePowerMinusOne = self::checkedIntegerSum(
                    self::checkedIntegerProduct($primePowerMinusOne, $prime, 'jordan()'),
                    $prime - 1,
                    'jordan()',
                );
            }

            $component = $primePowerMinusOne;
            if ($exponent > 1) {
                if ($primePowerMinusOne === PHP_INT_MAX) {
                    throw new \OverflowException('jordan() result exceeds the host integer range.');
                }
                $primePower = $primePowerMinusOne + 1;
                for ($power = 1; $power < $exponent; ++$power) {
                    $component = self::checkedIntegerProduct($component, $primePower, 'jordan()');
                }
            }

            $result = self::checkedIntegerProduct($result, $component, 'jordan()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function dedekindPsi(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'dedekindpsi');
        $result = 1;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            $component = $prime + 1;
            for ($power = 1; $power < $exponent; ++$power) {
                $component = self::checkedIntegerProduct($component, $prime, 'dedekindpsi()');
            }
            $result = self::checkedIntegerProduct($result, $component, 'dedekindpsi()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function divisorCount(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'divisorcount');
        $result = 1;
        foreach (self::primeFactorization($number) as $exponent) {
            $result = self::checkedIntegerProduct($result, $exponent + 1, 'divisorcount()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function unitaryDivisorCount(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'unitarydivisorcount');
        $count = 1;
        foreach (self::primeFactorization($number) as $_exponent) {
            $count = self::checkedIntegerProduct($count, 2, 'unitarydivisorcount()');
        }

        return $count;
    }

    /** @param list<int|float> $arguments */
    private static function unitaryDivisorSum(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'unitarydivisorsum');
        $sum = 1;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            $primePower = 1;
            for ($power = 0; $power < $exponent; ++$power) {
                $primePower = self::checkedIntegerProduct($primePower, $prime, 'unitarydivisorsum()');
            }
            $factor = self::checkedIntegerSum($primePower, 1, 'unitarydivisorsum()');
            $sum = self::checkedIntegerProduct($sum, $factor, 'unitarydivisorsum()');
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function unitaryAliquotSum(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'unitaryaliquotsum');

        return self::unitaryDivisorSum([$number]) - $number;
    }

    /** @param list<int|float> $arguments */
    private static function divisorSum(array $arguments): int
    {
        return self::divisorPowerSum($arguments, 'divisorsum');
    }

    /** @param list<int|float> $arguments */
    private static function sigmaFunction(array $arguments): int
    {
        return self::divisorPowerSum($arguments, 'sigma');
    }

    /** @param list<int|float> $arguments */
    private static function divisorPowerSum(array $arguments, string $function): int
    {
        $number = self::numberTheoryInput($arguments[0], $function);
        $powerOrder = self::requireNonNegativeInteger($arguments[1] ?? 1, $function);
        if ($powerOrder > 64) {
            throw new \DomainException($function . '() exponent must be an integer in [0, 64].');
        }

        $result = 1;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            $primePower = 1;
            for ($order = 0; $order < $powerOrder; ++$order) {
                $primePower = self::checkedIntegerProduct($primePower, $prime, $function . '()');
            }
            $power = 1;
            $factor = 1;
            for ($index = 0; $index < $exponent; ++$index) {
                $power = self::checkedIntegerProduct($power, $primePower, $function . '()');
                $factor = self::checkedIntegerSum($factor, $power, $function . '()');
            }
            $result = self::checkedIntegerProduct($result, $factor, $function . '()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function isPrime(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'isprime');
        if ($number === 1) {
            return 0;
        }

        $factors = self::primeFactorization($number);
        return count($factors) === 1 && array_values($factors)[0] === 1 ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function primeCount(array $arguments): int
    {
        $limit = self::requireNonNegativeInteger($arguments[0], 'primecount');
        if ($limit > self::MAX_PRIME_COUNT_INPUT) {
            throw new \DomainException(
                'primecount() supports integer inputs from 0 through ' . self::MAX_PRIME_COUNT_INPUT . '.',
            );
        }
        if ($limit < 2) {
            return 0;
        }
        if ($limit === 2) {
            return 1;
        }

        $oddCandidateCount = intdiv($limit - 1, 2);
        $isPrime = \str_repeat("\1", $oddCandidateCount);
        $primeCount = $oddCandidateCount + 1;

        for ($index = 0; $index < $oddCandidateCount; ++$index) {
            $prime = 2 * $index + 3;
            if ($prime * $prime > $limit) {
                break;
            }
            if ($isPrime[$index] !== "\1") {
                continue;
            }

            for (
                $compositeIndex = intdiv($prime * $prime - 3, 2);
                $compositeIndex < $oddCandidateCount;
                $compositeIndex += $prime
            ) {
                if ($isPrime[$compositeIndex] === "\1") {
                    $isPrime[$compositeIndex] = "\0";
                    --$primeCount;
                }
            }
        }

        return $primeCount;
    }

    /** @param list<int|float> $arguments */
    private static function nthPrime(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'nthprime');
        if ($index < 1 || $index > self::MAX_NTH_PRIME_INDEX) {
            throw new \DomainException(
                'nthprime() supports positive integer indices through ' . self::MAX_NTH_PRIME_INDEX . '.',
            );
        }
        if ($index <= 5) {
            return [2, 3, 5, 7, 11][$index - 1];
        }

        $logIndex = log((float) $index);
        $upperBound = (int) ceil($index * ($logIndex + log($logIndex)));
        $oddCandidateCount = intdiv($upperBound - 1, 2);
        $isPrime = \str_repeat("\1", $oddCandidateCount);
        for ($candidateIndex = 0; $candidateIndex < $oddCandidateCount; ++$candidateIndex) {
            $prime = 2 * $candidateIndex + 3;
            if ($prime > intdiv($upperBound, $prime)) {
                break;
            }
            if ($isPrime[$candidateIndex] !== "\1") {
                continue;
            }
            for (
                $compositeIndex = intdiv($prime * $prime - 3, 2);
                $compositeIndex < $oddCandidateCount;
                $compositeIndex += $prime
            ) {
                $isPrime[$compositeIndex] = "\0";
            }
        }

        $remaining = $index - 2;
        for ($candidateIndex = 0; $candidateIndex < $oddCandidateCount; ++$candidateIndex) {
            if ($isPrime[$candidateIndex] !== "\1") {
                continue;
            }
            if ($remaining === 0) {
                return 2 * $candidateIndex + 3;
            }
            --$remaining;
        }

        throw new \LogicException('nthprime() sieve bound did not include the requested prime.');
    }

    /** @param list<int|float> $arguments */
    private static function nextPrime(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'nextprime');
        if ($number > self::MAX_PRIME_COUNT_INPUT) {
            throw new \DomainException('nextprime() supports integer inputs from 0 through 10000000.');
        }
        if ($number < 2) {
            return 2;
        }

        $candidate = $number + 1;
        if ($candidate > 2 && $candidate % 2 === 0) {
            ++$candidate;
        }
        while (self::isPrime([$candidate]) === 0) {
            $candidate += 2;
        }

        return $candidate;
    }

    /** @param list<int|float> $arguments */
    private static function previousPrime(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'prevprime');
        if ($number > self::MAX_PRIME_COUNT_INPUT) {
            throw new \DomainException('prevprime() supports integer inputs from 0 through 10000000.');
        }
        if ($number <= 2) {
            throw new \DomainException('prevprime() requires an integer greater than two.');
        }

        $candidate = $number - 1;
        if ($candidate % 2 === 0) {
            if ($candidate === 2) {
                return 2;
            }
            --$candidate;
        }
        while (self::isPrime([$candidate]) === 0) {
            $candidate -= 2;
        }

        return $candidate;
    }

    /** @param list<int|float> $arguments */
    private static function goldbachCount(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'goldbachcount');
        if ($number < 4 || $number % 2 !== 0) {
            throw new \DomainException('goldbachcount() requires an even integer of at least four.');
        }
        if ($number > self::MAX_PRIME_COUNT_INPUT) {
            throw new \DomainException('goldbachcount() supports even integer inputs through 10000000.');
        }
        if ($number === 4) {
            return 1;
        }

        $oddCandidateCount = intdiv($number - 1, 2);
        $isPrime = \str_repeat("\1", $oddCandidateCount);
        for ($candidateIndex = 0; $candidateIndex < $oddCandidateCount; ++$candidateIndex) {
            $prime = 2 * $candidateIndex + 3;
            if ($prime > intdiv($number, $prime)) {
                break;
            }
            if ($isPrime[$candidateIndex] !== "\1") {
                continue;
            }
            for (
                $compositeIndex = intdiv($prime * $prime - 3, 2);
                $compositeIndex < $oddCandidateCount;
                $compositeIndex += $prime
            ) {
                $isPrime[$compositeIndex] = "\0";
            }
        }

        $count = 0;
        for ($candidateIndex = 0, $maximum = intdiv($number - 6, 4); $candidateIndex <= $maximum; ++$candidateIndex) {
            if ($isPrime[$candidateIndex] !== "\1") {
                continue;
            }
            $prime = 2 * $candidateIndex + 3;
            $complement = $number - $prime;
            $complementIndex = intdiv($complement - 3, 2);
            if ($isPrime[$complementIndex] === "\1") {
                ++$count;
            }
        }

        return $count;
    }

    /** @param list<int|float> $arguments */
    private static function logarithmicIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logintegral() requires a finite positive argument.');
        }
        if ($value === 1.0) {
            throw new \DomainException('logintegral() is singular at one.');
        }

        return self::exponentialIntegralEi(\log($value), 'logintegral');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialIntegralEiFacade(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('ei() requires a finite argument other than zero.');
        }
        if ($value === 0.0) {
            throw new \DomainException('ei() is singular at zero.');
        }

        return self::exponentialIntegralEi($value, 'ei');
    }

    /** @param list<int|float> $arguments */
    private static function exponentialIntegralEiDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value === 0.0) {
            throw new \DomainException('eiprime() requires a finite argument other than zero.');
        }

        return self::finiteSpecialResult(\exp($value) / $value, 'eiprime');
    }

    /** @param list<int|float> $arguments */
    private static function entireExponentialIntegralDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('einprime() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(-\expm1(-$value) / $value, 'einprime');
    }

    /** @param list<int|float> $arguments */
    private static function entireExponentialIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('ein() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        if (\abs($value) <= 1.0) {
            $term = $value;
            $sum = $term;
            for ($order = 2; $order <= 10000; ++$order) {
                $term *= -$value * ($order - 1.0) / ($order * $order);
                $sum += $term;
                if ($order > \abs($value) && \abs($term) <= max(\abs($sum), 1.0) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult($sum, 'ein');
        }
        if ($value > 0.0) {
            return self::finiteSpecialResult(
                0.5772156649015328606065120900824024 + \log($value)
                    + self::exponentialIntegralE1([$value]),
                'ein',
            );
        }

        return self::finiteSpecialResult(
            0.5772156649015328606065120900824024 + \log(-$value)
                - self::exponentialIntegralEi(-$value, 'ein'),
            'ein',
        );
    }

    /** @param list<int|float> $arguments */
    private static function dilogarithm(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value) || $value > 1.0) {
            throw new \DomainException('dilog() requires a finite real argument less than or equal to one.');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value === 1.0) {
            return M_PI * M_PI / 6.0;
        }
        if ($value < -1.0) {
            $logMagnitude = log(-$value);

            return self::finiteSpecialResult(
                -M_PI * M_PI / 6.0 - 0.5 * $logMagnitude * $logMagnitude
                    - self::dilogarithm([1.0 / $value]),
                'dilog',
            );
        }
        if ($value < 0.0) {
            $transformed = $value / ($value - 1.0);

            return self::finiteSpecialResult(
                -self::dilogarithm([$transformed]) - 0.5 * log1p(-$value) ** 2,
                'dilog',
            );
        }
        if ($value > 0.5) {
            return self::finiteSpecialResult(
                M_PI * M_PI / 6.0 - log($value) * log1p(-$value)
                    - self::dilogarithm([1.0 - $value]),
                'dilog',
            );
        }

        return self::dilogarithmSeries($value);
    }

    private static function dilogarithmSeries(float $value): float
    {
        $sum = 0.0;
        $compensation = 0.0;
        $power = $value;
        for ($order = 1; $order <= 1000; ++$order) {
            $term = $power / ($order * $order);
            $adjusted = $term - $compensation;
            $next = $sum + $adjusted;
            $compensation = ($next - $sum) - $adjusted;
            $sum = $next;
            if (abs($term) <= max(1.0, abs($sum)) * 2.0e-16) {
                break;
            }
            $power *= $value;
        }

        return self::finiteSpecialResult($sum, 'dilog');
    }

    /** @param list<int|float> $arguments */
    private static function polylogarithm(array $arguments): float
    {
        $order = (float) $arguments[0];
        $value = (float) $arguments[1];
        if (!is_finite($order) || !is_finite($value) || $value < -1.0 || $value > 1.0) {
            throw new \DomainException('polylog() requires finite real inputs and an argument in [-1, 1].');
        }
        if ($value === 0.0) {
            return 0.0;
        }
        if ($value === 1.0) {
            if ($order <= 1.0) {
                throw new \DomainException('polylog() at one requires an order greater than one.');
            }

            return self::zetaFunction([$order]);
        }
        if ($value === -1.0) {
            if ($order <= 0.0) {
                throw new \DomainException('polylog() at minus one requires a positive order.');
            }

            return -self::dirichletEtaFunction([$order]);
        }

        $sum = 0.0;
        $compensation = 0.0;
        $term = $value;
        for ($index = 1; $index <= self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $adjusted = $term - $compensation;
            $nextSum = $sum + $adjusted;
            $compensation = ($nextSum - $sum) - $adjusted;
            $sum = $nextSum;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('polylog() result exceeds the finite floating-point range.');
            }

            $nextRatio = $value * (($index / ($index + 1.0)) ** $order);
            $nextTerm = $term * $nextRatio;
            if (abs($nextRatio) < 1.0 && abs($nextTerm) <= max(1.0, abs($sum)) * 2.0e-16) {
                return self::finiteSpecialResult($sum, 'polylog');
            }
            $term = $nextTerm;
        }

        throw new \OverflowException('polylog() series did not converge within the supported iteration limit.');
    }

    /** @param list<int|float> $arguments */
    private static function lerchPhi(array $arguments): float
    {
        $value = (float) $arguments[0];
        $order = (float) $arguments[1];
        $offset = (float) $arguments[2];
        if (
            !is_finite($value) || !is_finite($order) || !is_finite($offset)
            || $value < -1.0 || $value > 1.0 || $offset <= 0.0
        ) {
            throw new \DomainException('lerchphi() requires finite inputs, z in [-1, 1], and a positive offset.');
        }
        if ($value === 1.0) {
            if ($order === 1.0) {
                throw new \DomainException('lerchphi() has a pole at z = 1 and s = 1.');
            }

            return self::hurwitzZetaFunction([$order, $offset]);
        }
        if ($value === -1.0 && $order !== 1.0) {
            $difference = self::hurwitzZetaFunction([$order, $offset / 2.0])
                - self::hurwitzZetaFunction([$order, ($offset + 1.0) / 2.0]);

            return self::finiteSpecialResult(exp(-$order * log(2.0)) * $difference, 'lerchphi');
        }
        if ($value === -1.0) {
            return self::finiteSpecialResult(self::lerchPhiAlternating($order, $offset), 'lerchphi');
        }

        $term = $offset ** (-$order);
        $sum = 0.0;
        $compensation = 0.0;
        for ($index = 0; $index < self::MAX_HYPERGEOMETRIC_TERMS; ++$index) {
            $adjusted = $term - $compensation;
            $nextSum = $sum + $adjusted;
            $compensation = ($nextSum - $sum) - $adjusted;
            $sum = $nextSum;
            if (!is_finite($sum) || !is_finite($term)) {
                throw new \OverflowException('lerchphi() result exceeds the finite floating-point range.');
            }
            if ($value === 0.0) {
                return self::finiteSpecialResult($sum, 'lerchphi');
            }

            $ratio = $value * (($offset + $index) / ($offset + $index + 1.0)) ** $order;
            $nextTerm = $term * $ratio;
            if (abs($ratio) < 1.0 && abs($nextTerm) <= max(1.0, abs($sum)) * 2.0e-16) {
                return self::finiteSpecialResult($sum, 'lerchphi');
            }
            $term = $nextTerm;
        }

        throw new \OverflowException('lerchphi() series did not converge within the supported iteration limit.');
    }

    private static function lerchPhiAlternating(float $order, float $offset): float
    {
        $differences = [];
        for ($index = 0; $index < 128; ++$index) {
            $differences[] = ($offset + $index) ** (-$order);
        }

        $sum = 0.0;
        $compensation = 0.0;
        $divisor = 2.0;
        while ($differences !== []) {
            $term = $differences[0] / $divisor;
            $adjusted = $term - $compensation;
            $nextSum = $sum + $adjusted;
            $compensation = ($nextSum - $sum) - $adjusted;
            $sum = $nextSum;
            if (abs($term) <= max(1.0, abs($sum)) * 2.0e-16) {
                break;
            }

            $nextDifferences = [];
            $count = count($differences) - 1;
            for ($index = 0; $index < $count; ++$index) {
                $nextDifferences[] = $differences[$index] - $differences[$index + 1];
            }
            $differences = $nextDifferences;
            $divisor *= 2.0;
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function sineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('sineintegral() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $sign = $value < 0.0 ? -1.0 : 1.0;
        $magnitude = \abs($value);
        if ($magnitude <= 8.0) {
            $term = $magnitude;
            $sum = $term;
            $compensation = 0.0;
            for ($index = 1; $index <= 1000; ++$index) {
                $odd = 2.0 * $index - 1.0;
                $term *= -$magnitude * $magnitude * $odd / ((2.0 * $index + 1.0) ** 2 * (2.0 * $index));
                $correctedTerm = $term - $compensation;
                $nextSum = $sum + $correctedTerm;
                $compensation = ($nextSum - $sum) - $correctedTerm;
                $sum = $nextSum;
                if (\abs($term) <= \abs($sum) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult($sign * $sum, 'sineintegral');
        }
        if ($magnitude < 32.0) {
            return self::finiteSpecialResult(
                $sign * (self::sineIntegral([8.0]) + self::sineCosineIntegralQuadrature($magnitude, false)),
                'sineintegral',
            );
        }

        [$f, $g] = self::sineCosineIntegralAsymptotic($magnitude);
        $inverse = 1.0 / $magnitude;
        $result = M_PI / 2.0 - \cos($magnitude) * ($inverse * $f)
            - \sin($magnitude) * ($inverse * $inverse * $g);

        return self::finiteSpecialResult($sign * $result, 'sineintegral');
    }

    /** @param list<int|float> $arguments */
    private static function cosineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('cosineintegral() requires a finite positive argument.');
        }
        if ($value <= 8.0) {
            $term = -0.25 * $value * $value;
            $sum = $term;
            $compensation = 0.0;
            for ($index = 2; $index <= 1000; ++$index) {
                $even = 2.0 * $index - 2.0;
                $term *= -$value * $value * $even / ((2.0 * $index) ** 2 * (2.0 * $index - 1.0));
                $correctedTerm = $term - $compensation;
                $nextSum = $sum + $correctedTerm;
                $compensation = ($nextSum - $sum) - $correctedTerm;
                $sum = $nextSum;
                if (\abs($term) <= max(\abs($sum), 1.0) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult(
                0.5772156649015328606065120900824024 + \log($value) + $sum,
                'cosineintegral',
            );
        }
        if ($value < 32.0) {
            return self::finiteSpecialResult(
                self::cosineIntegral([8.0]) + self::sineCosineIntegralQuadrature($value, true),
                'cosineintegral',
            );
        }

        [$f, $g] = self::sineCosineIntegralAsymptotic($value);
        $inverse = 1.0 / $value;
        $result = \sin($value) * ($inverse * $f) - \cos($value) * ($inverse * $inverse * $g);

        return self::finiteSpecialResult($result, 'cosineintegral');
    }

    /** @param list<int|float> $arguments */
    private static function cosineIntegralEntire(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('cin() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $magnitude = \abs($value);
        if ($magnitude >= 8.0) {
            $cosineIntegral = self::cosineIntegral([$magnitude]);
            return self::finiteSpecialResult(
                0.5772156649015328606065120900824024 + \log($magnitude) - $cosineIntegral,
                'cin',
            );
        }

        $term = ($magnitude * $magnitude) / 4.0;
        $sum = $term;
        $compensation = 0.0;
        for ($index = 2; $index <= 10000; ++$index) {
            $even = 2.0 * $index - 2.0;
            $term *= -$magnitude * $magnitude * $even
                / ((2.0 * $index) ** 2 * (2.0 * $index - 1.0));
            $correctedTerm = $term - $compensation;
            $nextSum = $sum + $correctedTerm;
            $compensation = ($nextSum - $sum) - $correctedTerm;
            $sum = $nextSum;
            if (\abs($term) <= max(\abs($sum), 1.0) * 2.0e-16) {
                break;
            }
        }

        return self::finiteSpecialResult($sum, 'cin');
    }

    /** @param list<int|float> $arguments */
    private static function sineIntegralDerivative(array $arguments): float
    {
        return self::sinc([(float) $arguments[0]]);
    }

    /** @param list<int|float> $arguments */
    private static function cosineIntegralDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value <= 0.0) {
            throw new \DomainException('cosineintegralprime() requires a finite positive argument.');
        }

        return self::finiteSpecialResult(\cos($value) / $value, 'cosineintegralprime');
    }

    /** @param list<int|float> $arguments */
    private static function cosineIntegralEntireDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        return self::finiteSpecialResult($value * self::cosineQuotient([$value]), 'cinprime');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSineIntegralDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value === 0.0) {
            return 1.0;
        }

        return self::finiteSpecialResult(\sinh($value) / $value, 'shiprime');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicCosineIntegralDerivative(array $arguments): float
    {
        $value = (float) $arguments[0];
        if ($value === 0.0) {
            throw new \DomainException('chiprime() is singular at zero.');
        }

        return self::finiteSpecialResult(\cosh($value) / $value, 'chiprime');
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicSineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('shi() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        $magnitude = \abs($value);
        if ($magnitude <= 16.0) {
            $term = $magnitude;
            $sum = $term;
            for ($index = 1; $index <= 10000; ++$index) {
                $odd = 2.0 * $index - 1.0;
                $term *= $magnitude * $magnitude * $odd / ((2.0 * $index + 1.0) ** 2 * (2.0 * $index));
                $sum += $term;
                if ($term <= $sum * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult(($value < 0.0 ? -1.0 : 1.0) * $sum, 'shi');
        }

        if ($magnitude > 50.0) {
            return self::finiteSpecialResult(
                ($value < 0.0 ? -1.0 : 1.0) * self::asymptoticExponentialIntegralHalf($magnitude, 'shi'),
                'shi',
            );
        }

        $positiveEi = self::exponentialIntegralEi($magnitude, 'shi');
        $negativeEi = self::exponentialIntegralEi(-$magnitude, 'shi');
        return self::finiteSpecialResult(
            ($value < 0.0 ? -1.0 : 1.0) * (($positiveEi - $negativeEi) / 2.0),
            'shi',
        );
    }

    /** @param list<int|float> $arguments */
    private static function hyperbolicCosineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value === 0.0) {
            throw new \DomainException('chi() requires a finite non-zero argument.');
        }
        $magnitude = \abs($value);

        if ($magnitude <= 16.0) {
            $term = ($magnitude * $magnitude) / 4.0;
            $sum = $term;
            for ($index = 1; $index <= 10000; ++$index) {
                $even = 2.0 * ($index + 1.0);
                $previousEven = $even - 2.0;
                $term *= ($magnitude * $magnitude * $previousEven)
                    / ($even * $even * ($even - 1.0));
                $sum += $term;
                if ($term <= $sum * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult(
                0.5772156649015328606065120900824024 + \log($magnitude) + $sum,
                'chi',
            );
        }

        return self::finiteSpecialResult(
            self::asymptoticExponentialIntegralHalf($magnitude, 'chi'),
            'chi',
        );
    }

    private static function asymptoticExponentialIntegralHalf(float $value, string $function): float
    {
        $term = 1.0;
        $sum = 1.0;
        for ($index = 1; $index <= 10000; ++$index) {
            $nextTerm = $term * ($index / $value);
            if ($nextTerm >= $term) {
                break;
            }
            $sum += $nextTerm;
            $term = $nextTerm;
            if ($term <= $sum * 2.0e-16) {
                break;
            }
        }

        $logResult = $value - \log($value) - \log(2.0) + \log($sum);
        if ($logResult > \log(\PHP_FLOAT_MAX)) {
            throw new \OverflowException($function . '() result exceeds the finite floating-point range.');
        }

        return self::finiteSpecialResult(\exp($logResult), $function);
    }

    private static function sineCosineIntegralQuadrature(float $upper, bool $cosine): float
    {
        $intervalCount = (int) \ceil(($upper - 8.0) / 0.002);
        if ($intervalCount % 2 !== 0) {
            ++$intervalCount;
        }
        $step = ($upper - 8.0) / $intervalCount;
        $sum = 0.0;
        for ($index = 0; $index <= $intervalCount; ++$index) {
            $point = 8.0 + $index * $step;
            $integrand = ($cosine ? \cos($point) : \sin($point)) / $point;
            $weight = $index === 0 || $index === $intervalCount
                ? 1.0
                : ($index % 2 === 0 ? 2.0 : 4.0);
            $sum += $weight * $integrand;
        }

        return $step * $sum / 3.0;
    }

    /** @return array{float, float} */
    private static function sineCosineIntegralAsymptotic(float $value): array
    {
        $inverseSquare = (1.0 / $value) / $value;
        $fTerm = 1.0;
        $f = 1.0;
        $gTerm = 1.0;
        $g = 1.0;
        for ($index = 0; $index < 1000; ++$index) {
            $nextF = -$fTerm * (2.0 * $index + 1.0) * (2.0 * $index + 2.0) * $inverseSquare;
            if (\abs($nextF) >= \abs($fTerm)) {
                break;
            }
            $f += $nextF;
            $fTerm = $nextF;
            if (\abs($fTerm) <= \abs($f) * 2.0e-16) {
                break;
            }
        }
        for ($index = 0; $index < 1000; ++$index) {
            $nextG = -$gTerm * (2.0 * $index + 2.0) * (2.0 * $index + 3.0) * $inverseSquare;
            if (\abs($nextG) >= \abs($gTerm)) {
                break;
            }
            $g += $nextG;
            $gTerm = $nextG;
            if (\abs($gTerm) <= \abs($g) * 2.0e-16) {
                break;
            }
        }

        return [$f, $g];
    }

    /** @param list<int|float> $arguments */
    private static function fresnelCosineIntegralDerivative(array $arguments): float
    {
        return self::fresnelIntegralDerivative($arguments, false, 'fresnelcprime');
    }

    /** @param list<int|float> $arguments */
    private static function fresnelSineIntegralDerivative(array $arguments): float
    {
        return self::fresnelIntegralDerivative($arguments, true, 'fresnelsprime');
    }

    /** @param list<int|float> $arguments */
    private static function fresnelCosineIntegralSecondDerivative(array $arguments): float
    {
        return self::fresnelIntegralSecondDerivative($arguments, false, 'fresnelcsecond');
    }

    /** @param list<int|float> $arguments */
    private static function fresnelSineIntegralSecondDerivative(array $arguments): float
    {
        return self::fresnelIntegralSecondDerivative($arguments, true, 'fresnelssecond');
    }

    /** @param list<int|float> $arguments */
    private static function fresnelIntegralSecondDerivative(
        array $arguments,
        bool $sine,
        string $function,
    ): float {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        $absolute = \abs($value);
        $maximumArgument = \sqrt(\PHP_FLOAT_MAX) * \sqrt(2.0 / \M_PI);
        if ($absolute > $maximumArgument) {
            throw new \OverflowException($function . '() phase exceeds the finite floating-point range.');
        }

        $phase = (\M_PI / 2.0) * ($value * $value);
        $result = $sine ? \M_PI * $value * \cos($phase) : -\M_PI * $value * \sin($phase);

        return self::finiteSpecialResult($result, $function);
    }

    /** @param list<int|float> $arguments */
    private static function fresnelIntegralDerivative(array $arguments, bool $sine, string $function): float
    {
        $value = (float) $arguments[0];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        $absolute = abs($value);
        $maximumArgument = sqrt(PHP_FLOAT_MAX) * sqrt(2.0 / M_PI);
        if ($absolute > $maximumArgument) {
            throw new \OverflowException($function . '() phase exceeds the finite floating-point range.');
        }

        $phase = (M_PI / 2.0) * ($value * $value);
        $result = $sine ? sin($phase) : cos($phase);

        return self::finiteSpecialResult($result, $function);
    }

    /** @param list<int|float> $arguments */
    private static function fresnelCosineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('fresnelc() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        [$cosine] = self::fresnelValues(\abs($value));
        return self::finiteSpecialResult($value < 0.0 ? -$cosine : $cosine, 'fresnelc');
    }

    /** @param list<int|float> $arguments */
    private static function fresnelSineIntegral(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value)) {
            throw new \DomainException('fresnels() requires a finite argument.');
        }
        if ($value === 0.0) {
            return 0.0;
        }

        [, $sine] = self::fresnelValues(\abs($value));
        return self::finiteSpecialResult($value < 0.0 ? -$sine : $sine, 'fresnels');
    }

    /** @return array{float, float} */
    private static function fresnelValues(float $value): array
    {
        if ($value <= 2.0) {
            $cosineTerm = $value;
            $cosine = $cosineTerm;
            $sineTerm = (M_PI / 2.0) * $value * $value * $value / 3.0;
            $sine = $sineTerm;
            for ($index = 0; $index < 1000; ++$index) {
                $cosineTerm *= -(M_PI * M_PI / 4.0) * $value ** 4 * (4.0 * $index + 1.0)
                    / ((4.0 * $index + 5.0) * (2.0 * $index + 1.0) * (2.0 * $index + 2.0));
                $sineTerm *= -(M_PI * M_PI / 4.0) * $value ** 4 * (4.0 * $index + 3.0)
                    / ((4.0 * $index + 7.0) * (2.0 * $index + 2.0) * (2.0 * $index + 3.0));
                $cosine += $cosineTerm;
                $sine += $sineTerm;
                if (
                    \abs($cosineTerm) <= \abs($cosine) * 2.0e-16
                    && \abs($sineTerm) <= \abs($sine) * 2.0e-16
                ) {
                    break;
                }
            }

            return [
                self::finiteSpecialResult($cosine, 'fresnelc'),
                self::finiteSpecialResult($sine, 'fresnels'),
            ];
        }
        if ($value < 8.0) {
            [$baseCosine, $baseSine] = self::fresnelValues(2.0);
            return [
                $baseCosine + self::fresnelQuadrature($value, false),
                $baseSine + self::fresnelQuadrature($value, true),
            ];
        }

        $inverse = 1.0 / $value;
        $inverseSquare = $inverse * $inverse;
        $inverseFourth = $inverseSquare * $inverseSquare;
        $fTerm = 1.0;
        $f = 1.0;
        $gTerm = 1.0;
        $g = 1.0;
        for ($index = 0; $index < 1000; ++$index) {
            $nextF = -$fTerm * (4.0 * $index + 1.0) * (4.0 * $index + 3.0)
                * $inverseFourth / (M_PI * M_PI);
            if (\abs($nextF) >= \abs($fTerm)) {
                break;
            }
            $f += $nextF;
            $fTerm = $nextF;
            $nextG = -$gTerm * (4.0 * $index + 3.0) * (4.0 * $index + 5.0)
                * $inverseFourth / (M_PI * M_PI);
            if (\abs($nextG) >= \abs($gTerm)) {
                break;
            }
            $g += $nextG;
            $gTerm = $nextG;
            if (\abs($fTerm) <= \abs($f) * 2.0e-16 && \abs($gTerm) <= \abs($g) * 2.0e-16) {
                break;
            }
        }

        $reducedValue = \fmod($value, 4.0);
        $phase = (M_PI / 2.0) * \fmod($reducedValue * $reducedValue, 4.0);
        $sinePhase = \sin($phase);
        $cosinePhase = \cos($phase);
        $f *= $inverse / M_PI;
        $g *= $inverse * $inverse * $inverse / (M_PI * M_PI);

        return [
            self::finiteSpecialResult(0.5 + $f * $sinePhase - $g * $cosinePhase, 'fresnelc'),
            self::finiteSpecialResult(0.5 - $f * $cosinePhase - $g * $sinePhase, 'fresnels'),
        ];
    }

    private static function fresnelQuadrature(float $upper, bool $sine): float
    {
        $intervalCount = (int) \ceil(($upper - 2.0) / 0.0002);
        if ($intervalCount % 2 !== 0) {
            ++$intervalCount;
        }
        $step = ($upper - 2.0) / $intervalCount;
        $sum = 0.0;
        for ($index = 0; $index <= $intervalCount; ++$index) {
            $point = 2.0 + $index * $step;
            $phase = (M_PI / 2.0) * $point * $point;
            $integrand = $sine ? \sin($phase) : \cos($phase);
            $weight = $index === 0 || $index === $intervalCount
                ? 1.0
                : ($index % 2 === 0 ? 2.0 : 4.0);
            $sum += $weight * $integrand;
        }

        return $step * $sum / 3.0;
    }

    /** @param list<int|float> $arguments */
    private static function exponentialIntegralE1(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('expint1() requires a finite positive argument.');
        }

        if ($value <= 1.0) {
            $eulerMascheroni = 0.5772156649015328606065120900824024;
            $term = -$value;
            $sum = $term;
            for ($order = 2; $order <= 10000; ++$order) {
                $term *= -$value * ($order - 1.0) / ($order * $order);
                $sum += $term;
                if ($order > $value && \abs($term) <= max(\abs($sum), 1.0) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult(-$eulerMascheroni - \log($value) - $sum, 'expint1');
        }

        $b = $value + 1.0;
        $c = 1.0e300;
        $d = 1.0 / $b;
        $continuedFraction = $d;
        for ($iteration = 1; $iteration <= 10000; ++$iteration) {
            $coefficient = -(float) ($iteration * $iteration);
            $b += 2.0;
            $d = $coefficient * $d + $b;
            if (\abs($d) < 1.0e-300) {
                $d = 1.0e-300;
            }
            $d = 1.0 / $d;
            $c = $b + $coefficient / $c;
            if (\abs($c) < 1.0e-300) {
                $c = 1.0e-300;
            }
            $delta = $c * $d;
            $continuedFraction *= $delta;
            if (\abs($delta - 1.0) <= 2.0e-15) {
                break;
            }
        }

        return self::finiteSpecialResult(\exp(-$value) * $continuedFraction, 'expint1');
    }

    /** @param list<int|float> $arguments */
    private static function logExponentialIntegralE1(array $arguments): float
    {
        $value = (float) $arguments[0];
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logexpint1() requires a finite positive argument.');
        }
        if ($value <= 1.0) {
            return self::finiteSpecialResult(\log(self::exponentialIntegralE1([$value])), 'logexpint1');
        }

        $b = $value + 1.0;
        $c = 1.0e300;
        $d = 1.0 / $b;
        $fraction = $d;
        for ($iteration = 1; $iteration <= 10000; ++$iteration) {
            $coefficient = -(float) ($iteration * $iteration);
            $b += 2.0;
            $d = $coefficient * $d + $b;
            if (\abs($d) < 1.0e-300) {
                $d = 1.0e-300;
            }
            $d = 1.0 / $d;
            $c = $b + $coefficient / $c;
            if (\abs($c) < 1.0e-300) {
                $c = 1.0e-300;
            }
            $delta = $c * $d;
            $fraction *= $delta;
            if (\abs($delta - 1.0) <= 2.0e-15) {
                break;
            }
        }

        return self::finiteSpecialResult(-$value + \log($fraction), 'logexpint1');
    }

    /** @param list<int|float> $arguments */
    private static function generalizedExponentialIntegral(array $arguments): float
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'expint');
        $value = (float) $arguments[1];
        if ($order < 1 || $order > 64) {
            throw new \DomainException('expint() order must be an integer in [1, 64].');
        }
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('expint() requires a finite positive argument.');
        }
        if ($order === 1) {
            return self::exponentialIntegralE1([$value]);
        }

        if ($value <= 1.0) {
            $result = self::exponentialIntegralE1([$value]);
            for ($currentOrder = 2; $currentOrder <= $order; ++$currentOrder) {
                $result = (\exp(-$value) - $value * $result) / ($currentOrder - 1.0);
            }

            return self::finiteSpecialResult($result, 'expint');
        }

        // Continued fraction for E_n(x), avoiding cancellation in upward recurrence.
        $b = $value + $order;
        $c = 1.0e300;
        $d = 1.0 / $b;
        $fraction = $d;
        for ($iteration = 1; $iteration <= 10000; ++$iteration) {
            $a = -(float) ($iteration * ($order - 1 + $iteration));
            $b += 2.0;
            $d = $a * $d + $b;
            if (\abs($d) < 1.0e-300) {
                $d = 1.0e-300;
            }
            $d = 1.0 / $d;
            $c = $b + $a / $c;
            if (\abs($c) < 1.0e-300) {
                $c = 1.0e-300;
            }
            $delta = $c * $d;
            $fraction *= $delta;
            if (\abs($delta - 1.0) <= 2.0e-15) {
                break;
            }
        }

        return self::finiteSpecialResult(\exp(-$value) * $fraction, 'expint');
    }

    /** @param list<int|float> $arguments */
    private static function logGeneralizedExponentialIntegral(array $arguments): float
    {
        $order = self::requireNonNegativeInteger($arguments[0], 'logexpint');
        $value = (float) $arguments[1];
        if ($order < 1 || $order > 64) {
            throw new \DomainException('logexpint() order must be an integer in [1, 64].');
        }
        if (!\is_finite($value) || $value <= 0.0) {
            throw new \DomainException('logexpint() requires a finite positive argument.');
        }
        if ($order === 1) {
            return self::logExponentialIntegralE1([$value]);
        }
        if ($value <= 1.0) {
            return self::finiteSpecialResult(\log(self::generalizedExponentialIntegral([$order, $value])), 'logexpint');
        }

        $b = $value + $order;
        $c = 1.0e300;
        $d = 1.0 / $b;
        $fraction = $d;
        for ($iteration = 1; $iteration <= 10000; ++$iteration) {
            $coefficient = -(float) ($iteration * ($order - 1 + $iteration));
            $b += 2.0;
            $d = $coefficient * $d + $b;
            if (\abs($d) < 1.0e-300) {
                $d = 1.0e-300;
            }
            $d = 1.0 / $d;
            $c = $b + $coefficient / $c;
            if (\abs($c) < 1.0e-300) {
                $c = 1.0e-300;
            }
            $delta = $c * $d;
            $fraction *= $delta;
            if (\abs($delta - 1.0) <= 2.0e-15) {
                break;
            }
        }

        return self::finiteSpecialResult(-$value + \log($fraction), 'logexpint');
    }

    private static function exponentialIntegralEi(float $value, string $function): float
    {
        $eulerMascheroni = 0.5772156649015328606065120900824024;
        if ($value > 0.0) {
            $term = $value;
            $sum = $term;
            for ($order = 2; $order <= 10000; ++$order) {
                $term *= $value * ($order - 1.0) / ($order * $order);
                $sum += $term;
                if (!\is_finite($sum)) {
                    throw new \OverflowException($function . '() result exceeds the finite floating-point range.');
                }
                if ($order > $value && $term <= $sum * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult($eulerMascheroni + \log($value) + $sum, $function);
        }

        $magnitude = -$value;
        if ($magnitude <= 1.0) {
            $term = -$magnitude;
            $sum = $term;
            for ($order = 2; $order <= 10000; ++$order) {
                $term *= -$magnitude * ($order - 1.0) / ($order * $order);
                $sum += $term;
                if ($order > $magnitude && \abs($term) <= \max(\abs($sum), 1.0) * 2.0e-16) {
                    break;
                }
            }

            return self::finiteSpecialResult($eulerMascheroni + \log($magnitude) + $sum, $function);
        }

        $b = $magnitude + 1.0;
        $c = 1.0e300;
        $d = 1.0 / $b;
        $continuedFraction = $d;
        for ($iteration = 1; $iteration <= 10000; ++$iteration) {
            $coefficient = -(float) ($iteration * $iteration);
            $b += 2.0;
            $d = $coefficient * $d + $b;
            if (\abs($d) < 1.0e-300) {
                $d = 1.0e-300;
            }
            $d = 1.0 / $d;
            $c = $b + $coefficient / $c;
            if (\abs($c) < 1.0e-300) {
                $c = 1.0e-300;
            }
            $delta = $c * $d;
            $continuedFraction *= $delta;
            if (\abs($delta - 1.0) <= 2.0e-15) {
                break;
            }
        }

        return self::finiteSpecialResult(-\exp(-$magnitude) * $continuedFraction, $function);
    }

    /** @param list<int|float> $arguments */
    private static function isComposite(array $arguments): int
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'iscomposite'));
        if (count($factors) > 1) {
            return 1;
        }

        return ($factors !== [] && array_values($factors)[0] > 1) ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isPrimePower(array $arguments): int
    {
        return count(self::primeFactorization(self::numberTheoryInput($arguments[0], 'isprimepower'))) === 1
            ? 1
            : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isPerfectPower(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'isperfectpower');
        if ($number === 1) {
            return 0;
        }

        $factors = self::primeFactorization($number);
        if (isset($arguments[1])) {
            $exponent = self::requireNonNegativeInteger($arguments[1], 'isperfectpower');
            if ($exponent < 2 || $exponent > 64) {
                throw new \DomainException('isperfectpower() exponent must be an integer in [2, 64].');
            }

            foreach ($factors as $factorExponent) {
                if ($factorExponent % $exponent !== 0) {
                    return 0;
                }
            }

            return 1;
        }

        $commonExponent = 0;
        foreach ($factors as $factorExponent) {
            $commonExponent = self::greatestCommonDivisor([$commonExponent, $factorExponent]);
        }

        return $commonExponent > 1 ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isSemiprime(array $arguments): int
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'issemiprime'));

        return array_sum($factors) === 2 ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isCarmichaelNumber(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'iscarmichael');
        $factors = self::primeFactorization($number);
        if (count($factors) < 2) {
            return 0;
        }

        foreach ($factors as $prime => $exponent) {
            if ($exponent !== 1 || ($number - 1) % ($prime - 1) !== 0) {
                return 0;
            }
        }

        return 1;
    }

    /** @param list<int|float> $arguments */
    private static function isPowerful(array $arguments): int
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'ispowerful'));
        foreach ($factors as $exponent) {
            if ($exponent < 2) {
                return 0;
            }
        }

        return 1;
    }

    /** @param list<int|float> $arguments */
    private static function mobiusFunction(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'mobius');
        $sign = 1;
        foreach (self::primeFactorization($number) as $exponent) {
            if ($exponent > 1) {
                return 0;
            }
            $sign = -$sign;
        }

        return $sign;
    }

    /** @param list<int|float> $arguments */
    private static function mertensFunction(array $arguments): int
    {
        $limit = self::requireNonNegativeInteger($arguments[0], 'mertens');
        if ($limit > 10_000_000) {
            throw new \DomainException('mertens() supports integer inputs from 0 through 10000000.');
        }

        $mobius = \str_repeat("\x01", $limit + 1);
        $primeSieve = \str_repeat("\x01", $limit + 1);
        $mobius[0] = "\x00";
        $primeSieve[0] = "\x00";
        if ($limit >= 1) {
            $primeSieve[1] = "\x00";
        }

        for ($prime = 2; $prime * $prime <= $limit; ++$prime) {
            if ($primeSieve[$prime] !== "\x01") {
                continue;
            }
            for ($composite = $prime * $prime; $composite <= $limit; $composite += $prime) {
                $primeSieve[$composite] = "\x00";
            }
        }

        for ($prime = 2; $prime <= $limit; ++$prime) {
            if ($primeSieve[$prime] !== "\x01") {
                continue;
            }
            for ($multiple = $prime; $multiple <= $limit; $multiple += $prime) {
                if ($mobius[$multiple] === "\x01") {
                    $mobius[$multiple] = "\xFF";
                } elseif ($mobius[$multiple] === "\xFF") {
                    $mobius[$multiple] = "\x01";
                }
            }
            $square = $prime * $prime;
            for ($multiple = $square; $multiple <= $limit; $multiple += $square) {
                $mobius[$multiple] = "\x00";
            }
        }

        $sum = 0;
        for ($number = 1; $number <= $limit; ++$number) {
            if ($mobius[$number] === "\x01") {
                ++$sum;
            } elseif ($mobius[$number] === "\xFF") {
                --$sum;
            }
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function isSquareFree(array $arguments): int
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'issquarefree'));
        foreach ($factors as $exponent) {
            if ($exponent > 1) {
                return 0;
            }
        }

        return 1;
    }

    /** @param list<int|float> $arguments */
    private static function liouvilleFunction(array $arguments): int
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'liouville'));
        $totalMultiplicity = array_sum($factors);

        return $totalMultiplicity % 2 === 0 ? 1 : -1;
    }

    /** @param list<int|float> $arguments */
    private static function primeFactorCount(array $arguments): int
    {
        return count(self::primeFactorization(self::numberTheoryInput($arguments[0], 'omega')));
    }

    /** @param list<int|float> $arguments */
    private static function primeFactorMultiplicity(array $arguments): int
    {
        return array_sum(self::primeFactorization(self::numberTheoryInput($arguments[0], 'bigomega')));
    }

    /** @param list<int|float> $arguments */
    private static function vonMangoldt(array $arguments): float
    {
        $factors = self::primeFactorization(self::numberTheoryInput($arguments[0], 'vonmangoldt'));
        if (count($factors) !== 1) {
            return 0.0;
        }

        $prime = array_key_first($factors);
        return \log((float) $prime);
    }

    /** @param list<int|float> $arguments */
    private static function squareFreeKernel(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'radical');
        $result = 1;
        foreach (array_keys(self::primeFactorization($number)) as $prime) {
            $result = self::checkedIntegerProduct($result, $prime, 'radical()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function arithmeticDerivative(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'arithderivative');
        $derivative = 0;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            $term = self::checkedIntegerProduct(
                intdiv($number, $prime),
                $exponent,
                'arithderivative()',
            );
            $derivative = self::checkedIntegerSum($derivative, $term, 'arithderivative()');
        }

        return $derivative;
    }

    /** @param list<int|float> $arguments */
    private static function primorial(array $arguments): int
    {
        $limit = self::requireNonNegativeInteger($arguments[0], 'primorial');
        $result = 1;
        for ($candidate = 2; $candidate <= $limit; ++$candidate) {
            $factors = self::primeFactorization($candidate);
            if (count($factors) === 1 && array_values($factors)[0] === 1) {
                $result = self::checkedIntegerProduct($result, $candidate, 'primorial()');
            }
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function carmichaelFunction(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'carmichael');
        if ($number === 1) {
            return 1;
        }

        $result = 1;
        foreach (self::primeFactorization($number) as $prime => $exponent) {
            if ($prime === 2) {
                $component = match (true) {
                    $exponent === 1 => 1,
                    $exponent === 2 => 2,
                    default => 1 << ($exponent - 2),
                };
            } else {
                $component = $prime - 1;
                for ($power = 1; $power < $exponent; ++$power) {
                    $component = self::checkedIntegerProduct($component, $prime, 'carmichael()');
                }
            }

            $result = self::leastCommonMultiple([$result, $component]);
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function aliquotSum(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'aliquotsum');
        return self::divisorPowerSum([$number, 1], 'aliquotsum') - $number;
    }

    /** @param list<int|float> $arguments */
    private static function isPerfectNumber(array $arguments): int
    {
        return self::classifyAliquotSum($arguments, 'perfect');
    }

    /** @param list<int|float> $arguments */
    private static function isAbundantNumber(array $arguments): int
    {
        return self::classifyAliquotSum($arguments, 'abundant');
    }

    /** @param list<int|float> $arguments */
    private static function isDeficientNumber(array $arguments): int
    {
        return self::classifyAliquotSum($arguments, 'deficient');
    }

    /** @param list<int|float> $arguments */
    private static function areAmicableNumbers(array $arguments): int
    {
        $left = self::numberTheoryInput($arguments[0], 'isamicable');
        $right = self::numberTheoryInput($arguments[1], 'isamicable');
        if ($left === $right) {
            return 0;
        }

        return self::aliquotSum([$left]) === $right && self::aliquotSum([$right]) === $left ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isSociableNumber(array $arguments): int
    {
        $start = self::numberTheoryInput($arguments[0], 'issociable');
        $length = self::requireNonNegativeInteger($arguments[1], 'issociable');
        if ($length < 1 || $length > 1000) {
            throw new \DomainException('issociable() cycle length must be an integer in [1, 1000].');
        }

        $visited = [$start => true];
        $current = $start;
        for ($step = 1; $step <= $length; ++$step) {
            $current = self::divisorPowerSum([$current, 1], 'issociable') - $current;
            if ($step === $length) {
                return $current === $start ? 1 : 0;
            }
            if ($current < 1 || $current > self::MAX_NUMBER_THEORY_INPUT || isset($visited[$current])) {
                return 0;
            }
            $visited[$current] = true;
        }

        return 0;
    }

    /**
     * @param list<int|float> $arguments
     * @param 'perfect'|'abundant'|'deficient' $classification
     */
    private static function classifyAliquotSum(array $arguments, string $classification): int
    {
        $number = self::numberTheoryInput($arguments[0], 'is' . $classification);
        $properDivisorSum = self::divisorPowerSum([$number, 1], 'is' . $classification) - $number;

        return (int) match ($classification) {
            'perfect' => $properDivisorSum === $number,
            'abundant' => $properDivisorSum > $number,
            'deficient' => $properDivisorSum < $number,
        };
    }

    private static function numberTheoryInput(int|float $value, string $function): int
    {
        $number = self::requireNonNegativeInteger($value, $function);
        if ($number < 1 || $number > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                $function . '() requires a positive integer no greater than ' . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        return $number;
    }

    /** @param list<int|float> $arguments */
    private static function digitSum(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'digitsum');
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'digitsum');
        $sum = 0;
        while ($number > 0) {
            $sum += $number % $base;
            $number = intdiv($number, $base);
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function digitProduct(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'digitproduct');
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'digitproduct');
        if ($number === 0) {
            return 0;
        }

        $product = 1;
        while ($number > 0) {
            $product = self::checkedIntegerProduct($product, $number % $base, 'digitproduct()');
            $number = intdiv($number, $base);
        }

        return $product;
    }

    /** @param list<int|float> $arguments */
    private static function digitalRoot(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'digitalroot');
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'digitalroot');
        if ($number === 0) {
            return 0;
        }

        return 1 + (($number - 1) % ($base - 1));
    }

    /** @param list<int|float> $arguments */
    private static function additivePersistence(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'additivepersistence');
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'additivepersistence');
        $steps = 0;
        while ($number >= $base) {
            $number = self::digitSum([$number, $base]);
            ++$steps;
        }

        return $steps;
    }

    /** @param list<int|float> $arguments */
    private static function multiplicativePersistence(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'multiplicativepersistence');
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'multiplicativepersistence');
        $steps = 0;
        while ($number >= $base) {
            $number = self::digitProduct([$number, $base]);
            ++$steps;
        }

        return $steps;
    }

    /** @param list<int|float> $arguments */
    private static function isHarshadNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'isharshad');
        if ($number === 0) {
            throw new \DomainException('isharshad() requires a positive integer.');
        }
        $base = self::digitArithmeticBase($arguments[1] ?? 10, 'isharshad');
        $remaining = $number;
        $sum = 0;
        while ($remaining > 0) {
            $sum += $remaining % $base;
            $remaining = intdiv($remaining, $base);
        }

        return $number % $sum === 0 ? 1 : 0;
    }

    /** @param list<int|float> $arguments */
    private static function isHappyNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'ishappy');
        if ($number > self::MAX_NUMBER_THEORY_INPUT) {
            throw new \DomainException(
                'ishappy() requires a non-negative integer no greater than ' . self::MAX_NUMBER_THEORY_INPUT . '.',
            );
        }

        $slow = $number;
        $fast = $number;
        do {
            $slow = self::sumSquaredDecimalDigits($slow);
            $fast = self::sumSquaredDecimalDigits(self::sumSquaredDecimalDigits($fast));
        } while ($slow !== $fast);

        return $slow === 1 ? 1 : 0;
    }

    private static function sumSquaredDecimalDigits(int $number): int
    {
        $sum = 0;
        while ($number > 0) {
            $digit = $number % 10;
            $sum += $digit * $digit;
            $number = intdiv($number, 10);
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function isSmithNumber(array $arguments): int
    {
        $number = self::numberTheoryInput($arguments[0], 'issmith');
        if ($number < 4) {
            return 0;
        }

        $factorization = self::primeFactorization($number);
        if (count($factorization) === 1 && reset($factorization) === 1) {
            return 0;
        }

        $factorDigitSum = 0;
        foreach ($factorization as $prime => $multiplicity) {
            $factorDigitSum += self::digitSum([$prime]) * $multiplicity;
        }

        return self::digitSum([$number]) === $factorDigitSum ? 1 : 0;
    }

    private static function digitArithmeticBase(int|float $value, string $function): int
    {
        $base = self::requireNonNegativeInteger($value, $function);
        if ($base < 2 || $base > 36) {
            throw new \DomainException($function . '() base must be an integer in [2, 36].');
        }

        return $base;
    }

    /** @return array<int, int> prime => exponent */
    private static function primeFactorization(int $number): array
    {
        $factors = [];
        for ($prime = 2; $prime <= intdiv($number, $prime); $prime += ($prime === 2 ? 1 : 2)) {
            if ($number % $prime !== 0) {
                continue;
            }

            $exponent = 0;
            do {
                $number = intdiv($number, $prime);
                ++$exponent;
            } while ($number % $prime === 0);
            $factors[$prime] = $exponent;
        }
        if ($number > 1) {
            $factors[$number] = 1;
        }

        return $factors;
    }

    /** @param list<int|float> $arguments */
    private static function factorialFunction(array $arguments): int
    {
        $operand = self::requireNonNegativeInteger($arguments[0], 'factorial');

        return self::factorialValue($operand, 'factorial');
    }

    /** @param list<int|float> $arguments */
    private static function logFactorial(array $arguments): float
    {
        $operand = self::requireNonNegativeInteger($arguments[0], 'logfactorial');

        return self::finiteSpecialResult(self::logGammaPositive((float) $operand + 1.0), 'logfactorial');
    }

    /** @param list<int|float> $arguments */
    private static function logBinomial(array $arguments): float
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'logbinomial');
        $k = self::requireNonNegativeInteger($arguments[1], 'logbinomial');
        if ($k > $n) {
            throw new \DomainException('logbinomial() requires k to be less than or equal to n.');
        }
        $k = min($k, $n - $k);

        return self::finiteSpecialResult(
            self::logFallingProduct($n - $k + 1, $k) - self::logFactorial([$k]),
            'logbinomial',
        );
    }

    /** @param list<int|float> $arguments */
    private static function logPermutation(array $arguments): float
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'logpermutation');
        $k = self::requireNonNegativeInteger($arguments[1], 'logpermutation');
        if ($k > $n) {
            throw new \DomainException('logpermutation() requires k to be less than or equal to n.');
        }

        return self::finiteSpecialResult(self::logFallingProduct($n - $k + 1, $k), 'logpermutation');
    }

    private static function logFallingProduct(int $firstFactor, int $count): float
    {
        if ($count === 0) {
            return 0.0;
        }

        if ($count <= 10_000) {
            $logarithm = 0.0;
            for ($offset = 0; $offset < $count; ++$offset) {
                $logarithm += log((float) ($firstFactor + $offset));
            }

            return $logarithm;
        }

        return self::logGammaPositive((float) $firstFactor + (float) $count)
            - self::logGammaPositive((float) $firstFactor);
    }

    /** @param list<int|float> $arguments */
    private static function harmonicNumber(array $arguments): float
    {
        $index = (float) $arguments[0];
        if (!is_finite($index) || $index < 0.0) {
            throw new \DomainException('harmonicnumber() requires a finite non-negative real index.');
        }
        if ($index > self::MAX_HARMONIC_NUMBER_INDEX) {
            throw new \DomainException('harmonicnumber() index must not exceed 1000000.');
        }
        $order = (float) ($arguments[1] ?? 1.0);
        if (!\is_finite($order) || $order <= 0.0) {
            throw new \DomainException('harmonicnumber() requires a finite positive order.');
        }
        if (floor($index) !== $index) {
            if ($order === 1.0) {
                return self::finiteSpecialResult(
                    self::digammaFunction([$index + 1.0]) + 0.5772156649015328606065120900824024,
                    'harmonicnumber',
                );
            }

            return self::finiteSpecialResult(
                self::zetaFunction([$order]) - self::hurwitzZetaFunction([$order, $index + 1.0]),
                'harmonicnumber',
            );
        }

        $sum = 0.0;
        $compensation = 0.0;
        for ($denominator = 1; $denominator <= (int) $index; ++$denominator) {
            $term = \pow((float) $denominator, -$order);
            $adjusted = $term - $compensation;
            $next = $sum + $adjusted;
            $compensation = ($next - $sum) - $adjusted;
            $sum = $next;
        }

        return self::finiteSpecialResult($sum, 'harmonicnumber');
    }

    /** @param list<int|float> $arguments */
    private static function legendrePolynomial(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'legendrepoly');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('legendrepoly() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!\is_finite($value)) {
            throw new \DomainException('legendrepoly() requires a finite argument.');
        }
        if ($degree === 0 || $value === 1.0) {
            return 1.0;
        }
        if ($value === -1.0) {
            return $degree % 2 === 0 ? 1.0 : -1.0;
        }

        $previousPrevious = 1.0;
        $previous = $value;
        for ($order = 2; $order <= $degree; ++$order) {
            $leadingTerm = (2 * $order - 1) * $value * $previous;
            $trailingTerm = ($order - 1) * $previousPrevious;
            $current = ($leadingTerm - $trailingTerm) / $order;
            self::finiteSpecialResult($current, 'legendrepoly');
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function associatedLegendrePolynomial(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'associatedlegendre');
        $order = self::requireNonNegativeInteger($arguments[1], 'associatedlegendre');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('associatedlegendre() degree must not exceed 10000.');
        }
        if ($order > $degree) {
            throw new \DomainException('associatedlegendre() requires order m no greater than degree n.');
        }
        $value = (float) $arguments[2];
        if (!is_finite($value) || $value < -1.0 || $value > 1.0) {
            throw new \DomainException('associatedlegendre() requires a finite argument in [-1, 1].');
        }
        if ($order === 0) {
            return self::legendrePolynomial([$degree, $value]);
        }
        if (abs($value) === 1.0) {
            return 0.0;
        }

        // Condon–Shortley convention: P_m^m(x) = (-1)^m (2m-1)!! (1-x²)^(m/2).
        $root = sqrt((1.0 - $value) * (1.0 + $value));
        $diagonal = 1.0;
        for ($index = 1; $index <= $order; ++$index) {
            $diagonal *= -(2.0 * $index - 1.0) * $root;
            self::finiteSpecialResult($diagonal, 'associatedlegendre');
        }
        if ($degree === $order) {
            return $diagonal;
        }

        $previousPrevious = $diagonal;
        $previous = (2.0 * $order + 1.0) * $value * $diagonal;
        self::finiteSpecialResult($previous, 'associatedlegendre');
        if ($degree === $order + 1) {
            return $previous;
        }
        for ($currentDegree = $order + 2; $currentDegree <= $degree; ++$currentDegree) {
            $current = ((2.0 * $currentDegree - 1.0) * $value * $previous
                    - ($currentDegree + $order - 1.0) * $previousPrevious)
                / ($currentDegree - $order);
            self::finiteSpecialResult($current, 'associatedlegendre');
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function associatedLegendreDerivative(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'associatedlegendreprime');
        $order = self::requireNonNegativeInteger($arguments[1], 'associatedlegendreprime');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('associatedlegendreprime() degree must not exceed 10000.');
        }
        if ($order > $degree) {
            throw new \DomainException('associatedlegendreprime() requires order m no greater than degree n.');
        }
        $value = (float) $arguments[2];
        if (!is_finite($value) || $value < -1.0 || $value > 1.0) {
            throw new \DomainException('associatedlegendreprime() requires a finite argument in [-1, 1].');
        }
        if ($order === 0) {
            return self::legendrePolynomialDerivative([$degree, $value]);
        }
        if (abs($value) === 1.0) {
            if ($order === 1) {
                throw new \DomainException('associatedlegendreprime() is singular at the endpoints for order one.');
            }
            if ($order > 2) {
                return 0.0;
            }

            $secondDerivative = self::legendrePolynomialSecondDerivative([$degree, $value]);
            return $value > 0.0 ? -2.0 * $secondDerivative : 2.0 * $secondDerivative;
        }

        $root = sqrt((1.0 - $value) * (1.0 + $value));
        $diagonal = 1.0;
        for ($index = 1; $index <= $order; ++$index) {
            $diagonal *= -(2.0 * $index - 1.0) * $root;
        }
        $diagonalDerivative = -$order * $value * $diagonal / (1.0 - $value * $value);
        if ($degree === $order) {
            return self::finiteSpecialResult($diagonalDerivative, 'associatedlegendreprime');
        }

        $previousPrevious = $diagonal;
        $derivativePreviousPrevious = $diagonalDerivative;
        $previous = (2.0 * $order + 1.0) * $value * $diagonal;
        $derivativePrevious = (2.0 * $order + 1.0) * ($diagonal + $value * $diagonalDerivative);
        if ($degree === $order + 1) {
            return self::finiteSpecialResult($derivativePrevious, 'associatedlegendreprime');
        }
        for ($currentDegree = $order + 2; $currentDegree <= $degree; ++$currentDegree) {
            $factor = 2.0 * $currentDegree - 1.0;
            $trailing = $currentDegree + $order - 1.0;
            $divisor = $currentDegree - $order;
            $current = ($factor * $value * $previous - $trailing * $previousPrevious) / $divisor;
            $derivativeCurrent = (
                $factor * ($previous + $value * $derivativePrevious)
                - $trailing * $derivativePreviousPrevious
            ) / $divisor;
            self::finiteSpecialResult($current, 'associatedlegendreprime');
            self::finiteSpecialResult($derivativeCurrent, 'associatedlegendreprime');
            $previousPrevious = $previous;
            $previous = $current;
            $derivativePreviousPrevious = $derivativePrevious;
            $derivativePrevious = $derivativeCurrent;
        }

        return $derivativePrevious;
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevFirstKind(array $arguments): float
    {
        return self::chebyshevPolynomial($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevSecondKind(array $arguments): float
    {
        return self::chebyshevPolynomial($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdKind(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKind($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevFourthKind(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKind($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdKindDerivative(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKindDerivative($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevFourthKindDerivative(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKindDerivative($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdKindSecondDerivative(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKindSecondDerivative($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevFourthKindSecondDerivative(array $arguments): float
    {
        return self::chebyshevThirdOrFourthKindSecondDerivative($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdOrFourthKind(array $arguments, bool $fourthKind): float
    {
        $function = $fourthKind ? 'chebyshevw' : 'chebyshevv';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }
        if ($value === 1.0) {
            return $fourthKind ? (float) (2 * $degree + 1) : 1.0;
        }
        if ($value === -1.0) {
            if ($fourthKind) {
                return $degree % 2 === 0 ? 1.0 : -1.0;
            }

            $endpoint = (float) (2 * $degree + 1);
            return $degree % 2 === 0 ? $endpoint : -$endpoint;
        }

        $previousPrevious = 1.0;
        $previous = 2.0 * $value + ($fourthKind ? 1.0 : -1.0);
        if ($degree === 1) {
            return self::finiteSpecialResult($previous, $function);
        }
        for ($order = 2; $order <= $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            self::finiteSpecialResult($current, $function);
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdOrFourthKindDerivative(array $arguments, bool $fourthKind): float
    {
        $function = $fourthKind ? 'chebyshevwprime' : 'chebyshevvprime';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = 2.0 * $value + ($fourthKind ? 1.0 : -1.0);
        $derivativePreviousPrevious = 0.0;
        $derivativePrevious = 2.0;
        if ($degree === 1) {
            return self::finiteSpecialResult($derivativePrevious, $function);
        }
        for ($order = 2; $order <= $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            $derivativeCurrent = 2.0 * ($previous + $value * $derivativePrevious)
                - $derivativePreviousPrevious;
            self::finiteSpecialResult($current, $function);
            self::finiteSpecialResult($derivativeCurrent, $function);
            $previousPrevious = $previous;
            $previous = $current;
            $derivativePreviousPrevious = $derivativePrevious;
            $derivativePrevious = $derivativeCurrent;
        }

        return $derivativePrevious;
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevThirdOrFourthKindSecondDerivative(array $arguments, bool $fourthKind): float
    {
        $function = $fourthKind ? 'chebyshevwsecond' : 'chebyshevvsecond';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree < 2) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = 2.0 * $value + ($fourthKind ? 1.0 : -1.0);
        $firstDerivativePreviousPrevious = 0.0;
        $firstDerivativePrevious = 2.0;
        $secondDerivativePreviousPrevious = 0.0;
        $secondDerivativePrevious = 0.0;
        for ($order = 2; $order <= $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            $firstDerivativeCurrent = 2.0 * ($previous + $value * $firstDerivativePrevious)
                - $firstDerivativePreviousPrevious;
            $secondDerivativeCurrent = 2.0 * (
                2.0 * $firstDerivativePrevious + $value * $secondDerivativePrevious
            ) - $secondDerivativePreviousPrevious;
            self::finiteSpecialResult($current, $function);
            self::finiteSpecialResult($firstDerivativeCurrent, $function);
            self::finiteSpecialResult($secondDerivativeCurrent, $function);
            $previousPrevious = $previous;
            $previous = $current;
            $firstDerivativePreviousPrevious = $firstDerivativePrevious;
            $firstDerivativePrevious = $firstDerivativeCurrent;
            $secondDerivativePreviousPrevious = $secondDerivativePrevious;
            $secondDerivativePrevious = $secondDerivativeCurrent;
        }

        return $secondDerivativePrevious;
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevPolynomial(array $arguments, bool $secondKind): float
    {
        $function = $secondKind ? 'chebyshevu' : 'chebyshevt';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!\is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }
        if ($value === 1.0 || $value === -1.0) {
            if (!$secondKind) {
                return $value === 1.0 || $degree % 2 === 0 ? 1.0 : -1.0;
            }

            $endpoint = (float) ($degree + 1);
            return $value === 1.0 || $degree % 2 === 0 ? $endpoint : -$endpoint;
        }

        $previousPrevious = 1.0;
        $previous = $secondKind ? 2.0 * $value : $value;
        if ($degree === 1) {
            return self::finiteSpecialResult($previous, $function);
        }

        for ($order = 2; $order <= $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            self::finiteSpecialResult($current, $function);
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function hermitePhysicist(array $arguments): float
    {
        return self::hermitePolynomial($arguments, true);
    }

    /** @param list<int|float> $arguments */
    private static function hermiteProbabilist(array $arguments): float
    {
        return self::hermitePolynomial($arguments, false);
    }

    /** @param list<int|float> $arguments */
    private static function hermitePolynomial(array $arguments, bool $physicist): float
    {
        $function = $physicist ? 'hermite' : 'hermiteprobabilist';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!\is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }

        $previousPrevious = 1.0;
        $previous = $physicist ? 2.0 * $value : $value;
        if ($degree === 1) {
            return self::finiteSpecialResult($previous, $function);
        }
        for ($order = 1; $order < $degree; ++$order) {
            $leadingTerm = ($physicist ? 2.0 : 1.0) * $value * $previous;
            $trailingTerm = ($physicist ? 2.0 : 1.0) * $order * $previousPrevious;
            $current = $leadingTerm - $trailingTerm;
            self::finiteSpecialResult($current, $function);
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function laguerrePolynomial(array $arguments): float
    {
        return self::evaluateLaguerrePolynomial($arguments[0], 0.0, $arguments[1], 'laguerre');
    }

    /** @param list<int|float> $arguments */
    private static function associatedLaguerrePolynomial(array $arguments): float
    {
        return self::evaluateLaguerrePolynomial($arguments[0], $arguments[1], $arguments[2], 'laguerreassoc');
    }

    private static function evaluateLaguerrePolynomial(
        int|float $degreeValue,
        float|int $alphaValue,
        float|int $valueArgument,
        string $function,
    ): float {
        $degree = self::requireNonNegativeInteger($degreeValue, $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $alpha = (float) $alphaValue;
        $value = (float) $valueArgument;
        if (!\is_finite($alpha) || $alpha <= -1.0) {
            throw new \DomainException($function . '() requires a finite parameter greater than -1.');
        }
        if (!\is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }

        $previousPrevious = 1.0;
        $previous = 1.0 + $alpha - $value;
        self::finiteSpecialResult($previous, $function);
        for ($order = 1; $order < $degree; ++$order) {
            $leadingTerm = (2.0 * $order + 1.0 + $alpha - $value) * $previous;
            $trailingTerm = ($order + $alpha) * $previousPrevious;
            $current = ($leadingTerm - $trailingTerm) / ($order + 1.0);
            self::finiteSpecialResult($current, $function);
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function jacobiPolynomial(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'jacobipoly');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('jacobipoly() degree must not exceed 10000.');
        }
        $alpha = (float) $arguments[1];
        $beta = (float) $arguments[2];
        $value = (float) $arguments[3];
        if (!\is_finite($alpha) || $alpha <= -1.0 || !\is_finite($beta) || $beta <= -1.0) {
            throw new \DomainException('jacobipoly() requires finite parameters alpha and beta greater than -1.');
        }
        if (!\is_finite($value)) {
            throw new \DomainException('jacobipoly() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }

        $parameterSum = $alpha + $beta;
        if (!\is_finite($parameterSum)) {
            throw new \OverflowException('jacobipoly() coefficients exceed the finite floating-point range.');
        }
        $previousPrevious = 1.0;
        $previous = 0.5 * (($alpha - $beta) + ($parameterSum + 2.0) * $value);
        self::finiteSpecialResult($previous, 'jacobipoly');
        for ($order = 1; $order < $degree; ++$order) {
            $twiceOrderAndParameters = 2.0 * $order + $parameterSum;
            $denominator = 2.0 * ($order + 1.0) * ($order + $parameterSum + 1.0)
                * $twiceOrderAndParameters;
            $leadingCoefficient = ($twiceOrderAndParameters + 1.0)
                * (
                    $twiceOrderAndParameters * ($twiceOrderAndParameters + 2.0) * $value
                    + ($alpha - $beta) * $parameterSum
                ) / $denominator;
            $trailingCoefficient = 2.0 * ($order + $alpha) * ($order + $beta)
                * ($twiceOrderAndParameters + 2.0) / $denominator;
            $current = $leadingCoefficient * $previous - $trailingCoefficient * $previousPrevious;
            self::finiteSpecialResult($current, 'jacobipoly');
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function bernsteinPolynomial(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'bernstein');
        $index = self::requireNonNegativeInteger($arguments[1], 'bernstein');
        $value = (float) $arguments[2];
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('bernstein() degree must not exceed 10000.');
        }
        if ($index > $degree) {
            throw new \DomainException('bernstein() requires k <= n.');
        }
        if (!is_finite($value) || $value < 0.0 || $value > 1.0) {
            throw new \DomainException('bernstein() requires x in [0, 1].');
        }
        if ($value === 0.0) {
            return $index === 0 ? 1.0 : 0.0;
        }
        if ($value === 1.0) {
            return $index === $degree ? 1.0 : 0.0;
        }

        $logCoefficient = self::logGammaFunction([$degree + 1.0])
            - self::logGammaFunction([$index + 1.0])
            - self::logGammaFunction([$degree - $index + 1.0]);
        $logValue = $logCoefficient + $index * log($value)
            + ($degree - $index) * log1p(-$value);

        return self::finiteSpecialResult(exp($logValue), 'bernstein');
    }

    /** @param list<int|float> $arguments */
    private static function gegenbauerPolynomial(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'gegenbauer');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('gegenbauer() degree must not exceed 10000.');
        }
        $lambda = (float) $arguments[1];
        $value = (float) $arguments[2];
        if (!is_finite($lambda) || $lambda <= -0.5) {
            throw new \DomainException('gegenbauer() requires a finite parameter lambda greater than -1/2.');
        }
        if (!is_finite($value)) {
            throw new \DomainException('gegenbauer() requires a finite argument.');
        }
        if ($degree === 0) {
            return 1.0;
        }
        if ($lambda === 0.0) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = 2.0 * $lambda * $value;
        self::finiteSpecialResult($previous, 'gegenbauer');
        for ($order = 1; $order < $degree; ++$order) {
            $current = (2.0 * ($order + $lambda) * $value * $previous
                    - ($order + 2.0 * $lambda - 1.0) * $previousPrevious)
                / ($order + 1.0);
            self::finiteSpecialResult($current, 'gegenbauer');
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function legendrePolynomialDerivative(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'legendrepolyprime');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('legendrepolyprime() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('legendrepolyprime() requires a finite argument.');
        }
        if ($degree === 0) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = $value;
        $derivativePreviousPrevious = 0.0;
        $derivativePrevious = 1.0;
        for ($order = 1; $order < $degree; ++$order) {
            $factor = 2.0 * $order + 1.0;
            $divisor = $order + 1.0;
            $current = ($factor * $value * $previous - $order * $previousPrevious) / $divisor;
            $derivativeCurrent = (
                $factor * ($previous + $value * $derivativePrevious)
                - $order * $derivativePreviousPrevious
            ) / $divisor;
            self::finiteSpecialResult($current, 'legendrepolyprime');
            self::finiteSpecialResult($derivativeCurrent, 'legendrepolyprime');
            $previousPrevious = $previous;
            $previous = $current;
            $derivativePreviousPrevious = $derivativePrevious;
            $derivativePrevious = $derivativeCurrent;
        }

        return $derivativePrevious;
    }

    /** @param list<int|float> $arguments */
    private static function legendrePolynomialSecondDerivative(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'legendrepolysecond');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('legendrepolysecond() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException('legendrepolysecond() requires a finite argument.');
        }
        if ($degree < 2) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = $value;
        $firstDerivativePreviousPrevious = 0.0;
        $firstDerivativePrevious = 1.0;
        $secondDerivativePreviousPrevious = 0.0;
        $secondDerivativePrevious = 0.0;
        for ($order = 2; $order <= $degree; ++$order) {
            $factor = 2.0 * $order - 1.0;
            $divisor = (float) $order;
            $current = ($factor * $value * $previous - ($order - 1.0) * $previousPrevious) / $divisor;
            $firstDerivativeCurrent = (
                $factor * ($previous + $value * $firstDerivativePrevious)
                - ($order - 1.0) * $firstDerivativePreviousPrevious
            ) / $divisor;
            $secondDerivativeCurrent = (
                $factor * (2.0 * $firstDerivativePrevious + $value * $secondDerivativePrevious)
                - ($order - 1.0) * $secondDerivativePreviousPrevious
            ) / $divisor;
            self::finiteSpecialResult($current, 'legendrepolysecond');
            self::finiteSpecialResult($firstDerivativeCurrent, 'legendrepolysecond');
            self::finiteSpecialResult($secondDerivativeCurrent, 'legendrepolysecond');
            $previousPrevious = $previous;
            $previous = $current;
            $firstDerivativePreviousPrevious = $firstDerivativePrevious;
            $firstDerivativePrevious = $firstDerivativeCurrent;
            $secondDerivativePreviousPrevious = $secondDerivativePrevious;
            $secondDerivativePrevious = $secondDerivativeCurrent;
        }

        return $secondDerivativePrevious;
    }

