    /** @param list<int|float> $arguments */
    private static function chebyshevPolynomialDerivative(array $arguments, bool $secondKind): float
    {
        $function = $secondKind ? 'chebyshevuprime' : 'chebyshevtprime';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = $secondKind ? 2.0 * $value : $value;
        $derivativePreviousPrevious = 0.0;
        $derivativePrevious = $secondKind ? 2.0 : 1.0;
        if ($degree === 1) {
            return self::finiteSpecialResult($derivativePrevious, $function);
        }
        for ($order = 1; $order < $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            $derivativeCurrent = 2.0 * ($previous + $value * $derivativePrevious)
                - $derivativePreviousPrevious;
            self::finiteSpecialResult($current, $function);
            self::finiteSpecialResult($derivativeCurrent, $function);
            $previousPrevious = $previous;
            $previous = $current;
            $derivativePreviousPrevious = $derivativePrevious;
            $derivativePrevious = $derivativeCurrent;
        }

        return $derivativePrevious;
    }

    /** @param list<int|float> $arguments */
    private static function chebyshevPolynomialSecondDerivative(array $arguments, bool $secondKind): float
    {
        $function = $secondKind ? 'chebyshevusecond' : 'chebyshevtsecond';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree < 2) {
            return 0.0;
        }

        $previousPrevious = 1.0;
        $previous = $secondKind ? 2.0 * $value : $value;
        $firstDerivativePreviousPrevious = 0.0;
        $firstDerivativePrevious = $secondKind ? 2.0 : 1.0;
        $secondDerivativePreviousPrevious = 0.0;
        $secondDerivativePrevious = 0.0;
        for ($order = 2; $order <= $degree; ++$order) {
            $current = 2.0 * $value * $previous - $previousPrevious;
            $firstDerivativeCurrent = 2.0 * ($previous + $value * $firstDerivativePrevious)
                - $firstDerivativePreviousPrevious;
            $secondDerivativeCurrent = 2.0 * (
                2.0 * $firstDerivativePrevious + $value * $secondDerivativePrevious
            ) - $secondDerivativePreviousPrevious;
            self::finiteSpecialResult($current, $function);
            self::finiteSpecialResult($firstDerivativeCurrent, $function);
            self::finiteSpecialResult($secondDerivativeCurrent, $function);
            $previousPrevious = $previous;
            $previous = $current;
            $firstDerivativePreviousPrevious = $firstDerivativePrevious;
            $firstDerivativePrevious = $firstDerivativeCurrent;
            $secondDerivativePreviousPrevious = $secondDerivativePrevious;
            $secondDerivativePrevious = $secondDerivativeCurrent;
        }

        return $secondDerivativePrevious;
    }

