    /** @param list<int|float> $arguments */
    private static function hermitePolynomialSecondDerivative(array $arguments, bool $physicist): float
    {
        $function = $physicist ? 'hermitesecond' : 'hermiteprobabilistsecond';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree < 2) {
            return 0.0;
        }

        $factor = $physicist ? 4.0 * $degree * ($degree - 1.0) : $degree * ($degree - 1.0);
        $polynomial = self::hermitePolynomial([$degree - 2, $value], $physicist);
        return self::finiteSpecialResult($factor * $polynomial, $function);
    }

    /** @param list<int|float> $arguments */
    private static function hermitePolynomialDerivative(array $arguments, bool $physicist): float
    {
        $function = $physicist ? 'hermiteprime' : 'hermiteprobabilistprime';
        $degree = self::requireNonNegativeInteger($arguments[0], $function);
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException($function . '() degree must not exceed 10000.');
        }
        $value = (float) $arguments[1];
        if (!is_finite($value)) {
            throw new \DomainException($function . '() requires a finite argument.');
        }
        if ($degree === 0) {
            return 0.0;
        }
        $polynomial = self::hermitePolynomial([$degree - 1, $value], $physicist);
        $factor = ($physicist ? 2.0 : 1.0) * $degree;

        return self::finiteSpecialResult($factor * $polynomial, $function);
    }

    /** @param list<int|float> $arguments */
