    /** @param list<int|float> $arguments */
    private static function jacobiPolynomialDerivative(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'jacobipolyprime');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('jacobipolyprime() degree must not exceed 10000.');
        }
        $alpha = (float) $arguments[1];
        $beta = (float) $arguments[2];
        $value = (float) $arguments[3];
        if (!is_finite($alpha) || $alpha <= -1.0 || !is_finite($beta) || $beta <= -1.0) {
            throw new \DomainException('jacobipoly() requires finite parameters alpha and beta greater than -1.');
        }
        if (!is_finite($value)) {
            throw new \DomainException('jacobipoly() requires a finite argument.');
        }
        if ($degree === 0) {
            self::jacobiPolynomial($arguments);
            return 0.0;
        }
        $coefficient = 0.5 * ($degree + $alpha + $beta + 1.0);
        if (!is_finite($coefficient)) {
            throw new \OverflowException('jacobipolyprime() coefficient exceeds the finite floating-point range.');
        }
        $shifted = self::jacobiPolynomial([$degree - 1, $alpha + 1.0, $beta + 1.0, $value]);

        return self::finiteSpecialResult($coefficient * $shifted, 'jacobipolyprime');
    }

    /** @param list<int|float> $arguments */
    private static function jacobiPolynomialSecondDerivative(array $arguments): float
