        $order = self::requireNonNegativeInteger($arguments[4], 'jacobipolyderivative');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE || $order > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('jacobipolyderivative() degree and derivative order must not exceed 10000.');
        }
