        $value = (float) $arguments[2];
        if (!is_finite($lambda) || $lambda <= -0.5) {
            throw new \DomainException('gegenbauer() requires a finite parameter lambda greater than -1/2.');
        }
        if (!is_finite($value)) {
            throw new \DomainException('gegenbauer() requires a finite argument.');
        }
        if ($degree < 3 || $lambda === 0.0) {
            self::gegenbauerPolynomial($arguments);
            return 0.0;
        }

        $coefficient = 8.0 * $lambda * ($lambda + 1.0) * ($lambda + 2.0);
        if (!is_finite($coefficient)) {
            throw new \OverflowException('gegenbauerthird() coefficient exceeds the finite floating-point range.');
        }
        $shifted = self::gegenbauerPolynomial([$degree - 3, $lambda + 3.0, $value]);

        return self::finiteSpecialResult($coefficient * $shifted, 'gegenbauerthird');
    }

    /** @param list<int|float> $arguments */
    private static function gegenbauerPolynomialNthDerivative(array $arguments): float
    {
        $degree = self::requireNonNegativeInteger($arguments[0], 'gegenbauerderivative');
        $order = self::requireNonNegativeInteger($arguments[3], 'gegenbauerderivative');
        if ($degree > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE || $order > self::MAX_LEGENDRE_POLYNOMIAL_DEGREE) {
            throw new \DomainException('gegenbauerderivative() degree and derivative order must not exceed 10000.');
        }
        $lambda = (float) $arguments[1];
        $value = (float) $arguments[2];
        if (!is_finite($lambda) || $lambda <= -0.5) {
            throw new \DomainException('gegenbauer() requires a finite parameter lambda greater than -1/2.');
        }
        if (!is_finite($value)) {
            throw new \DomainException('gegenbauer() requires a finite argument.');
        }
        if ($order === 0) {
            return self::gegenbauerPolynomial([$degree, $lambda, $value]);
        }
        if ($order > $degree || ($degree > 0 && $lambda === 0.0)) {
            self::gegenbauerPolynomial([$degree, $lambda, $value]);
            return 0.0;
        }

        $coefficient = 1.0;
        for ($index = 0; $index < $order; ++$index) {
            $coefficient *= 2.0 * ($lambda + $index);
            if (!is_finite($coefficient)) {
                throw new \OverflowException(
                    'gegenbauerderivative() coefficient exceeds the finite floating-point range.',
                );
            }
        }
        $shifted = self::gegenbauerPolynomial([$degree - $order, $lambda + $order, $value]);

        return self::finiteSpecialResult($coefficient * $shifted, 'gegenbauerderivative');
    }

    /** @param list<int|float> $arguments */
    private static function partitionNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'partition');
        if ($number > 10_000) {
            throw new \DomainException('partition() supports integer arguments from 0 through 10000.');
        }

        $partitions = array_fill(0, $number + 1, 0);
        $partitions[0] = 1;
        for ($current = 1; $current <= $number; ++$current) {
            $total = 0;
            for ($index = 1; $index <= $current; ++$index) {
                $firstPentagonal = intdiv($index * (3 * $index - 1), 2);
                if ($firstPentagonal > $current) {
                    break;
                }
                $sign = $index % 2 === 1 ? 1 : -1;
                $total = self::addPartitionTerm($total, $partitions[$current - $firstPentagonal], $sign);

                $secondPentagonal = intdiv($index * (3 * $index + 1), 2);
                if ($secondPentagonal <= $current) {
                    $total = self::addPartitionTerm($total, $partitions[$current - $secondPentagonal], $sign);
                }
            }
            $partitions[$current] = $total;
        }

        return $partitions[$number];
    }

    /** @param list<int|float> $arguments */
    private static function partitionCount(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'partitioncount');
        $parts = self::requireNonNegativeInteger($arguments[1], 'partitioncount');
        if ($number > 10_000) {
            throw new \DomainException('partitioncount() supports integer n from 0 through 10000.');
        }
        if ($parts > $number && $number !== 0) {
            return 0;
        }
        if ($number === 0) {
            return $parts === 0 ? 1 : 0;
        }
        if ($parts === 0) {
            return 0;
        }

        $remainder = $number - $parts;
        $counts = array_fill(0, $remainder + 1, 0);
        $counts[0] = 1;
        for ($part = 1; $part <= $parts; ++$part) {
            for ($sum = $part; $sum <= $remainder; ++$sum) {
                $counts[$sum] = self::checkedIntegerSum(
                    $counts[$sum],
                    $counts[$sum - $part],
                    'partitioncount()',
                );
            }
        }

        return $counts[$remainder];
    }

    /** @param list<int|float> $arguments */
    private static function distinctPartitionCount(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'distinctpartitioncount');
        $parts = self::requireNonNegativeInteger($arguments[1], 'distinctpartitioncount');
        if ($number > 10_000) {
            throw new \DomainException('distinctpartitioncount() supports integer n from 0 through 10000.');
        }
        if ($parts > $number && $number !== 0) {
            return 0;
        }
        if ($number === 0) {
            return $parts === 0 ? 1 : 0;
        }
        if ($parts === 0) {
            return 0;
        }

        $offset = intdiv($parts * ($parts + 1), 2);
        if ($offset > $number) {
            return 0;
        }

        $remainder = $number - $offset;
        $counts = array_fill(0, $remainder + 1, 0);
        $counts[0] = 1;
        for ($part = 1; $part <= $parts; ++$part) {
            for ($sum = $part; $sum <= $remainder; ++$sum) {
                $counts[$sum] = self::checkedIntegerSum(
                    $counts[$sum],
                    $counts[$sum - $part],
                    'distinctpartitioncount()',
                );
            }
        }

        return $counts[$remainder];
    }

    /** @param list<int|float> $arguments */
    private static function distinctPartitionNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'distinctpartitions');
        if ($number > 10_000) {
            throw new \DomainException('distinctpartitions() supports integer arguments from 0 through 10000.');
        }

        $partitions = array_fill(0, $number + 1, 0);
        $partitions[0] = 1;
        for ($part = 1; $part <= $number; ++$part) {
            for ($sum = $number; $sum >= $part; --$sum) {
                $partitions[$sum] = self::checkedIntegerSum(
                    $partitions[$sum],
                    $partitions[$sum - $part],
                    'distinctpartitions()',
                );
            }
        }

        return $partitions[$number];
    }

    /** @param list<int|float> $arguments */
    private static function primePartitionNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'primepartition');
        if ($number > 10_000) {
            throw new \DomainException('primepartition() supports integer arguments from 0 through 10000.');
        }

        $isPrime = array_fill(0, $number + 1, true);
        $isPrime[0] = false;
        if ($number >= 1) {
            $isPrime[1] = false;
        }
        for ($candidate = 2; $candidate * $candidate <= $number; ++$candidate) {
            if (!$isPrime[$candidate]) {
                continue;
            }
            for ($composite = $candidate * $candidate; $composite <= $number; $composite += $candidate) {
                $isPrime[$composite] = false;
            }
        }

        $partitions = array_fill(0, $number + 1, 0);
        $partitions[0] = 1;
        for ($prime = 2; $prime <= $number; ++$prime) {
            if (!$isPrime[$prime]) {
                continue;
            }
            for ($sum = $prime; $sum <= $number; ++$sum) {
                $partitions[$sum] = self::checkedIntegerSum(
                    $partitions[$sum],
                    $partitions[$sum - $prime],
                    'primepartition()',
                );
            }
        }

        return $partitions[$number];
    }

    private static function addPartitionTerm(int $total, int $term, int $sign): int
    {
        if ($sign > 0) {
            if ($total > PHP_INT_MAX - $term) {
                throw new \OverflowException('partition() result exceeds the host integer range.');
            }

            return $total + $term;
        }
        if ($total < PHP_INT_MIN + $term) {
            throw new \OverflowException('partition() result exceeds the host integer range.');
        }

        return $total - $term;
    }

    /** @param list<int|float> $arguments */
    private static function stirlingFirstKind(array $arguments): int
    {
        return self::stirlingNumber($arguments, 'signedFirst');
    }

    /** @param list<int|float> $arguments */
    private static function stirlingFirstKindUnsigned(array $arguments): int
    {
        return self::stirlingNumber($arguments, 'unsignedFirst');
    }

    /** @param list<int|float> $arguments */
    private static function stirlingSecondKind(array $arguments): int
    {
        return self::stirlingNumber($arguments, 'second');
    }

    /** @param list<int|float> $arguments */
    private static function bellNumber(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'bellnumber');
        if ($number > 10_000) {
            throw new \DomainException('bellnumber() supports integer arguments from 0 through 10000.');
        }
        if ($number === 0) {
            return 1;
        }

        /** @var list<int> $previousRow */
        $previousRow = [1];
        for ($row = 1; $row <= $number; ++$row) {
            /** @var list<int> $currentRow */
            $currentRow = array_fill(0, $row + 1, 0);
            for ($column = 1; $column <= $row; ++$column) {
                $sameColumn = $previousRow[$column] ?? 0;
                $product = self::checkedIntegerProduct($sameColumn, $column, 'bellnumber()');
                $currentRow[$column] = self::checkedIntegerSum($previousRow[$column - 1], $product, 'bellnumber()');
            }
            $previousRow = $currentRow;
        }

        $total = 0;
        foreach ($previousRow as $stirlingValue) {
            $total = self::checkedIntegerSum($total, $stirlingValue, 'bellnumber()');
        }

        return $total;
    }

    /**
     * @param list<int|float> $arguments
     * @param 'signedFirst'|'unsignedFirst'|'second' $kind
     */
    private static function stirlingNumber(array $arguments, string $kind): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'stirling');
        $k = self::requireNonNegativeInteger($arguments[1], 'stirling');
        if ($n > 10_000) {
            throw new \DomainException('stirling functions support integer n from 0 through 10000.');
        }
        if ($k > $n) {
            throw new \DomainException('stirling functions require k <= n.');
        }
        if ($n === 0) {
            return 1;
        }
        if ($k === 0) {
            return 0;
        }

        $previous = [1];
        for ($row = 1; $row <= $n; ++$row) {
            $maximumColumn = min($row, $k);
            $current = array_fill(0, $maximumColumn + 1, 0);
            for ($column = 1; $column <= $maximumColumn; ++$column) {
                $sameColumn = $previous[$column] ?? 0;
                $previousColumn = $previous[$column - 1] ?? 0;
                $factor = $kind === 'second' ? $column : $row - 1;
                $product = self::checkedIntegerProduct($sameColumn, $factor, 'stirling');
                $current[$column] = $kind === 'signedFirst'
                    ? self::checkedIntegerDifference($previousColumn, $product, 'stirling')
                    : self::checkedIntegerSum($previousColumn, $product, 'stirling');
            }
            $previous = $current;
        }

        return $previous[$k] ?? 0;
    }

    /** @param list<int|float> $arguments */
    private static function eulerianNumber(array $arguments): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'eulerian');
        $k = self::requireNonNegativeInteger($arguments[1], 'eulerian');
        if ($n > 10_000) {
            throw new \DomainException('eulerian() supports integer n from 0 through 10000.');
        }
        if ($n === 0) {
            if ($k !== 0) {
                throw new \DomainException('eulerian() requires k = 0 when n = 0.');
            }

            return 1;
        }
        if ($k >= $n) {
            throw new \DomainException('eulerian() requires k from 0 through n - 1.');
        }
        if ($k === 0 || $k === $n - 1) {
            return 1;
        }

        $k = min($k, $n - 1 - $k);
        $row = [1];
        for ($rowNumber = 1; $rowNumber <= $n; ++$rowNumber) {
            $maximumColumn = min($rowNumber - 1, $k);
            $nextRow = [];
            for ($column = 0; $column <= $maximumColumn; ++$column) {
                $sameColumn = $row[$column] ?? 0;
                $previousColumn = $column > 0 ? ($row[$column - 1] ?? 0) : 0;
                $firstTerm = self::checkedIntegerProduct($column + 1, $sameColumn, 'eulerian()');
                $secondTerm = self::checkedIntegerProduct(
                    $rowNumber - $column,
                    $previousColumn,
                    'eulerian()',
                );
                $nextRow[] = self::checkedIntegerSum($firstTerm, $secondTerm, 'eulerian()');
            }
            $row = $nextRow;
        }

        return $row[$k];
    }

    /** @param list<int|float> $arguments */
    private static function lahNumber(array $arguments): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'lah');
        $k = self::requireNonNegativeInteger($arguments[1], 'lah');
        if ($n > 10_000) {
            throw new \DomainException('lah() supports integer n from 0 through 10000.');
        }
        if ($k > $n) {
            throw new \DomainException('lah() requires k <= n.');
        }
        if ($n === 0) {
            return 1;
        }
        if ($k === 0) {
            return 0;
        }

        $factorialRatio = 1;
        for ($factor = $k + 1; $factor <= $n; ++$factor) {
            $factorialRatio = self::checkedIntegerProduct($factorialRatio, $factor, 'lah()');
        }

        return self::checkedIntegerProduct(self::binomial([$n - 1, $k - 1]), $factorialRatio, 'lah()');
    }

    /** @param list<int|float> $arguments */
    private static function narayanaNumber(array $arguments): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'narayana');
        $k = self::requireNonNegativeInteger($arguments[1], 'narayana');
        if ($n < 1 || $n > 10000) {
            throw new \DomainException('narayana() supports integer n from 1 through 10000.');
        }
        if ($k < 1 || $k > $n) {
            throw new \DomainException('narayana() requires k from 1 through n.');
        }

        $left = self::binomial([$n, $k]);
        $right = self::binomial([$n, $k - 1]);
        $denominator = $n;
        $divisor = self::greatestCommonDivisor([$left, $denominator]);
        $left = intdiv($left, $divisor);
        $denominator = intdiv($denominator, $divisor);
        $divisor = self::greatestCommonDivisor([$right, $denominator]);
        $right = intdiv($right, $divisor);
        $denominator = intdiv($denominator, $divisor);
        if ($denominator !== 1) {
            throw new \LogicException('narayana() reduction failed to produce an integer.');
        }

        return self::checkedIntegerProduct($left, $right, 'narayana()');
    }

    /** @param list<int|float> $arguments */
    private static function motzkinNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'motzkin');
        $sequence = [1];
        for ($number = 1; $number <= $index; ++$number) {
            $current = $sequence[$number - 1];
            for ($split = 0; $split <= $number - 2; ++$split) {
                $product = self::checkedIntegerProduct(
                    $sequence[$split],
                    $sequence[$number - 2 - $split],
                    'motzkin()',
                );
                $current = self::checkedIntegerSum($current, $product, 'motzkin()');
            }
            $sequence[] = $current;
        }

        return $sequence[$index];
    }

    private static function checkedIntegerProduct(int $value, int $factor, string $function): int
    {
        if ($factor === 0 || $value === 0) {
            return 0;
        }
        if (
            ($value > 0 && $value > intdiv(PHP_INT_MAX, $factor))
            || ($value < 0 && $value < intdiv(PHP_INT_MIN, $factor))
        ) {
            throw new \OverflowException($function . ' result exceeds the host integer range.');
        }

        return $value * $factor;
    }

    private static function checkedIntegerSum(int $left, int $right, string $function): int
    {
        if (($right > 0 && $left > PHP_INT_MAX - $right) || ($right < 0 && $left < PHP_INT_MIN - $right)) {
            throw new \OverflowException($function . ' result exceeds the host integer range.');
        }

        return $left + $right;
    }

    private static function checkedIntegerDifference(int $left, int $right, string $function): int
    {
        if (($right > 0 && $left < PHP_INT_MIN + $right) || ($right < 0 && $left > PHP_INT_MAX + $right)) {
            throw new \OverflowException($function . ' result exceeds the host integer range.');
        }

        return $left - $right;
    }

    /** @param list<int|float> $arguments */
    private static function fibonacciNumber(array $arguments): int
    {
        $index = self::requireInteger($arguments[0], 'fibonacci');
        $magnitude = self::nonNegativeSequenceIndex($index, 'fibonacci');
        $previous = 0;
        $current = 1;
        for ($step = 0; $step < $magnitude; ++$step) {
            [$previous, $current] = [
                $current,
                self::checkedIntegerSum($previous, $current, 'fibonacci()'),
            ];
        }

        if ($index < 0 && $magnitude % 2 === 0) {
            return -$previous;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function fibonacciSum(array $arguments): int
    {
        return self::linearRecurrenceSum($arguments, [0, 1], [1, 1], 'fibonaccisum');
    }

    /** @param list<int|float> $arguments */
    private static function lucasSum(array $arguments): int
    {
