    }

    /** @param list<int|float> $arguments */
    private static function padovanSum(array $arguments): int
    {
        return self::linearRecurrenceSum($arguments, [1, 1, 1], [0, 1, 1], 'padovansum');
    }

    /** @param list<int|float> $arguments */
    private static function perrinSum(array $arguments): int
    {
        return self::linearRecurrenceSum($arguments, [3, 0, 2], [0, 1, 1], 'perrinsum');
    }

    /**
     * @param list<int|float> $arguments
     * @param list<int> $seeds
     * @param list<int> $coefficients
     */
    private static function linearRecurrenceSum(
        array $arguments,
        array $seeds,
        array $coefficients,
        string $function,
    ): int {
        $lastIndex = self::requireNonNegativeInteger($arguments[0], $function);
        if ($lastIndex > 10000) {
            throw new \DomainException($function . '() supports integer indices from 0 through 10000.');
        }

        $window = [];
        $sum = 0;
        foreach ($seeds as $seed) {
            $window[] = $seed;
            if (count($window) <= $lastIndex + 1) {
                $sum = self::checkedIntegerSum($sum, $seed, $function . '()');
            }
        }

        for ($index = count($seeds); $index <= $lastIndex; ++$index) {
            $next = 0;
            foreach ($coefficients as $lag => $coefficient) {
                $term = self::checkedIntegerProduct(
                    $coefficient,
                    $window[count($window) - $lag - 1],
                    $function . '()',
                );
                $next = self::checkedIntegerSum($next, $term, $function . '()');
            }
            array_shift($window);
            $window[] = $next;
            $sum = self::checkedIntegerSum($sum, $next, $function . '()');
        }

        return $sum;
    }

    /** @param list<int|float> $arguments */
    private static function lucasNumber(array $arguments): int
    {
        $index = self::requireInteger($arguments[0], 'lucas');
        $magnitude = self::nonNegativeSequenceIndex($index, 'lucas');
        $previous = 2;
        $current = 1;
        for ($step = 0; $step < $magnitude; ++$step) {
            [$previous, $current] = [
                $current,
                self::checkedIntegerSum($previous, $current, 'lucas()'),
            ];
        }

        if ($index < 0 && $magnitude % 2 === 1) {
            return -$previous;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function pellNumber(array $arguments): int
    {
        $index = self::requireInteger($arguments[0], 'pell');
        $magnitude = self::nonNegativeSequenceIndex($index, 'pell');
        $previous = 0;
        $current = 1;
        for ($step = 0; $step < $magnitude; ++$step) {
            [$previous, $current] = [
                $current,
                self::checkedIntegerSum(
                    self::checkedIntegerProduct($current, 2, 'pell()'),
                    $previous,
                    'pell()',
                ),
            ];
        }

        if ($index < 0 && $magnitude % 2 === 0) {
            return -$previous;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function pellLucasNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'pelllucas');
        if ($index === 0 || $index === 1) {
            return 2;
        }

        $previous = 2;
        $current = 2;
        for ($step = 2; $step <= $index; ++$step) {
            [$previous, $current] = [
                $current,
                self::checkedIntegerSum(
                    self::checkedIntegerProduct($current, 2, 'pelllucas()'),
                    $previous,
                    'pelllucas()',
                ),
            ];
        }

        return $current;
    }

