    /** @param list<int|float> $arguments */
    private static function thirdOrderSequence(
        array $arguments,
        int $first,
        int $second,
        int $third,
        string $function,
    ): int {
        $index = self::requireNonNegativeInteger($arguments[0], $function);
        if ($index === 0) {
            return $first;
        }
        if ($index === 1) {
            return $second;
        }
        if ($index === 2) {
            return $third;
        }

        for ($step = 3; $step <= $index; ++$step) {
            [$first, $second, $third] = [
                $second,
                $third,
                self::checkedIntegerSum($first, $second, $function . '()'),
            ];
        }

        return $third;
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function secondOrderSequence(array $arguments, int $first, int $second, string $function): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], $function);
        if ($index === 0) {
            return $first;
        }
        if ($index === 1) {
            return $second;
        }

        for ($step = 2; $step <= $index; ++$step) {
            [$first, $second] = [
                $second,
                self::checkedIntegerSum(
                    $second,
                    self::checkedIntegerProduct($first, 2, $function . '()'),
                    $function . '()',
                ),
            ];
        }

        return $second;
    }

    /** @param list<int|float> $arguments */
    private static function nacciNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'nacci');
        $order = self::requireNonNegativeInteger($arguments[1], 'nacci');
        if ($order < 2 || $order > 64) {
            throw new \DomainException('nacci() order must be an integer in [2, 64].');
        }

        $window = array_fill(0, $order - 1, 0);
        $window[] = 1;
        if ($index < $order) {
            return $window[$index];
        }

        for ($term = $order; $term <= $index; ++$term) {
            $next = 0;
            foreach ($window as $value) {
                $next = self::checkedIntegerSum($next, $value, 'nacci()');
            }
            array_shift($window);
            $window[] = $next;
        }

        return $window[$order - 1];
    }

    /** @param list<int|float> $arguments */
    private static function tribonacciNumber(array $arguments): int
    {
        return self::nacciNumber([$arguments[0], 3]);
    }

    /** @param list<int|float> $arguments */
    private static function sternDiatomicSequence(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'stern');
        if ($index === 0) {
            return 0;
        }

        $lower = 0;
        $upper = 1;
        $bits = decbin($index);
        for ($position = 0, $length = strlen($bits); $position < $length; ++$position) {
            $sum = self::checkedIntegerSum($lower, $upper, 'stern()');
            if ($bits[$position] === '0') {
                $upper = $sum;
            } else {
                $lower = $sum;
            }
        }

        return $lower;
    }

    /** @param list<int|float> $arguments */
    private static function triangularNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'triangular');
        if ($index % 2 === 0) {
            return self::checkedIntegerProduct(intdiv($index, 2), $index + 1, 'triangular()');
        }

        return self::checkedIntegerProduct($index, intdiv($index, 2) + 1, 'triangular()');
    }

    /** @param list<int|float> $arguments */
    private static function polygonalNumber(array $arguments): int
    {
        $sides = self::requireNonNegativeInteger($arguments[0], 'polygonal');
        if ($sides < 3) {
            throw new \DomainException('polygonal() requires at least three sides.');
        }
        $index = self::requireNonNegativeInteger($arguments[1], 'polygonal');

        return self::polygonalNumberValue($sides, $index, 'polygonal');
    }

    /** @param list<int|float> $arguments */
    private static function pentagonalNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'pentagonal');
        return self::polygonalNumberValue(5, $index, 'pentagonal');
    }

    /** @param list<int|float> $arguments */
    private static function hexagonalNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'hexagonal');
        return self::polygonalNumberValue(6, $index, 'hexagonal');
    }

    /** @param list<int|float> $arguments */
    private static function heptagonalNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'heptagonal');
        return self::polygonalNumberValue(7, $index, 'heptagonal');
    }

    /** @param list<int|float> $arguments */
    private static function octagonalNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'octagonal');
        return self::polygonalNumberValue(8, $index, 'octagonal');
    }

    private static function polygonalNumberValue(int $sides, int $index, string $function): int
    {
        if ($index < 2) {
            return $index;
        }

        try {
            $triangularOffset = self::binomial([$index, 2]);
        } catch (\OverflowException) {
            throw new \OverflowException($function . '() result exceeds the host integer range.');
        }

        return self::checkedIntegerSum(
            $index,
            self::checkedIntegerProduct($sides - 2, $triangularOffset, $function . '()'),
            $function . '()',
        );
    }

    /** @param list<int|float> $arguments */
    private static function tetrahedralNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'tetrahedral');
        if ($index > \PHP_INT_MAX - 2) {
            throw new \OverflowException('tetrahedral() result exceeds the host integer range.');
        }

        $factors = [$index, $index + 1, $index + 2];
        foreach ([2, 3] as $divisor) {
            foreach ($factors as $factorIndex => $factor) {
                if ($factor % $divisor === 0) {
                    $factors[$factorIndex] = intdiv($factor, $divisor);
                    break;
                }
            }
        }

        return self::checkedIntegerProduct(
            self::checkedIntegerProduct($factors[0], $factors[1], 'tetrahedral()'),
            $factors[2],
            'tetrahedral()',
        );
    }

    /** @param list<int|float> $arguments */
    private static function simplexNumber(array $arguments): int
    {
        $dimension = self::requireNonNegativeInteger($arguments[0], 'simplex');
        if ($dimension < 1) {
            throw new \DomainException('simplex() dimension must be at least one.');
        }
        $index = self::requireNonNegativeInteger($arguments[1], 'simplex');
        if ($index === 0) {
            return 0;
        }
        if ($index > \PHP_INT_MAX - ($dimension - 1)) {
            throw new \OverflowException('simplex() result exceeds the host integer range.');
        }

        try {
            return self::binomial([$index + $dimension - 1, $dimension]);
        } catch (\OverflowException) {
            throw new \OverflowException('simplex() result exceeds the host integer range.');
        }
    }

    /** @param list<int|float> $arguments */
    private static function pyramidalNumber(array $arguments): int
    {
        $sides = self::requireNonNegativeInteger($arguments[0], 'pyramidal');
        if ($sides < 3) {
            throw new \DomainException('pyramidal() requires at least three sides.');
        }
        $index = self::requireNonNegativeInteger($arguments[1], 'pyramidal');

        return self::pyramidalNumberValue($sides, $index, 'pyramidal');
    }

    /** @param list<int|float> $arguments */
    private static function squarePyramidalNumber(array $arguments): int
    {
        $index = self::requireNonNegativeInteger($arguments[0], 'squarepyramidal');

        return self::pyramidalNumberValue(4, $index, 'squarepyramidal');
    }

    private static function pyramidalNumberValue(int $sides, int $index, string $function): int
    {
        if ($index === 0) {
            return 0;
        }
        if ($index === PHP_INT_MAX) {
            throw new \OverflowException($function . '() result exceeds the host integer range.');
        }

        $layerFactor = self::checkedIntegerSum(
            self::checkedIntegerProduct($sides - 2, $index, $function . '()'),
            5 - $sides,
            $function . '()',
        );
        $factors = [$index, $index + 1, $layerFactor];
        foreach ([2, 3] as $divisor) {
            foreach ($factors as $factorIndex => $factor) {
                if ($factor % $divisor === 0) {
                    $factors[$factorIndex] = intdiv($factor, $divisor);
                    break;
                }
            }
        }

        return self::checkedIntegerProduct(
            self::checkedIntegerProduct($factors[0], $factors[1], $function . '()'),
            $factors[2],
            $function . '()',
        );
    }

    /** @param list<int|float> $arguments */
    private static function superFactorial(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'superfactorial');
        $product = 1;
        $factorial = 1;
        for ($index = 1; $index <= $number; ++$index) {
            $factorial = self::checkedIntegerProduct($factorial, $index, 'superfactorial()');
            $product = self::checkedIntegerProduct($product, $factorial, 'superfactorial()');
        }

        return $product;
    }

    /** @param list<int|float> $arguments */
    private static function hyperFactorial(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'hyperfactorial');
        $product = 1;
        for ($base = 1; $base <= $number; ++$base) {
            $power = 1;
            for ($exponent = 0; $exponent < $base; ++$exponent) {
                $power = self::checkedIntegerProduct($power, $base, 'hyperfactorial()');
            }
            $product = self::checkedIntegerProduct($product, $power, 'hyperfactorial()');
        }

        return $product;
    }

    private static function nonNegativeSequenceIndex(int $index, string $function): int
    {
        if ($index === PHP_INT_MIN) {
            throw new \OverflowException($function . '() index magnitude exceeds the host integer range.');
        }

        return abs($index);
    }

    /** @param list<int|float> $arguments */
    private static function binomial(array $arguments): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'binomial');
        $k = self::requireNonNegativeInteger($arguments[1], 'binomial');
        if ($k > $n) {
            throw new \DomainException('binomial() requires k to be less than or equal to n.');
        }

        $k = min($k, $n - $k);
        $result = 1;
        for ($index = 1; $index <= $k; ++$index) {
            $numerator = $n - $k + $index;
            $denominator = $index;
            $common = self::integerGcd($numerator, $denominator);
            $numerator = intdiv($numerator, $common);
            $denominator = intdiv($denominator, $common);
            $common = self::integerGcd($result, $denominator);
            $result = intdiv($result, $common);
            $denominator = intdiv($denominator, $common);
            if ($denominator !== 1) {
                throw new \LogicException('binomial() reduction failed to produce an integer.');
            }
            if ($result > intdiv(\PHP_INT_MAX, $numerator)) {
                throw new \OverflowException('binomial() result exceeds the host integer range.');
            }
            $result *= $numerator;
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function generalizedBinomial(array $arguments): float
    {
        $upper = (float) $arguments[0];
        if (!\is_finite($upper)) {
            throw new \DomainException('genbinomial() requires a finite upper argument.');
        }
        $order = self::requireNonNegativeInteger($arguments[1], 'genbinomial');
        if ($order > 10_000) {
            throw new \DomainException('genbinomial() order must be an integer in [0, 10000].');
        }
        if ($order === 0) {
            return 1.0;
        }

        $result = 1.0;
        for ($index = 0; $index < $order; ++$index) {
            $result *= ($upper - $index) / ($index + 1.0);
            if (!\is_finite($result)) {
                throw new \OverflowException('genbinomial() result exceeds the finite floating-point range.');
            }
            if ($result === 0.0) {
                break;
            }
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function permutation(array $arguments): int
    {
        $n = self::requireNonNegativeInteger($arguments[0], 'permutation');
        $k = self::requireNonNegativeInteger($arguments[1], 'permutation');
        if ($k > $n) {
            throw new \DomainException('permutation() requires k to be less than or equal to n.');
        }
        if ($k === 0) {
            return 1;
        }

        $result = 1;
        for ($value = $n - $k + 1; $value <= $n; ++$value) {
            if ($value !== 0 && $result > intdiv(\PHP_INT_MAX, $value)) {
                throw new \OverflowException('permutation() result exceeds the host integer range.');
            }
            $result *= $value;
            if ($value === $n) {
                break;
            }
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function multinomial(array $arguments): int
    {
        $result = 1;
        $total = 0;
        foreach ($arguments as $argument) {
            $count = self::requireNonNegativeInteger($argument, 'multinomial');
            if ($total > \PHP_INT_MAX - $count) {
                throw new \OverflowException('multinomial() result exceeds the host integer range.');
            }

            $total += $count;
            try {
                $factor = self::binomial([$total, $count]);
            } catch (\OverflowException) {
                throw new \OverflowException('multinomial() result exceeds the host integer range.');
            }
            $result = self::checkedIntegerProduct($result, $factor, 'multinomial()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function catalan(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'catalan');
        $result = 1;
        for ($index = 1; $index <= $number; ++$index) {
            $numerator = 4 * $index - 2;
            $denominator = $index + 1;
            $common = self::integerGcd($numerator, $denominator);
            $numerator = intdiv($numerator, $common);
            $denominator = intdiv($denominator, $common);
            $common = self::integerGcd($result, $denominator);
            $result = intdiv($result, $common);
            $denominator = intdiv($denominator, $common);
            if ($denominator !== 1) {
                throw new \LogicException('catalan() reduction failed to produce an integer.');
            }

            $result = self::checkedIntegerProduct($result, $numerator, 'catalan()');
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function subfactorial(array $arguments): int
    {
        $number = self::requireNonNegativeInteger($arguments[0], 'subfactorial');
        if ($number === 0) {
            return 1;
        }
        if ($number === 1) {
            return 0;
        }

        $previousPrevious = 1;
        $previous = 0;
        for ($index = 2; $index <= $number; ++$index) {
            $sum = self::checkedIntegerSum($previous, $previousPrevious, 'subfactorial()');
            $current = self::checkedIntegerProduct($index - 1, $sum, 'subfactorial()');
            $previousPrevious = $previous;
            $previous = $current;
        }

        return $previous;
    }

    /** @param list<int|float> $arguments */
    private static function doubleFactorial(array $arguments): int
    {
        $operand = self::requireNonNegativeInteger($arguments[0], 'doublefactorial');
        $result = 1;
        for ($factor = $operand; $factor > 1; $factor -= 2) {
            if ($result > intdiv(\PHP_INT_MAX, $factor)) {
                throw new \OverflowException('doublefactorial() result exceeds the host integer range.');
            }
            $result *= $factor;
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function multiFactorial(array $arguments): int
    {
        $operand = self::requireNonNegativeInteger($arguments[0], 'multifactorial');
        $step = self::requireNonNegativeInteger($arguments[1], 'multifactorial');
        if ($step === 0) {
            throw new \DomainException('multifactorial() step must be a positive integer.');
        }

        $result = 1;
        for ($factor = $operand; $factor > 1; $factor -= min($step, $factor)) {
            if ($result > intdiv(PHP_INT_MAX, $factor)) {
                throw new \OverflowException('multifactorial() result exceeds the host integer range.');
            }
            $result *= $factor;
        }

        return $result;
    }

    /** @param list<int|float> $arguments */
    private static function risingFactorial(array $arguments): int|float
    {
        $order = (float) $arguments[1];
        if (is_finite($order) && floor($order) !== $order) {
            return self::realOrderRisingFactorial($arguments[0], $order);
        }

        return self::finiteProductFactorial($arguments, true, 'risingfactorial');
    }

    private static function realOrderRisingFactorial(int|float $start, float $order): float
    {
        $value = (float) $start;
        if (!is_finite($value) || !is_finite($order) || $order < 0.0 || $order > 10_000.0) {
            throw new \DomainException(
                'risingfactorial() requires a finite start and real order from 0 through 10000.',
            );
        }
        if ($value <= 0.0 && floor($value) === $value) {
            return 0.0;
        }

        $gammaArgument = $value + $order;
        if (!is_finite($gammaArgument)) {
            throw new \OverflowException('risingfactorial() result exceeds the finite numeric range.');
        }
        if ($gammaArgument <= 0.0 && floor($gammaArgument) === $gammaArgument) {
            throw new \DomainException('risingfactorial() gamma ratio has a pole.');
        }

        $logMagnitude = self::logGammaFunction([$gammaArgument]) - self::logGammaFunction([$value]);
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('risingfactorial() result exceeds the finite numeric range.');
        }
        $sign = self::gammaSign([$gammaArgument]) * self::gammaSign([$value]);

        return self::finiteSpecialResult($sign * exp($logMagnitude), 'risingfactorial');
    }

    /** @param list<int|float> $arguments */
    private static function fallingFactorial(array $arguments): int|float
    {
        $order = (float) $arguments[1];
        if (is_finite($order) && floor($order) !== $order) {
            return self::realOrderFallingFactorial($arguments[0], $order);
        }

        return self::finiteProductFactorial($arguments, false, 'fallingfactorial');
    }

    private static function realOrderFallingFactorial(int|float $start, float $order): float
    {
        $value = (float) $start;
        if (!is_finite($value) || !is_finite($order) || $order < 0.0 || $order > 10_000.0) {
            throw new \DomainException(
                'fallingfactorial() requires a finite start and real order from 0 through 10000.',
            );
        }
        if ($value >= 0.0 && floor($value) === $value && $order > $value) {
            return 0.0;
        }

        $gammaArgument = $value - $order + 1.0;
        if (!is_finite($gammaArgument)) {
            throw new \OverflowException('fallingfactorial() result exceeds the finite numeric range.');
        }
        if ($gammaArgument <= 0.0 && floor($gammaArgument) === $gammaArgument) {
            throw new \DomainException('fallingfactorial() gamma ratio has a pole.');
        }

        $logMagnitude = self::logGammaFunction([$value + 1.0]) - self::logGammaFunction([$gammaArgument]);
        if ($logMagnitude > log(PHP_FLOAT_MAX)) {
            throw new \OverflowException('fallingfactorial() result exceeds the finite numeric range.');
        }
        $sign = self::gammaSign([$value + 1.0]) * self::gammaSign([$gammaArgument]);

        return self::finiteSpecialResult($sign * exp($logMagnitude), 'fallingfactorial');
    }

    /**
     * @param list<int|float> $arguments
     */
    private static function finiteProductFactorial(array $arguments, bool $rising, string $function): int|float
    {
        $start = $arguments[0];
        $order = self::requireNonNegativeInteger($arguments[1], $function);
        if ($order > 10_000) {
            throw new \DomainException($function . '() supports integer order from 0 through 10000.');
        }

        $result = 1;
        for ($index = 0; $index < $order; ++$index) {
            $offset = $rising ? $index : -$index;
            if (\is_int($start) && !\is_float($result)) {
                if (
                    ($offset > 0 && $start > PHP_INT_MAX - $offset)
                    || ($offset < 0 && $start < PHP_INT_MIN - $offset)
                ) {
                    $factor = (float) $start + $offset;
                } else {
                    $factor = $start + $offset;
                }
                if (\is_int($factor)) {
                    try {
                        $result = self::checkedIntegerProduct($result, $factor, $function . '()');
                        continue;
                    } catch (\OverflowException) {
                        $result = (float) $result;
                    }
                }
            } else {
                $factor = (float) $start + $offset;
            }

            $result = (float) $result * (float) $factor;
            if (!\is_finite($result)) {
                throw new \OverflowException($function . '() result exceeds the finite numeric range.');
            }
        }

        return $result;
    }

    private static function factorialValue(int $operand, string $function): int
    {
        $result = 1;
        for ($factor = 2; $factor <= $operand; ++$factor) {
            if ($result > intdiv(\PHP_INT_MAX, $factor)) {
                throw new \OverflowException($function . '() result exceeds the host integer range.');
            }
            $result *= $factor;
        }

        return $result;
    }

    private static function integerGcd(int $left, int $right): int
    {
        while ($right !== 0) {
            [$left, $right] = [$right, $left % $right];
        }

        return abs($left);
    }

    private static function requireNonNegativeInteger(int|float $value, string $function): int
    {
        $integer = self::requireInteger($value, $function);
        if ($integer < 0) {
            throw new \DomainException($function . '() requires non-negative integer arguments.');
        }

        return $integer;
    }

    private static function requireInteger(int|float $value, string $function): int
    {
        if (is_int($value)) {
            return $value;
        }

        $magnitudeBits = \PHP_INT_SIZE * 8 - 1;
        $lowerBound = -(2.0 ** $magnitudeBits);
        $upperBound = 2.0 ** $magnitudeBits;
        if (
            !is_finite($value)
            || floor($value) !== $value
            || $value < $lowerBound
            || $value >= $upperBound
        ) {
            throw new \DomainException($function . '() requires finite integer arguments.');
        }

        return (int) $value;
    }
}
